INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('1.00','1.00','Introduction to Computers and Engineering Problem Solving','This course presents the fundamentals of object-oriented software design and development, computational methods and sensing for engineering, and scientific and managerial applications. It cover topics, including design of classes, inheritance, graphical user interfaces, numerical methods, streams, threads, sensors, and data structures. Students use Java ® programming language to complete weekly software assignments. How is 1.00 different from other intro programming courses offered at MIT? 1.00 is a first course in programming. It assumes no prior experience, and it focuses on the use of computation to solve problems in engineering, science and management. The audience for 1.00 is non-computer science majors. 1.00 does not focus on writing compilers or parsers or computing tools where the computer is the system; it focuses on engineering problems where the computer is part of the system, or is used to model a physical or logical system. 1.00 teaches the Java programming language, and it focuses on the design and development of object-oriented software for technical problems. 1.00 is taught in an active learning style. Lecture segments alternating with laboratory exercises are used in every class to allow students to put concepts into practice immediately; this teaching style generates questions and feedback, and allows the teaching staff and students to interact when concepts are first introduced to ensure that core ideas are understood. Like many MIT classes, 1.00 has weekly assignments, which are programs based on actual engineering, science or management applications. The weekly assignments build on the class material from the previous week, and require students to put the concepts taught in the small in-class labs into a larger program that uses multiple elements of Java together.','Computational Science and Engineering Computer Science Engineering Programming Languages Software Design and Engineering Systems Engineering','2012','https://ocw.mit.edu/courses/1-00-introduction-to-computers-and-engineering-problem-solving-spring-2012/','https://ocw.mit.edu/courses/1-00-introduction-to-computers-and-engineering-problem-solving-spring-2012/pages/syllabus/','677d2183343657be641979a6a5db4419aa71a508408199ed0785b8cb6eeffe34','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. George Kocur","Dr. Christopher Cassa","Prof. Marta C. Gonzalez"]','structured','Prerequisites 18.01 (Single Variable Calculus) . We use calculus in class and homework.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('1.00',0,'18.01');
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('1.020','1.020','Ecology II: Engineering for Sustainability','This course provides a review of physical, chemical, ecological, and economic principles used to examine interactions between humans and the natural environment. Mass balance concepts are applied to ecology, chemical kinetics, hydrology, and transportation; energy balance concepts are applied to building design, ecology, and climate change; and economic and life cycle concepts are applied to resource evaluation and engineering design. Numerical models are used to integrate concepts and to assess environmental impacts of human activities. Problem sets involve development of MATLAB® models for particular engineering applications. Some experience with computer programming is helpful but not essential.','Biology Civil Engineering Earth Science Ecology Engineering Environmental Science Science Sustainability','2008','https://ocw.mit.edu/courses/1-020-ecology-ii-engineering-for-sustainability-spring-2008/','https://ocw.mit.edu/courses/1-020-ecology-ii-engineering-for-sustainability-spring-2008/pages/syllabus/','d043cac3379fbd138417b23b9af27821d52dccd7b0c57872e0bdbb4b9c5fde56','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Dennis McLaughlin"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('1.050','1.050','Solid Mechanics','1.050 is a sophomore-level engineering mechanics course, commonly labelled “Statics and Strength of Materials” or “Solid Mechanics I.” This course introduces students to the fundamental principles and methods of structural mechanics. Topics covered include: static equilibrium, force resultants, support conditions, analysis of determinate planar structures (beams, trusses, frames), stresses and strains in structural elements, states of stress (shear, bending, torsion), statically indeterminate systems, displacements and deformations, introduction to matrix methods, elastic stability, and approximate methods. Design exercises are used to encourage creative student initiative and systems thinking.','Aerospace Engineering Engineering Materials Science and Engineering Mechanical Engineering Solid Mechanics Structural Mechanics','2004','https://ocw.mit.edu/courses/1-050-solid-mechanics-fall-2004/','https://ocw.mit.edu/courses/1-050-solid-mechanics-fall-2004/pages/syllabus/','2b4e00dc3f6bff231426c0b0d28e6d0618122d9134df36f5b9727490b4952ef6','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Louis Bucciarelli"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('1.101','1.101','Introduction to Civil and Environmental Engineering Design I','In this sophomore design course, you will be challenged with three design tasks: a first concerning water resources/treatment, a second concerning structural design, and a third focusing on the conceptual (re)design of a large system, Boston’s Back Bay. The first two tasks require the design, fabrication and testing of hardware. Several laboratory experiments will be carried out and lectures will be presented to introduce students to the conceptual and experimental basis for design in both domains. This course was based in large part on the Fall 2005 offering of 1.101, developed by Prof. Harold Hemond.','Civil Engineering Engineering Environmental Engineering','2006','https://ocw.mit.edu/courses/1-101-introduction-to-civil-and-environmental-engineering-design-i-fall-2006/','https://ocw.mit.edu/courses/1-101-introduction-to-civil-and-environmental-engineering-design-i-fall-2006/pages/syllabus/','7e4b10bc9843636e927583fea5c8ccbb7c4082a6d24fef462300c6376b5654bf','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Heidi Nepf","Prof. Herbert Einstein","Prof. Louis Bucciarelli"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('1.201J','1.201J','Introduction to Transportation Systems','1.201J/11.545J/ESD.210J is required for all first-year Master of Science in Transportation students. It would be of interest to, as well as accessible to, students in Urban Studies and Planning, Political Science, Technology and Policy, Management, and various engineering departments. It is a good subject for those who plan to take only one subject in transportation and serves as an entry point to other transportation subjects as well. The subject focuses on fundamental principles of transportation systems, introduces transportation systems components and networks, and addresses how one invests in and operates them effectively. The tie between transportation and related systems is emphasized.','Social Science Transportation Planning Urban Studies','2006','https://ocw.mit.edu/courses/1-201j-introduction-to-transportation-systems-fall-2006/','https://ocw.mit.edu/courses/1-201j-introduction-to-transportation-systems-fall-2006/pages/syllabus/','e7b7c9b795100e0315a0d25998bbd336915a0d2d34f25bedd33812bfb5be89d6','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Joseph Sussman","Prof. Nigel Wilson"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('1.221J','1.221J','Transportation Systems','Approaching transportation as a complex, large-scale, integrated, open system (CLIOS), this course strives to be an interdisciplinary systems subject in the “open” sense. It introduces qualitative modeling ideas and various techniques and philosophies of modeling complex transportation enterprises. It also introduces conceptual frameworks for qualitative analysis, such as frameworks for regional strategic planning, institutional change analysis, and new technology development and deployment. And it covers transportation as a large-scale, integrated system that interacts directly with the social, political, and economic aspects of contemporary society. Fundamental elements and issues shaping traveler and freight transportation systems are covered, along with underlying principles governing transportation planning, investment, operations, and maintenance.','Civil Engineering Engineering Social Science Transportation Engineering Transportation Planning Urban Studies','2004','https://ocw.mit.edu/courses/1-221j-transportation-systems-fall-2004/','https://ocw.mit.edu/courses/1-221j-transportation-systems-fall-2004/pages/syllabus/','cf2a7d2af6de058a1c0c0795853bdd036cf6f9ab62ea1752026f1a3d777a1bd6','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Joseph Sussman"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('1.259J','1.259J','Transit Management','This course discusses management methods of relevance to public transportation systems. Topics include strategic planning management, labor relations, maintenance planning and administration, financing, marketing and fare policy, and management information and decision support systems. The course shows how these general management tasks are dealt with in the transit industry and presents alternative strategies. It also identifies alternative arrangements for service provision, including different ways of involving the private sector in public transportation.','Business Operations Management Social Science Transportation Planning Urban Studies','2006','https://ocw.mit.edu/courses/1-259j-transit-management-fall-2006/','https://ocw.mit.edu/courses/1-259j-transit-management-fall-2006/pages/syllabus/','165f6ae7137fda0c3d9aefc71deb65829dda7c6d0403c6f40309775b5cb90fd3','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Nigel Wilson"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('1.46','1.46','Strategic Management in the Design and Construction Value Chain','This course provides an overview of key concepts in strategic management in the construction, real estate, and architecture industries. Topics include supply chain analysis, market segmentation, vertical integration, competitive advantage, and industry transformation. This course is of interest to students seeking more understanding of the business dynamics of real estate and construction; seeking to provide value in firms which they may join; or seeking to build a foundation for their own entrepreneurial pursuits.','Business Civil Engineering Construction Management Engineering Operations Management Supply Chain Management','2003','https://ocw.mit.edu/courses/1-46-strategic-management-in-the-design-and-construction-value-chain-fall-2003/','https://ocw.mit.edu/courses/1-46-strategic-management-in-the-design-and-construction-value-chain-fall-2003/pages/syllabus/','2113703e8a718decb9383314d0115cb2c5d5b9d5a6742edb6c7a6135821180a6','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. John Macomber"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('1.72','1.72','Groundwater Hydrology','This course covers fundamentals of subsurface flow and transport, emphasizing the role of groundwater in the hydrologic cycle, the relation of groundwater flow to geologic structure, and the management of contaminated groundwater. The class includes laboratory and computer demonstrations.','Earth Science Engineering Environmental Engineering Geology Hydrology and Water Resource Systems Science','2005','https://ocw.mit.edu/courses/1-72-groundwater-hydrology-fall-2005/','https://ocw.mit.edu/courses/1-72-groundwater-hydrology-fall-2005/pages/syllabus/','7777411e5a97c0de9f10bee419e8c5c221486fc92cb7615b2f08cb1b999fe316','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Charles Harvey"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('1.782','1.782','Environmental Engineering Masters of Engineering Project','This class is one of the core requirements for the Environmental Masters of Engineering program. It is designed to teach about environmental engineering through the use of case studies, computer software tools, and seminars from industrial experts. Case studies provide the basis for group projects as well as individual theses. Past case studies have included the MMR Superfund site on Cape Cod; restoration of the Florida Everglades; dredging of Boston Harbor; local watershed trading programs; appropriate wastewater treatment technology for Brazil; point-of-use water treatment for Nepal, Brownfields Development in Providence, RI, and water resource planning for the island of Cyprus. This class spans the entire academic year: students must register for the Fall term, IAP, and the Spring term.','Aquatic Sciences and Water Quality Control Engineering Environmental Engineering Environmental Management Hydrology and Water Resource Systems','2003','https://ocw.mit.edu/courses/1-782-environmental-engineering-masters-of-engineering-project-fall-2003-spring-2004/','https://ocw.mit.edu/courses/1-782-environmental-engineering-masters-of-engineering-project-fall-2003-spring-2004/pages/syllabus/','b272877799eb2826c1579b6eadb863251a890bf3cb43d6add1e8a070bc1a1a52','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Daniele Lantagne","Dr. Eric Adams","Dr. Peter Shanahan","Susan Murcott"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('1.963','1.963','Environmental Engineering Applications of Geographic Information Systems','This graduate seminar is taught in a lecture and lab exercise format. The subject matter is tailored to introduce Environmental Engineering students to the use and potential of Geographic Information Systems in their discipline. Lectures will cover the general concepts of GIS use and introduce the material in the exercises that demonstrate the practical application of GIS.','Business Computer Science Data Mining Engineering Environmental Engineering Geography Information Technology Social Science','2004','https://ocw.mit.edu/courses/1-963-environmental-engineering-applications-of-geographic-information-systems-fall-2004/','https://ocw.mit.edu/courses/1-963-environmental-engineering-applications-of-geographic-information-systems-fall-2004/pages/syllabus/','a94be6a45be6daca57fa6d554be971a5d6e51bbcc590bc2ea784f8b5eebbd755','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Daniel Sheehan"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('10.34','10.34','Numerical Methods Applied to Chemical Engineering','This course focuses on the use of modern computational and mathematical techniques in chemical engineering. Starting from a discussion of linear systems as the basic computational unit in scientific computing, methods for solving sets of nonlinear algebraic equations, ordinary differential equations, and differential-algebraic (DAE) systems are presented. Probability theory and its use in physical modeling is covered, as is the statistical analysis of data and parameter estimation. The finite difference and finite element techniques are presented for converting the partial differential equations obtained from transport phenomena to DAE systems. The use of these techniques will be demonstrated throughout the course in the MATLAB® computing environment.','Applied Mathematics Chemical Engineering Computational Modeling and Simulation Computer Science Data Mining Engineering Mathematics Probability and Statistics Systems Engineering','2005','https://ocw.mit.edu/courses/10-34-numerical-methods-applied-to-chemical-engineering-fall-2005/','https://ocw.mit.edu/courses/10-34-numerical-methods-applied-to-chemical-engineering-fall-2005/pages/syllabus/','dbcad10adf3ca5a0ee1da3eb4408f00bdcbf12b604fba942d9cf2621d005c178','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Kenneth Beers"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('10.467','10.467','Polymer Science Laboratory','Experiments in this class are broadly aimed at acquainting students with the range of properties of polymers, methods of synthesis, and physical chemistry. Some examples of laboratory work include solution polymerization of acrylamide, bead polymerization of divinylbenzene, and interfacial polymerization of nylon 6,10. Evaluation of networks by tensile and swelling experiments, rheology of polymer solutions and suspensions, and physical properties of natural and silicone rubber are also covered.','Chemical Engineering Chemistry Engineering Materials Science and Engineering Physical Chemistry Polymeric Materials Polymers Science','2005','https://ocw.mit.edu/courses/10-467-polymer-science-laboratory-fall-2005/','https://ocw.mit.edu/courses/10-467-polymer-science-laboratory-fall-2005/pages/syllabus/','bf5b46fbe6c6099a6ce1178e39d6667ec73017757d45a6b38a2392883a7ed0b8','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Mr. Harlan Breindel","Prof. Paula Hammond"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('10.520','10.520','Molecular Aspects of Chemical Engineering','This class covers molecular-level engineering and analysis of chemical processes. The use of chemical bonding, reactivity, and other key concepts in the design and tailoring of organic systems are discussed in this class. Specific class topics include application and development of structure-property relationships, and descriptions of the chemical forces and structural factors that govern supramolecular and interfacial phenomena for molecular and polymeric systems.','Analytical Chemistry Chemical Engineering Chemistry Engineering Molecular Engineering Organic Chemistry Science','2004','https://ocw.mit.edu/courses/10-520-molecular-aspects-of-chemical-engineering-fall-2004/','https://ocw.mit.edu/courses/10-520-molecular-aspects-of-chemical-engineering-fall-2004/pages/syllabus/','9d374cc96c9d8c14e49f50da71e491022f64d69ac64c1be1f3a648e3905c0e39','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Paula Hammond"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('11.001J','11.001J','Introduction to Urban Design and Development','This course examines the evolving structure of cities and the way that cities, suburbs, and metropolitan areas can be designed and developed. Boston and other American cities are studied to see how physical, social, political and economic forces interact to shape and reshape cities over time.','Architectural Design Architecture Environmental Design Fine Arts Social Science Urban Planning Urban Studies','2006','https://ocw.mit.edu/courses/11-001j-introduction-to-urban-design-and-development-spring-2006/','https://ocw.mit.edu/courses/11-001j-introduction-to-urban-design-and-development-spring-2006/pages/syllabus/','ff2d56efea90f43193cba89e3850d0bc4afa68b161292de8239db6e8b19f3ea6','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Susan Silberberg"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('11.011','11.011','The Art and Science of Negotiation','This course provides an introduction to bargaining and negotiation in public, business, and legal settings. It combines a “hands-on” skill-building orientation with a look at pertinent social theory. Strategy, communications, ethics, and institutional influences are examined as they influence the ability of actors to analyze problems, negotiate agreements, and resolve disputes in social, organizational, and political circumstances characterized by interdependent interests.','Business Leadership Social Science Sociology','2006','https://ocw.mit.edu/courses/11-011-the-art-and-science-of-negotiation-spring-2006/','https://ocw.mit.edu/courses/11-011-the-art-and-science-of-negotiation-spring-2006/pages/syllabus/','50f348fb16352a1164860d230a1ab70b25d64540eca2a7235024f1e6519ea98a','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. David Laws"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('11.027','11.027','City to City: Comparing, Researching and Writing about Cities: New Orleans','City to City, as a class, will jump into the complexity of planning in New Orleans, a post-disaster city. City-to-City will ask how a post-disaster city grapple with its ideas of identity, what it is, who it represents, and how it projects its sense of self to residences, businesses, tourists, and to the outside world. In considering its people, how do city planners think about who lives where and why? At the same time, how can city planners celebrate a city’s history and its culture and how can these elements be woven into reconstruction? Students will travel from Cambridge to New Orleans over Spring Break to meet and consult with their alumni clients, and continue to work on projects.','Social Science Urban Planning Urban Studies','2011','https://ocw.mit.edu/courses/11-027-city-to-city-comparing-researching-and-writing-about-cities-new-orleans-spring-2011/','https://ocw.mit.edu/courses/11-027-city-to-city-comparing-researching-and-writing-about-cities-new-orleans-spring-2011/pages/syllabus/','4cffe8fe08b55a71e684210ed1ab01d517e77b61ca52d6e0310b8d8654636983','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Cherie Miot Abbanat"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('11.125','11.125','Introduction to Education: Understanding and Evaluating Education','This class uses K-12 classroom experiences, along with student-centered classroom activities and student-led classes, to explore issues in schools and education. Students in this course spend time each week observing pre-college math and science classes. Topics of study include design and implementation of curriculum, addressing the needs of a diversity of students, standards in math and science, student misconceptions, methods of instruction, the digital divide, teaching through different media, and student assessment.','Curriculum and Teaching Education Policy Teaching and Education','2009','https://ocw.mit.edu/courses/11-125-introduction-to-education-understanding-and-evaluating-education-spring-2009/','https://ocw.mit.edu/courses/11-125-introduction-to-education-understanding-and-evaluating-education-spring-2009/pages/syllabus/','8382452993f4adc98eb42c877cce17e4d7a195f4abedb83ecbf28001d2601689','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Eric Klopfer"]','no_formal_course','There are no prequisites for this course.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('11.164','11.164','Human Rights: At Home and Abroad','This course provides a rigorous and critical introduction to the foundation, structure and operation of the international human rights movement, as it has evolved through the years and as it impacts the United States. The course introduces students to the key theoretical debates in the field including the historical origin and character of the modern idea of human rights, the debate between universality and cultural relativism, between civil and human rights, between individual and community, and the historically contentious relationship between the West and the Rest in matters of sovereignty and human rights, drawing on real life examples from current affairs.','Humanities International Relations Philosophy Political Philosophy Political Science Public Administration Public Policy Social Justice Social Science Sociology','2015','https://ocw.mit.edu/courses/11-164-human-rights-at-home-and-abroad-fall-2015/','https://ocw.mit.edu/courses/11-164-human-rights-at-home-and-abroad-fall-2015/pages/syllabus/','654de58142c6a9e122b7119bfd82c4732b22ea0f747d36ca8d8bb1931cf693e8','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Balakrishnan Rajagopal"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('11.201','11.201','Gateway: Planning Action','This course introduces persistent themes and challenges facing planners. It emphasizes the historical roots of contemporary urban planning problems and comparative study of practice in the U.S. and other countries. It is a nine week module intended for first semester Master in City Planning students.','Social Science Urban Planning Urban Studies','2005','https://ocw.mit.edu/courses/11-201-gateway-planning-action-fall-2005/','https://ocw.mit.edu/courses/11-201-gateway-planning-action-fall-2005/pages/syllabus/','df64401a331035d587e7521ca772f29c880502e883ba58325a24fea905920a0c','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Cherie Miot Abbanat","Prof. Lawrence Vale","Prof. Xavier de Souza Briggs","Prof. Annette M. Kim","Prof. Balakrishnan Rajagopal"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('11.205','11.205','Introduction to Spatial Analysis','Geographic Information System (GIS) software manages data that represent the location of features (geographic coordinate data) and what they are like (attribute data); it also provides the ability to query, manipulate, and analyze those data. Because GIS allows one to represent social and environmental data on maps, it is a powerful tool for analysis and planning in various fields. This course is meant to introduce students to the basic capabilities of GIS.','Computer Science Engineering Geography Graphics and Visualization Social Science','2019','https://ocw.mit.edu/courses/11-205-introduction-to-spatial-analysis-fall-2019/','https://ocw.mit.edu/courses/11-205-introduction-to-spatial-analysis-fall-2019/pages/syllabus/','124e212553f6c74e6e4c9d04ea6ad2c0ff2cad14906212f732c3e0d9ad48f25f','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Sarah Williams","Eric Robsky Huntley"]','no_formal_course','There are no prerequisites for this course.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('11.233','11.233','Research Design for Policy Analysis and Planning','This course develops skills in research design for policy analysis and planning. The emphasis is on the logic of the research process and its constituent elements. The course relies on a seminar format so students are expected to read all of the assigned materials and come to class prepared to discuss key themes, ideas, and controversies. Since the materials draw broadly on the social sciences, and since students have diverse interests and methodological preferences, ongoing themes in our discussions will be linking concepts to planning scholarship in general and considering how different epistemological orientations and methodological techniques map on to planning specializations.','Public Administration Public Policy Social Science Urban Planning Urban Studies','2007','https://ocw.mit.edu/courses/11-233-research-design-for-policy-analysis-and-planning-fall-2007/','https://ocw.mit.edu/courses/11-233-research-design-for-policy-analysis-and-planning-fall-2007/pages/syllabus/','ace29f7c1b3dd93998e50810e0ea16c7e767e72b8f2dcc65e5cbfdb3ed98b446','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. JoAnn Carmin"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('11.304J','11.304J','Site and Infrastructure Systems Planning','This course is a client-based land analysis and site planning project. The primary focus of the course changes from year to year. This year the focus is on Japan’s New Towns. Students will review land inventory, analysis, and planning of sites and the infrastructure systems that serve them. They will also examine spatial organization of uses, parcelization, design of roadways, grading, utility systems, stormwater runoff, parking, traffic and off-site impacts, as well as landscaping. Lectures will cover analytical techniques and examples of good site-planning practice. Requirements include a series of assignments and a client-based project.','Architecture Civil Engineering Engineering Environmental Design Fine Arts Housing Development Social Science Urban Planning Urban Studies','2009','https://ocw.mit.edu/courses/11-304j-site-and-infrastructure-systems-planning-spring-2009/','https://ocw.mit.edu/courses/11-304j-site-and-infrastructure-systems-planning-spring-2009/pages/syllabus/','c8a5a7d0d4c3914e5a4a70c03780e5a651f2f164fcc965c1d6165deb1bbb928a','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Eran Ben-Joseph"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('11.309J','11.309J','Sensing Place: Photography as Inquiry','This course explores photography as a disciplined way of seeing, as a research method, and as a medium of inquiry and of expressing ideas. Readings, observations, and photographs form the basis of discussions on landscape, light, significant detail, place, narrative, and how photography can inform research, design, and planning, among other issues. The class is highly recommended for students who want to employ visual methods in their thesis or dissertation.','Architecture Environmental Design Fine Arts Photography Social Science Urban Studies Visual Arts','2024','https://ocw.mit.edu/courses/11-309j-sensing-place-photography-as-inquiry-spring-2024/','https://ocw.mit.edu/courses/11-309j-sensing-place-photography-as-inquiry-spring-2024/pages/syllabus/','12e2519b96b4004580ff796049276c73f1792e5251c2e5944b4bd8c1bb31eca9','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Anne Whiston Spirn"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('11.332J','11.332J','Urban Design','For many years, Cambridge, MA, as host to two major research universities, has been the scene of debates as to how best to meet the competing expectations of different stakeholders. Where there has been success, it has frequently been the result, at least in part, of inventive urban design proposals and the design and implementation of new institutional arrangements to accomplish those proposals. Where there has been failure it has often been explained by the inability - or unwillingness - of one stakeholder to accept and accommodate the expectations of another. The two most recent fall Urban Design Studios have examined these issues at a larger scale. In 2001 we looked at the possible patterns for growth and change in Cambridge, UK, as triggered by the plans of Cambridge University. And in 2002 we looked at these same issues along the length of the MIT ‘frontier’ in Cambridge, MA as they related to the development of MIT and the biotech research industry. In the fall 2003 Urban Design Studio we propose to focus in on an area adjacent to Cambridgeport and the western end of the MIT campus, roughly centered on Fort Washington. Our goal is to discover the ways in which good urban form, an apt mix of activities, and effective institutional mechanisms might all be brought together in ways that respect shared expectations and reconcile competing expectations - perhaps in unexpected and adroit ways.','Architecture Environmental Design Fine Arts Social Science Urban Planning Urban Studies','2003','https://ocw.mit.edu/courses/11-332j-urban-design-fall-2003/','https://ocw.mit.edu/courses/11-332j-urban-design-fall-2003/pages/syllabus/','5ff8e3cb3f3575a70e7d52fca1752227c07450db1c4aa0a1c6674789cab266d5','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Carol Burns","Prof. John de Monchaux"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('11.360','11.360','Community Growth and Land Use Planning','This subject explores the techniques, processes, and personal and professional skills required to effectively manage growth and land use change. While primarily focused on the planning practice in the United States, the principles and techniques reviewed and presented may have international application. This course is not for bystanders; it is designed for those who wish to become actively involved or exposed to the planning discipline and profession as it is practiced today, and as it may need to be practiced in the future.','Community Development Public Administration Public Policy Social Science Sociology Urban Planning Urban Studies','2003','https://ocw.mit.edu/courses/11-360-community-growth-and-land-use-planning-fall-2003/','https://ocw.mit.edu/courses/11-360-community-growth-and-land-use-planning-fall-2003/pages/syllabus/','66f3089cad2b8feae6615665c30766d779129bdff38900f2b763b488a97548aa','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Terry Szold"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('11.364','11.364','International Environmental Negotiation','This seminar will explore the difficulties of getting agreement on global definitions of sustainability; in particularly building international support for efforts to combat climate change created by greenhouse gas emissions as well as other international resource management efforts. We will focus on possible changes in the way global environmental agreements are formulated and implemented, especially on ways of shifting from the current “pollution control” approach to combating climate change to a more comprehensive strategy for taking advantage of sustainable development opportunities.','Earth Science Engineering Environmental Engineering Environmental Management Environmental Policy International Relations Political Science Public Administration Science Social Science Sustainability Urban Studies','2010','https://ocw.mit.edu/courses/11-364-international-environmental-negotiation-fall-2010/','https://ocw.mit.edu/courses/11-364-international-environmental-negotiation-fall-2010/pages/syllabus/','6b528ee19120a9819ab60a0a449f0a3b85d625d0cb6ba08f3a2e4c2c561fe4bb','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. William Moomaw","Prof. Lawrence Susskind"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('11.375','11.375','Role of Science and Scientists in Collaborative Approaches to Environmental Policymaking','This course examines joint fact-finding within the context of adaptive and ecosystem-based management. Challenges and obstacles to collaborative approaches for deciding environmental and natural resource policy and the institutional changes within federal agencies necessary to utilize joint fact-finding as a means to link science and societal decisions are discussed and reviewed with scientists and managers. Senior-level federal policymakers also participate in these discussions.','Engineering Environmental Engineering Environmental Management Environmental Policy Public Administration Public Policy Science and Technology Policy Social Science','2006','https://ocw.mit.edu/courses/11-375-role-of-science-and-scientists-in-collaborative-approaches-to-environmental-policymaking-spring-2006/','https://ocw.mit.edu/courses/11-375-role-of-science-and-scientists-in-collaborative-approaches-to-environmental-policymaking-spring-2006/pages/syllabus/','4e47fffe5427df42a330c2bf86d08788383e326d44ab6145b7bc8fb7df6aded5','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Herman Karl"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('11.409','11.409','Institutions of Modern Capitalism','This course introduces students to a set of analytic tools and conceptual frameworks through which to assess the origins and evolution of the institutions that constitute modern capitalism. The course takes an inter-disciplinary political economy approach that draws insights from economics, sociology, political science, history, geography, science and technology studies, and law.','Economics Political Science Social Science','2020','https://ocw.mit.edu/courses/11-409-institutions-of-modern-capitalism-spring-2020/','https://ocw.mit.edu/courses/11-409-institutions-of-modern-capitalism-spring-2020/pages/syllabus/','b680457fc4fdd0da60ff6cca3c9050548c66f16cd44e6ac96cc251da419ac5f0','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Jason Jackson"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('11.433J','11.433J','Real Estate Economics','This course, offered by the MIT Center for Real Estate , focuses on developing an understanding of the macroeconomic factors that shape and influence markets for real property. We will develop the theory of land markets and locational choice. The material covered includes studies of changing economic activities, demographic trends, transportation and local government behavior as they affect real estate.','Business Economics Macroeconomics Public Administration Real Estate Social Science Urban Studies','2008','https://ocw.mit.edu/courses/11-433j-real-estate-economics-fall-2008/','https://ocw.mit.edu/courses/11-433j-real-estate-economics-fall-2008/pages/syllabus/','7f35e2c792abea8622acce950a75a8709ceed57ca9a74da59d12f4636b983fd7','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. William Wheaton"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('11.467J','11.467J','Property Rights in Transition','This course examines the theories and policy debates over who can own real property, how to communicate and enforce property rights, and the range of liberties that they confer. It explores alternative economic, political, and sociological perspectives of property rights and their policy and planning implications.','Business Humanities Legal Studies Philosophy Political Philosophy Public Administration Public Policy Real Estate Social Justice Social Science Sociology Urban Studies','2005','https://ocw.mit.edu/courses/11-467j-property-rights-in-transition-spring-2005/','https://ocw.mit.edu/courses/11-467j-property-rights-in-transition-spring-2005/pages/syllabus/','9f9794b3a584b64836c1ada6e775d1a67233b430ffc81434de78595250052b1f','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Annette M. Kim"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('11.481J','11.481J','Analyzing and Accounting for Regional Economic Growth','This course focuses on alternative ways in which the issues of growth, restructuring, innovation, knowledge, learning, and accounting and measurements can be examined, covering both industrialized and emerging countries. We give special emphasis to recent transformations in regional economies throughout the world and to the implications these changes have for the theories and research methods used in spatial economic analyses. Readings will relate mainly to the United States, but we cover pertinent material on foreign countries in lectures.','Economics Macroeconomics Political Economy Regional Planning Social Science Urban Studies','2009','https://ocw.mit.edu/courses/11-481j-analyzing-and-accounting-for-regional-economic-growth-spring-2009/','https://ocw.mit.edu/courses/11-481j-analyzing-and-accounting-for-regional-economic-growth-spring-2009/pages/syllabus/','3901fd47e99d5988d166a9fb7509dd9e27675019b792c04ab0a7ee888a50b51d','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Karen R. Polenske"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('11.487','11.487','Urban Public Finance in Developing Countries','This readings-based course analyzes the structure and operation of government systems in developing countries, with particular emphasis on regional and local governments. Major topics include: the role of decentralization in national economic reform programs, the potential impact of decentralized governments on local economic development, determination of optimal arrangements for sharing fiscal responsibilities among levels of government, evaluation of local revenue and expenditure decisions, and assessment of prospects and options for intergovernmental fiscal reform. Emphasis is on basic economic concerns, with consideration given to political, institutional, and cultural factors.','Business Developmental Economics Economics Finance Public Administration Public Economics Public Policy Social Science Urban Studies','2004','https://ocw.mit.edu/courses/11-487-urban-public-finance-in-developing-countries-fall-2004/','https://ocw.mit.edu/courses/11-487-urban-public-finance-in-developing-countries-fall-2004/pages/syllabus/','2592d65d44edb345bfff575092fa20ce12a6b009999994f27376446b60f3bd1b','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Annette M. Kim"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('11.520','11.520','A Workshop on Geographic Information Systems','This class uses lab exercises and a workshop setting to help students develop a solid understanding of the planning and public management uses of geographic information systems (GIS). The goals are to help students: acquire technical skills in the use of GIS software; acquire qualitative methods skills in data and document gathering, analyzing information, and presenting results; and investigate the potential and practicality of GIS technologies in a typical planning setting and evaluate possible applications. The workshop teaches GIS techniques and basic database management at a level that extends somewhat beyond the basic thematic mapping and data manipulation skills included in the MCP core classes (viz. 11.204 and 11.220). Instead of focusing on one thematic map of a single variable, students will concentrate on more open-ended planning questions that invite spatial analysis but will require judgment and exploration to select relevant data and mapping techniques; involve mixing and matching new, local data with extracts from official records (such as census data, parcel data and regional employment and population forecasts); utilize spatial analysis techniques such as buffering, address matching, overlays; use other modeling and visualization techniques beyond thematic mapping; and raise questions about the skills, strategy, and organizational support needed to sustain such analytic capability within a variety of local and regional planning settings. Students seeking graduate credit should enroll in the subject 11.520; undergraduates should enroll in the subject 11.188. The subjects meet together and have nearly identical content. ArcGIS/ArcMap/ArcInfo Graphical User Interface is the intellectual property of ESRI and is used herein with permission. Copyright © ESRI. All rights reserved.','Business Civil Engineering Computer Science Data Mining Engineering Graphics and Visualization Information Technology Public Administration Social Science Surveying Urban Planning Urban Studies','2005','https://ocw.mit.edu/courses/11-520-a-workshop-on-geographic-information-systems-fall-2005/','https://ocw.mit.edu/courses/11-520-a-workshop-on-geographic-information-systems-fall-2005/pages/syllabus/','4d969004ffbd5f071bdb6879451c11df51f64aed599adc30df370c5d41b591b1','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Joseph Ferreira"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('11.800','11.800','Doctoral Research Seminar: Knowledge in the Public Arena','This is a course about how research knowledge and other types of knowledge come to be actionable and influential in the world — or not. The course explores ways to make research knowledge more accessible, credible, and useful in the realm of public policy and practice, a project in which the course faculty collectively bring decades of professional experience, in both academic and non-academic roles. The course addresses the politics of the policymaking process, the power of framing and agenda-setting, fads and paradigms in the design professions and society in general, how knowledge diffuses along knowledge and influence networks, and how varied types of knowledge (rational, craft, other) and deliberation shape decision-making and action. The course engages a number of guests to present case studies of research in use (and abuse) in varied fields, highlighting rich areas for potential research contributions, along with major conflicts in public values, political interests, ethical obligations, and more. The resulting dilemmas confront scholars, policymakers, practitioners, and others as they look to research — sometimes — for useful guidance, influence, or both.','Communication Political Science Public Administration Public Policy Social Justice Social Science Sociology Urban Planning Urban Studies','2007','https://ocw.mit.edu/courses/11-800-doctoral-research-seminar-knowledge-in-the-public-arena-spring-2007/','https://ocw.mit.edu/courses/11-800-doctoral-research-seminar-knowledge-in-the-public-arena-spring-2007/pages/syllabus/','7269f83f105b6bf033c1aab7e7dedae8d28e1afa98e7122d34a96707086cd4c6','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Frank Levy","Prof. Martin Rein","Prof. Xavier de Souza Briggs"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('11.941','11.941','Use of Joint Fact Finding in Science Intensive Policy Disputes, Part I','11.941 and 11.942 make up a one-year seminar. The goal of this seminar is to explore the role of science and scientists in ecosystems and natural resources management focusing on joint fact finding as a new approach to environmental policy-making. Increasingly scientists and science organizations are confronting a conundrum: Why is science often ignored in important societal decisions even as the call for decisions based on sound science escalates? One reason is that decision-making is often driven by a variety of nonscientific, adversarial, and stakeholder dynamics. Thus, even though science helps inform choices, it is only one of many values and interests considered by each stakeholder. In response to this emerging challenge, scientists, and science agencies such as the U.S. Geological Survey, are embarking upon research that explores the problems of incorporating science into value-laden societal decisions. This research includes designing experiments that will assess the appropriateness of using the new and emerging approach of Joint Fact Finding to address some of the Nation’s most contentious environmental conflicts. In the first few sessions we will examine the problems of using science in environmental disputes. In following sessions, students will analyze and discuss cases that involved or that should have involved Joint Fact Finding of various kinds.','Engineering Environmental Engineering Environmental Management Environmental Policy Public Administration Science and Technology Policy Social Science','2003','https://ocw.mit.edu/courses/11-941-use-of-joint-fact-finding-in-science-intensive-policy-disputes-part-i-fall-2003/','https://ocw.mit.edu/courses/11-941-use-of-joint-fact-finding-in-science-intensive-policy-disputes-part-i-fall-2003/pages/syllabus/','5bc1a2bd87115badfbc7e131a1c403ebdf9a3ec47d488fdbf6d238c681c1400d','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Herman Karl","Prof. Lawrence Susskind"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('11.945','11.945','Springfield Studio','The Springfield Studio is a practicum design course that focuses on the physical, programmatic, and social renewal of an urban community in Springfield, Massachusetts by combining classroom work with an applied class project. The course content covers the areas of physical design/urban design and the related analysis and planning tools used to understand and assess urban conditions from a design and development perspective. Urban design issues are investigated in the context of social and economic challenges within the community. Thus, the course has dual goals: analyze physical conditions in the community, assess community need, propose physical design interventions; and assess community capacity and programmatic needs. The ultimate goal is to explore the integration of social, programmatic and physical development interventions in ways that reinforce community revitalization efforts, and to apply this knowledge through the development of a formal neighborhood revitalization plan that addresses community needs.','Architecture Community Development Environmental Design Fine Arts Regional Planning Social Science Sociology Urban Planning Urban Studies','2004','https://ocw.mit.edu/courses/11-945-springfield-studio-spring-2004/','https://ocw.mit.edu/courses/11-945-springfield-studio-spring-2004/pages/syllabus/','0c8e94d7ac9d5014586a481c9ba3a0c1e55b38f909eaf231c015c1ea7778fb1c','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Ceasar McDowell","Prof. Susan Silberberg"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('11.947','11.947','Race, Immigration, and Planning','This course provides an introduction to the issues of immigrants, planning, and race. It identifies the complexities and identities of immigrant populations emerging in the United States context and how different community groups negotiate that complexity. It explores the critical differences and commonalities between immigrant and non-immigrant communities, as well as how the planning profession does and should respond to those differences. Finally, the course explores the intersection of immigrant communities’ formation and their interactions with African Americans and the idea of race in the United States.','African American Studies Anthropology Community Development Humanities Philosophy Political Philosophy Social Anthropology Social Science Society Sociology Urban Planning Urban Studies','2005','https://ocw.mit.edu/courses/11-947-race-immigration-and-planning-spring-2005/','https://ocw.mit.edu/courses/11-947-race-immigration-and-planning-spring-2005/pages/syllabus/','ffe960bbf378b312e3414e5958a00d1a68d667527aa4544ce780a196c568d444','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. J. Phillip Thompson","Prof. Alethia Jones"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('11.949','11.949','City Visions: Past and Future','This class is intended to introduce students to understandings of the city generated from both social science literature and the field of urban design. The first part of the course examines literature on the history and theory of the city. Among other factors, it pays special attention to the larger territorial settings in which cities emerged and developed (ranging from the global to the national to the regional context) and how these affected the nature, character, and functioning of cities and the lives of their inhabitants. The remaining weeks focus more explicitly on the theory and practice of design visions for the city, the latter in both utopian and realized form. One of our aims will be to assess the conditions under which a variety of design visions were conceived, and to assess them in terms of the varying patterns of territorial “nestedness” (local, regional, national, imperial, and global) examined in the first part of the course. Another will be to encourage students to think about the future prospects of cities (in terms of territorial context or other political functions and social aims) and to offer design visions that might reflect these new dynamics.','Architecture Comparative History Environmental Design Fine Arts History Humanities Social Science Sociology Urban Studies','2004','https://ocw.mit.edu/courses/11-949-city-visions-past-and-future-spring-2004/','https://ocw.mit.edu/courses/11-949-city-visions-past-and-future-spring-2004/pages/syllabus/','37c19569568a88a080bfcd94a367d5edfd56ef78f90a5519ce3e2e2e703d73f7','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Diane Davis","Prof. Lawrence Vale"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('11.957','11.957','Frameworks of Urban Governance','Urban governance comprises the various forces, institutions, and movements that guide economic and physical development, the distribution of resources, social interactions, and other aspects of daily life in urban areas. This course examines governance from legal, political, social, and economic perspectives. In addition, we will discuss how these structures constrain collective decision making about particular urban issues (immigration, education…). Assignments will be nightly readings and a short paper relating an urban issue to the frameworks outlined in the class.','Economics Political Economy Public Administration Regional Politics Social Science Urban Studies','2007','https://ocw.mit.edu/courses/11-957-frameworks-of-urban-governance-january-iap-2007/','https://ocw.mit.edu/courses/11-957-frameworks-of-urban-governance-january-iap-2007/pages/syllabus/','38c6b73cca33864f443f33eed126d302499b70bc0bc8f185ce5d4405d58c36c1','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Deborah Kobes"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('11.975','11.975','Feeding Cities in the Global South: Challenges and Opportunities for Action in Cartagena','The purpose of this seminar is to provide a context for understanding the challenges of urban food provisioning from a perspective of sustainability and social inclusion in cities of the global South. The seminar will be specifically geared towards preparing students for direct participation in urban markets and food policy project intervention in Cartagena, Colombia.','Business Developmental Economics Economics Public Administration Regional Planning Social Science Social Welfare Supply Chain Management Urban Studies','2009','https://ocw.mit.edu/courses/11-975-feeding-cities-in-the-global-south-challenges-and-opportunities-for-action-in-cartagena-fall-2009/','https://ocw.mit.edu/courses/11-975-feeding-cities-in-the-global-south-challenges-and-opportunities-for-action-in-cartagena-fall-2009/pages/syllabus/','51bcc520efd6114f4f64276514dfb524f38907284f229629c130819d4fb7922b','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Alejandro Guarín","Dr. Edgar Blanco","Prof. Ralph Gakenheimer","Prof. Martha Bonilla","Ms. Alexa T Mills"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('11.S945','11.S945','Equity & Inclusion: Local Policy-Driven Strategies for Economic Development & the Just City','This course explores equity as a key value, measure, and framework for operationalizing local economic development plans and policies. It examines the implementation of local policy initiatives for equity in U.S. cities and investigates a wide range of contemporary theory and practice in the field of urban economic development, from contracting and municipal procurement to arts and culture-driven approaches.','Community Development Public Administration Public Policy Social Justice Social Science Sociology','2019','https://ocw.mit.edu/courses/11-s945-equity-inclusion-local-policy-driven-strategies-for-economic-development-the-just-city-spring-2019/','https://ocw.mit.edu/courses/11-s945-equity-inclusion-local-policy-driven-strategies-for-economic-development-the-just-city-spring-2019/pages/syllabus/','75aa7adb147c818aba674875f4422b96bbea5f54db7ae02d2a1cefb016d66957','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Karilyn Crockett"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('12.002','12.002','Physics and Chemistry of the Terrestrial Planets','This course introduces the structure, composition, and physical processes governing the terrestrial planets, including their formation and basic orbital properties. Topics include plate tectonics, earthquakes, seismic waves, rheology, impact cratering, gravity and magnetic fields, heat flux, thermal structure, mantle convection, deep interiors, planetary magnetism, and core dynamics. Suitable for majors and non-majors seeking general background in geophysics and planetary structure.','Earth Science Geophysics Planetary Science Science','2008','https://ocw.mit.edu/courses/12-002-physics-and-chemistry-of-the-terrestrial-planets-fall-2008/','https://ocw.mit.edu/courses/12-002-physics-and-chemistry-of-the-terrestrial-planets-fall-2008/pages/syllabus/','2d3dec16d57b11aa1af0e31b81a834d51bfa35a881836a7a1133406cc5d81d46','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Benjamin Weiss","Prof. Leigh Royden"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('12.010','12.010','Computational Methods of Scientific Programming','This course introduces programming languages and techniques used by physical scientists: FORTRAN, C, C++, MATLAB®, and Mathematica. Emphasis is placed on program design, algorithm development and verification, and comparative advantages and disadvantages of different languages.','Algorithms and Data Structures Computational Science and Engineering Computer Science Engineering Programming Languages Systems Engineering','2011','https://ocw.mit.edu/courses/12-010-computational-methods-of-scientific-programming-fall-2011/','https://ocw.mit.edu/courses/12-010-computational-methods-of-scientific-programming-fall-2011/pages/syllabus/','6b61acc14b5bf7bb1a95c1f29cce5e9edbb3d06202730cfd4545421afa243e69','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Thomas Herring","Dr. Chris Hill"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('12.091','12.091','Basics of Analysis with Antineutrinos from Heat Producing Elements - K, U, Th in the Earth','This course covers the following questions. What are the predominant heat producing elements of the Earth? Where and how much are they? Are they present in the core of the Earth? Detection of antineutrinos generated in the Earth provides: 1) information on the sources of the terrestrial heat, 2) direct test of the Bulk Silicate Earth (BSE) model and 3) testing of non-conventional models of Earth’s core. Use of antineutrinos to probe the deep interior of our planet is becoming practical due to recent fundamental advances in the antineutrino detectors.','Analytical Chemistry Chemistry Earth Science Engineering Geophysics High Energy Physics Nuclear Engineering Nuclear Materials Nuclear Physics Particle Physics Physics Planetary Science Science','2010','https://ocw.mit.edu/courses/12-091-basics-of-analysis-with-antineutrinos-from-heat-producing-elements-k-u-th-in-the-earth-january-iap-2010/','https://ocw.mit.edu/courses/12-091-basics-of-analysis-with-antineutrinos-from-heat-producing-elements-k-u-th-in-the-earth-january-iap-2010/pages/syllabus/','f9a8b0d6f42d16d17904f339800d03559414e08117f1145173a63791868784e7','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Ila Pillalamarri"]','review_required','Permission of instructor') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('12.102','12.102','Environmental Earth Science','The geologic record demonstrates that our environment has changed over a variety of time scales from seconds to billions of years. This course explores the many ways in which geologic processes control and modify the Earth’s environment and serves as an introduction to Environmental Earth Science Field Course (12.120), which addresses field applications of these principles in the American Southwest.','Earth Science Environmental Science Geochemistry Geology Planetary Science Science','2005','https://ocw.mit.edu/courses/12-102-environmental-earth-science-fall-2005/','https://ocw.mit.edu/courses/12-102-environmental-earth-science-fall-2005/pages/syllabus/','41204cb46f9a6af6c83cd3bde440416d93ac4d1030878144bee13ee89f04f1f5','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Samuel Bowring"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('12.110','12.110','Sedimentary Geology','Survey of the important aspects of modern sediments and ancient sedimentary rocks. Emphasis is on fundamental materials, features, and processes. Textures of siliciclastic sediments and sedimentary rocks: particle size, particle shape, and particle packing. Mechanics of sediment transport. Survey of siliciclastic sedimentary rocks: sandstones, conglomerates, and shales. Carbonate sediments and sedimentary rocks; cherts; evaporites. Siliciclastic and carbonate diagenesis. Paleontology, with special reference to fossils in sedimentary rocks. Modern and ancient depositional environments. Stratigraphy. Sedimentary basins. Fossil fuels: coal, petroleum.','Earth Science Geochemistry Geology Geophysics Oceanography Science','2007','https://ocw.mit.edu/courses/12-110-sedimentary-geology-spring-2007/','https://ocw.mit.edu/courses/12-110-sedimentary-geology-spring-2007/pages/syllabus/','678932c3dbf88f4fbe2566c24d4dbbaef138502c8a1ef83ae7b510dcc4388059','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. John Southard"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('12.163','12.163','Surface Processes and Landscape Evolution','The course offers an introduction to quantitative analysis of geomorphic processes, and examines the interaction of climate, tectonics, and surface processes in the sculpting of Earth’s surface.','Earth Science Environmental Science Geology Geophysics Science','2004','https://ocw.mit.edu/courses/12-163-surface-processes-and-landscape-evolution-fall-2004/','https://ocw.mit.edu/courses/12-163-surface-processes-and-landscape-evolution-fall-2004/pages/syllabus/','a4085ff28c7c4841fdd402df7ebbe5fd8255b3b4be3e5b748a34567c6ab08c95','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Ben Crosby","Prof. Kelin Whipple"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('12.340','12.340','Global Warming Science','This course provides students with a scientific foundation of anthropogenic climate change and an introduction to climate models. It focuses on fundamental physical processes that shape climate (e.g. solar variability, orbital mechanics, greenhouse gases, atmospheric and oceanic circulation, and volcanic and soil aerosols) and on evidence for past and present climate change. During the course they discuss material consequences of climate change, including sea level change, variations in precipitation, vegetation, storminess, and the incidence of disease. This course also examines the science behind mitigation and adaptation proposals.','Atmospheric Science Climate Climate Studies Earth Science Energy Environmental Science Science','2012','https://ocw.mit.edu/courses/12-340-global-warming-science-spring-2012/','https://ocw.mit.edu/courses/12-340-global-warming-science-spring-2012/pages/syllabus/','b8f2d9f09f3caacf498c0b9831d277e1760cf5abe842fd71fe4748982db2d006','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Kerry Emanuel","Prof. Sara Seager","Prof. Daniel Cziczo","Prof. David McGee"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('12.453','12.453','Crosby Lectures in Geology: History of Africa','This course is a series of presentations on an advanced topic in the field of geology by the visiting William Otis Crosby lecturer. The Crosby lectureship is awarded to a distinguished international scientist each year to introduce new scientific perspectives to the MIT community. This year’s Crosby lecturer is Prof. Kevin Burke. His lecture is about African history. The basic theme is the distinctiveness of the African continent in both the way that it originated 600 million years ago and in the way that it has developed ever since.','African History Earth Science Geology Geophysics History Humanities Science','2005','https://ocw.mit.edu/courses/12-453-crosby-lectures-in-geology-history-of-africa-fall-2005/','https://ocw.mit.edu/courses/12-453-crosby-lectures-in-geology-history-of-africa-fall-2005/pages/syllabus/','eadd8fcc46612c734b74bed50af5d16aeb3db52fe4404a45567e18c4019381bf','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Kevin Burke"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('12.491','12.491','Biogeochemistry of Sulfur','This course is designed for advanced undergraduate and graduate students with an interest in using primary research literature to discuss and learn about current research around sulfur biogeochemistry and astrobiology.','Biochemistry Biology Earth Science Geobiology Geochemistry Planetary Science Science','2007','https://ocw.mit.edu/courses/12-491-biogeochemistry-of-sulfur-fall-2007/','https://ocw.mit.edu/courses/12-491-biogeochemistry-of-sulfur-fall-2007/pages/syllabus/','3d8f47d0dcd9955bfb37063ea7b32caf5f6b92dc277196f17d743586e519f2ae','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Roger Summons","Prof. Shuhei Ono"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('12.520','12.520','Geodynamics','This course deals with mechanics of deformation of the crust and mantle, with emphasis on the importance of different rheological descriptions: brittle, elastic, linear and nonlinear fluids, and viscoelastic.','Earth Science Geology Geophysics Science','2006','https://ocw.mit.edu/courses/12-520-geodynamics-fall-2006/','https://ocw.mit.edu/courses/12-520-geodynamics-fall-2006/pages/syllabus/','fd110569dd3d22caa90ae05a20ee8b2183e5b19a76c85b1b5054a16e25e0de58','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Bradford Hager"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('12.571','12.571','Near-Surface Geophysical Imaging','This graduate level course presents theories, methodologies, and applications of seismic imaging for solving the shallow near-surface (0 - 500 m) effects on the seismic data processing for oil and gas exploration on land. It introduces both conventional and advanced imaging technologies that have been developed in academia and the seismic industry.','Computer Science Data Mining Earth Science Engineering Geology Geophysics Science','2009','https://ocw.mit.edu/courses/12-571-near-surface-geophysical-imaging-fall-2009/','https://ocw.mit.edu/courses/12-571-near-surface-geophysical-imaging-fall-2009/pages/syllabus/','e0dfe89c287c3ca872de5b24e021e553682944e1d7da8d9d621e337a485934bd','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Jie Zhang"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('12.746','12.746','Marine Organic Geochemistry','This class is designed to provide the student with a global to molecular-level perspective of organic matter cycling in the oceans and marine sediments. Topics include: Organic matter (C,N,P) composition, reactivity and budgets within, and fluxes through, major ocean reservoirs; microbial recycling pathways for organic matter; models of organic matter degradation and preservation; role of anoxia in organic matter burial; relationships between dissolved and particulate (sinking and suspended) organic matter; methods for characterization of sedimentary organic matter; and application of biological markers as tools in oceanography. Both structural and isotopic aspects are covered.','Chemistry Earth Science Geobiology Geochemistry Oceanography Organic Chemistry Science','2005','https://ocw.mit.edu/courses/12-746-marine-organic-geochemistry-spring-2005/','https://ocw.mit.edu/courses/12-746-marine-organic-geochemistry-spring-2005/pages/syllabus/','42f87704f763aa92e7556e5863c2cd48b04e9f22c47e5b989ddfbea71aa3c79c','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Daniel Repeta","Prof. Timothy Eglinton"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('12.802','12.802','Wave Motion in the Ocean and the Atmosphere','This course is an introduction to basic ideas of geophysical wave motion in rotating, stratified, and rotating-stratified fluids. Subject begins with general wave concepts of phase and group velocity. It also covers the dynamics and kinematics of gravity waves with a focus on dispersion, energy flux, initial value problems, etc.','Atmospheric Science Earth Science Engineering Environmental Engineering Fluid Mechanics Geophysics Hydrodynamics Hydrodynamics and Coastal Engineering Mechanical Engineering Ocean Engineering Oceanography Science','2008','https://ocw.mit.edu/courses/12-802-wave-motion-in-the-ocean-and-the-atmosphere-spring-2008/','https://ocw.mit.edu/courses/12-802-wave-motion-in-the-ocean-and-the-atmosphere-spring-2008/pages/syllabus/','a0064a8bf1c98302e879b7ff31f98c85337fccca58b40a55160cdc835000dc40','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Paola Rizzoli"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('12.810','12.810','Dynamics of the Atmosphere','This course discusses the dynamics of the atmosphere, with emphasis on the large scale. Topics include internal gravity waves in the atmosphere; potential vorticity conservation and Rossby waves; baroclinic instability and extratropical storms; the general circulation including the role of eddies, isentropic coordinates and tracer transport. This class builds on a previous version of 12.810 taught by Professor Alan Plumb.','Atmospheric Science Earth Science Geophysics Science','2023','https://ocw.mit.edu/courses/12-810-dynamics-of-the-atmosphere-spring-2023/','https://ocw.mit.edu/courses/12-810-dynamics-of-the-atmosphere-spring-2023/pages/syllabus/','6114377582d5d02d57abfd43ffdf53c1483b7e1acd60301b23e93ce7f6558d63','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Paul O''Gorman"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('12.820','12.820','Turbulence in the Ocean and Atmosphere','This course presents the phenomena, theory, and modeling of turbulence in the Earth’s oceans and atmosphere. The scope ranges from centimeter to planetary scale motions. The regimes of turbulence include homogeneous isotropic three dimensional turbulence, convection, quasi-geostrophic turbulence, shallow water turbulence, baroclinic turbulence, macroturbulence in the ocean and atmosphere.','Atmospheric Science Earth Science Engineering Fluid Mechanics Hydrodynamics Mechanical Engineering Ocean Engineering Oceanography Planetary Science Science','2007','https://ocw.mit.edu/courses/12-820-turbulence-in-the-ocean-and-atmosphere-spring-2007/','https://ocw.mit.edu/courses/12-820-turbulence-in-the-ocean-and-atmosphere-spring-2007/pages/syllabus/','ceaf67cbd5ba8654be918b6974d1ca64a2a2e633bdf3b91c39c77dede1a7a8d8','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Glenn Flierl","Prof. Raffaele Ferrari"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('12.S56','12.S56','GPS: Where Are You?','This is a freshman advising seminar . The professor of a FAS is the first year advisor to the (no more than 8) students in the seminar. The use of Global Positioning System (GPS) in a wide variety of applications has exploded in the last few years. In this seminar we explore how positions on the Earth were determined before GPS; how GPS itself works and the range of applications in which GPS is now a critical element. This seminar is followed by a UROP research project in the spring semester where results from precise GPS measurements will be analyzed and displayed on the Web.','Atmospheric Science Civil Engineering Earth Science Engineering Geography Geophysics Science Social Science Surveying','2008','https://ocw.mit.edu/courses/12-s56-gps-where-are-you-fall-2008/','https://ocw.mit.edu/courses/12-s56-gps-where-are-you-fall-2008/pages/syllabus/','02416607e0c6e4bc9bacc49d6a3659ad30cf1e2ef46726429aab319a965b5aaf','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Thomas Herring"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('14.04','14.04','Intermediate Microeconomic Theory ','This course provides an introduction to theory and data designed to meet the needs of students interested in economic science. It provides an introduction to consumer choice, the theory of the firm, and general equilibrium models, with an overview of the main results and tools used in studying these topics, both directly in economics and indirectly in various other fields.','Economics Microeconomics Social Science','2020','https://ocw.mit.edu/courses/14-04-intermediate-microeconomic-theory-fall-2020/','https://ocw.mit.edu/courses/14-04-intermediate-microeconomic-theory-fall-2020/pages/syllabus/','3b1ec9794cd10d65c517b5e08d8e53def0a11db6a6deb22c75733ae6f16acab4','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Robert M. Townsend"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('14.12','14.12','Economic Applications of Game Theory ','Game theory is the mathematical analysis of strategic interaction. It is used to analyze situations in which one person’s best decision depends on the decisions taken by others. Examples include traditional games such as chess and poker, but also collusion by cartels, political competition, voting, bargaining, auctions, and evolution. This course will introduce the fundamental tools of game theory and use these tools to analyze applications.','Economics Game Theory Social Science','2025','https://ocw.mit.edu/courses/14-12-economic-applications-of-game-theory-fall-2025/','https://ocw.mit.edu/courses/14-12-economic-applications-of-game-theory-fall-2025/pages/syllabus/','8d0752de48a4753bda16674bb5d93c7a8b365186aeaf32b8cebb500fc7f10fd4','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Ian Ball"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('14.129','14.129','Blockchain and the Design of Financial Systems','This course synthesizes the computer science technologies underlying cryptocurrency, blockchain, tokenization, platforms, and computational algorithms with the economics tools of contract theory, mechanism design, general equilibrium theory, and monetary theory. The goal is to understand the assumptions, existing shortcomings, and potential impact on legacy systems of distributed ledgers, smart contracts, and encryption and to explore possibilities for new financial designs and for regulation.','Economics Financial Economics Social Science','2025','https://ocw.mit.edu/courses/14-129-blockchain-and-the-design-of-financial-systems-spring-2025/','https://ocw.mit.edu/courses/14-129-blockchain-and-the-design-of-financial-systems-spring-2025/pages/syllabus/','9c2d3e73d1c9c15ee648d0d0dee4a7f9e9f4eb3c5aa643dae8148fc3acb19c37','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Robert M. Townsend"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('14.16','14.16','Strategy and Information','This is an advanced course in game theory. We begin with a rigorous overview of the main equilibrium concepts for non-­cooperative games in both static and dynamic settings with either complete or incomplete information. We define and explore properties of iterated strict dominance, rationalizability, Nash equilibrium, subgame perfection, sequential, perfect and proper equilibria, the intuitive criterion, and iterated weak dominance. We discuss applications to auctions, bargaining, and repeated games. Then we introduce solution concepts for cooperative games and study non-­cooperative implementations. Other topics include matching theory and networks.','Economics Game Theory Social Science','2016','https://ocw.mit.edu/courses/14-16-strategy-and-information-spring-2016/','https://ocw.mit.edu/courses/14-16-strategy-and-information-spring-2016/pages/syllabus/','397f36f4114d8798adee31eb79c9e491bad822a1f2f27275d87619e04fc4ef82','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Mihai Manea"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('14.30','14.30','Introduction to Statistical Methods in Economics','This course will provide a solid foundation in probability and statistics for economists and other social scientists. We will emphasize topics needed for further study of econometrics and provide basic preparation for 14.32 Econometrics . Topics include elements of probability theory, sampling theory, statistical estimation, and hypothesis testing.','Econometrics Economics Mathematics Probability and Statistics Social Science','2009','https://ocw.mit.edu/courses/14-30-introduction-to-statistical-methods-in-economics-spring-2009/','https://ocw.mit.edu/courses/14-30-introduction-to-statistical-methods-in-economics-spring-2009/pages/syllabus/','0b91597eabaf4ba4b3d996a7d620e29fbc1f1320436a9889af1960df1e4beff5','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Konrad Menzel"]','review_required','No prior preparation in probability in statistics is required, but familiarity with basic algebra and calculus (single and multi-variable) is assumed. Calculus at the level of 18.01 Single Variable Calculus and 18.02 Multivariable Calculus is sufficient.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('14.385','14.385','Nonlinear Econometric Analysis','This course presents micro-econometric models, including large sample theory for estimation and hypothesis testing, generalized method of moments (GMM), estimation of censored and truncated specifications, quantile regression, structural estimation, nonparametric and semiparametric estimation, treatment effects, panel data, bootstrapping, simulation methods, and Bayesian methods. The methods are illustrated with economic applications.','Econometrics Economics Mathematics Microeconomics Probability and Statistics Social Science','2007','https://ocw.mit.edu/courses/14-385-nonlinear-econometric-analysis-fall-2007/','https://ocw.mit.edu/courses/14-385-nonlinear-econometric-analysis-fall-2007/pages/syllabus/','7f1125db702ff0255c9726cce11f55026be9a18adf9d497bdb30b80705d5e3fb','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Victor Chernozhukov","Prof. Whitney Newey"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('14.451','14.451','Macroeconomic Theory I','Introduction to the theories of economic growth. Topics will include basic facts of economic growth and long-run economic development; brief overview of optimal control theory and dynamic programming; basic neoclassical growth model under a variety of market structures; human capital and economic growth; endogenous growth models; models with endogenous technology; models of directed technical change; competition, market structure and growth; financial and economic development; international trade and economic growth; institutions and economic development. This is a half-term subject. The class size is limited.','Economics Macroeconomics Social Science','2007','https://ocw.mit.edu/courses/14-451-macroeconomic-theory-i-spring-2007/','https://ocw.mit.edu/courses/14-451-macroeconomic-theory-i-spring-2007/pages/syllabus/','b0f916ef5ebb1d8003cc75cc0ae9cf006bd18fd82cb15ebc9723b930cefd463e','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. George-Marios Angeletos"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('14.462','14.462','Advanced Macroeconomics II','14.462 is the second semester of the second-year Ph.D. macroeconomics sequence. The course is intended to introduce the students, not only to particular areas of current research, but also to some very useful analytical tools. It covers a selection of topics that varies from year to year. Recent topics include: Growth and Fluctuations Heterogeneity and Incomplete Markets Optimal Fiscal Policy Time Inconsistency Reputation Coordination Games and Macroeconomic Complementarities Information','Economics Industrial Organization Macroeconomics Social Science','2004','https://ocw.mit.edu/courses/14-462-advanced-macroeconomics-ii-spring-2004/','https://ocw.mit.edu/courses/14-462-advanced-macroeconomics-ii-spring-2004/pages/syllabus/','fb742942f0370c9655940fbd1071716f5aba0f8cf11e38b92ec51c53dda788d6','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. George-Marios Angeletos","Prof. Gilles Saint-Paul"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('14.661','14.661','Labor Economics I','This course aims to acquaint students with traditional and contemporary topics in labor economics and to encourage the development of independent research interests. The class provides a systematic development of the theory of labor supply, labor demand, and human capital. Topics covered include wage and employment determination, immigration, unemployment, equalizing differences, among many others. There is a particular emphasis on the interaction between theoretical and empirical modeling.','Economics Labor Economics Social Science','2017','https://ocw.mit.edu/courses/14-661-labor-economics-i-fall-2017/','https://ocw.mit.edu/courses/14-661-labor-economics-i-fall-2017/pages/syllabus/','bad584b7adb55037ab25d96831e03bf208d6010a97ac2f26ceec3c6452637192','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Daron Acemoglu","Prof. Joshua Angrist"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('14.731','14.731','Economic History','This course offers a comprehensive survey of world economic history, designed to introduce economics graduate students to the subject matter and methodology of economic history. Topics are chosen to show a wide variety of historical experience and illuminate the process of industrialization. A final term paper is due at the end of the course.','Economics History Humanities Industrial Organization Social Science World History','2006','https://ocw.mit.edu/courses/14-731-economic-history-fall-2006/','https://ocw.mit.edu/courses/14-731-economic-history-fall-2006/pages/syllabus/','4c3a65daef3f494cd5213526416fd4b442abf5491d8bac691649668328a385dc','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Dora Costa","Prof. Peter Temin"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('14.772','14.772','Development Economics: Macroeconomics','This course emphasizes dynamic models of growth and development. Topics covered include: migration, modernization, and technological change; static and dynamic models of political economy; the dynamics of income distribution and institutional change; firm structure in developing countries; development, transparency, and functioning of financial markets; privatization; and banks and credit market institutions in emerging markets. At MIT, this course was team taught by Prof. Robert Townsend, who taught for the first half of the semester, and Prof. Abhijit Banerjee, who taught during the second half. On OCW we are only including materials associated with sessions one through 13, which comprise the first half of the class.','Developmental Economics Econometrics Economics Macroeconomics Microeconomics Social Science','2013','https://ocw.mit.edu/courses/14-772-development-economics-macroeconomics-spring-2013/','https://ocw.mit.edu/courses/14-772-development-economics-macroeconomics-spring-2013/pages/syllabus/','a1a29d529d787a52d3d19af68e4fe639819c61388a439580c0216cbaaffe6ecc','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Robert M. Townsend"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.020','15.020','Competition in Telecommunications','Competition in Telecommunications provides an introduction to the economics, business strategies, and technology of telecommunications markets. This includes markets for wireless communications, local and long-distance services, and customer equipment. The convergence of computers, cable TV and telecommunications and the competitive emergence of the Internet are covered in depth. A number of speakers from leading companies in the industry will give course lectures.','Business Economics Electrical Engineering Engineering Industrial Organization Information Technology Social Science Telecommunications','2003','https://ocw.mit.edu/courses/15-020-competition-in-telecommunications-fall-2003/','https://ocw.mit.edu/courses/15-020-competition-in-telecommunications-fall-2003/pages/syllabus/','4d71e5ca3a4eb18d201e1fed6ab0e5d146358bd8bbdeb626c5b7f59ea6de609a','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Jerry Hausman"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.053','15.053','Optimization Methods in Management Science','This course introduces students to the theory, algorithms, and applications of optimization. The optimization methodologies include linear programming, network optimization, integer programming, and decision trees. Applications to logistics, manufacturing, transportation, marketing, project management, and finance. Includes a team project in which students select and solve a problem in practice.','Applied Mathematics Business Engineering Game Theory Mathematics Operations Management Probability and Statistics Project Management Social Science Systems Engineering Systems Optimization','2013','https://ocw.mit.edu/courses/15-053-optimization-methods-in-management-science-spring-2013/','https://ocw.mit.edu/courses/15-053-optimization-methods-in-management-science-spring-2013/pages/syllabus/','2b0f13b532a8f70c1e26a423697eb28bdc3f65dd0893c7451e39d5bae017a861','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. James Orlin","Dr. Ebrahim Nasrabadi"]','no_formal_course','Prerequisites This subject has no formal prerequisites.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.060','15.060','Data, Models, and Decisions','This course is designed to introduce first-year Sloan MBA students to the fundamental techniques of using data. In particular, the course focuses on various ways of modeling, or thinking structurally about decision problems in order to make informed management decisions.','Business Computer Science Data Mining Engineering Management Mathematics Operations Management Probability and Statistics Supply Chain Management Systems Engineering Systems Optimization','2014','https://ocw.mit.edu/courses/15-060-data-models-and-decisions-fall-2014/','https://ocw.mit.edu/courses/15-060-data-models-and-decisions-fall-2014/pages/syllabus/','55e50aed5e6ee1f39f76ddf6a54829fec9c61fb53f13a9941bde476b1e8b971e','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Robert Freund","Prof. Cynthia Rudin","Juan Pablo Vielma Centeno"]','review_required','No explicit prerequisite section was found in the archived syllabus HTML. Instructor review is required; no absence of requirements is inferred.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.067','15.067','Competitive Decision-Making and Negotiation','This course aims to develop negotiation skills by active participation in a variety of negotiation settings, and a series of integrative bargaining cases between two and more than two parties over multiple issues. Ethical dilemmas in negotiation are discussed at various times throughout the course.','Business Business Ethics Management','2011','https://ocw.mit.edu/courses/15-067-competitive-decision-making-and-negotiation-spring-2011/','https://ocw.mit.edu/courses/15-067-competitive-decision-making-and-negotiation-spring-2011/pages/syllabus/','54b7b02a8c58b6e0e7ef8ad4055df7f38a8397c0209bd5f6377d619eea72ccbd','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Gordon Kaufman"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.071','15.071','The Analytics Edge','This course presents real-world examples in which quantitative methods provide a significant competitive edge that has led to a first order impact on some of today’s most important companies. We outline the competitive landscape and present the key quantitative methods that created the edge (data-mining, dynamic optimization, simulation), and discuss their impact.','Business Management Mathematics Operations Management Probability and Statistics','2017','https://ocw.mit.edu/courses/15-071-the-analytics-edge-spring-2017/','https://ocw.mit.edu/courses/15-071-the-analytics-edge-spring-2017/pages/syllabus/','ba46365ac506c78f39ca148816d70ce7b4b3623478f07fa2a088c00c867e56af','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Dimitris Bertsimas"]','structured','Prerequisites 15.060 Data, Models, and Decisions or a basic statistics and a basic optimization course.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('15.071',0,'15.060');
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.083J','15.083J','Integer Programming and Combinatorial Optimization','The course is a comprehensive introduction to the theory, algorithms and applications of integer optimization and is organized in four parts: formulations and relaxations, algebra and geometry of integer optimization, algorithms for integer optimization, and extensions of integer optimization.','Applied Mathematics Computation Engineering Mathematics Systems Engineering Systems Optimization','2009','https://ocw.mit.edu/courses/15-083j-integer-programming-and-combinatorial-optimization-fall-2009/','https://ocw.mit.edu/courses/15-083j-integer-programming-and-combinatorial-optimization-fall-2009/pages/syllabus/','a7b0136e537c85d508f4e3afe87cc861b2c688b57777e6a43e65e5fc8ade67b2','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Dimitris Bertsimas","Prof. Andreas Schulz"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.099','15.099','Readings in Optimization','In keeping with the tradition of the last twenty-some years, the Readings in Optimization seminar will focus on an advanced topic of interest to a portion of the MIT optimization community: randomized methods for deterministic optimization. In contrast to conventional optimization algorithms whose iterates are computed and analyzed deterministically, randomized methods rely on stochastic processes and random number/vector generation as part of the algorithm and/or its analysis. In the seminar, we will study some very recent papers on this topic, many by MIT faculty, as well as some older papers from the existing literature that are only now receiving attention.','Applied Mathematics Engineering Mathematics Systems Engineering Systems Optimization','2003','https://ocw.mit.edu/courses/15-099-readings-in-optimization-fall-2003/','https://ocw.mit.edu/courses/15-099-readings-in-optimization-fall-2003/pages/syllabus/','6274ea3951a9e0baa4db465a3e5bb1883f14eafc2fffdb46878fa9561c23ee30','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Robert Freund"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.225','15.225','Economy and Business in Modern China and India','As markets or production bases, China and India are becoming important and integral players in the global economy. Foreign direct investment (FDI), portfolio investments and outsourcing businesses have increased dramatically in these two economies. Despite the rising importance of these two economies on the world stage, our knowledge and analysis of these two countries in an integrated manner has remained poor. The two are often lumped together by business analysts as “emerging markets,” despite the substantial differences in their political systems, reform policies and business organizations. Academics, in contrast, have tended to treat the two countries separately, preferring to specialize in issues and questions specific to one or the other country. The purpose of this course is to analyze these two countries within a coherent analytical framework. Our learning model is inductive, and heavily based on class discussions and participation. The group projects should aim at integrating analysis, knowledge and understanding of these two countries. We will also experiment with other forms of group projects, such as creating and working on business plans and those projects that integrate research from field trips with more traditional research, such as library research. There is no prerequisite but 15.012 (Applied Macro- and International Economics) and 15.223 (Global Markets, National Policies and the Competitive Advantage of Firms) are highly recommended.','Asian Studies Business Economics Globalization International Economics Social Science Society','2008','https://ocw.mit.edu/courses/15-225-economy-and-business-in-modern-china-and-india-spring-2008/','https://ocw.mit.edu/courses/15-225-economy-and-business-in-modern-china-and-india-spring-2008/pages/syllabus/','a7d6aa9c6f8c05b45010103deef94010de4795b001c206d717243724f134877a','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Yasheng Huang"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.270','15.270','Ethical Practice: Leading Through Professionalism, Social Responsibility, and System Design','This course offers an introduction to ethics in business, with a focus on business management. Students explore theoretical concepts in business ethics, and cases representing the challenges they will likely face as managers. There is opportunity to work with guest faculty as well as business and other professional practitioners. Individual class sessions take the form of moderated discussion, with occasional short lectures from the instructor.','Business Business Ethics Management','2016','https://ocw.mit.edu/courses/15-270-ethical-practice-leading-through-professionalism-social-responsibility-and-system-design-spring-2016/','https://ocw.mit.edu/courses/15-270-ethical-practice-leading-through-professionalism-social-responsibility-and-system-design-spring-2016/pages/syllabus/','10c762db2148882c7157d67cbb39de0111f4c366ed466bc61a5303f956ebd58e','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Leigh Hafrey"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.301','15.301','Managerial Psychology','This course introduces you to behavioral science theories, methods, and tools and provides opportunities to use and apply them to problems you will encounter in your work and career. The course material will begin with an overview of work and organizations in modern industrial society, and then examine individual behavior, move to behavior in groups or teams, and finally discuss organizations as a whole. It is expected that at the end of the course you will: (a) know something about managerial psychology, (b) know how to learn more, (c) understand the behavioral research process, and (d) develop skills in presenting your ideas in oral and written reports.','Business Management Organizational Behavior Psychology Social Science','2006','https://ocw.mit.edu/courses/15-301-managerial-psychology-fall-2006/','https://ocw.mit.edu/courses/15-301-managerial-psychology-fall-2006/pages/syllabus/','05dfdc0890fb637ec2effc2cc55b4de31c697c65bc0ff6f6a95f2400d997feb3','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. John Carroll","Prof. Li Tao"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.322','15.322','Leading Organizations II','Through lectures, discussions, and class exercises, 15.322 analyzes the human processes underlying organizational behavior and change. The class makes students aware of the challenge of organizational change and equips them to better handle it. There are many psychological and sociological phenomena that regularly occur in organizations, though many of these forces are difficult to see. The aim is to increase the students’ understanding of these forces – in themselves and in others – so they become more visible and manageable. The prerequisite for this course is 15.321 Leading Organizations I .','Business Leadership Management Organizational Behavior Social Science Sociology','2003','https://ocw.mit.edu/courses/15-322-leading-organizations-ii-fall-2003/','https://ocw.mit.edu/courses/15-322-leading-organizations-ii-fall-2003/pages/syllabus/','1fb3c16b14b9ce418a5abeb721a728b3bcad7d4739b292c26c5ce7b7b87e4eb8','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. John Van Maanen"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.348','15.348','Doctoral Seminar in Research Methods II','A large proportion of contemporary research on organizations, strategy and management relies on quantitative research methods. This course is designed to provide an introduction to some of the most commonly used quantitative techniques, including logit/probit models, count models, event history models, and pooled cross-section techniques.','Mathematics Probability and Statistics Social Science','2004','https://ocw.mit.edu/courses/15-348-doctoral-seminar-in-research-methods-ii-spring-2004/','https://ocw.mit.edu/courses/15-348-doctoral-seminar-in-research-methods-ii-spring-2004/pages/syllabus/','fbabc0f12bb9e85cef693a5fe5b21d6ca823962b3de31e9fe97574fd6c87759b','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Jesper B. Sorensen"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.358','15.358','The Software Business','This subject is a seminar-style course aimed at anyone who is interested in founding a software company or working for a software company or company that uses software technology extensively as a senior manager, developer, or product/program manager. It is also appropriate for people interested in the industry or in working as an industry analyst. Many of the issues we discuss are highly relevant for companies whose businesses are heavily dependent on software, such as in e-business or financial services, or embedded software for industrial applications.','Business Computer Science Engineering Entrepreneurship Information Technology Management Software Design and Engineering','2005','https://ocw.mit.edu/courses/15-358-the-software-business-fall-2005/','https://ocw.mit.edu/courses/15-358-the-software-business-fall-2005/pages/syllabus/','a552d510bd88c6a2bdd5236f7f8d3c6631a79c7a583510718501fe32defbe50e','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Michael Cusumano"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.389B','15.389B','Global Entrepreneurship Lab: Latin America, the Middle East, and Africa','15.389B Global Entrepreneurship Lab: Latin America, the Middle East, and Africa enables teams of students to work with the top management of global start-ups and gain experience in running, and consulting to, a new enterprise outside the United States. The focus is on start-ups operating in emerging markets throughout the world, with a special focus on Latin America, the Middle East, and Africa. The course combines an internship in a growing firm with in-class discussions of the issues and policies that affect the climate for innovation and start-up success around the world. Special Features 15.389B is part of a two-section course and includes materials that cover entrepreneurship in Latin America, the Middle East, and Africa. 15.389A Global Entrepreneurship Lab: Asia-Pacific is also available on OpenCourseWare and covers topics pertinent to these additional regions.','Business Economics Entrepreneurship Globalization Industrial Organization Social Science','2010','https://ocw.mit.edu/courses/15-389b-global-entrepreneurship-lab-latin-america-the-middle-east-and-africa-fall-2010/','https://ocw.mit.edu/courses/15-389b-global-entrepreneurship-lab-latin-america-the-middle-east-and-africa-fall-2010/pages/syllabus/','eaf2ab9295e6408a3ea59d2bc5874cfba548bc558d5de18626c23c4f5c0136cd','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Simon Johnson","Prof. Yasheng Huang","Michellana Jester"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.390','15.390','New Enterprises','This course covers the process of identifying and quantifying market opportunities, then conceptualizing, planning, and starting a new, technology-based enterprise. Students develop detailed business plans for a startup. It is intended for students who want to start their own business, further develop an existing business, be a member of a management team in a new enterprise, or better understand the entrepreneur and the entrepreneurial process.','Business Entrepreneurship Leadership Management','2013','https://ocw.mit.edu/courses/15-390-new-enterprises-spring-2013/','https://ocw.mit.edu/courses/15-390-new-enterprises-spring-2013/pages/syllabus/','f53758a19c6a00dc654cc8bc8c75931a1c7a322730695425508c289010299494','https://creativecommons.org/licenses/by-nc-sa/4.0/','["William Aulet","Howard Anderson","Prof. Matt Marx"]','review_required','No explicit prerequisite section was found in the archived syllabus HTML. Instructor review is required; no absence of requirements is inferred.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.395','15.395','Entrepreneurship Without Borders','This course examines opportunities and problems for entrepreneurs globally, including Europe, Latin America, and Asia. Linkages between the business environment, the institutional framework, and new venture creation are covered with a special focus on blockchain technology. In addition to discussing a range of global entrepreneurial situations, student groups pick one particular cluster on which to focus and to understand what further development would entail. Classroom interactions are based primarily on case studies.','Business Economics Entrepreneurship Finance Social Science','2016','https://ocw.mit.edu/courses/15-395-entrepreneurship-without-borders-fall-2016/','https://ocw.mit.edu/courses/15-395-entrepreneurship-without-borders-fall-2016/pages/syllabus/','64152c8ef5283f6ccd754ae95abf3f3dd830d4e8b416c7f53bfb2e3d66a11500','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Michael Casey","Brian Forde","Prof. Simon Johnson"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.450','15.450','Analytics of Finance','This course covers the key quantitative methods of finance: financial econometrics and statistical inference for financial applications; dynamic optimization; Monte Carlo simulation; stochastic (Itô) calculus. These techniques, along with their computer implementation, are covered in depth. Application areas include portfolio management, risk management, derivatives, and proprietary trading.','Business Econometrics Economics Finance Financial Economics Mathematics Probability and Statistics Social Science','2010','https://ocw.mit.edu/courses/15-450-analytics-of-finance-fall-2010/','https://ocw.mit.edu/courses/15-450-analytics-of-finance-fall-2010/pages/syllabus/','0d1d2085e28f01931d0a62b08e743900c6e29456b47a59d7d1b13cd0e37dd92d','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Leonid Kogan"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.515','15.515','Financial Accounting','Our goal is to help you develop a framework for understanding financial, managerial, and tax reports. The course goal is divided into five subordinate challenges that can help you organize the way you learn accounting: The record keeping and reporting challenge The computation challenge The judgment challenge The usage challenge The search challenge The course adopts a decision-maker perspective of accounting by emphasizing the relation between accounting data and the underlying economic events generating them. Restricted to first-year Sloan MBA students. Acknowledgements Acknowledgment is hereby given to Professor G. Peter Wilson for his authorship of the following content in this course: The Five Challenges (see Syllabus and Lecture 1) “What Do Intel and Accountants Have in Common?” (see Lecture 1) A Conceptual Framework for Financial Accounting (see Lecture 1)','Accounting Business Finance Management','2003','https://ocw.mit.edu/courses/15-515-financial-accounting-fall-2003/','https://ocw.mit.edu/courses/15-515-financial-accounting-fall-2003/pages/syllabus/','3a11be10f5c7922ebcdcb6fec33e3c61d79ae4cd172e21378a437a40423daedf','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. George Plesko","Prof. Kin Lo","Prof. Richard Frankel"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.565J','15.565J','Integrating eSystems & Global Information Systems','The strategic importance of information technology is now widely accepted. It has also become increasingly clear that the identification of strategic applications alone does not result in success for an organization. A careful coordination of strategic applications, information technologies, and organizational structures must be made to attain success. This course addresses strategic, technological, and organizational connectivity issues to support effective and meaningful integration of information and systems. This course is especially relevant to those who wish to effectively exploit information technology and create new business processes and opportunities.','Business Computer Science Data Mining Electrical Engineering Engineering Information Technology Organizational Behavior Telecommunications','2002','https://ocw.mit.edu/courses/15-565j-integrating-esystems-global-information-systems-spring-2002/','https://ocw.mit.edu/courses/15-565j-integrating-esystems-global-information-systems-spring-2002/pages/syllabus/','cb67fab652e85604f9e9e9dd116af0f842bb5a72152622110e4d5b4c4156a259','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Stuart Madnick"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.598','15.598','IT and Business Transformation','The purpose of this Proseminar in Information Technology and Business Transformation (ITBT) is to provide students with a view of IT-enabled transformation and the strategic issues in the management of IT. The seminar will bring in CIOs, CEOs, and experienced consultants and industry observers to provide their perspectives and tell their stories about the use and management of IT today. Their talks will deal with the new technology, the new applications, the issues of implementation, the changes in industries and companies, and the strategic management of IT. In addition, there will be several case discussions of issues to be decided by senior management, with students taking on the position of executives and consultants. There will also be frameworks presented and used to position all material and speakers. Finally, one session will consist of ITBT alumni discussing career opportunities and issues for students, particularly from MIT, with these interests. Students will gain a perspective of the strategic role of and issues in managing IT as manifested in e-business applications, as a driver and enabler of business transformation, and as an underlying infrastructure resource for all businesses.','Business Information Technology Innovation Management Organizational Behavior','2003','https://ocw.mit.edu/courses/15-598-it-and-business-transformation-spring-2003/','https://ocw.mit.edu/courses/15-598-it-and-business-transformation-spring-2003/pages/syllabus/','a8f2311466d81aa4beb76f6842006a343e9aeeacfdc292f85c7a143248e177ac','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Cyrus Gibson"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.649','15.649','The Law of Mergers and Acquisitions','This course is designed to give students an introduction to the law-sensitive aspects of Mergers & Acquisitions (M&A). In Module I, we examine the legal implications of key roles and deal structures, and walk through some of the issues that would typically arise in a simple and friendly transaction. We also give a class to the legal issues arising in LBOs and the legal concerns of financial sponsors more generally, and another class to employment-related issues, including those relating to managers facing unsettled circumstances. In Module II, we look at a variety of complications, including those that arise in the friendly or unfriendly purchase of a publicly-held company; deals involving distressed and hi-tech companies; antitrust concerns; allegations of misconduct by management or board members; and deals involving non-U.S. companies.','Business Finance Industrial Relations and Human Resource Management Legal Studies Social Science','2003','https://ocw.mit.edu/courses/15-649-the-law-of-mergers-and-acquisitions-spring-2003/','https://ocw.mit.edu/courses/15-649-the-law-of-mergers-and-acquisitions-spring-2003/pages/syllabus/','4f240e0a848805b268722ec1975d5a60ca1f4b7546f8e6e1609ec58a18f496b5','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. John Akula"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.677J','15.677J','Urban Labor Markets and Employment Policy','This subject discusses the broader trends in the labor market, how urban labor markets function, public and private training policy, other labor market programs, the link between labor market policy and economic development, and the organization of work within firms.','Business Economics Industrial Organization Industrial Relations and Human Resource Management Labor Economics Social Science','2005','https://ocw.mit.edu/courses/15-677j-urban-labor-markets-and-employment-policy-spring-2005/','https://ocw.mit.edu/courses/15-677j-urban-labor-markets-and-employment-policy-spring-2005/pages/syllabus/','6616787e75ff82fe9e515f938866eaa754c7b664a5f2bf738250040a84e7b950','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Paul Osterman"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.764','15.764','The Theory of Operations Management','The doctoral seminar 15.764 focuses on theoretical work for studying operations planning and control problems. This term’s special topic, “Customer-Driven Operations,” considers how a number of companies have succeeded in focusing their operation systems on the customer. The class reviews the quantitative models and theoretical tools underlying some of the customer-driven operational practices of these cutting-edge companies. Students will read and present research papers on topics such as distribution systems, short life-cycle product management, and forecast evolution models. This MIT OpenCourseWare site is dedicated to the memory of Bhuwan Singh, a member of the class.','Business Operations Management Supply Chain Management','2004','https://ocw.mit.edu/courses/15-764-the-theory-of-operations-management-spring-2004/','https://ocw.mit.edu/courses/15-764-the-theory-of-operations-management-spring-2004/pages/syllabus/','e5d6a34034e80702e6d3f1051ef9a81a1969a46980554f0769752f1b78865130','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Jérémie Gallien"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.783J','15.783J','Product Design and Development','Product Design and Development is a project-based course that covers modern tools and methods for product design and development. The cornerstone is a project in which teams of management, engineering, and industrial design students conceive, design and prototype a physical product. Class sessions are conducted in workshop mode and employ cases and hands-on exercises to reinforce the key ideas. Topics include identifying customer needs, concept generation, product architecture, industrial design, and design-for-manufacturing.','Business Engineering Innovation Marketing Operations Management Systems Design Systems Engineering','2006','https://ocw.mit.edu/courses/15-783j-product-design-and-development-spring-2006/','https://ocw.mit.edu/courses/15-783j-product-design-and-development-spring-2006/pages/syllabus/','294c2c5c0720acdda2bb3db3647d5bb52e071be0e1deb3274f62080692160972','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Matthew Kressy","Prof. Steven Eppinger","Prof. Thomas Roemer","Prof. Warren Seering"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.818','15.818','Pricing','This course is designed to teach students how to price goods and services by providing a framework for understanding pricing strategies and tactics. Topics covered include economic value analysis, price elasticities, price customization, pricing complementary products, pricing in platform markets and anticipating competitive price responses.','Business Economics Industrial Organization Marketing Microeconomics Operations Management Social Science','2010','https://ocw.mit.edu/courses/15-818-pricing-spring-2010/','https://ocw.mit.edu/courses/15-818-pricing-spring-2010/pages/syllabus/','1085380ac3c7d54914e81f44c47fc95fa6a81fb13e3c4d220a663d57d7ab2c5d','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Catherine Tucker"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.871','15.871','Introduction to System Dynamics','Introduction to systems thinking and system dynamics modeling applied to strategy, organizational change, and policy design. Students use simulation models, management flight simulators, and case studies to develop conceptual and modeling skills for the design and management of high-performance organizations in a dynamic world.','Business Computational Modeling and Simulation Engineering Management Operations Management Organizational Behavior Systems Engineering Systems Optimization','2013','https://ocw.mit.edu/courses/15-871-introduction-to-system-dynamics-fall-2013/','https://ocw.mit.edu/courses/15-871-introduction-to-system-dynamics-fall-2013/pages/syllabus/','e5b52aee6e07fa86369a0029465b7949a8f04583dd365b0ae029d3a93bc8118e','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. John Sterman","Prof. Hazhir Rahmandad"]','review_required','Permission of instructor. No prior computer modeling experience is needed.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.904','15.904','Strategic Management II','This course is intended to be an extension of course 15.902 Strategic Management I, with the purpose of allowing the students to experience an in-depth application of the concepts and frameworks of strategic management. Throughout the course, Prof. Arnoldo Hax will discuss the appropriate methodologies, concepts, and tools pertinent to strategic analyses and will illustrate their use by discussing many applications in real-life settings, drawn from his own personal experiences.','Business Leadership Management','2005','https://ocw.mit.edu/courses/15-904-strategic-management-ii-fall-2005/','https://ocw.mit.edu/courses/15-904-strategic-management-ii-fall-2005/pages/syllabus/','e45540d7cd9345df2db4f44ec3c3fff08c11ecbd46682e3116566aee7cc34b4d','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Arnoldo Hax"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.965','15.965','Technology Strategy for System Design and Management','This course provides you with a framework to understand the structure and dynamics of high-tech businesses, together with an approach for their effective strategic management. It is focused on domains in which systems are important, because either or both products are parts of larger and more complex systems, or they are comprised of systems. The domains covered include computing, communications (in particular the mobile and IP domains), consumer electronics, industrial networking, automotive, aerospace and medical devices. The course will be of particular interest to those interested in managing a business in which technology will likely play a major role, and also to those interested in investing in or providing counsel to these businesses. The emphasis throughout is on the development and application of ways of thinking or mental models that bring clarity to the complex co-evolution of technological innovation, the demand opportunity, systems architecture, business ecosystems, and decision-making and execution within the business.','Business Leadership Management Marketing Operations Management','2009','https://ocw.mit.edu/courses/15-965-technology-strategy-for-system-design-and-management-spring-2009/','https://ocw.mit.edu/courses/15-965-technology-strategy-for-system-design-and-management-spring-2009/pages/syllabus/','a1a2b676b2e628e6201ceea936eb8cdc864b5871a5e0e893d69f75b22f7137c3','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Michael A. M. Davies"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.974','15.974','Practical Leadership','Practical Leadership is an interactive seminar where students receive repeated coaching and real-time feedback on their own leadership capabilities from their peers and the instructor. The course is structured around a set of readings. However, the key component is each student’s own self-assessment. These self-assessments are done by the students in the first week of the semester. The areas for improvement that the students identify are then targeted in the weekly role plays that are customized for each student in the class. The goal of the class is for each student to increase his or her own leadership abilities through an ongoing cycle of practice, feedback and reflection.','Business Communication Leadership Social Science','2004','https://ocw.mit.edu/courses/15-974-practical-leadership-fall-2004/','https://ocw.mit.edu/courses/15-974-practical-leadership-fall-2004/pages/syllabus/','d2fa94654fffeded8c40f1c3465d4a217b5a0cb4bf4ba45ebe5f36611f0001d2','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Pat Bentley"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.996','15.996','Cross-Cultural Leadership','Cross Cultural Leadership is a collaborative research seminar that examines what constitutes “effective” leadership across cultures. It is collaborative because the students are expected to provide some of the content. The weekly readings target particular aspects of cultural differentiation. Working within those topics, students are asked to describe aspects of leadership in particular cultures based on their research and/or personal experiences. The goal of the course is to help prepare students for business assignments outside of their native countries. Course deliverables include: active participation in the class, contribution of class content on a weekly basis and an end of course paper that explores some aspect of leadership across cultures.','Anthropology Business Cultural Anthropology Leadership Social Science','2004','https://ocw.mit.edu/courses/15-996-cross-cultural-leadership-fall-2004/','https://ocw.mit.edu/courses/15-996-cross-cultural-leadership-fall-2004/pages/syllabus/','1088e62a5bb4a3ea7f8f75f31093952419d9ab4b76f81846380bde13c9bbdf8e','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Pat Bentley"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('15.S50','15.S50','How to Win at Texas Hold''em Poker','Offered during MIT’s Independent Activites Period (IAP), this short course covers the poker concepts, math concepts, and general concepts needed to play the game of Texas Hold’em on a professional level. IAP is a special 4-week term in January that provides members of the MIT community including students, faculty, staff, and alums with an opportunity to organize, sponsor and participate in a wide variety of activities and topics that are often outside of the regular MIT curriculum. Faculty Advisor: Paul Mende','Mathematics Probability and Statistics','2016','https://ocw.mit.edu/courses/15-s50-how-to-win-at-texas-holdem-poker-january-iap-2016/','https://ocw.mit.edu/courses/15-s50-how-to-win-at-texas-holdem-poker-january-iap-2016/pages/syllabus/','e84ff1209356564719635cc6b78289300fdc0c7444e371df5e47922ef6563c36','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Will Ma"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('16.06','16.06','Principles of Automatic Control','This course introduces the design of feedback control systems as applied to a variety of air and spacecraft systems. Topics include the properties and advantages of feedback systems, time-domain and frequency-domain performance measures, stability and degree of stability, the Root locus method, Nyquist criterion, frequency-domain design, and state space methods.','Aerospace Engineering Engineering Guidance and Control Systems','2012','https://ocw.mit.edu/courses/16-06-principles-of-automatic-control-fall-2012/','https://ocw.mit.edu/courses/16-06-principles-of-automatic-control-fall-2012/pages/syllabus/','7e647274425dbda1f2eb1969c3414d960413d8f743214425ef35f18847e8499f','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Steven Hall"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('16.20','16.20','Structural Mechanics','Applies solid mechanics to analysis of high-technology structures. Structural design considerations. Review of three-dimensional elasticity theory; stress, strain, anisotropic materials, and heating effects. Two-dimensional plane stress and plane strain problems. Torsion theory for arbitrary sections. Bending of unsymmetrical section and mixed material beams. Bending, shear, and torsion of thin-wall shell beams. Buckling of columns and stability phenomena. Introduction to structural dynamics. Exercises in the design of general and aerospace structures.','Aerospace Engineering Engineering Mechanical Engineering Solid Mechanics Structural Mechanics','2002','https://ocw.mit.edu/courses/16-20-structural-mechanics-fall-2002/','https://ocw.mit.edu/courses/16-20-structural-mechanics-fall-2002/pages/syllabus/','a2e758f1a43be83cf3c04c5a78d0ed857ea35e66c47374f9e0b5ca944c17265f','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Paul A. Lagace"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('16.323','16.323','Principles of Optimal Control','This course studies basic optimization and the principles of optimal control. It considers deterministic and stochastic problems for both discrete and continuous systems. The course covers solution methods including numerical search algorithms, model predictive control, dynamic programming, variational calculus, and approaches based on Pontryagin’s maximum principle, and it includes many examples and applications of the theory.','Aerospace Engineering Engineering Guidance and Control Systems Systems Engineering Systems Optimization','2008','https://ocw.mit.edu/courses/16-323-principles-of-optimal-control-spring-2008/','https://ocw.mit.edu/courses/16-323-principles-of-optimal-control-spring-2008/pages/syllabus/','dd5fe74fba2e93c5068ee20435494e74b3791c049233fc22e38244ea75b68bf7','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Jonathan P. How"]','review_required','Course assumes a good working knowledge of linear algebra and differential equations. New material will be covered in depth in the class, but a strong background will be necessary. Solid background in control design is best to fully understand this material, but not essential. Course material and homework assume a good working knowledge of MATLAB.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('16.410','16.410','Principles of Autonomy and Decision Making','This course surveys a variety of reasoning, optimization and decision making methodologies for creating highly autonomous systems and decision support aids. The focus is on principles, algorithms, and their application, taken from the disciplines of artificial intelligence and operations research. Reasoning paradigms include logic and deduction, heuristic and constraint-based search, model-based reasoning, planning and execution, and machine learning. Optimization paradigms include linear programming, integer programming, and dynamic programming. Decision-making paradigms include decision theoretic planning, and Markov decision processes.','Algorithms and Data Structures Artificial Intelligence Cognitive Science Computer Science Engineering Game Theory Science Social Science Systems Engineering Systems Optimization','2010','https://ocw.mit.edu/courses/16-410-principles-of-autonomy-and-decision-making-fall-2010/','https://ocw.mit.edu/courses/16-410-principles-of-autonomy-and-decision-making-fall-2010/pages/syllabus/','81854eebe4af0b3cf4dc04d76a114d79362ba5919002452541b7e785b48ba703','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Brian Charles Williams","Prof. Emilio Frazzoli"]','structured','6.01 or 1.00 .') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('16.410',0,'6.01');
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('16.410',0,'1.00');
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('16.50','16.50','Introduction to Propulsion Systems','This course presents aerospace propulsive devices as systems, with functional requirements and engineering and environmental limitations along with requirements and limitations that constrain design choices. Both air-breathing and rocket engines are covered, at a level which enables rational integration of the propulsive system into an overall vehicle design. Mission analysis, fundamental performance relations, and exemplary design solutions are presented.','Aerospace Engineering Engineering Propulsion Systems','2012','https://ocw.mit.edu/courses/16-50-introduction-to-propulsion-systems-spring-2012/','https://ocw.mit.edu/courses/16-50-introduction-to-propulsion-systems-spring-2012/pages/syllabus/','9a2604d7f4ff2cb60fee89121de135d73c08f53606b72723697f2bb707736bef','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Manuel Martinez-Sanchez"]','structured','16.50 Introduction to Propulsion Systems has 16.004 Unified Engineering IV or 2.005 Thermal-Fluids Engineering I as a prerequisite.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('16.50',0,'16.004');
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('16.50',0,'2.005');
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('16.621','16.621','Experimental Projects I','The Experimental Project Lab in the Department of Aeronautics and Astronautics is a two-semester course sequence: 16.621 Experimental Projects I (this course) and 16.622 Experimental Projects II . This site offers material on 16.621. In the course, two-person teams initiate a project of their own conception and design in 16.621 and then complete it in 16.622. For many students, this is a first encounter with research standards and techniques. It is a complicated course that requires a lot of interaction and support and also access to facilities and materials, but it is rewarding for students to explore an hypothesis under the guidance of a faculty advisor. This OCW site presents the building block materials of the course, which can provide only a profile of the course because the most important learning elements are the interactions between student team, faculty, project advisor, and shop staff and also between student team members. However, this site offers some of the preparation and guidance materials for students embarking on an experimental project. To emphasize the focus on communication skills, a set of study materials and examples of student work are provided.','Aerospace Engineering Computer Science Data Mining Engineering Science Systems Design Systems Engineering','2003','https://ocw.mit.edu/courses/16-621-experimental-projects-i-spring-2003/','https://ocw.mit.edu/courses/16-621-experimental-projects-i-spring-2003/pages/syllabus/','056006ccdd7f567d8eea4ada919602b4332d0fd62a6489c7ecb93ec07b36a3e8','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Earll Murman","Prof. Edward Greitzer","Prof. Jennifer L. Craig","Prof. John Deyst"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('16.687','16.687','Private Pilot Ground School','This is a three-day workshop that took place during the MIT Independent Activities Period (IAP) in January, 2019. This workshop aims to provide information for students to prepare for the FAA Private Pilot Knowledge Test. Topics include airplane aerodynamics, aircraft systems, navigation, meteorology, aircraft ownership and maintenance, aircraft performance, multi-engine and jets.','Aerospace Engineering Engineering','2019','https://ocw.mit.edu/courses/16-687-private-pilot-ground-school-january-iap-2019/','https://ocw.mit.edu/courses/16-687-private-pilot-ground-school-january-iap-2019/pages/syllabus/','c59aba940c3f744b9926be85bf6fb09d667c8a29087a9f9fab93e046a794fb73','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Philip Greenspun","Dr. Tina Srivastava"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('16.83X','16.83X','Space Systems Engineering','Space Systems Engineering (16.83X) is the astronautical capstone course option in the Department of Aeronautics and Astronautics. Between Spring 2002 and Spring 2003, the course was offered in a 3-semester format, using a Conceive, Design, Implement and Operate (C-D-I-O) teaching model. 16.83X is shorthand for the three course numbers: 16.83, 16.831, and 16.832. The first semester (16.83) is the Conceive-Design phase of the project, which results in a detailed system design, but precedes assembly. The second semester (16.831) is the Implement phase, and involves building the students’ system. The final semester (16.832) is the Operate phase, in which the system is tested and readied to perform in its intended environment. This year’s project objective was to demonstrate the feasibility of an electromagnetically controlled array of formation flying satellites. The project, “EMFFORCE”, was an extension of the first C-D-I-O course project, “SPHERES”, which ran from Spring 1999 through Spring 2000, and demonstrated satellite formation flying using gas thrusters for station-keeping. The whole class works on the same project, but divides into smaller subsystem teams, such as power, metrology, and structures, to handle design details.','Aerospace Engineering Astrodynamics Business Engineering Guidance and Control Systems Project Management','2002','https://ocw.mit.edu/courses/16-83x-space-systems-engineering-spring-2002-spring-2003/','https://ocw.mit.edu/courses/16-83x-space-systems-engineering-spring-2002-spring-2003/pages/syllabus/','21a190118d8dc7b456ec1787535e4acda00e17717eb388a3f9a4b51aa6bbab52','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. David Miller","Col. John Keesee"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('16.885J','16.885J','Aircraft Systems Engineering','Aircraft are complex products comprised of many subsystems which must meet demanding customer and operational lifecycle value requirements. This course adopts a holistic view of the aircraft as a system, covering: basic systems engineering; cost and weight estimation; basic aircraft performance; safety and reliability; lifecycle topics; aircraft subsystems; risk analysis and management; and system realization. Small student teams “retrospectively analyze” an existing aircraft covering: key design drivers and decisions; aircraft attributes and subsystems; and operational experience. Finally, the student teams deliver oral and written versions of the case study.','Aerospace Engineering Business Engineering Project Management Systems Engineering','2004','https://ocw.mit.edu/courses/16-885j-aircraft-systems-engineering-fall-2004/','https://ocw.mit.edu/courses/16-885j-aircraft-systems-engineering-fall-2004/pages/syllabus/','48d36f0bcde8a046fcbb33eac7deccc56ecc3fa3f4059a02e8f7bc47ce18da2e','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Earll Murman","Prof. John Hansman","Prof. Robert Liebeck","Allen Haggerty"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('16.920J','16.920J','Numerical Methods for Partial Differential Equations (SMA 5212)','A presentation of the fundamentals of modern numerical techniques for a wide range of linear and nonlinear elliptic, parabolic and hyperbolic partial differential equations and integral equations central to a wide variety of applications in science, engineering, and other fields. Topics include: Mathematical Formulations; Finite Difference and Finite Volume Discretizations; Finite Element Discretizations; Boundary Element Discretizations; Direct and Iterative Solution Methods. This course was also taught as part of the Singapore-MIT Alliance (SMA) programme as course number SMA 5212 (Numerical Methods for Partial Differential Equations).','Applied Mathematics Differential Equations Mathematics','2003','https://ocw.mit.edu/courses/16-920j-numerical-methods-for-partial-differential-equations-sma-5212-spring-2003/','https://ocw.mit.edu/courses/16-920j-numerical-methods-for-partial-differential-equations-sma-5212-spring-2003/pages/syllabus/','78e414fd79c13c3b2b02312e6d4619619d9c9628f47c3b5039a5b2e10ecb40a4','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Boo Cheong Khoo","Prof. Jacob White","Prof. Jaime Peraire","Prof. Anthony T. Patera"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('17.196','17.196','Globalization','This seminar explores changes in the international economy and their effects on domestic politics, economy, and society. Is globalization really a new phenomenon? Is it irreversible? What are effects on wages and inequality, on social safety nets, on production, and innovation? How does it affect relations between developed countries and developing countries? How globalization affects democracy? These are some of the key issues that will be examined.','Business Economics Globalization International Economics Political Economy Social Justice Social Science Sociology','2005','https://ocw.mit.edu/courses/17-196-globalization-fall-2005/','https://ocw.mit.edu/courses/17-196-globalization-fall-2005/pages/syllabus/','74907c5326b647110d5427096c6889657595c242e717e9451009fe128903d280','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Suzanne Berger"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('17.202','17.202','Graduate Seminar in American Politics II','This is the second in a sequence of two field seminars in American politics intended for graduate students in political science, in preparation for taking the general examination in American politics. The material covered in this semester focuses on American political institutions. The readings covered here are not comprehensive, but it is sufficiently broad to give students an introduction to major empirical questions and theoretical approaches that guide the study of American political institutions these days.','American Politics Political Science Social Science','2010','https://ocw.mit.edu/courses/17-202-graduate-seminar-in-american-politics-ii-spring-2010/','https://ocw.mit.edu/courses/17-202-graduate-seminar-in-american-politics-ii-spring-2010/pages/syllabus/','8bc8cb68477a7f2e38b9f82a7c9d342f82ee162403eae96e72a59b68e497e8c2','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Charles Stewart"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('17.269','17.269','Race, Ethnicity, and American Politics','This course explores the role of race and ethnicity in modern American politics. It focuses on social science approaches to measuring the effects of race, both at the individual level and more broadly. Topics include race and representation, measurement of racial and ethnic identities, voting rights and electoral districting, protest and other forms of political participation, and the meaning and measurement of racial attitudes.','African American Studies American Politics Political Science Social Science Society','2017','https://ocw.mit.edu/courses/17-269-race-ethnicity-and-american-politics-spring-2017/','https://ocw.mit.edu/courses/17-269-race-ethnicity-and-american-politics-spring-2017/pages/syllabus/','33f9866b5088e105319a1b9a8868861cc778037367b5d362d8829039d630ced2','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Ariel White"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('17.408','17.408','Chinese Foreign Policy','This course explores the leading theoretical and methodological approaches to studying China’s interaction with the international system since 1949. Readings include books and articles that integrate the study of China’s foreign policy with the field of international relations.','International Relations Political Science Social Science','2013','https://ocw.mit.edu/courses/17-408-chinese-foreign-policy-fall-2013/','https://ocw.mit.edu/courses/17-408-chinese-foreign-policy-fall-2013/pages/syllabus/','14aec4d58d33c6021703aacad0edc07d610d09259b1bcc2557d89581a32a5d6c','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. M. Taylor Fravel"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('17.433','17.433','International Relations of East Asia','The aim of this course is to introduce and analyze the international relations of East Asia. With four great powers, three nuclear weapons states, and two of the world’s largest economies, East Asia is one of the most dynamic and consequential regions in world politics. This course will examine the sources of conflict and cooperation in both periods, assessing competing explanations for key events in East Asia’s international relations. Readings will be drawn from international relations theory, political science and history.','Asian History Asian Studies History Humanities International Relations Political Science Social Science Society','2011','https://ocw.mit.edu/courses/17-433-international-relations-of-east-asia-spring-2011/','https://ocw.mit.edu/courses/17-433-international-relations-of-east-asia-spring-2011/pages/syllabus/','f101e15ab62c1f7b1dc099dc7dcce572b4ee316e5da3d090b62c67a7266f35fa','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. M. Taylor Fravel"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('17.46','17.46','U.S. National Security Policy','This course provides a comprehensive introduction to the making of US foreign and national security policy. It examines the laws that guide policy-making, studies the actors and organizations involved in the inter-agency process, and explores how interaction between the executive, legislative, and judicial branches shapes policy development and implementation. Students acquire practical experience through policy writing and a crisis simulation. This course is designed for students interested in international relations, security, and public policy.','International Relations Political Science Public Administration Security Studies Social Science','2023','https://ocw.mit.edu/courses/17-46-u-s-national-security-policy-fall-2023/','https://ocw.mit.edu/courses/17-46-u-s-national-security-policy-fall-2023/pages/syllabus/','b57cb49e88bfef23467f5b709850418a867c69e361f72c1fed8af8d051a69a83','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Erik Lin-Greenberg"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('17.486','17.486','Japan and East Asian Security','This course explores Japan’s role in world orders, past, present, and future. It focuses on Japanese conceptions of security; rearmament debates; the relationship of domestic politics to foreign policy; the impact of Japanese technological and economic transformation at home and abroad; alternative trade and security regimes; Japan’s response to 9/11; and relations with Asian neighbors, Russia, and the alliance with the United States.','Asian Studies Economics International Relations Military Studies Political Economy Political Science Public Administration Security Studies Social Science Society','2016','https://ocw.mit.edu/courses/17-486-japan-and-east-asian-security-fall-2016/','https://ocw.mit.edu/courses/17-486-japan-and-east-asian-security-fall-2016/pages/syllabus/','5563db3fa6902474aad70e50368f40953a1bb8d5b271c4edafd5873959871de9','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Richard J. Samuels"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('17.522','17.522','Politics and Religion','This graduate reading seminar explores the role of religious groups, institutions, and ideas in politics using social science theories. It is open to advanced undergraduate students with permission of the instructor.','Anthropology Humanities Political Science Religion Social Anthropology Social Science Sociology','2006','https://ocw.mit.edu/courses/17-522-politics-and-religion-fall-2006/','https://ocw.mit.edu/courses/17-522-politics-and-religion-fall-2006/pages/syllabus/','4f83f9dc947b737873b3b43ffc4cb3d7f2b39a7c8ad093a48688db3d30438886','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Lily Tsai"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('17.55J','17.55J','Introduction to Latin American Studies','Interdisciplinary introduction to contemporary Latin America, drawing on films, literature, popular press accounts, and scholarly research. Topics include economic development, ethnic and racial identity, religion, revolution, democracy, transitional justice, and the rule of law. Examples draw on a range of countries in the region, especially Mexico, Chile, and Brazil. Includes a heavy oral participation component, with regular breakout groups, formal class presentations on pressing social issues (such as criminal justice and land tenure), and a structured class debate.','Anthropology Cultural Anthropology Latin and Caribbean Studies Political Science Social Science Society The Developing World','2006','https://ocw.mit.edu/courses/17-55j-introduction-to-latin-american-studies-fall-2006/','https://ocw.mit.edu/courses/17-55j-introduction-to-latin-american-studies-fall-2006/pages/syllabus/','5c6a0f9fcf13d7264a48bd93e02ae27258242c4bb2784c35e64af6f8546a4a51','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Chappell Lawson"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('17.584','17.584','Civil-Military Relations','This course centers on mechanisms of civilian control of the military. Relying on the influential texts of Lasswell, Huntington, and Finer, the first classes clarify the basic tensions between the military and civilians. A wide-ranging series of case studies follows. These cases are chosen to create a field of variation that includes states with stable civilian rule, states with stable military influence, and states exhibiting fluctuations between military and civilian control. The final three weeks of the course are devoted to the broader relationship between military and society.','Comparative Politics Humanities Military Studies Philosophy Political Philosophy Political Science Public Administration Security Studies Social Science','2003','https://ocw.mit.edu/courses/17-584-civil-military-relations-spring-2003/','https://ocw.mit.edu/courses/17-584-civil-military-relations-spring-2003/pages/syllabus/','0b19348f9ce7220a4ea80dc9b8b070f4799933a79f903c8a8981c5dc7d688f3b','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Roger Petersen"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('17.871','17.871','Political Science Laboratory','This course introduces students to the conduct of political research using quantitative methodologies. The methods are examined in the context of specific political research activities like public opinion surveys, voting behavior, Congressional behavior, comparisons of political processes in different countries, and the evaluation of public policies. Students participate in joint class projects and conduct individual projects.','Mathematics Political Science Probability and Statistics Social Science','2012','https://ocw.mit.edu/courses/17-871-political-science-laboratory-spring-2012/','https://ocw.mit.edu/courses/17-871-political-science-laboratory-spring-2012/pages/syllabus/','d2ca203ab657ea1040a95632bca23162a0c55dba43df56873b83d92f687adf89','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Charles Stewart"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('17.951','17.951','Nuclear Weapons in International Politics: Past, Present and Future','This course will expose students to tools and methods of analysis for use in assessing the challenges and dangers associated with nuclear weapons in international politics. The first two weeks of the course will look at the technology and design of nuclear weapons and their means of production. The next five weeks will look at the role they played in the Cold War, the organizations that managed them, the technologies that were developed to deliver them, and the methods used to analyze nuclear force structures and model nuclear exchanges. The last six weeks of the course will look at theories and cases of nuclear decision making beyond the original five weapon states, and will look particularly at why states pursue or forego nuclear weapons, the role that individuals and institutions play, and the potential for both new sources of proliferation and new consequences.','History Humanities International Relations Military History Military Studies Political Science Public Administration Security Studies Social Science','2009','https://ocw.mit.edu/courses/17-951-nuclear-weapons-in-international-politics-past-present-and-future-spring-2009/','https://ocw.mit.edu/courses/17-951-nuclear-weapons-in-international-politics-past-present-and-future-spring-2009/pages/syllabus/','bda87eb707938b31f8cd31ee1013065147d8f1b4e828c6d60fa6876fc80a9a82','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Owen Cote","Dr. James Walsh"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('17.S950','17.S950','Emotions and Politics','This course is premised on the belief that emotions are a fundamental part of human nature. Accordingly, understanding emotions and incorporating emotions into our research can help us better explain variation in important political phenomena. Research on emotions and how emotions can influence decision-making has dramatically increased over the past two decades. This class aims to pick up on new findings from psychology and other disciplines and marshal this knowledge toward the most important issues of political science.','Political Science Psychology Social Science','2018','https://ocw.mit.edu/courses/17-s950-emotions-and-politics-fall-2018/','https://ocw.mit.edu/courses/17-s950-emotions-and-politics-fall-2018/pages/syllabus/','790796bbd371f7282fd5541dd68b40094b4552eb5f3f1f9228d43dd21431a1b5','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Roger Petersen"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.01','18.01SC','Single Variable Calculus','This calculus course covers differentiation and integration of functions of one variable, and concludes with a brief discussion of infinite series. Calculus is fundamental to many scientific disciplines including physics, engineering, and economics. Course Format This course has been designed for independent study. It includes all of the materials you will need to understand the concepts covered in this subject. The materials in this course include: Lecture Videos with supporting written notes Recitation Videos of problem-solving tips Worked Examples with detailed solutions to sample problems Problem sets with solutions Exams with solutions Interactive Java Applets (“Mathlets”) to reinforce key concepts Content Development David Jerison Arthur Mattuck Haynes Miller Benjamin Brubaker Jeremy Orloff Heidi Burgiel Christine Breiner David Jordan Joel Lewis About OCW Scholar OCW Scholar courses are designed specifically for OCW’s single largest audience: independent learners. These courses are substantially more complete than typical OCW courses, and include new custom-created content as well as materials repurposed from previously published courses.','Calculus Differential Equations Mathematics','2010','https://ocw.mit.edu/courses/18-01sc-single-variable-calculus-fall-2010/','https://ocw.mit.edu/courses/18-01sc-single-variable-calculus-fall-2010/pages/syllabus/','cda8c96e6589d96e84a4f04dc49a7a1da66354628908adab0b29e2864ce03e6b','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. David Jerison"]','no_formal_course','Prerequisites Single Variable Calculus is a first-year, first-semester course at MIT. The prerequisites are high school algebra and trigonometry. Prior experience with calculus is helpful but not essential.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.013A','18.013A','Calculus with Applications','This is an undergraduate course on differential calculus in one and several dimensions. It is intended as a one and a half term course in calculus for students who have studied calculus in high school. The format allows it to be entirely self contained, so that it is possible to follow it without any background in calculus.','Applied Mathematics Calculus Differential Equations Mathematics','2005','https://ocw.mit.edu/courses/18-013a-calculus-with-applications-spring-2005/','https://ocw.mit.edu/courses/18-013a-calculus-with-applications-spring-2005/pages/syllabus/','1705ddfcaced89c922be4d5b2c1e0a9067d90ce74b92f4554f48bc1f02b3101d','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Daniel Kleitman"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.02','18.02SC','Multivariable Calculus','This course covers differential, integral and vector calculus for functions of more than one variable. These mathematical tools and methods are used extensively in the physical sciences, engineering, economics and computer graphics. The materials have been organized to support independent study. The website includes all of the materials you will need to understand the concepts covered in this subject. The materials in this course include: Lecture Videos recorded on the MIT campus Recitation Videos with problem-solving tips Examples of solutions to sample problems Problems for you to solve, with solutions Exams with solutions Interactive Java Applets (“Mathlets”) to reinforce key concepts Content Development Denis Auroux Arthur Mattuck Jeremy Orloff John Lewis Heidi Burgiel Christine Breiner David Jordan Joel Lewis','Calculus Differential Equations Linear Algebra Mathematics','2010','https://ocw.mit.edu/courses/18-02sc-multivariable-calculus-fall-2010/','https://ocw.mit.edu/courses/18-02sc-multivariable-calculus-fall-2010/pages/syllabus/','599a73ced6295581781114521c0f8897a1adee76dcc8c8f1dc22a0f4b2a975e2','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Denis Auroux"]','structured','Prerequisites The prerequisite to this course is 18.01 Single Variable Calculus .') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('18.02',0,'18.01');
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.024','18.024','Multivariable Calculus with Theory','This course is a continuation of 18.014 Calculus with Theory . It covers the same material as 18.02 Multivariable Calculus , but at a deeper level, emphasizing careful reasoning and understanding of proofs. There is considerable emphasis on linear algebra and vector integral calculus.','Calculus Differential Equations Linear Algebra Mathematics','2011','https://ocw.mit.edu/courses/18-024-multivariable-calculus-with-theory-spring-2011/','https://ocw.mit.edu/courses/18-024-multivariable-calculus-with-theory-spring-2011/pages/syllabus/','591d6067350bac2f161ff6cb3bfb7afc402c9467d6372e075e82a4df8dff7e26','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Christine Breiner"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.03','18.03SC','Differential Equations','The laws of nature are expressed as differential equations. Scientists and engineers must know how to model the world in terms of differential equations, and how to solve those equations and interpret the solutions. This course focuses on the equations and techniques most useful in science and engineering. Course Format This course has been designed for independent study. It provides everything you will need to understand the concepts covered in the course. The materials include: Lecture Videos by Professor Arthur Mattuck. Course Notes on every topic. Practice Problems with Solutions . Problem Solving Videos taught by experienced MIT Recitation Instructors. Problem Sets to do on your own with Solutions to check your answers against when you’re done. A selection of Interactive Java® Demonstrations called Mathlets to illustrate key concepts. A full set of Exams with Solutions , including practice exams to help you prepare. Content Development Haynes Miller Jeremy Orloff Dr. John Lewis Arthur Mattuck','Differential Equations Linear Algebra Mathematics','2011','https://ocw.mit.edu/courses/18-03sc-differential-equations-fall-2011/','https://ocw.mit.edu/courses/18-03sc-differential-equations-fall-2011/pages/syllabus/','83cf4d5899c9715bd76e0bd2e9d544fb5535e673a532e96ad7edba8c809d8c70','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Arthur Mattuck","Prof. Haynes Miller","Dr. Jeremy Orloff","Dr. John Lewis"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.05','18.05','Introduction to Probability and Statistics','This course provides an elementary introduction to probability and statistics with applications. Topics include basic combinatorics, random variables, probability distributions, Bayesian inference, hypothesis testing, confidence intervals, and linear regression. These same course materials, including interactive components (online reading questions and problem checkers) are available on MIT’s Open Learning Library , which is free to use. You have the option to enroll and track your progress, or you can view and use the materials without enrolling.','Discrete Mathematics Mathematics Probability and Statistics','2022','https://ocw.mit.edu/courses/18-05-introduction-to-probability-and-statistics-spring-2022/','https://ocw.mit.edu/courses/18-05-introduction-to-probability-and-statistics-spring-2022/pages/syllabus/','e7e0d22c95cf9b33d139baad58f621286962c24e7ac5f083ca171898046bd665','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Jeremy Orloff","Dr. Jennifer French Kamrin"]','structured','Prerequisites 18.02 Multivariable Calculus') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('18.05',0,'18.02');
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.06','18.06SC','Linear Algebra','This course covers matrix theory and linear algebra, emphasizing topics useful in other disciplines such as physics, economics and social sciences, natural sciences, and engineering. It parallels the combination of theory and applications in Professor Strang’s textbook Introduction to Linear Algebra . Course Format This course has been designed for independent study. It provides everything you will need to understand the concepts covered in the course. The materials include: A complete set of Lecture Videos by Professor Gilbert Strang. Summary Notes for all videos along with suggested readings in Prof. Strang’s textbook Linear Algebra . Problem Solving Videos on every topic taught by an experienced MIT Recitation Instructor. Problem Sets to do on your own with Solutions to check your answers against when you’re done. A selection of Java® Demonstrations to illustrate key concepts. A full set of Exams with Solutions , including review material to help you prepare.','Linear Algebra Mathematics','2011','https://ocw.mit.edu/courses/18-06sc-linear-algebra-fall-2011/','https://ocw.mit.edu/courses/18-06sc-linear-algebra-fall-2011/pages/syllabus/','a0dd3d39f62f72d66bcc010663ea4d6497af804443fa3de39b94d5437fac92c4','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Gilbert Strang"]','structured','Prerequisites 18.02 Multivariable Calculus is a formal prerequisite for MIT students wishing to enroll in 18.06 Linear Algebra, but knowledge of calculus is not required to learn the subject. To succeed in this course you will need to be comfortable with vectors, matrices, and three-dimensional coordinate systems. This material is presented in the first few lectures of 18.02 Multivariable Calculus, and again here. The basic operations of linear algebra are those you learned in grade school – addition and multiplication to produce “linear combinations.” But with vectors, we move into four-dimensional space and n-dimensional space!') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('18.06',0,'18.02');
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.065','18.065','Matrix Methods in Data Analysis, Signal Processing, and Machine Learning','Linear algebra concepts are key for understanding and creating machine learning algorithms, especially as applied to deep learning and neural networks. This course reviews linear algebra with applications to probability and statistics and optimization–and above all a full explanation of deep learning.','Applied Mathematics Computation Electrical Engineering Engineering Linear Algebra Mathematics Signal Processing','2018','https://ocw.mit.edu/courses/18-065-matrix-methods-in-data-analysis-signal-processing-and-machine-learning-spring-2018/','https://ocw.mit.edu/courses/18-065-matrix-methods-in-data-analysis-signal-processing-and-machine-learning-spring-2018/pages/syllabus/','0aff7f1db2d89cef3afc6614c36e521ba1f23545c74f63cd30162965196639cb','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Gilbert Strang"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.086','18.086','Mathematical Methods for Engineers II','This graduate-level course is a continuation of Mathematical Methods for Engineers I (18.085). Topics include numerical methods; initial-value problems; network flows; and optimization.','Applied Mathematics Computational Science and Engineering Differential Equations Engineering Linear Algebra Mathematics Systems Engineering','2006','https://ocw.mit.edu/courses/18-086-mathematical-methods-for-engineers-ii-spring-2006/','https://ocw.mit.edu/courses/18-086-mathematical-methods-for-engineers-ii-spring-2006/pages/syllabus/','ba9605d540b8cfa85dcc21a3911e2ced024f321fe8984f9a80a949fe846b1702','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Gilbert Strang"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.100C','18.100C','Real Analysis','This course covers the fundamentals of mathematical analysis: convergence of sequences and series, continuity, differentiability, Riemann integral, sequences and series of functions, uniformity, and the interchange of limit operations. It shows the utility of abstract concepts and teaches an understanding and construction of proofs. MIT students may choose to take one of three versions of Real Analysis; this version offers three additional units of credit for instruction and practice in written and oral presentation. The three options for 18.100: Option A (18.100A) chooses less abstract definitions and proofs, and gives applications where possible. Option B (18.100B) is more demanding and for students with more mathematical maturity; it places more emphasis from the beginning on point-set topology and n-space, whereas Option A is concerned primarily with analysis on the real line, saving for the last weeks work in 2-space (the plane) and its point-set topology. Option C (18.100C) is a 15-unit variant of Option B, with further instruction and practice in written and oral communication. This fulfills the MIT CI requirement.','Calculus Mathematical Analysis Mathematics','2012','https://ocw.mit.edu/courses/18-100c-real-analysis-fall-2012/','https://ocw.mit.edu/courses/18-100c-real-analysis-fall-2012/pages/syllabus/','5dca3b0d92ee1834e3da52480458cf462d0beab3e481008265f399f46a5aba84','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Paul Seidel"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.112','18.112','Functions of a Complex Variable','This is an advanced undergraduate course dealing with calculus in one complex variable with geometric emphasis. Since the course Analysis I (18.100B) is a prerequisite, topological notions like compactness, connectedness, and related properties of continuous functions are taken for granted. This course offers biweekly problem sets with solutions, two term tests and a final exam, all with solutions.','Calculus Mathematical Analysis Mathematics Topology and Geometry','2008','https://ocw.mit.edu/courses/18-112-functions-of-a-complex-variable-fall-2008/','https://ocw.mit.edu/courses/18-112-functions-of-a-complex-variable-fall-2008/pages/syllabus/','3682572dae0a31739ab3916a8358e09b1ac476656418f40c68bf1e7094b4f80c','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Sigurdur Helgason"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.156','18.156','Differential Analysis II: Partial Differential Equations and Fourier Analysis','In this course, we study elliptic Partial Differential Equations (PDEs) with variable coefficients building up to the minimal surface equation. Then we study Fourier and harmonic analysis, emphasizing applications of Fourier analysis. We will see some applications in combinatorics / number theory, like the Gauss circle problem, but mostly focus on applications in PDE, like the Calderon-Zygmund inequality for the Laplacian, and the Strichartz inequality for the Schrodinger equation. In the last part of the course, we study solutions to the linear and the non-linear Schrodinger equation. All through the course, we work on the craft of proving estimates.','Differential Equations Mathematical Analysis Mathematics','2016','https://ocw.mit.edu/courses/18-156-differential-analysis-ii-partial-differential-equations-and-fourier-analysis-spring-2016/','https://ocw.mit.edu/courses/18-156-differential-analysis-ii-partial-differential-equations-and-fourier-analysis-spring-2016/pages/syllabus/','199e7f142634901746d7790b63cb0715b32eb6122b850855ee0fa0e1e2cbeb73','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Lawrence D Guth"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.212','18.212','Algebraic Combinatorics','This course covers the applications of algebra to combinatorics. Topics include enumeration methods, permutations, partitions, partially ordered sets and lattices, Young tableaux, graph theory, matrix tree theorem, electrical networks, convex polytopes, and more.','Algebra and Number Theory Discrete Mathematics Mathematics','2019','https://ocw.mit.edu/courses/18-212-algebraic-combinatorics-spring-2019/','https://ocw.mit.edu/courses/18-212-algebraic-combinatorics-spring-2019/pages/syllabus/','4baf3d5b18635a9b524e6f60acc5bcc6503ca8aff2380d63c30eabdc4a082bbe','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Alexander Postnikov"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.303','18.303','Linear Partial Differential Equations: Analysis and Numerics','This course provides students with the basic analytical and computational tools of linear partial differential equations (PDEs) for practical applications in science engineering, including heat / diffusion, wave, and Poisson equations. Analytics emphasize the viewpoint of linear algebra and the analogy with finite matrix problems. Numerics focus on finite-difference and finite-element techniques to reduce PDEs to matrix problems. The Julia Language (a free, open-source environment) is introduced and used in homework for simple examples.','Applied Mathematics Differential Equations Linear Algebra Mathematics','2014','https://ocw.mit.edu/courses/18-303-linear-partial-differential-equations-analysis-and-numerics-fall-2014/','https://ocw.mit.edu/courses/18-303-linear-partial-differential-equations-analysis-and-numerics-fall-2014/pages/syllabus/','ddc1d4ae9dd8c0a1b01b59a351615a42a42743fa7c7763e8dd9a99eaf4ac5827','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Steven G. Johnson"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.310','18.310','Principles of Discrete Applied Mathematics','This course is an introduction to discrete applied mathematics. Topics include probability, counting, linear programming, number-theoretic algorithms, sorting, data compression, and error-correcting codes. This is a Communication Intensive in the Major (CI-M) course, and thus includes a writing component.','Applied Mathematics Communication Discrete Mathematics Mathematics Probability and Statistics Social Science','2013','https://ocw.mit.edu/courses/18-310-principles-of-discrete-applied-mathematics-fall-2013/','https://ocw.mit.edu/courses/18-310-principles-of-discrete-applied-mathematics-fall-2013/pages/syllabus/','ca9fae981edd12f6d64ecf61d65dc5eb1179a6cf645f967b49f345767184ad7f','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Michel Goemans","Susan Ruff","Dr. Lorenzo Orecchia","Dr. Richard Peng"]','structured','18.02 Multivariable Calculus') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('18.310',0,'18.02');
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.325','18.325','Topics in Applied Mathematics: Waves and Imaging','This class covers the mathematics of inverse problems involving waves, with examples taken from reflection seismology, synthetic aperture radar, and computerized tomography.','Applied Mathematics Computation Mathematics','2015','https://ocw.mit.edu/courses/18-325-topics-in-applied-mathematics-waves-and-imaging-fall-2015/','https://ocw.mit.edu/courses/18-325-topics-in-applied-mathematics-waves-and-imaging-fall-2015/pages/syllabus/','a64d93790ba758bb51d6a2e99a1f2c2f6625f2a7b00546570c2e2158597c2324','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Laurent Demanet"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.337J','18.337J','Parallel Computing','This is an advanced interdisciplinary introduction to applied parallel computing on modern supercomputers. It has a hands-on emphasis on understanding the realities and myths of what is possible on the world’s fastest machines. We will make prominent use of the Julia Language , a free, open-source, high-performance dynamic programming language for technical computing.','Algorithms and Data Structures Applied Mathematics Computation Computer Design and Engineering Computer Science Engineering Linear Algebra Mathematics Theory of Computation','2011','https://ocw.mit.edu/courses/18-337j-parallel-computing-fall-2011/','https://ocw.mit.edu/courses/18-337j-parallel-computing-fall-2011/pages/syllabus/','b77a13bd68bede691923ba81cc0bacc2b08bf20f5839b0974ce8330367cfd8d4','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Alan Edelman"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.369','18.369','Mathematical Methods in Nanophotonics','Find out what solid-state physics has brought to Electromagnetism in the last 20 years. This course surveys the physics and mathematics of nanophotonics—electromagnetic waves in media structured on the scale of the wavelength. Topics include computational methods combined with high-level algebraic techniques borrowed from solid-state quantum mechanics: linear algebra and eigensystems, group theory, Bloch’s theorem and conservation laws, perturbation methods, and coupled-mode theories, to understand surprising optical phenomena from band gaps to slow light to nonlinear filters. Note: An earlier version of this course was published on OCW as 18.325 Topics in Applied Mathematics: Mathematical Methods in Nanophotonics, Fall 2005.','Applied Mathematics Atomic, Molecular, Optical Physics Engineering Linear Algebra Mathematics Nanotechnology Physics Quantum Mechanics Science','2008','https://ocw.mit.edu/courses/18-369-mathematical-methods-in-nanophotonics-spring-2008/','https://ocw.mit.edu/courses/18-369-mathematical-methods-in-nanophotonics-spring-2008/pages/syllabus/','4c0aaa86605fa195119cd0f03b0df190b0ef416f4e4f3cc55a82c159d468f4cb','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Steven G. Johnson"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.409','18.409','Algorithmic Aspects of Machine Learning','This course is organized around algorithmic issues that arise in machine learning. Modern machine learning systems are often built on top of algorithms that do not have provable guarantees, and it is the subject of debate when and why they work. In this class, we focus on designing algorithms whose performance we can rigorously analyze for fundamental machine learning problems.','Algorithms and Data Structures Applied Mathematics Computer Science Discrete Mathematics Engineering Mathematics Theory of Computation','2015','https://ocw.mit.edu/courses/18-409-algorithmic-aspects-of-machine-learning-spring-2015/','https://ocw.mit.edu/courses/18-409-algorithmic-aspects-of-machine-learning-spring-2015/pages/syllabus/','04d9625aeebb362ad790c9a2db8eb7eff0d2c44fd18ae2c43ec0b2688181d171','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Ankur Moitra"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.435J','18.435J','Quantum Computation','This course provides an introduction to the theory and practice of quantum computation. Topics covered include: physics of information processing, quantum logic, quantum algorithms including Shor’s factoring algorithm and Grover’s search algorithm, quantum error correction, quantum communication, and cryptography.','Algorithms and Data Structures Computation Computer Science Cryptography Discrete Mathematics Engineering Mathematics Physics Quantum Mechanics Science Theory of Computation','2003','https://ocw.mit.edu/courses/18-435j-quantum-computation-fall-2003/','https://ocw.mit.edu/courses/18-435j-quantum-computation-fall-2003/pages/syllabus/','dfa1542c2cd47cd10a7b467708c8b9248732d1a76106dd02442671eeee0517b1','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Peter Shor"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.440','18.440','Probability and Random Variables','This course introduces students to probability and random variables. Topics include distribution functions, binomial, geometric, hypergeometric, and Poisson distributions. The other topics covered are uniform, exponential, normal, gamma and beta distributions; conditional probability; Bayes theorem; joint distributions; Chebyshev inequality; law of large numbers; and central limit theorem.','Discrete Mathematics Mathematics Probability and Statistics','2014','https://ocw.mit.edu/courses/18-440-probability-and-random-variables-spring-2014/','https://ocw.mit.edu/courses/18-440-probability-and-random-variables-spring-2014/pages/syllabus/','b7cd3cb9a06413775f866ac2ce6a9d1325b3d7dd513d10f8dd23b4f4ecc842c8','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Scott Sheffield"]','structured','Prerequisites 18.02SC Multivariable Calculus') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('18.440',0,'18.02');
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.465','18.465','Topics in Statistics: Statistical Learning Theory','The main goal of this course is to study the generalization ability of a number of popular machine learning algorithms such as boosting, support vector machines and neural networks. Topics include Vapnik-Chervonenkis theory, concentration inequalities in product spaces, and other elements of empirical process theory.','Algorithms and Data Structures Artificial Intelligence Cognitive Science Computer Science Engineering Mathematics Probability and Statistics Science','2007','https://ocw.mit.edu/courses/18-465-topics-in-statistics-statistical-learning-theory-spring-2007/','https://ocw.mit.edu/courses/18-465-topics-in-statistics-statistical-learning-theory-spring-2007/pages/syllabus/','6099ff9a69c8f44f565b57215e54cd57fe73f193e1c649a35ad0a067f0d96c1f','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Dmitry Panchenko"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.650','18.650','Statistics for Applications ','This course offers an in-depth the theoretical foundations for statistical methods that are useful in many applications. The goal is to understand the role of mathematics in the research and development of efficient statistical methods.','Mathematics Probability and Statistics','2016','https://ocw.mit.edu/courses/18-650-statistics-for-applications-fall-2016/','https://ocw.mit.edu/courses/18-650-statistics-for-applications-fall-2016/pages/syllabus/','0921f3daa0275f2c479688315b42b208ac18bfbaf6b071a5295af04355c04917','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Philippe Rigollet"]','review_required','Prerequisites Probability theory at the level of 18.440 Probability and Random Variables . Some linear algebra (matrices, vectors, eigenvalues).') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('18.650',0,'18.440');
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.701','18.701','Algebra I','This undergraduate level Algebra I course covers groups, vector spaces, linear transformations, symmetry groups, bilinear forms, and linear groups.','Algebra and Number Theory Linear Algebra Mathematics','2010','https://ocw.mit.edu/courses/18-701-algebra-i-fall-2010/','https://ocw.mit.edu/courses/18-701-algebra-i-fall-2010/pages/syllabus/','be9f77c44809ec1c1b945cc9b09609804abebc738c43b99712ffe77ed781acee','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Michael Artin"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.706','18.706','Noncommutative Algebra','Noncommutative algebra studies algebraic phenomena involving multiplication for which commutativity law fails, such as product of matrices in linear algebra; such phenomena arise in various disciplines ranging from quantum physics to number theory.','Algebra and Number Theory Mathematics','2023','https://ocw.mit.edu/courses/18-706-noncommutative-algebra-spring-2023/','https://ocw.mit.edu/courses/18-706-noncommutative-algebra-spring-2023/pages/syllabus/','7508af9c41414c15b5621b517a72d875aa0b44e7b61a79aae056b6a28777875e','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Roman Bezrukavnikov"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.727','18.727','Topics in Algebraic Geometry: Intersection Theory on Moduli Spaces','The topics for this course vary each semester. This semester, the course aims to introduce techniques for studying intersection theory on moduli spaces. In particular, it covers the geometry of homogeneous varieties, the Deligne-Mumford moduli spaces of stable curves and the Kontsevich moduli spaces of stable maps using intersection theory.','Algebra and Number Theory Mathematics Topology and Geometry','2006','https://ocw.mit.edu/courses/18-727-topics-in-algebraic-geometry-intersection-theory-on-moduli-spaces-spring-2006/','https://ocw.mit.edu/courses/18-727-topics-in-algebraic-geometry-intersection-theory-on-moduli-spaces-spring-2006/pages/syllabus/','597ef26fa0bc43d4ed1222a060b38bbf723950878942471aa25d9b4777c9cc75','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Izzet Coskun"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.769','18.769','Topics in Lie Theory: Tensor Categories','This course will give a detailed introduction to the theory of tensor categories and review some of its connections to other subjects (with a focus on representation-theoretic applications). In particular, we will discuss categorifications of such notions from ring theory as: module, morphism of modules, Morita equivalence of rings, commutative ring, the center of a ring, the centralizer of a subring, the double centralizer property, graded ring, etc.','Algebra and Number Theory Linear Algebra Mathematics Topology and Geometry','2009','https://ocw.mit.edu/courses/18-769-topics-in-lie-theory-tensor-categories-spring-2009/','https://ocw.mit.edu/courses/18-769-topics-in-lie-theory-tensor-categories-spring-2009/pages/syllabus/','d5c28ddb0f9bc0d98d08199a94d183e3c5bc01325577e1711ee485693622ee36','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Pavel Etingof"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.786','18.786','Number Theory II: Class Field Theory','This course is the continuation of 18.785 Number Theory I . It begins with an analysis of the quadratic case of Class Field Theory via Hilbert symbols, in order to give a more hands-on introduction to the ideas of Class Field Theory. More advanced topics in number theory are discussed in this course, such as Galois cohomology, proofs of class field theory, modular forms and automorphic forms, Galois representations, and quadratic forms.','Algebra and Number Theory Mathematics Topology and Geometry','2016','https://ocw.mit.edu/courses/18-786-number-theory-ii-class-field-theory-spring-2016/','https://ocw.mit.edu/courses/18-786-number-theory-ii-class-field-theory-spring-2016/pages/syllabus/','ba185e525f4380fab04d0161645efd7e72f6f81676fcf771b09600e13e89427b','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Sam Raskin"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.905','18.905','Algebraic Topology I','This is a course on the singular homology of topological spaces. Topics include: Singular homology, CW complexes, Homological algebra, Cohomology, and Poincare duality.','Mathematics Topology and Geometry','2016','https://ocw.mit.edu/courses/18-905-algebraic-topology-i-fall-2016/','https://ocw.mit.edu/courses/18-905-algebraic-topology-i-fall-2016/pages/syllabus/','bf9c63104d8de802984fbecc29be724f46caf289efc6acf953b02d255e5a7d66','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Haynes Miller"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.966','18.966','Geometry of Manifolds','This is a second-semester graduate course on the geometry of manifolds. The main emphasis is on the geometry of symplectic manifolds, but the material also includes long digressions into complex geometry and the geometry of 4-manifolds, with special emphasis on topological considerations.','Differential Equations Linear Algebra Mathematics Topology and Geometry','2007','https://ocw.mit.edu/courses/18-966-geometry-of-manifolds-spring-2007/','https://ocw.mit.edu/courses/18-966-geometry-of-manifolds-spring-2007/pages/syllabus/','91ee1dae520e8bce8e65bc04540066eeacff5cea247fe9e694d9aae3209b1ebb','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Denis Auroux"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.996A','18.996A','Simplicity Theory','This is an advanced topics course in model theory whose main theme is simple theories. We treat simple theories in the framework of compact abstract theories, which is more general than that of first order theories. We cover the basic properties of independence (i.e., non-dividing) in simple theories, the characterization of simple theories by the existence of a notion of independence, and hyperimaginary canonical bases.','Algebra and Number Theory Mathematical Logic Mathematics','2004','https://ocw.mit.edu/courses/18-996a-simplicity-theory-spring-2004/','https://ocw.mit.edu/courses/18-996a-simplicity-theory-spring-2004/pages/syllabus/','6ab965515e5999f23f28118cf24ba1b649f7280e528d42a1de5e979b8b66e9eb','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Itay Ben-Yaacov"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.S097','18.S097','Applied Category Theory ','Category theory is a relatively new branch of mathematics that has transformed much of pure math research. The technical advance is that category theory provides a framework in which to organize formal systems and by which to translate between them, allowing one to transfer knowledge from one field to another. But this same organizational framework also has many compelling examples outside of pure math. In this course, we will give seven sketches on real-world applications of category theory.','Applied Mathematics Mathematics Topology and Geometry','2019','https://ocw.mit.edu/courses/18-s097-applied-category-theory-january-iap-2019/','https://ocw.mit.edu/courses/18-s097-applied-category-theory-january-iap-2019/pages/syllabus/','6b8e7b358a6fea4e963d021365f0053e1150c85c9da9d3085608eed4cf07b4ab','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. David I. Spivak","Dr. Brendan Fong"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('18.S996','18.S996','Category Theory for Scientists','The goal of this class is to prove that category theory is a powerful language for understanding and formalizing common scientific models. The power of the language will be tested by its ability to penetrate into taken-for-granted ideas, either by exposing existing weaknesses or flaws in our understanding, or by highlighting hidden commonalities across scientific fields.','Discrete Mathematics Mathematical Logic Mathematics Science','2013','https://ocw.mit.edu/courses/18-s996-category-theory-for-scientists-spring-2013/','https://ocw.mit.edu/courses/18-s996-category-theory-for-scientists-spring-2013/pages/syllabus/','c5263fdaa8e896f2ebdd76288ab6f3043973334d44b97ab60b908d314b8bfd23','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. David I. Spivak"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('2.002','2.002','Mechanics and Materials II','This course provides Mechanical Engineering students with an awareness of various responses exhibited by solid engineering materials when subjected to mechanical and thermal loadings; an introduction to the physical mechanisms associated with design-limiting behavior of engineering materials, especially stiffness, strength, toughness, and durability; an understanding of basic mechanical properties of engineering materials, testing procedures used to quantify these properties, and ways in which these properties characterize material response; quantitative skills to deal with materials-limiting problems in engineering design; and a basis for materials selection in mechanical design.','Engineering Materials Science and Engineering Mechanical Engineering Solid Mechanics','2004','https://ocw.mit.edu/courses/2-002-mechanics-and-materials-ii-spring-2004/','https://ocw.mit.edu/courses/2-002-mechanics-and-materials-ii-spring-2004/pages/syllabus/','6f49d6d3b0da33c5aebae018d8810859e935860628a041c51848d48aa4d53810','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. David Parks","Prof. Lallit Anand"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('2.004','2.004','Modeling Dynamics and Control II','This course is the second subject of a two-term sequence on modeling, analysis and control of dynamic systems. Topics covered include: kinematics and dynamics of mechanical systems, including rigid bodies in plane motion linear and angular momentum principles impact and collision problems linearization about equilibrium free and forced vibrations sensors and actuators control of mechanical systems integral and derivative action, lead and lag compensators root-locus design methods frequency-domain design methods applications to case-studies of multi-domain systems','Applied Mathematics Computational Modeling and Simulation Dynamics and Control Engineering Mathematics Mechanical Engineering Systems Engineering','2003','https://ocw.mit.edu/courses/2-004-modeling-dynamics-and-control-ii-spring-2003/','https://ocw.mit.edu/courses/2-004-modeling-dynamics-and-control-ii-spring-2003/pages/syllabus/','5bc1dfabec68be4ed2a9ce2d2e62882aae406280ffe94f5e45b34c92e491acc4','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. George Haller","Prof. Peter So","Prof. Triantaphyllos Akylas"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('2.00B','2.00B','Toy Product Design','Toy Product Design is a MIT Public Service Center service learning design course offered in the Spring semester. This course, previously listed as SP.778, is an introduction to the product design process with a focus on designing for play and entertainment. In this course, students work in small teams of 5-6 members to design and prototype new toys. Students work closely with a local sponsor, an elementary school, and experienced mentors on a themed toy design project. Students will be introduced to the product development process, including determining customer needs; brainstorming; estimation; sketching; sketch modeling; concept development; design aesthetics; detailed design; prototyping; and written, visual, and oral communication. At the end of the course, students present their toy products at the Playsentations to toy designers, engineers, elementary school children and the MIT community. For more information about this course, see the 2.00B Web site .','Engineering Mechanical Design Mechanical Engineering Systems Design Systems Engineering','2008','https://ocw.mit.edu/courses/2-00b-toy-product-design-spring-2008/','https://ocw.mit.edu/courses/2-00b-toy-product-design-spring-2008/pages/syllabus/','41a3cacc813cfd7b1cb998d45db132727185b089ed6fa9ec8bfad58f59bce0d0','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. David Wallace","Barry Kudrowitz"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('2.032','2.032','Dynamics','This course reviews momentum and energy principles, and then covers the following topics: Hamilton’s principle and Lagrange’s equations; three-dimensional kinematics and dynamics of rigid bodies; steady motions and small deviations therefrom, gyroscopic effects, and causes of instability; free and forced vibrations of lumped-parameter and continuous systems; nonlinear oscillations and the phase plane; nonholonomic systems; and an introduction to wave propagation in continuous systems. This course was originally developed by Professor T. Akylas.','Classical Mechanics Dynamics and Control Engineering Mechanical Engineering Physics Quantum Mechanics Science','2004','https://ocw.mit.edu/courses/2-032-dynamics-fall-2004/','https://ocw.mit.edu/courses/2-032-dynamics-fall-2004/pages/syllabus/','c7f715a86994a66268f463769656075bc872657acf7401f2c82819cebe45e9d6','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. George Haller"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('2.062J','2.062J','Wave Propagation','This course discusses theoretical concepts and analysis of wave problems in science and engineering. Examples are chosen from elasticity, acoustics, geophysics, hydrodynamics, blood flow, nondestructive evaluation, and other applications.','Classical Mechanics Earth Science Engineering Environmental Engineering Fluid Mechanics Geophysics Hydrodynamics Hydrodynamics and Coastal Engineering Mechanical Engineering Ocean Engineering Physics Quantum Mechanics Science','2017','https://ocw.mit.edu/courses/2-062j-wave-propagation-spring-2017/','https://ocw.mit.edu/courses/2-062j-wave-propagation-spring-2017/pages/syllabus/','53eb861c36cb2d7069398db046b59f9e5c26084c3a997a2485a31a88225660d1','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Triantaphyllos Akylas"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('2.086','2.086','Numerical Computation for Mechanical Engineers','This class introduces elementary programming concepts including variable types, data structures, and flow control. After an introduction to linear algebra and probability, it covers numerical methods relevant to mechanical engineering, including approximation (interpolation, least squares and statistical regression), integration, solution of linear and nonlinear equations, ordinary differential equations, and deterministic and probabilistic approaches. Examples are drawn from mechanical engineering disciplines, in particular from robotics, dynamics, and structural analysis. Assignments require MATLAB® programming.','Differential Equations Engineering Linear Algebra Mathematics Mechanical Engineering Numerical Simulation Probability and Statistics Systems Engineering','2012','https://ocw.mit.edu/courses/2-086-numerical-computation-for-mechanical-engineers-fall-2012/','https://ocw.mit.edu/courses/2-086-numerical-computation-for-mechanical-engineers-fall-2012/pages/syllabus/','8ebf1ea825fe85cca66d46604d263b0d6a13e555157517f7dcf434f2a58b03be','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Anthony T. Patera","Prof. Daniel Frey","Prof. Nicholas Hadjiconstantinou"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('2.12','2.12','Introduction to Robotics','This course provides an overview of robot mechanisms, dynamics, and intelligent controls. Topics include planar and spatial kinematics, and motion planning; mechanism design for manipulators and mobile robots, multi-rigid-body dynamics, 3D graphic simulation; control design, actuators, and sensors; wireless networking, task modeling, human-machine interface, and embedded software. Weekly laboratories provide experience with servo drives, real-time control, and embedded software. Students will design and fabricate working robotic systems in a group-based term project.','Classical Mechanics Dynamics and Control Electrical Engineering Engineering Mechanical Design Mechanical Engineering Physics Robotics and Control Systems Science','2005','https://ocw.mit.edu/courses/2-12-introduction-to-robotics-fall-2005/','https://ocw.mit.edu/courses/2-12-introduction-to-robotics-fall-2005/pages/syllabus/','eeedd00821d7f336b109f5172b4ebdcd28e26b2187c9789a38aa9c0905038859','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Harry Asada","Prof. John Leonard"]','review_required','2.004 and 2.003 . This course is a restricted elective (professional subject).') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('2.171','2.171','Analysis and Design of Digital Control Systems','This course is a comprehensive introduction to control system synthesis in which the digital computer plays a major role, reinforced with hands-on laboratory experience. The course covers elements of real-time computer architecture; input-output interfaces and data converters; analysis and synthesis of sampled-data control systems using classical and modern (state-space) methods; analysis of trade-offs in control algorithms for computation speed and quantization effects. Laboratory projects emphasize practical digital servo interfacing and implementation problems with timing, noise, and nonlinear devices.','Computer Design and Engineering Computer Science Digital Systems Dynamics and Control Electrical Engineering Engineering Mechanical Engineering Robotics and Control Systems Signal Processing','2006','https://ocw.mit.edu/courses/2-171-analysis-and-design-of-digital-control-systems-fall-2006/','https://ocw.mit.edu/courses/2-171-analysis-and-design-of-digital-control-systems-fall-2006/pages/syllabus/','e439ae4a815aba160d3dd48a21aa9b8325eb6c39e0447b3a005972da602edc60','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. David Trumper"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('2.25','2.25','Advanced Fluid Mechanics','This course is a survey of principal concepts and methods of fluid dynamics. Topics include mass conservation, momentum, and energy equations for continua; Navier-Stokes equation for viscous flows; similarity and dimensional analysis; lubrication theory; boundary layers and separation; circulation and vorticity theorems; potential flow; introduction to turbulence; lift and drag; surface tension and surface tension driven flows.','Engineering Fluid Mechanics Hydrodynamics Mechanical Engineering Ocean Engineering','2013','https://ocw.mit.edu/courses/2-25-advanced-fluid-mechanics-fall-2013/','https://ocw.mit.edu/courses/2-25-advanced-fluid-mechanics-fall-2013/pages/syllabus/','278e82e21f6eba14db690198c929e9421a6524671a5508bb7a0eb30635366708','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Gareth McKinley"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('2.43','2.43','Advanced Thermodynamics','This course is a self-contained concise review of general thermodynamics concepts, multicomponent equilibrium properties, chemical equilibrium, electrochemical potentials, and chemical kinetics, as needed to introduce the methods of nonequilibrium thermodynamics and to provide a unified understanding of phase equilibria, transport, and nonequilibrium phenomena useful for future energy and climate engineering technologies. Applications include second-law efficiencies and methods to allocate primary energy consumptions and CO₂ emissions in cogeneration and hybrid power systems, minimum work of separation, maximum work of mixing, osmotic pressure and membrane equilibria, metastable states, spinodal decomposition, and Onsager’s near-equilibrium reciprocity in thermodiffusive, thermoelectric, and electrokinetic cross effects.','Chemical Engineering Chemistry Combustion Energy Engineering Fluid Mechanics Fossil Fuels Mechanical Engineering Physical Chemistry Physics Renewables Science Thermodynamics Transport Processes','2024','https://ocw.mit.edu/courses/2-43-advanced-thermodynamics-spring-2024/','https://ocw.mit.edu/courses/2-43-advanced-thermodynamics-spring-2024/pages/syllabus/','163549493cfb45c0be6421420000fa36a71b9cdb891954056bbeee9e69c0e591','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Gian Paolo Beretta"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('2.61','2.61','Internal Combustion Engines','This course studies the fundamentals of how the design and operation of internal combustion engines affect their performance, efficiency, fuel requirements, and environmental impact. Topics include fluid flow, thermodynamics, combustion, heat transfer and friction phenomena, and fuel properties, with reference to engine power, efficiency, and emissions. Students examine the design features and operating characteristics of different types of internal combustion engines: spark-ignition, diesel, stratified-charge, and mixed-cycle engines. The class includes lab project in the Engine Laboratory.','Chemical Engineering Combustion Energy Engineering Fossil Fuels Mechanical Engineering Physics Science Thermodynamics Transport Processes Transportation','2017','https://ocw.mit.edu/courses/2-61-internal-combustion-engines-spring-2017/','https://ocw.mit.edu/courses/2-61-internal-combustion-engines-spring-2017/pages/syllabus/','b38d89fee122c4cbaa5a7302be143bf24e6cbc8eccdb1b96a6a418cf018e4e71','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Wai Cheng"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('2.682','2.682','Acoustical Oceanography','This course will begin with brief overview of what important current research topics are in oceanography (physical, geological, and biological) and how acoustics can be used as a tool to address them. Three typical examples are climate, bottom geology, and marine mammal behavior. Will then address the acoustic inverse problem, reviewing inverse methods (linear and nonlinear) and the combination of acoustical methods with other measurements as an integrated system. Last part of course will concentrate on specific case studies, taken from current research journals. This course is taught on campus at MIT and with simultaneous video at Woods Hole Oceanographic Institution.','Earth Science Engineering Ocean Engineering Oceanography Physics Science','2012','https://ocw.mit.edu/courses/2-682-acoustical-oceanography-spring-2012/','https://ocw.mit.edu/courses/2-682-acoustical-oceanography-spring-2012/pages/syllabus/','7c5f982d92857c6a71c8c90ff227f746a29bb4223f79be1d24a657a2e65471bc','https://creativecommons.org/licenses/by-nc-sa/4.0/','["James Lynch"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('2.72','2.72','Elements of Mechanical Design','This is an advanced course on modeling, design, integration and best practices for use of machine elements such as bearings, springs, gears, cams and mechanisms. Modeling and analysis of these elements is based upon extensive application of physics, mathematics and core mechanical engineering principles (solid mechanics, fluid mechanics, manufacturing, estimation, computer simulation, etc.). These principles are reinforced via (1) hands-on laboratory experiences wherein students conduct experiments and disassemble machines and (2) a substantial design project wherein students model, design, fabricate and characterize a mechanical system that is relevant to a real world application. Students master the materials via problems sets that are directly related to, and coordinated with, the deliverables of their project. Student assessment is based upon mastery of the course materials and the student’s ability to synthesize, model and fabricate a mechanical device subject to engineering constraints (e.g. cost and time/schedule).','Business Engineering Mechanical Design Mechanical Engineering Project Management','2009','https://ocw.mit.edu/courses/2-72-elements-of-mechanical-design-spring-2009/','https://ocw.mit.edu/courses/2-72-elements-of-mechanical-design-spring-2009/pages/syllabus/','b5bce2c7f7f22b816d3a795275ecd5d15ca2f10688869980e883012663963cd8','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Martin Culpepper"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('2.785J','2.785J','Cell-Matrix Mechanics','This course teaches the effects of mechanical forces (strains) on cells and how cells generate mechanical forces by their contraction. Critical to both topics is the mechanical behavior of the extracellular matrix (ECM), which the cells have synthesized and remodeled. The ECM affects cell behavior by mediating exogenous mechanical strains, which stimulate certain cellular processes.','Anatomy and Physiology Biological Engineering Biology Biomaterials Biomechanics Biophysics Cell Biology Cell and Tissue Engineering Developmental Biology Engineering Health and Medicine Materials Science and Engineering Mechanical Engineering Science','2016','https://ocw.mit.edu/courses/2-785j-cell-matrix-mechanics-fall-2016/','https://ocw.mit.edu/courses/2-785j-cell-matrix-mechanics-fall-2016/pages/syllabus/','696f31a9e9029564afb549ef5b2730c74445b3fe9d6307bf007789d2a8a54991','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Myron Spector","Prof. Ioannis Yannas"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('2.854','2.854','Introduction to Manufacturing Systems','This course provides ways to analyze manufacturing systems in terms of material flow and storage, information flow, capacities, and times and durations of events. Fundamental topics include probability, inventory and queuing models, optimization, and linear and dynamic systems. Factory planning and scheduling topics include flow planning, bottleneck characterization, buffer and batch-size analysis, and dynamic behavior of production systems.','Business Engineering Mathematics Mechanical Engineering Operations Management Probability and Statistics Systems Engineering','2016','https://ocw.mit.edu/courses/2-854-introduction-to-manufacturing-systems-fall-2016/','https://ocw.mit.edu/courses/2-854-introduction-to-manufacturing-systems-fall-2016/pages/syllabus/','2b9bc269b78f293df1b0678538feb017a0772f03acdfe3d25c7ad8e3b537c9c5','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Stanley Gershwin"]','no_formal_course','There is no prerequisite for this course.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('2.993','2.993','Designing Paths to Peace','Teaches creative design based on the scientific method through the design, engineering, and manufacture of a detailed inlaid tile. This is an introductory lecture/studio course designed to teach students the basic principles of design and expose them to the design process. Throughout the course, students will be introduced to the terminology and concepts that underlie all forms of visual art; which–in many ways–forms the basis for the design of all physical objects. Along with learning mechanical skills, thinking both critically and visually, and working with different media, the students will consider how the arts grow out of and respond to particular cultural contexts and ideas; and how these thinking patterns can be applied to virtually all types of design. Presentations, lectures, demonstrations, discussions and various artistic works will be used to show students how other artists and designers have dealt with the same issues they will be facing in lab. Each class will begin with a critique of the students’ homework, followed by a discussion (and presentation when appropriate) of the pertinent issues of that week. All aspects of the course will aid the teams of students in designing and building a major inlaid tile whose elements are designed as digital solid models and manufactured on an abrasive waterjet machining center. The course will conclude with an exhibit of the completed tiles open to the MIT and the Greater-Boston public. Enrollment is limited to 16 students who will be divided into groups of 4 students each. Preference will be given to students who attend the first day of class in a pre-selected team of 4.','Engineering Fine Arts Graphic Design Mechanical Design Mechanical Engineering Systems Design Systems Engineering Visual Arts','2002','https://ocw.mit.edu/courses/2-993-designing-paths-to-peace-fall-2002/','https://ocw.mit.edu/courses/2-993-designing-paths-to-peace-fall-2002/pages/syllabus/','4b17c04c708b239c61fd4af14e2c67088b6def9a174e790a50092228754fcf5c','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Alex Slocum"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('2.997','2.997','Decision Making in Large Scale Systems','This course is an introduction to the theory and application of large-scale dynamic programming. Topics include Markov decision processes, dynamic programming algorithms, simulation-based algorithms, theory and algorithms for value function approximation, and policy search methods. The course examines games and applications in areas such as dynamic resource allocation, finance and queueing networks.','Algorithms and Data Structures Computational Modeling and Simulation Computer Science Engineering Game Theory Social Science Systems Engineering Systems Optimization','2004','https://ocw.mit.edu/courses/2-997-decision-making-in-large-scale-systems-spring-2004/','https://ocw.mit.edu/courses/2-997-decision-making-in-large-scale-systems-spring-2004/pages/syllabus/','cbd2d3947e37e16dbb91f6e2894eb30ab4aff8b804ccbf680c6ed5bb90904da6','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Daniela Pucci De Farias"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('20.020','20.020','Introduction to Biological Engineering Design','This class is a project-based introduction to the engineering of synthetic biological systems. Throughout the term, students develop projects that are responsive to real-world problems of their choosing, and whose solutions depend on biological technologies. Lectures, discussions, and studio exercises will introduce (1) components and control of prokaryotic and eukaryotic behavior, (2) DNA synthesis, standards, and abstraction in biological engineering, and (3) issues of human practice, including biological safety; security; ownership, sharing, and innovation; and ethics. Enrollment preference is given to freshmen. This subject was originally developed and first taught in Spring 2008 by Drew Endy and Natalie Kuldell. Many of Drew’s materials are used in this Spring 2009 version, and are included with his permission. This OCW Web site is based on the OpenWetWare class Wiki, found at OpenWetWare: 20.020 (S09)','Biological Engineering Engineering Synthetic Biology','2009','https://ocw.mit.edu/courses/20-020-introduction-to-biological-engineering-design-spring-2009/','https://ocw.mit.edu/courses/20-020-introduction-to-biological-engineering-design-spring-2009/pages/syllabus/','4c9f954ae18aeb1de3164d8943e86db912297d3317171c8a006027015669ecfa','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Natalie Kuldell","Prof. Andrew Endy"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('20.110J','20.110J','Thermodynamics of Biomolecular Systems','This subject deals primarily with equilibrium properties of macroscopic and microscopic systems, basic thermodynamics, chemical equilibrium of reactions in gas and solution phase, and macromolecular interactions.','Biological Engineering Biomaterials Chemistry Engineering Physical Chemistry Physics Science Thermodynamics','2005','https://ocw.mit.edu/courses/20-110j-thermodynamics-of-biomolecular-systems-fall-2005/','https://ocw.mit.edu/courses/20-110j-thermodynamics-of-biomolecular-systems-fall-2005/pages/syllabus/','b59fc11c444c2a05ae79adc53db6d5bc626bbcbf85ff51adc513cd7eb38c7cb7','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Kim Hamad-Schifferli","Prof. Linda Griffith","Prof. Moungi Bawendi","Prof. Robert Field"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('20.320','20.320','Analysis of Biomolecular and Cellular Systems','This course focuses on computational and experimental analysis of biological systems across a hierarchy of scales, including genetic, molecular, cellular, and cell population levels. The two central themes of the course are modeling of complex dynamic systems and protein design and engineering. Topics include gene sequence analysis, molecular modeling, metabolic and gene regulation networks, signal transduction pathways and cell populations in tissues. Emphasis is placed on experimental methods, quantitative analysis, and computational modeling.','Biological Engineering Biology Engineering Science','2012','https://ocw.mit.edu/courses/20-320-analysis-of-biomolecular-and-cellular-systems-fall-2012/','https://ocw.mit.edu/courses/20-320-analysis-of-biomolecular-and-cellular-systems-fall-2012/pages/syllabus/','98a8ea767699d83be26a0455c5a1135dc5c0095d880bc70cadc4870540f1c852','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Ernest Fraenkel","Prof. Forest White"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('20.420J','20.420J','Biomolecular Kinetics and Cellular Dynamics (BE.420J)','This subject deals primarily with kinetic and equilibrium mathematical models of biomolecular interactions, as well as the application of these quantitative analyses to biological problems across a wide range of levels of organization, from individual molecular interactions to populations of cells.','Biological Engineering Biology Biomechanics Biophysics Cell Biology Computational Biology Engineering Molecular Biology Science','2004','https://ocw.mit.edu/courses/20-420j-biomolecular-kinetics-and-cellular-dynamics-be-420j-fall-2004/','https://ocw.mit.edu/courses/20-420j-biomolecular-kinetics-and-cellular-dynamics-be-420j-fall-2004/pages/syllabus/','0a063f7a6e9164929a5c768d7ff0588e5740fb5671c7eeb3d151ed9a29a1b27e','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Bruce Tidor","Prof. Karl Wittrup"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('20.453J','20.453J','Biomedical Information Technology','This course teaches the design of contemporary information systems for biological and medical data. Examples are chosen from biology and medicine to illustrate complete life cycle information systems, beginning with data acquisition, following to data storage and finally to retrieval and analysis. Design of appropriate databases, client-server strategies, data interchange protocols, and computational modeling architectures. Students are expected to have some familiarity with scientific application software and a basic understanding of at least one contemporary programming language (e.g. C, C++, Java, Lisp, Perl, Python). A major term project is required of all students. This subject is open to motivated seniors having a strong interest in biomedical engineering and information system design with the ability to carry out a significant independent project. This course was offered as part of the Singapore-MIT Alliance (SMA) program as course number SMA 5304.','Biological Engineering Biomedical Instrumentation Biomedicine Business Computational Biology Computer Science Data Mining Engineering Health and Medicine Information Technology Medical Imaging','2008','https://ocw.mit.edu/courses/20-453j-biomedical-information-technology-fall-2008/','https://ocw.mit.edu/courses/20-453j-biomedical-information-technology-fall-2008/pages/syllabus/','a685a7f38193f534002721166f7c2b956e2cee4bc68d993b6ae6e93625e29385','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. C. Forbes Dewey","Prof. Hanry Yu","Prof. Sourav Saha Bhowmick"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21A.101J (FORMERLY 21A.218J)','21A.101J (FORMERLY 21A.218J)','Identity and Difference','This course explores how identities, whether of individuals or groups, are produced, maintained, and transformed. Students will be introduced to various theoretical perspectives that deal with identity formation, including constructions of “the normal.” We will explore the utility of these perspectives for understanding identity components such as gender, sexual orientation, race, ethnicity, religion, language, social class, and bodily difference. By semester’s end students will understand better how an individual can be at once cause and consequence of society, a unique agent of social action as well as a social product.','Anthropology Cultural Anthropology Ethnography Gender Studies Social Anthropology Social Science Society','2010','https://ocw.mit.edu/courses/21a-218j-identity-and-difference-spring-2010/','https://ocw.mit.edu/courses/21a-218j-identity-and-difference-spring-2010/pages/syllabus/','53da9b4938eda909dff55ca473fa1da34b65a75a3eceac45b4d2aefe07f7fe9c','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Jean Jackson"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21A.104','21A.104','Memory, Culture, Forgetting','This course introduces scholarly debates about the sociocultural practices through which individuals and societies create, sustain, recall, and erase memories. Emphasis is given to the history of knowledge, construction of memory, the role of authorities in shaping memory, and how societies decide on whose versions of memory are more “truthful” and “real.” Other topics include how memory works in the human brain, memory and trauma, amnesia, memory practices in the sciences, false memory, sites of memory, and the commodification of memory. Students taking the graduate version complete additional assignments.','Anthropology Biological Anthropology Cultural Anthropology Ethnography Social Anthropology Social Science','2016','https://ocw.mit.edu/courses/21a-104-memory-culture-forgetting-spring-2016/','https://ocw.mit.edu/courses/21a-104-memory-culture-forgetting-spring-2016/pages/syllabus/','05a40a8691b05c44b82445cfaec35b794006800e4feaa77b725ec07aa1ed3660','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Manduhai Buyandelger"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21A.155','21A.155','Food, Culture & Politics','This course explores connections between what we eat and who we are through cross-cultural study of how personal and collective identities, social relations, and economic inequalities are formed and maintained via practices of food production, preparation, and consumption. Discussions are organized around critical discussion of what makes “good” food good (tasty, healthy, authentic, ethical, etc.), and draw on anthropological studies as well as recent writing and films on the politics of food and agriculture. A primary goal of the course is to provide students with conceptual tools to understand and evaluate food systems at local and global levels. Instruction and practice in written and oral communication is provided.','Anthropology Cultural Anthropology Social Anthropology Social Science','2019','https://ocw.mit.edu/courses/21a-155-food-culture-politics-fall-2019/','https://ocw.mit.edu/courses/21a-155-food-culture-politics-fall-2019/pages/syllabus/','2b18e975570b9d6b20828bce44c98395b92a4d1495fd957a31503d058af07fe6','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Heather Paxson"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21A.270','21A.270','Anthropology Through Speculative Fiction','This class examines how anthropology and speculative fiction (SF) each explore ideas about culture and society, technology, morality, and life in “other” worlds. We investigate this convergence of interest through analysis of SF in print, film, and other media. Concepts include traditional and contemporary anthropological topics, including first contact; gift exchange; gender, marriage, and kinship; law, morality, and cultural relativism; religion; race and embodiment; politics, violence, and war; medicine, healing, and consciousness; technology and environment. Thematic questions addressed in the class include: what is an alien? What is “the human”? Could SF be possible without anthropology?','Anthropology Cultural Anthropology Fiction Humanities Literature Social Anthropology Social Science','2009','https://ocw.mit.edu/courses/21a-270-anthropology-through-speculative-fiction-fall-2009/','https://ocw.mit.edu/courses/21a-270-anthropology-through-speculative-fiction-fall-2009/pages/syllabus/','e2a58914368e306729c8f57156a407b0a17487b6ee5fa353b155bda115c03d23','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Erica James","Prof. Stefan Helmreich"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21A.342','21A.342','Environmental Struggles','This class explores the interrelationship between humans and natural environments. It does so by focusing on conflict over access to and use of the environment as well as ideas about “nature” in various parts of the world.','Anthropology Cultural Anthropology Environmental Policy Ethnography Humanities Philosophy Political Philosophy Public Administration Social Science','2004','https://ocw.mit.edu/courses/21a-342-environmental-struggles-fall-2004/','https://ocw.mit.edu/courses/21a-342-environmental-struggles-fall-2004/pages/syllabus/','46e825e8130cf691e6842b1c937a68034da8fe0ed314e41a0a2cd55be2d3bd6d','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Christine Walley"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21A.442J','21A.442J','Violence, Human Rights, and Justice','This course examines the problem of mass violence and oppression in the contemporary world, and the concept of human rights as a defense against such abuse. It explores questions of cultural relativism, race, gender and ethnicity. It examines case studies from war crimes tribunals, truth commissions, anti-terrorist policies and other judicial attempts to redress state-sponsored wrongs. It also considers whether the human rights framework effectively promotes the rule of law in modern societies. Students debate moral positions and address ideas of moral relativism.','Anthropology Cultural Anthropology Humanities Philosophy Political Philosophy Social Justice Social Science Sociology','2014','https://ocw.mit.edu/courses/21a-442j-violence-human-rights-and-justice-fall-2014/','https://ocw.mit.edu/courses/21a-442j-violence-human-rights-and-justice-fall-2014/pages/syllabus/','de32fa760a77531f79f9c00ccb31f24d8490e33970a70915a08ce37dd602e5b0','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Erica James"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21A.470J','21A.470J','Gender and Representation of Asian Women','This course explores stereotypes associated with Asian women in colonial, nationalist, state-authoritarian, and global/diasporic narratives about gender and power. Students will read ethnography, cultural studies, and history, and view films to examine the politics and circumstances that create and perpetuate the representation of Asian women as dragon ladies, lotus blossoms, despotic tyrants, desexualized servants, and docile subordinates. Students are introduced to the debates about Orientalism, gender, and power.','Anthropology Asian Studies Cultural Anthropology Ethnography Gender Studies Social Science Society Women''s Studies','2010','https://ocw.mit.edu/courses/21a-470j-gender-and-representation-of-asian-women-spring-2010/','https://ocw.mit.edu/courses/21a-470j-gender-and-representation-of-asian-women-spring-2010/pages/syllabus/','e2cabaf05cbe5b76fb91f6a8663b464a799c500813fcf8a6e60166719766c3ab','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Manduhai Buyandelger"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21A.506','21A.506','The Anthropology of Politics: U.S. Presidential Election Edition','This course examines the birth and international expansion of an American industry of political marketing. It focuses attention on the cultural processes, sociopolitical contexts and moral utopias that shape the practice of political marketing in the U.S. and in different countries. By looking at the debates and expert practices at the core of the business of politics, the course explores how the “universal” concept of democracy is interpreted and reworked through space and time, while examining how different cultural groups experimenting with political marketing understand the role of citizens in a democracy.','American Politics Anthropology Ethnography Political Science Social Science','2016','https://ocw.mit.edu/courses/21a-506-the-anthropology-of-politics-u-s-presidential-election-edition-fall-2016/','https://ocw.mit.edu/courses/21a-506-the-anthropology-of-politics-u-s-presidential-election-edition-fall-2016/pages/syllabus/','56f8f85589cb0c6291cc52ead994599b15c6ab2dd384197849c48dc5883de7b4','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Maria Vidart-Delgado"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21A.850J','21A.850J','The Anthropology of Cybercultures','This course explores a range of contemporary scholarship oriented to the study of ‘cybercultures,’ with a focus on research inspired by ethnographic and more broadly anthropological perspectives. Taking anthropology as a resource for cultural critique, the course will be organized through a set of readings chosen to illustrate central topics concerning the cultural and material practices that comprise digital technologies. We’ll examine social histories of automata and automation; the trope of the ‘cyber’ and its origins in the emergence of cybernetics during the last century; cybergeographies and politics; robots, agents and humanlike machines; bioinformatics and artificial life; online sociality and the cyborg imaginary; ubiquitous and mobile computing; ethnographies of research and development; and geeks, gamers and hacktivists. We’ll close by considering the implications for all of these topics of emerging reconceptualizations of sociomaterial relations, informed by feminist science and technology studies.','Anthropology Cultural Anthropology Digital Media Ethnography Fine Arts Media Studies Social Science','2009','https://ocw.mit.edu/courses/21a-850j-the-anthropology-of-cybercultures-spring-2009/','https://ocw.mit.edu/courses/21a-850j-the-anthropology-of-cybercultures-spring-2009/pages/syllabus/','ea4b844cbd1561569e7bf70374e4a9537ebf317449c23bfdf52c9511fae4550d','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Lucy Suchman"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21G.017','21G.017','Germany and its European Context','This course focuses on main currents in contemporary German literary and visual culture. Taking Nietzsche’s thought as a point of departure, students will survey the dialectics of tradition and modernity in both Germany and other European countries, particularly the UK, France, Denmark, and Poland. Primary works are drawn from literature, cinema, art, and performance, including works by Peter Sloterdijk, Thomas Vinterberg, and Michel Houellebecq.','Criticism European and Russian Studies Humanities International Literature Literature Society','2002','https://ocw.mit.edu/courses/21g-017-germany-and-its-european-context-fall-2002/','https://ocw.mit.edu/courses/21g-017-germany-and-its-european-context-fall-2002/pages/syllabus/','0a9322b5981d8721072551b605926858c22f51653e45a955bfdfcd41db011657','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Charity Scribner"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21G.030','21G.030','East Asian Culture: From Zen to K-Pop','This subject is an introduction to various forms of culture in East Asia (focusing on China, Japan and Korea), including both traditional and contemporary examples. Critically examines the shared cultural elements that are widely considered to constitute “East Asian culture,” and also the diversity within East Asia, historically and today. Examples include religious and philosophical beliefs (Confucianism and Buddhism), literature, art, food, architecture, and popular culture. The study of gender will be an integral part of this subject. The influence and presence of Asian cultural expressions in the U.S. are also considered. This class is suitable for students of all levels, and requires no Asian language background. Students who wish to fulfill the MISTI-Singapore requirement may do the final project on Singapore. Taught in English. The course includes field trips to the Museum of Fine Arts and the Peabody Essex Museum.','Anthropology Asian Studies Cultural Anthropology Social Science Society','2015','https://ocw.mit.edu/courses/21g-030-east-asian-culture-from-zen-to-k-pop-spring-2015/','https://ocw.mit.edu/courses/21g-030-east-asian-culture-from-zen-to-k-pop-spring-2015/pages/syllabus/','3b3d53cd9ccf2538baed2634f16f46209a8d186796b9a97a8e6cefae02817848','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Emma Teng"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21G.040','21G.040','A Passage to India: Introduction to Modern Indian Culture and Society','This course is an introduction to modern Indian culture and society through films, documentaries, short stories, novels, poems, and journalistic writing. The principal focus is on the study of major cultural developments and social debates in the last sixty five years of history through the reading of literature and viewing of film clips. The focus will be on the transformations of gender and class issues, representation of nationhood, the idea of regional identities and the place of the city in individual and communal lives. The cultural and historical background will be provided in class lectures. The idea is to explore the “other Indias” that lurk behind our constructed notion of a homogeneous national culture.','Anthropology Asian Studies Cultural Anthropology Fine Arts Humanities International Literature Literature Media Studies Social Science Society','2012','https://ocw.mit.edu/courses/21g-040-a-passage-to-india-introduction-to-modern-indian-culture-and-society-spring-2012/','https://ocw.mit.edu/courses/21g-040-a-passage-to-india-introduction-to-modern-indian-culture-and-society-spring-2012/pages/syllabus/','c03a0d056d2f62ed13effefe30a92daa73f9a151496d7bde37d592280d16fa41','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Sunil H. Sharma"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21G.053','21G.053','Understanding Contemporary French Politics','This course examines the changes in contemporary French society through the study of political debates, reforms and institutions since 1958, and analyzes the deep influence of politics on cultural and social life, despite a decline in political participation. Public controversies and political cleavages, from the Algerian war to postcolonial issues, from the birth of the European Union to the recent financial crisis, and from the moral “revolution” of the seventies to the recognition of new families are revisited. This course is taught in English.','European and Russian Studies Political Science Social Justice Social Science Society Sociology','2014','https://ocw.mit.edu/courses/21g-053-understanding-contemporary-french-politics-spring-2014/','https://ocw.mit.edu/courses/21g-053-understanding-contemporary-french-politics-spring-2014/pages/syllabus/','9b9fea7942feec971597353e4c1c358d9a6b6db3821a69906b78c717a61b1291','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Bruno Perreau"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21G.067J','21G.067J','Cultural Performances of Asia','This course examines cultural performances of Asia, including both traditional and contemporary forms, in a variety of genres. Students will explore the communicative power of performances with attention to the ways performers, media, cultural settings, and audiences interact. The representation of cultural difference is considered and how it is altered through processes of globalization. Performances are viewed live when possible, but the course also relies on video, audio, and online materials as necessary. There are no prerequisites for this course and it is taught in English.','Anthropology Asian Studies Cultural Anthropology Fine Arts Media Studies Performance Arts Social Science Society','2005','https://ocw.mit.edu/courses/21g-067j-cultural-performances-of-asia-fall-2005/','https://ocw.mit.edu/courses/21g-067j-cultural-performances-of-asia-fall-2005/pages/syllabus/','4ef2aef3a6782c67758a99be244d0b4ce5a0c3aaf2dc33a063689256b3d53589','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Ian Condry"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21G.104','21G.104','Chinese IV (Regular)','Together with 21G.103 Chinese III , this course forms the intermediate level of what constitutes a four-term foundation in Mandarin. Upon completion of Chinese III and IV, students should be able to speak Chinese with fluency on everyday topics, reach a literacy level of 750 characters (approximately 1200 common words written in both traditional and simplified characters), read materials written in simple standard written Chinese, and produce both orally and in writing short compositions on everyday topics. Throughout the course we will address issues of how cultural differences inform and are informed by different linguistic contexts and practices.','Chinese Humanities Language','2018','https://ocw.mit.edu/courses/21g-104-chinese-iv-regular-spring-2018/','https://ocw.mit.edu/courses/21g-104-chinese-iv-regular-spring-2018/pages/syllabus/','20e7b9d924dac4f129b6dbfd6fdc83e54d0bbd94396cbbdc0bb296c77b328e74','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Haohsiang Liao"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21G.111','21G.111','Chinese Calligraphy','Chinese calligraphy (书法 / 書法, shūfǎ)—the art of expressive brush writing—is one of the most esteemed and enduring artistic traditions in China. This introductory course invites students to explore calligraphy as both a classical discipline and a living art form that continues to evolve in contemporary contexts. The course integrates technical training, historical and cultural study, and reflective practice. Students will not only gain hands-on experience with the brush and ink, but also investigate the evolving role of calligraphy in Chinese society, from antiquity to the present day. Through museum visits, interdisciplinary exploration, and individual projects, students will gain a deeper understanding of Chinese culture, philosophy, and aesthetic values. A final video project allows students to reflect on their personal journey with calligraphy and document their artistic growth. No prior knowledge of the Chinese language is required.','Chinese Humanities Language','2024','https://ocw.mit.edu/courses/21g-111-chinese-calligraphy-spring-2024/','https://ocw.mit.edu/courses/21g-111-chinese-calligraphy-spring-2024/pages/syllabus/','8b66cf3f6daef8879e33a7ecbdfeeb4b0776c3feef88ff3f1de64987e72554be','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Kang Zhou"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21G.225','21G.225','Advanced Workshop in Writing for Science and Engineering (ELS)','This course offers analysis and practice of various forms of scientific and technical writing, from memos to journal articles, in addition to strategies for conveying technical information to specialist and non-specialist audiences. Comparable to 21W.780 Communicating in Technical Organizations , but methods in this course are designed to deal with special problems of advanced ELS or bilingual students. The goal of the workshop is to develop effective writing skills for academic and professional contexts. Models, materials, topics and assignments vary from term to term.','Academic Writing English as a Second Language Humanities Language Literature Nonfiction Prose Technical Writing','2016','https://ocw.mit.edu/courses/21g-225-advanced-workshop-in-writing-for-science-and-engineering-els-spring-2016/','https://ocw.mit.edu/courses/21g-225-advanced-workshop-in-writing-for-science-and-engineering-els-spring-2016/pages/syllabus/','a359310038caef00195fb93ef7f9a63fe7adba4da36686b35a64c91a66d0ee1f','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Jane Dunphy"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21G.312','21G.312','Basic Themes in French Literature and Culture','Childhood is a source of fascination in most Western cultures. It is both a major inspiration for artistic creation and a political ideal, which aims at protecting future generations. Which role does it play in French society and in other francophone areas? Why is the French national anthem (“La Marseillaise”) addressed to its “children”? This course will study the transformation of childhood since the 18th century and the development of sentimentality within the family. We will examine various representations of childhood in literature (e.g. Pagnol, Proust, Sarraute, Laye, Morgièvre), movies (e.g. Truffaut), and songs (e.g. Brel, Barbara). Course taught in French.','Anthropology Cultural Anthropology French Humanities International Literature Language Literature Social Science','2011','https://ocw.mit.edu/courses/21g-312-basic-themes-in-french-literature-and-culture-spring-2011/','https://ocw.mit.edu/courses/21g-312-basic-themes-in-french-literature-and-culture-spring-2011/pages/syllabus/','7b9baa0ad699b07854bd6542d99f8c8166eb9c925885dfc8cc7de61ec571ca81','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Bruno Perreau"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21G.341','21G.341','Contemporary French Film and Social Issues','This course covers issues in contemporary French society as expressed through movies made in the 2000s. Topics include France’s national self-image, the women’s movement, sexuality and gender, family life and class structure, post-colonialism and immigration, and American cultural imperialism. Films by Lelouch, Audiard, Doillon, Denis, Klapisch, Resnais, Rouan, Balasko, Collard, Dridi, Kassovitz, and others. Readings from French periodicals. Films shown with English subtitles. Taught in French.','European and Russian Studies Film and Video Fine Arts French Humanities International Literature Language Literature Society Visual Arts','2014','https://ocw.mit.edu/courses/21g-341-contemporary-french-film-and-social-issues-spring-2014/','https://ocw.mit.edu/courses/21g-341-contemporary-french-film-and-social-issues-spring-2014/pages/syllabus/','584c8e773517c0c4185900cc44c9f6550259a1b083ab51650bcbf2f35c84a7b1','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Catherine E Clark"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21G.403','21G.403','German III','This course expands skills in speaking, reading, listening, and writing. Students develop analytic and interpretative skills through the reading of a full-length drama as well as short prose and poetry (Biermann, Brecht, Dürrenmatt, Tawada and others) and through media selections on contemporary issues in German-speaking cultures. Coursework includes discussions and compositions based on these texts, and review of grammar and development of vocabulary-building strategies. It is recommended for students with two years of high school German.','German Humanities International Literature Language Literature','2004','https://ocw.mit.edu/courses/21g-403-german-iii-spring-2004/','https://ocw.mit.edu/courses/21g-403-german-iii-spring-2004/pages/syllabus/','283b99c49904141d088a9be0e14dea6e19349283c30a79689980243e53465b28','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dagmar Jaeger"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21G.414','21G.414','German Culture, Media, and Society','The topic for Fall 2006 is short film and radio plays. This course investigates current trends and topics in German literary, theater, film, television, radio, and other media arts productions. Students analyze media texts in the context of their production, reception, and distribution as well as the public debates initiated by these works. The topic for Fall 2006 is German Short Film, a popular format that represents most recent trends in film production, and German Radio Art, a striving genre that includes experimental radio plays, sound art, and audio installations. Special attention will be given to the representation of German minorities, contrasted by their own artistic expressions reflecting changes in identity and a new political voice. Students have the opportunity to discuss course topics with a writer, filmmaker, and/or media artist from Germany. The course is taught in German.','Anthropology Cultural Anthropology European and Russian Studies Film and Video Fine Arts German Humanities Language Media Studies Social Science Society Visual Arts','2006','https://ocw.mit.edu/courses/21g-414-german-culture-media-and-society-fall-2006/','https://ocw.mit.edu/courses/21g-414-german-culture-media-and-society-fall-2006/pages/syllabus/','1dafca297592dc729f98f6c794bc13fe8c1e3206d5d052e9853a2cbe85f74d0d','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Kurt Fendt"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21G.702','21G.702','Spanish II','Spanish II continues to develop students’ listening, speaking, reading and writing skills using the second part of the video-based program, Destinos , begun in Spanish I. Destinos is a soap opera that allows students to learn Spanish and experience its cultural diversity while following a good story full of surprises and human emotions. Spanish II also includes additional materials, such as Spanish films and other media, various types of reading selections and online resources.','Humanities Language Spanish','2004','https://ocw.mit.edu/courses/21g-702-spanish-ii-spring-2004/','https://ocw.mit.edu/courses/21g-702-spanish-ii-spring-2004/pages/syllabus/','2aac300278861f014ed9d6ebfe9d5351b4e8aad971d0628be435dfb59be22afc','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Margarita Ribas Groeger","José A. Ramos","Solivia Márquez"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21G.714','21G.714','Spanish for Bilingual Students','Spanish for Bilingual Students is an intermediate course designed principally for heritage learners, but which includes other students interested in specific content areas, such as US Latino immigration, identity, ethnicity, education and representation in the media. Linguistic goals include vocabulary acquisition, improvement in writing, and enhancement of formal communicative skills.','Humanities Language Literature Spanish','2003','https://ocw.mit.edu/courses/21g-714-spanish-for-bilingual-students-spring-2003/','https://ocw.mit.edu/courses/21g-714-spanish-for-bilingual-students-spring-2003/pages/syllabus/','1453c113b15f2578baf10c8bcaeb887371b6f2b6a735d29969e0892284c62549','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Douglas Morgenstern"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21G.801','21G.801','Portuguese I','This course provides an introduction to the language and culture of the Portuguese-speaking world, with special attention to Brazilian Portuguese. This course focuses are on basic oral expression, listening comprehension, and elementary reading and writing. Students develop their vocabulary and understanding of grammatical concepts through active communication. This is a coordinated language lab program and is designed for students with no knowledge of Portuguese. Class is conducted entirely in Portuguese.','Anthropology Cultural Anthropology Humanities Language Latin and Caribbean Studies Portuguese Social Science Society','2011','https://ocw.mit.edu/courses/21g-801-portuguese-i-fall-2011/','https://ocw.mit.edu/courses/21g-801-portuguese-i-fall-2011/pages/syllabus/','ab53f707c2a5eff5245950a6a960ff3d469c11669c4aa7fff072f0ccb63f6b66','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Nilma Dominique"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21G.S55','21G.S55','Japanese V','This is an experimental version of 21G.505, which offers a combination of in-person and synchronous remote instruction. It aims to achieve simultaneous progression of four skills—listening, speaking, reading, and writing. It immerses students in various aspects of Japanese culture through authentic everyday Japanese media.','Humanities Japanese Language','2022','https://ocw.mit.edu/courses/21g-s55-japanese-v-fall-2022/','https://ocw.mit.edu/courses/21g-s55-japanese-v-fall-2022/pages/syllabus/','bc05087a493e0fdeaf145ea1f000f34059cf071b29d74d318dff16bf1558b9df','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Takako Aikawa"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21H.102','21H.102','American History Since 1865','This course examines the social, cultural, political, and economic history of the United States, from the Civil War to the present. It uses secondary analysis and primary documents, such as court cases, personal accounts, photographs, and films, to examine some of the key issues in the shaping of modern America, including industrialization and urbanization, immigration, the rise of a mass consumer society, the emergence of the US as a global power, and the development of civil rights activism and other major social movements.','American History History Humanities Modern History','2018','https://ocw.mit.edu/courses/21h-102-american-history-since-1865-spring-2018/','https://ocw.mit.edu/courses/21h-102-american-history-since-1865-spring-2018/pages/syllabus/','87cc7174317225dc53d41ba452758dafc00d2a87ed700a51234878aa769035cf','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Caley Horan"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21H.132','21H.132','The Ancient World: Rome','This course covers the history of Rome from its humble beginnings to the 5th century A.D. The first half covers Kingship to Republican form; the conquest of Italy; Roman expansion: Pyrrhus, Punic Wars and provinces; classes, courts, and the Roman revolution; Augustus and the formation of empire. The second half covers Virgil to the Vandals; major social, economic, political and religious trends at Rome and in the provinces. There is an emphasis on the use of primary sources in translation.','Ancient History Classics European History History Humanities Literature','2017','https://ocw.mit.edu/courses/21h-132-the-ancient-world-rome-spring-2017/','https://ocw.mit.edu/courses/21h-132-the-ancient-world-rome-spring-2017/pages/syllabus/','8d5ce25d451c1e73d60bba09fbf50f81c9d30ab96cc171cea7e5eef54d452b19','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. William Broadhead"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21H.155','21H.155','Modern Japan: 1868 to Present','This course surveys Japanese history from the establishment of the Tokugawa shogunate in 1603 to the present and explores the local and global nature of modernity in Japan. It highlights key themes, including the emergence of a modern nation-state, the rise and fall of the Japanese Empire, the development of mass consumer culture and the middle class, and the continued importance of historical memory in Japan today.','Asian History History Humanities International Relations Military History Modern History Political Science Social Science','2017','https://ocw.mit.edu/courses/21h-155-modern-japan-1868-to-present-spring-2017/','https://ocw.mit.edu/courses/21h-155-modern-japan-1868-to-present-spring-2017/pages/syllabus/','c55171d0979c68781fe01d632ae2cf2ccca1c4433b96db0cfc0d0ba24fe66b31','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Hiromu Nagahara"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21H.209','21H.209','America in Depression and War','This course focuses on the Great Depression and World War II and how they led to a major reordering of American politics and society. We will examine how ordinary people experienced these crises and how those experiences changed their outlook on politics and the world around them.','American History American Politics Anthropology Cultural Anthropology History Humanities Military History Philosophy Political Philosophy Political Science Social Science','2012','https://ocw.mit.edu/courses/21h-209-america-in-depression-and-war-spring-2012/','https://ocw.mit.edu/courses/21h-209-america-in-depression-and-war-spring-2012/pages/syllabus/','c610c5e38059221afc3c80f95816d156eeb56d79e422dc3de36199f4a6814456','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Meg Jacobs"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21H.234J','21H.234J','Downtown','This seminar focuses on downtowns in U.S. cities from the late nineteenth century to the late twentieth century. Emphasis will be placed on downtown as an idea, place, and cluster of interests; on the changing character of downtown; and on recent efforts to rebuild it. Subjects to be considered will include subways, skyscrapers, highways, urban renewal, and retail centers. The focus will be on readings, discussions, and individual research projects.','American History Architecture Environmental Design Fine Arts History Humanities Social Science Urban Studies','2005','https://ocw.mit.edu/courses/21h-234j-downtown-spring-2005/','https://ocw.mit.edu/courses/21h-234j-downtown-spring-2005/pages/syllabus/','e176016d24e758b72d7a500362b2d3ad916a6d653eb77bfc033ecfdddd19f778','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Bernard Frieden","Prof. Robert Fogelson"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21H.301','21H.301','The Ancient World: Greece','This course elaborates the history of Ancient Greece from the Bronze Age to the death of Alexander. It covers major social, economic, political, and religious trends. It also includes discussions on Homer, heroism, and the Greek identity; the hoplite revolution and the rise of the city-state; Herodotus, Persia, and the (re)birth of history; Empire, Thucydidean rationalism, and the Peloponnesian War; Platonic constructs; Aristotle, Macedonia, and Hellenism. Emphasis is on use of primary sources in translation.','Ancient History Classics European History History Humanities Literature','2004','https://ocw.mit.edu/courses/21h-301-the-ancient-world-greece-fall-2004/','https://ocw.mit.edu/courses/21h-301-the-ancient-world-greece-fall-2004/pages/syllabus/','af115dbe1baaf90520e7789259c3526ffe8039bd4dc7084984b83d48fbadde7a','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. William Broadhead"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21H.336','21H.336','The Making of a Roman Emperor','Through close examination of the emperor Augustus and his Julio-Claudian successors, this subject investigates how Roman emperors used art, architecture, coinage, and other media to create and project an image of themselves, how the surviving literary sources from the Roman period reinforced or subverted that image, and how both phenomena have contributed to post-classical perceptions of Roman emperors. It also considers works of Suetonius and Tacitus as well as modern representations of the emperors such as those found in the films I, Claudius , Quo Vadis , and HBO’s Rome series.','Ancient History History Humanities','2023','https://ocw.mit.edu/courses/21h-336-the-making-of-a-roman-emperor-spring-2023/','https://ocw.mit.edu/courses/21h-336-the-making-of-a-roman-emperor-spring-2023/pages/syllabus/','ca6661e2d11294036f1a9033ca57cdf8eff02fbc84187f7390dd97da2ac1c3e7','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. William Broadhead"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21H.380J','21H.380J','People and Other Animals','This course is a historical exploration of the ways that people have interacted with their closest animal relatives, for example: hunting, domestication of livestock, exploitation of animal labor, scientific study of animals, display of exotic and performing animals, and pet-keeping. Themes include changing ideas about animal agency and intelligence, our moral obligations to animals, and the limits imposed on the use of animals. Students taking the graduate version complete additional assignments.','Anthropology Cultural Anthropology History History of Science and Technology Humanities Intellectual History Social Science','2013','https://ocw.mit.edu/courses/21h-380j-people-and-other-animals-fall-2013/','https://ocw.mit.edu/courses/21h-380j-people-and-other-animals-fall-2013/pages/syllabus/','87dcde982172516bd2f49533900820324244c764cf55344fc2e6da2063ed05dd','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Harriet Ritvo"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21H.411','21H.411','History of Western Thought, 500-1300','This course examines the development of the western intellectual tradition from the fall of the Roman Empire through the High Middle Ages. Our basic premise will be that the triumph of Christianity in the west was not the inevitable outcome it might appear from hindsight. Our attention will therefore be focused not only on the development of Christian thought and practice, but on its challengers as well. The core themes of the course include the emergence of a uniform Christian orthodoxy in late antiquity; the development of monastic practice and its attendant intellectual traditions; and the geographical spread of Christian beliefs. Working in opposition to those trends were other forces, which we will also address in our readings. In particular, we will consider the persistence of northern paganism; the rise of Islam; the solidification of a separate Byzantine orthodoxy; indigenous heretical movements; and the ambiguous position of Jews in all of European society.','European History History Humanities Intellectual History Medieval History Religion','2004','https://ocw.mit.edu/courses/21h-411-history-of-western-thought-500-1300-fall-2004/','https://ocw.mit.edu/courses/21h-411-history-of-western-thought-500-1300-fall-2004/pages/syllabus/','959c563cb283b1ff9934e9b4a08a18a8b248aeac25b32cdcb752f75365a64612','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Anne McCants"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21H.504','21H.504','East Asia in the World','This subject examines the interactions of East Asia with the rest of the world and the relationships of each of the East Asian countries with each other, from ca. 1500 to 2000 A.D. Primary focus on China and Japan, with some reference to Korea, Vietnam, and Central Asia. Asks how international diplomatic, commercial, military, religious, and cultural relationships joined with internal processes to direct the development of East Asian societies. Subject addresses perceptions and misperceptions among East Asians and foreigners.','Asian History Asian Studies Business Globalization History Humanities International Relations Political Science Social Science Society','2003','https://ocw.mit.edu/courses/21h-504-east-asia-in-the-world-spring-2003/','https://ocw.mit.edu/courses/21h-504-east-asia-in-the-world-spring-2003/pages/syllabus/','7071d10e5fcc23b40f3ea7b05e7be2761e1f28ecc16376377fe60e315f12fdef','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Peter C. Perdue"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21H.601','21H.601','Islam, the Middle East, and the West','This course aims to provide students with a general overview of basic themes and issues in Middle Eastern history from the rise of Islam to the present, with an emphasis on the encounters and exchanges between the “Middle East” (Southwest Asia and North Africa) and the “West” (Europe and the United States).','History Humanities Middle Eastern History Middle Eastern Studies Society World History','2006','https://ocw.mit.edu/courses/21h-601-islam-the-middle-east-and-the-west-fall-2006/','https://ocw.mit.edu/courses/21h-601-islam-the-middle-east-and-the-west-fall-2006/pages/syllabus/','718546838777623a8d2d19b467f96dbaa5c3561941c3bea5e956349a1a7ed712','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Mériam Belli"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21H.931','21H.931','Seminar in Historical Methods','This subject is designed to give 21H majors and minors an introduction to the methods that historians use to interpret the past. We will focus on two areas: archives and interpretation. In our work on archives, we will ask what constitutes an archive. We will visit one or two local archives, speak with archivists, and assemble our own archive related to life at MIT in 2003. Once we have a better understanding of the possibilities and limitations of historical archives, we will turn to the task of interpreting archival findings. We will discuss a series of readings organized around the theme of history and national identity in various parts of the world since the end of the eighteenth century.','Comparative History Historical Methods Historiography History Humanities Modern History','2003','https://ocw.mit.edu/courses/21h-931-seminar-in-historical-methods-spring-2003/','https://ocw.mit.edu/courses/21h-931-seminar-in-historical-methods-spring-2003/pages/syllabus/','bf2785041e6f9e0dfe95aa94cf64439fc3874b13e6537bc2d309c939d5bcc2fd','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Jeffrey S. Ravel"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21H.991','21H.991','Theories and Methods in the Study of History','We will doggedly ask two questions in this class: “What is history?” and “How do you do it in 2010?” In pursuit of the answers, we will survey a variety of approaches to the past used by historians writing in the last several decades. We will examine how these historians conceive of their object of study, how they use primary sources as a basis for their accounts, how they structure the narrative and analytical discussion of their topic, and the advantages and limitations of their approaches.','Historical Methods Historiography History Humanities','2010','https://ocw.mit.edu/courses/21h-991-theories-and-methods-in-the-study-of-history-fall-2010/','https://ocw.mit.edu/courses/21h-991-theories-and-methods-in-the-study-of-history-fall-2010/pages/syllabus/','0dc325f029c1b89ad03c1b077af2461cc91d63fdfcbf4f7854d340f287b1d591','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Jeffrey S. Ravel"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21L.001X','21L.001X','Foundations of World Culture I: World Civilizations and Texts','This course aims to introduce students to the rich diversity of human culture from antiquity to the early 17th century. In this course, we will explore human culture in its myriad expressions, focusing on the study of literary, religious and philosophical texts as ways of narrating, symbolizing, and commenting on all aspects of human social and material life. We will work comparatively, reading texts from various cultures: Mesopotamian, Greek, Judeo-Christian, Chinese, Indian, and Muslim. Throughout the semester, we will be asking questions like: How have different cultures imagined themselves? What are the rules that they draw up for human behavior? How do they represent the role of the individual in society? How do they imagine ‘universal’ concepts like love, family, duty? How have their writers and artists dealt with encounters with other cultures and other civilizations?','Anthropology Classics Comparative Literature Cultural Anthropology Humanities International Literature Literature Philosophy Social Science','2011','https://ocw.mit.edu/courses/21l-001x-foundations-of-world-culture-i-world-civilizations-and-texts-fall-2011/','https://ocw.mit.edu/courses/21l-001x-foundations-of-world-culture-i-world-civilizations-and-texts-fall-2011/pages/syllabus/','fd00376d4e3e1516587d3f7be41fc67aac1a86e1ebd128c51ccddc78898fa093','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Ghenwa Hayek"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21L.003-2','21L.003-2','Reading Fiction','Reading Fiction is designed to sharpen your skills as a critical reader. As we explore both short stories and novels focusing on the theme of “the city in literature,” we will learn about the various elements that shape the way we read texts - structure, narrative voice, character development, novelistic experimentation, historical and political contexts and reader response.','Criticism Fiction Humanities Literature','2007','https://ocw.mit.edu/courses/21l-003-2-reading-fiction-spring-2007/','https://ocw.mit.edu/courses/21l-003-2-reading-fiction-spring-2007/pages/syllabus/','2b43b33578d66978db5ef550c50b100b2a59cda559efdaa7d4f7b6304d72bcdd','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Alisa Braithwaite"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21L.004','21L.004','Reading Poetry: Social Poetics','The central concern of this class is the historical relationship between the social lives of everyday people and U.S. American poetics, with a special emphasis on what June Jordan once termed the “difficult miracle of Black poetry in America.” How does poetry help us to know one another? And how might we better understand the particular role of poetry, of poiesis, for those historically barred from the very practice of reading or writing, from ownership (even of one’s own body), and various generally recognized forms of belonging? For this course, these will be some of our animating questions.','African American Studies Humanities Literature Poetry Society','2023','https://ocw.mit.edu/courses/21l-004-reading-poetry-social-poetics-spring-2023/','https://ocw.mit.edu/courses/21l-004-reading-poetry-social-poetics-spring-2023/pages/syllabus/','33ec88294f3fc081e237b842151abe21b462d25c8080e8a0b1929d5d26b68023','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Joshua Bennett"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21L.007','21L.007','World Literatures: Travel Writing','This semester, we will read writing about travel and place from Columbus’s Diario through the present. Travel writing has some special features that will shape both the content and the work for this subject: reflecting the point of view, narrative choices, and style of individuals, it also responds to the pressures of a real world only marginally under their control. Whether the traveler is a curious tourist, the leader of a national expedition, or a starving, half-naked survivor, the encounter with place shapes what travel writing can be. Accordingly, we will pay attention not only to narrative texts but to maps, objects, archives, and facts of various kinds. Our materials are organized around three regions: North America, Africa and the Atlantic world, the Arctic and Antarctic. The historical scope of these readings will allow us to know something not only about the experiences and writing strategies of individual travelers, but about the progressive integration of these regions into global economic, political, and knowledge systems. Whether we are looking at the production of an Inuit film for global audiences, or the mapping of a route across the North American continent by water, these materials do more than simply record or narrate experiences and territories: they also participate in shaping the world and what it means to us. Authors will include Olaudah Equiano, Caryl Philips, Claude Lévi-Strauss, Joseph Conrad, Jamaica Kincaid, William Least Heat Moon, Louise Erdrich, Álvar Núñez Cabeza de Vaca. Expeditions will include those of Lewis and Clark (North America), Henry Morton Stanley (Africa), Ernest Shackleton and Robert F. Scott (Antarctica).','Humanities International Literature Literature Nonfiction Prose','2008','https://ocw.mit.edu/courses/21l-007-world-literatures-travel-writing-fall-2008/','https://ocw.mit.edu/courses/21l-007-world-literatures-travel-writing-fall-2008/pages/syllabus/','fa2e9b11d7d70741f058ccacde56bb81135e14ee49ba6e2d0aebf7ed465db3ea','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Mary Fuller"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21L.012','21L.012','Forms of Western Narrative','This class will investigate the ways in which the formal aspects of Western storytelling in various media have shaped both fantasies and perceptions, making certain understandings of experience possible through the selection, arrangement, and processing of narrative material. Surveying the field chronologically across the major narrative genres and sub-genres from Homeric epic through the novel and across media to include live performance, film, and video games, we will be examining the ways in which new ideologies and psychological insights become available through the development of various narrative techniques and new technologies. Emphasis will be placed on the generic conventions of story-telling as well as on literary and cultural issues, the role of media and modes of transmission, the artistic significance of the chosen texts and their identity as anthropological artifacts whose conventions and assumptions are rooted in particular times, places, and technologies. Authors will include: Homer, Sophocles, Herodotus, Christian evangelists, Marie de France, Cervantes, La Clos, Poe, Lang, Cocteau, Disney-Pixar, and Maxis-Electronic Arts, with theoretical readings in Propp, Bakhtin, Girard, Freud, and Marx.','Comparative Literature Criticism Fiction Fine Arts Humanities International Literature Literature Media Studies','2004','https://ocw.mit.edu/courses/21l-012-forms-of-western-narrative-spring-2004/','https://ocw.mit.edu/courses/21l-012-forms-of-western-narrative-spring-2004/pages/syllabus/','e3e9c15d69d3c8a598b0c99b8133f20f837763ef8688e6018fea5eee2e3462dc','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. James Cain"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21L.020J','21L.020J','Globalization: The Good, the Bad and the In-Between','This subject examines the paradoxes of contemporary globalization. Through lectures, discussions and student presentations, we will study the cultural, linguistic, social and political impact of globalization across broad international borders. We will pay attention to the subtle interplay of history, geography, language and cultural norms that gave rise to specific ways of life. The materials for the course include fiction, nonfiction, audio pieces, maps and visual materials.','Anthropology Business Cultural Anthropology Economics Global Poverty Globalization History Humanities International Relations Language Literature Philosophy Political Philosophy Political Science Social Science Society The Developing World World History','2016','https://ocw.mit.edu/courses/21l-020j-globalization-the-good-the-bad-and-the-in-between-fall-2016/','https://ocw.mit.edu/courses/21l-020j-globalization-the-good-the-bad-and-the-in-between-fall-2016/pages/syllabus/','f89c35a12263e2927248aa6cb08fbfcfb460d690bacc41d0ded2fc2aabb8c431','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Margery Resnick","Dr. Joaquín Terrones"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21L.315','21L.315','Prizewinners','This 6-unit subject gives students the opportunity to immerse themselves in the poetry of two living Nobel Laureates: the Caribbean poet, Derek Walcott, and the Northern-Irish poet, Seamus Heaney. We will begin and end the semester with their magnificent epic works: Heaney’s translation of the Anglo-Saxon epic Beowulf, and Walcott’s Omeros (a modern epic set in the West Indies). Between these major narrative poems, we will read a rich selection of their shorter poems, as well as some of their reflections in prose on what poetry does, on what other poets do, and what it means to write in English from the historical and political situation of Northern Ireland (for Heaney) or the Caribbean (for Walcott).','Criticism Humanities Literature Poetry','2007','https://ocw.mit.edu/courses/21l-315-prizewinners-spring-2007/','https://ocw.mit.edu/courses/21l-315-prizewinners-spring-2007/pages/syllabus/','32738262e8fa67991eb6203993049f34a3eeefb6c54f977a86933e9c4468b911','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Mary Fuller"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21L.423J','21L.423J','Introduction to Anglo-American Folk Music','This course examines the production, transmission, preservation and qualities of folk music in the British Isles and North America from the 18th century to the folk revival of the 1960s and the present. There is a special emphasis on balladry, fiddle styles, and African-American influences. The class sings ballads and folk songs from the Child and Lomax collections as well as other sources as we examine them from literary, historical, and musical points of view. Readings supply critical and background materials from a number of sources. Visitors and films bring additional perspectives.','Fine Arts Music Music History Performance Arts','2005','https://ocw.mit.edu/courses/21l-423j-introduction-to-anglo-american-folk-music-fall-2005/','https://ocw.mit.edu/courses/21l-423j-introduction-to-anglo-american-folk-music-fall-2005/pages/syllabus/','5ca4420f202835fe94e782641420732f244a105208b08c47eb8696016176ed7b','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. George Ruckert","Prof. Ruth Perry"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21L.434','21L.434','The Science Fiction of Freedom','What does it mean to be free? Is freedom a state of mind? An inalienable property of the self? The absence of coercive or oppressive structures? Such questions often inspire philosophers to develop thought experiments about alternative worlds. These same questions lie at the heart of many major works in science fiction. This subject will put the two together—philosophy and science fiction—to consider speculative techniques for imagining freedom.','Fiction Humanities Literature Society','2024','https://ocw.mit.edu/courses/21l-434-the-science-fiction-of-freedom-fall-2024/','https://ocw.mit.edu/courses/21l-434-the-science-fiction-of-freedom-fall-2024/pages/syllabus/','ceb888b6a0a330e2fd4e0c0a1d4067edf95da0f5a0dbfb72c2642a7ac02d57d0','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Ben Mangrum"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21L.451','21L.451','Introduction to Literary Theory','This subject examines the ways in which we read. It introduces some important strategies for engaging with literary texts developed in the twentieth century, paying special attention to poststructuralist theories and their legacy. The course is organized around specific theoretical paradigms. In general, we will: (1) work through the selected readings in order to see how they construe what literary interpretation is; (2) locate the limits of each particular approach; and (3) trace the emergence of subsequent theoretical paradigms as responses to what came before.','Criticism Film and Video Fine Arts Humanities Literature Philosophy Visual Arts','2014','https://ocw.mit.edu/courses/21l-451-introduction-to-literary-theory-fall-2014/','https://ocw.mit.edu/courses/21l-451-introduction-to-literary-theory-fall-2014/pages/syllabus/','352968e5b43893232533f97216b0ed8af4e30b0ba9034c3377dc719e06e0de87','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Shankar Raman"]','no_formal_course','This course has no prerequisites.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21L.460','21L.460','Medieval Literature: Medieval Women Writers','This survey provides a general introduction to medieval European literature (from Late Antiquity to the Fifteenth Century) from the perspective of women writers from a variety of cultures, social backgrounds, and historical timeperiods. Though much of the class will be devoted to exploring the evolution of a new literary tradition by and for women from its earliest emergence in the West, wider historical and cultural movements will also be addressed: the Fall of the Roman Empire, the growth of religious communities, the shift from orality to literacy, the culture of chivalry and courtly love, the emergence of scholasticism and universities, changes in devotional practices, the persecution of heretics, the rise of nationalism and class consciousness. Authors will include some of the most famous women of the period: Hildegard of Bingen, Heloise of Paris, Marie de France, Christine de Pizan, Joan of Arc, Margery Kempe, along with many interesting and intriguing though lesser known figures.','Criticism History Humanities International Literature Literature Medieval History Society Women''s Studies','2004','https://ocw.mit.edu/courses/21l-460-medieval-literature-medieval-women-writers-spring-2004/','https://ocw.mit.edu/courses/21l-460-medieval-literature-medieval-women-writers-spring-2004/pages/syllabus/','411103c7e8e9574990e9c199ccd6e9bc0a88ade345dd3a4b23eaacf8b7e7b0f8','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. James Cain"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21L.472','21L.472','Major European Novels','This subject traces the history of the European novel by studying texts that have been influential in connection with two interrelated ideas. (1) When serious fiction deals with matters of great consequence, it should not deal with the actions of persons of consequence—kings, princes, high elected officials and the like—but rather with the lives of apparently ordinary people and the everyday details of their social ambitions and desires. To use a phrase of Balzac’s, serious fiction deals with “what happens everywhere”. (2) This idea sometimes goes with another: that the most significant representations of the human condition are those dealing with persons who try to compel society to accept them as its destined agent, despite their absence of high birth or inheritance.','Criticism Fiction Humanities International Literature Literature','2008','https://ocw.mit.edu/courses/21l-472-major-european-novels-fall-2008/','https://ocw.mit.edu/courses/21l-472-major-european-novels-fall-2008/pages/syllabus/','e6ba9965024e7d02018dea41af030c8194510542e052603e808a60afa123c1ef','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Alvin Kibel"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21L.488','21L.488','Contemporary Literature: Literature, Development, and Human Rights','Central to our era is the gradual movement of all the world’s regions toward a uniform standard of economic and political development. In this class we will read a variety of recent narratives that partake of, dissent from, or contribute to this story, ranging from novels and poems to World Bank and IMF statements and National Geographic reports. We will seek to understand the many motives and voices – sometimes congruent, sometimes clashing – that are currently engaged in producing accounts of people in the developing world: their hardships, laughter, and courage, and how they help themselves and are helped by outsiders who may or may not have philanthropic motives. Readings will include literature by J. G. Ballard, Jamaica Kincaid, Rohinton Mistry, and John le Carré, as well as policy documents, newspaper and magazine articles, and the Web sites of a variety of trade and development commissions and organizations.','Criticism Humanities Literature Philosophy Political Philosophy Social Justice Social Science Society Sociology The Developing World','2008','https://ocw.mit.edu/courses/21l-488-contemporary-literature-literature-development-and-human-rights-spring-2008/','https://ocw.mit.edu/courses/21l-488-contemporary-literature-literature-development-and-human-rights-spring-2008/pages/syllabus/','9f39b332e886b7b9268c6a9c35d24e1ed3bcc63ebace6ff29e8c94c1a156f225','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Sarah Brouillette"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21L.512','21L.512','American Authors: American Women Authors','This subject, cross-listed in Literature and Women’s Studies, examines a range of American women authors from the seventeenth century to the present. It aims to introduce a number of literary genres and styles- the captivity narrative, slave novel, sensational, sentimental, realistic, and postmodern fiction- and also to address significant historical events in American women’s history: Puritanism, the American Revolution, industrialization and urbanization in the nineteenth century, the Harlem Renaissance, World War II, the 60s civil rights movements. A primary focus will be themes studied and understood through the lens of gender: war, violence, and sexual exploitation (Keller, Rowlandson, Rowson); the relationship between women and religion (Rowlandson, Rowson, Stowe); labor, poverty, and working conditions for women (Fern, Davis, Wharton); captivity and slavery (Rowlandson, Jacobs); class struggle (Fern, Davis, Wharton, Larsen); race and identity (Keller, Jacobs, Larsen, Morrison); feminist revisions of history (Stowe, Morrison, Keller); and the myth of the fallen woman (take your pick). Essays and in-class reports will focus more particularly on specific writers and themes and will stress the skills of close reading, annotation, research, and uses of multimedia where appropriate.','American Literature Criticism Gender Studies Humanities Literature Society Women''s Studies','2003','https://ocw.mit.edu/courses/21l-512-american-authors-american-women-authors-spring-2003/','https://ocw.mit.edu/courses/21l-512-american-authors-american-women-authors-spring-2003/pages/syllabus/','b243019a15199511680844b7245660897dbeaa88df277cb33dfc86833b658358','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Wyn Kelley"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21L.701','21L.701','Literary Interpretation: Literature and Photography: The Image','This course introduces the practice and theory of literary criticism. The seminar focuses on topics such as the history of critical methods and techniques, and the continuity of certain subjects in literary history. Instruction and practice in oral and written communication is a major component of the course. Other components include theory and use of figurative language and reading poetry.','Comparative Literature Criticism Fine Arts Humanities Literature Philosophy Philosophy of Language Photography Poetry Visual Arts','2005','https://ocw.mit.edu/courses/21l-701-literary-interpretation-literature-and-photography-the-image-fall-2005/','https://ocw.mit.edu/courses/21l-701-literary-interpretation-literature-and-photography-the-image-fall-2005/pages/syllabus/','32a8571a4ad711a8dda285f66659ed965c390797208ae5237bb940f7fbf19d45','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Marja Roholl","Prof. Stephen Tapscott"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21L.703','21L.703','Studies in Drama: Stoppard and Company','Taking as its starting point the works of one of Britain’s most respected, prolific—and funny—living dramatists, this seminar will explore a wide range of knowledge in fields such as math, philosophy, politics, history and art. The careful reading and discussion of plays by (Sir) Tom Stoppard and some of his most compelling contemporaries (including Caryl Churchill, Anna Deveare Smith and Howard Barker) will allow us to time-travel and explore other cultures, and to think about the medium of drama as well as one writer’s work in depth. Some seminar participants will report on earlier plays that influenced these writers, others will research everything from Lord Byron’s poetry to the bridges of Konigsberg, from Dadaism to Charter 77. Employing a variety of critical approaches (both theoretical and theatrical), we will consider what postmodernity means, as applied to these plays. In the process, we will analyze how drama connects with both the culture it represents and that which it addresses in performance. We will also explore the wit and verbal energy of these contemporary dramatists…not to mention, how Fermat’s theorem, classical translation, and chaos theory become the stuff of stage comedy.','Criticism Drama Fine Arts Humanities Literature Performance Arts Theater','2014','https://ocw.mit.edu/courses/21l-703-studies-in-drama-stoppard-and-company-spring-2014/','https://ocw.mit.edu/courses/21l-703-studies-in-drama-stoppard-and-company-spring-2014/pages/syllabus/','5ef7c67e4f11b24d17636ac8184509dde6e1a554b6e672247358de41e18da2ec','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Diana Henderson"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21L.704','21L.704','Studies in Poetry: From the Sonneteers to the Metaphysicals','This course introduces students to some of the most important practitioners of poetry in sixteenth- and seventeenth-century England, locating them in their historical and social contexts. We will be emphasizing love poetry or amatory verse, by combining close reading of selected poems with an investigation of the contexts of English verse.','Criticism Humanities Literature Poetry','2006','https://ocw.mit.edu/courses/21l-704-studies-in-poetry-from-the-sonneteers-to-the-metaphysicals-spring-2006/','https://ocw.mit.edu/courses/21l-704-studies-in-poetry-from-the-sonneteers-to-the-metaphysicals-spring-2006/pages/syllabus/','efc3d70836538a7957e65d6ed72110e258f0f2434f343650b3abb65ae1138321','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Shankar Raman"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21L.705','21L.705','Major Authors: Melville and Morrison','This seminar provides intensive study of texts by two American authors (Herman Melville, 1819-1891, and Toni Morrison, 1931-) who, using lyrical, radically innovative prose, explore in different ways epic notions of American identity. Focusing on Melville’s Typee (1846), Moby-Dick (1851), and The Confidence-Man (1857) and Morrison’s Sula (1973), Beloved (1987), Jazz (1992), and Paradise (1998), the class will address their common concerns with issues of gender, race, language, and nationhood. Be prepared to read deeply (i.e. a small number of texts with considerable care), to draw on a variety of sources in different media, and to employ them in creative research, writing, and multimedia projects.','American Literature Criticism Fiction Fine Arts Humanities Literature Media Studies Society Women''s Studies','2003','https://ocw.mit.edu/courses/21l-705-major-authors-melville-and-morrison-fall-2003/','https://ocw.mit.edu/courses/21l-705-major-authors-melville-and-morrison-fall-2003/pages/syllabus/','c7619f8a0816b6c2d0e14f41a6e349f720979e0bb468d535a5c59d259c65d39c','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Wyn Kelley"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21L.707','21L.707','Writing Early American Lives: Gender, Race, Nation, Faith','This course focuses on the period between roughly 1550-1850. American ideas of race had taken on a certain shape by the middle of the nineteenth century, consolidated by legislation, economics, and the institution of chattel slavery. But both race and identity meant very different things three hundred years earlier, both in their dictionary definitions and in their social consequences. How did people constitute their identities in early America, and how did they speak about these identities? Texts will include travel writing, captivity narratives, orations, letters, and poems, by Native American, English, Anglo-American, African, and Afro-American writers.','African American Studies American Literature Comparative Literature Criticism Gender Studies Humanities Literature Society','2005','https://ocw.mit.edu/courses/21l-707-writing-early-american-lives-gender-race-nation-faith-fall-2005/','https://ocw.mit.edu/courses/21l-707-writing-early-american-lives-gender-race-nation-faith-fall-2005/pages/syllabus/','88f2f0c02663467262eb26856846fe79860935e40a25bfa842b91eb27afd0f7c','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Mary Fuller"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21L.715','21L.715','Media in Cultural Context','This course explores the international trade in television text, considering the ways in which ‘foreign’ programs find places within ‘domestic’ schedules. Looking at the life television texts maintain outside of their home market, this course examines questions of globalization and national cultures of production and reception. Students will be introduced to a range of positions about the nature of international textual trade, including economic arguments about the structuring of international markets and ethnographic studies about the role imported content plays in the formation of hybrid national identities. Students will be encouraged to consider the role American content is made to play in non-American markets.','Anthropology Business Criticism Cultural Anthropology Fine Arts Globalization Humanities Literature Media Studies Social Science','2007','https://ocw.mit.edu/courses/21l-715-media-in-cultural-context-spring-2007/','https://ocw.mit.edu/courses/21l-715-media-in-cultural-context-spring-2007/pages/syllabus/','65200cbca531ac4e166e98d4477afc2ac670812233e3c228decede3d125a8337','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Joshua Green"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21M.030','21M.030','Introduction to World Music','This course is an introduction to diverse musical traditions of the world. Music from a wide range of geographical areas is studied in terms of structure, performance practice, social use, aesthetics, and cross-cultural contact. Course work includes hands-on music making, live demonstrations by guest artists, and ethnographic research projects.','Anthropology Cultural Anthropology Dance Fine Arts Music Music History Music Performance Music Theory Performance Arts Social Science','2013','https://ocw.mit.edu/courses/21m-030-introduction-to-world-music-spring-2013/','https://ocw.mit.edu/courses/21m-030-introduction-to-world-music-spring-2013/pages/syllabus/','35397ef6222bdacdfed167b0c1eee92ebcda985bcee15f1a8ba1328675c8d4c9','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Patricia Tang"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21M.250','21M.250','Beethoven to Mahler','This course surveys Romantic musical genres including song, choral music, opera, piano sonata, character cycle, concerto, symphony, and symphonic poem, including the composers Beethoven, Schubert, Berlioz, Chopin, Brahms, Wagner, Verdi, Tchaikovsky, and Mahler. Written essays and oral presentations are based on live performances as well as listening and reading assignments.','Fine Arts Music Music History','2014','https://ocw.mit.edu/courses/21m-250-beethoven-to-mahler-spring-2014/','https://ocw.mit.edu/courses/21m-250-beethoven-to-mahler-spring-2014/pages/syllabus/','73638c8cf92bc795f2ea0687154195da5eac2b05bf2c8293b945ee088d4f6f2c','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Teresa M. Neff"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21M.271','21M.271','Symphony and Concerto','This course is a survey of significant orchestral masterworks composed during three centuries. Listening assignments include 34 symphonies and 24 concertos, composed from the 1720s to the 1990s. Class discussion and oral presentations focus on the works in 18 miniature scores; prior score-reading experience is helpful. Each of the three written papers reviews a concert attended during the term. Since this is a participatory subject, each student will give oral presentations concerning composers and their symphonies and/or concertos.','Fine Arts Music Music History Music Theory','2007','https://ocw.mit.edu/courses/21m-271-symphony-and-concerto-spring-2007/','https://ocw.mit.edu/courses/21m-271-symphony-and-concerto-spring-2007/pages/syllabus/','07ec08849fecc8ec5c291f1f507b7541d8d8c48f7a95f510ca186b62f763a499','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Lowell Lindgren"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21M.299','21M.299','The Beatles','This class surveys the music of the Beatles, from the band’s early years to the break-up of the group, mapping how the Beatle’s musical style changed from skiffle and rock to studio-based experimentation. Cultural influences that helped to shape them, as well as the group’s influence worldwide, will be a continuous theme.','Film and Video Fine Arts Music Music History Visual Arts','2017','https://ocw.mit.edu/courses/21m-299-the-beatles-fall-2017/','https://ocw.mit.edu/courses/21m-299-the-beatles-fall-2017/pages/syllabus/','78f0a7ff0c6d8c9a176c9857f695f24ff43bd96cff7eed785295e566338a2f44','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Teresa M. Neff"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21M.351','21M.351','Music Composition','This course features directed composition of larger forms of original writing involving voices and/or instruments. It includes a weekly seminar in composition for the presentation and discussion of work in progress. Students are expected to produce at least one substantive work, performed in public, by the end of the term. Contemporary compositions and major works from 20th-century music literature are studied.','Fine Arts Music Music History Music Performance Music Theory','2008','https://ocw.mit.edu/courses/21m-351-music-composition-fall-2008/','https://ocw.mit.edu/courses/21m-351-music-composition-fall-2008/pages/syllabus/','d4f0df2b29a045f3f4ddfae17a24a21b5e9b5c968a3ae5308ed1bb7a8c41819a','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Peter Child"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21M.380','21M.380','Music and Technology: Recording Techniques and Audio Production','This course is an introduction to music recording and audio production from both a practical and a theoretical perspective. Learn about the physical nature and human perception of sound, how it is transformed to and from electrical signals by means of microphones and loudspeakers, and how it can be creatively modeled through mixing consoles, signal processors, and digital audio workstations. The course covers making informed choices about microphone selection and positioning, and various editing, mixing, and mastering techniques.','Digital Media Electrical Engineering Engineering Fine Arts Media Studies Music Music History Music Performance Music Theory Signal Processing','2016','https://ocw.mit.edu/courses/21m-380-music-and-technology-recording-techniques-and-audio-production-fall-2016/','https://ocw.mit.edu/courses/21m-380-music-and-technology-recording-techniques-and-audio-production-fall-2016/pages/syllabus/','8f40854f73ef87648eb3eebc5690f2e52fb994c0da96c11bd99b50f7b4e2f1bc','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Florian Hollerweger"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21M.542','21M.542','Interdisciplinary Approaches to Musical Time','This course is an interdisciplinary exploration of three broad topics concerning music in relation to time. Music as Architecture: the creation of musical shapes in time; Music as Memory: how musical understanding depends upon memory and reminiscence, with attention to analysis of musical structures; and Time as the Substance of Music: how different disciplines such as philosophy and neuroscience view the temporal dimension of musical processes and/or performances. Classroom discussion of these topics is complemented by three weekend concerts with pre-concert forums, jointly presented by the Boston Chamber Music Society (BCMS) and MIT Music & Theater Arts.','Cognitive Science Fine Arts Humanities Music Music Theory Philosophy Science','2010','https://ocw.mit.edu/courses/21m-542-interdisciplinary-approaches-to-musical-time-january-iap-2010/','https://ocw.mit.edu/courses/21m-542-interdisciplinary-approaches-to-musical-time-january-iap-2010/pages/syllabus/','eacd25973975cb0224d51069b92e6406276cd166274360687a9cb886384823e7','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Martin Marks","Prof. Marcus A Thompson","Prof. Charles Shadle"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21T.1002','21T.1002','Traditions in American Concert Dance: Gender and Autobiography','This course explores the forms, contents, and context of world traditions in dance that played a crucial role in shaping American concert dance. For example, we will identify dances from an African American vernacular tradition that were transferred from the social space to the concert stage. We will explore the artistic lives of such American dance artists as Katherine Dunham, Pearl Primus, and Alvin Ailey along with Isadora Duncan, Martha Graham, George Balanchine, and Merce Cunningham as American dance innovators. Of particular importance to our investigation will be the construction of gender and autobiography that lie at the heart of concert dance practice, and the ways in which these qualities have been choreographed by American artists.','African American Studies Anthropology Dance Ethnography Fine Arts Gender Studies Performance Arts Social Science Society Women''s Studies','2008','https://ocw.mit.edu/courses/21m-670-traditions-in-american-concert-dance-gender-and-autobiography-spring-2008/','https://ocw.mit.edu/courses/21m-670-traditions-in-american-concert-dance-gender-and-autobiography-spring-2008/pages/syllabus/','eea7165b1d9f7770e6f67b106bb0065c648ed6b816bf6567343399f491f71a83','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Melissa Blanco"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21T.220','21T.220','Design for the Theater: Scenery','This course will examine theory of scenic design as currently practiced, as well as historical traditions for use of performance space and audience/performer engagement. Four play scripts and one opera or dance theater piece will be designed after in-depth analysis; emphasis will be on the social, political and cultural milieu at the time of their creation, and now.','Fine Arts Performance Arts Theatrical Design','2005','https://ocw.mit.edu/courses/21m-734-design-for-the-theater-scenery-spring-2005/','https://ocw.mit.edu/courses/21m-734-design-for-the-theater-scenery-spring-2005/pages/syllabus/','7ae2028bbef39d995ebe651db4d92a5a5e098d37ee837889e0f6606d6a62730b','https://creativecommons.org/licenses/by-nc-sa/4.0/','["William Fregosi"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21T.423','21T.423','Theater Arts Topics','Directed practice in acting, directing, or design on a sustained theater piece, either one-act or full length, from pre-rehearsal preparation to workshop production.','Fine Arts Performance Arts Theater Theatrical Design','2004','https://ocw.mit.edu/courses/21m-873-theater-arts-topics-fall-2004-january-iap-2005/','https://ocw.mit.edu/courses/21m-873-theater-arts-topics-fall-2004-january-iap-2005/pages/syllabus/','a79e49baa286d1a2bf326c9e4477f78cf4571804809403f0def24a5a8b8192a5','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Janet Sonenberg"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21W.022','21W.022','Writing and Experience: Reading and Writing Autobiography','The reading and writing in this course will focus on the art of self-narrative or autobiographical writing. Such writing can be crafted in the form of a longer autobiography or of separate, shorter autobiographically-inspired essays. The various forms of autobiographical narrative can both reflect on personal experience and comment on larger issues in society. This course explores, through reading and writing, what it means to construct a sense of self-and a life narrative-in relation to the larger social world of family and friends, education, media, work, and community. What does it mean to see ourselves as embodying particular ethical values or belonging to a certain ethnic, racial, national or religious group(s)? How do we imagine ourselves within larger “family narrative(s)” and friendship groups? In what ways do we view our identities as connected to and expressed by our educational and work experiences, including experiences at MIT? How do we see ourselves as shaping and shaped by the popular media culture of our society? How do we think about our ethical and social responsibility to our friends, families and communities (large and small)? Readings will include autobiographically-inspired nonfiction and fiction.','Creative Writing Fine Arts Humanities Literature Media Studies','2014','https://ocw.mit.edu/courses/21w-022-03-writing-and-experience-reading-and-writing-autobiography-spring-2014/','https://ocw.mit.edu/courses/21w-022-03-writing-and-experience-reading-and-writing-autobiography-spring-2014/pages/syllabus/','97ecb33b7c9a391c321d049ba11c094201eeedea75aeecae6ed01c9d2a57d294','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Andrea Walsh"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21W.731-1','21W.731-1','Writing and Experience: Exploring Self in Society','The reading and writing for this course will focus on what it means to construct a sense of self and a life narrative in relation to the larger social world of family and friends, education, media, work, and community. Readings will include nonfiction and fiction works by authors such as Maya Angelou, James Baldwin, Andre Dubus, Anne Frank, Tim O’Brien, Flannery O’Connor, George Orwell, John Steinbeck, Amy Tan, Tobias Wolff, and Alice Walker. Students will explore the craft of storytelling and the multiple ways in which one can employ the tools of fiction in crafting creative nonfiction and fiction narratives.','Creative Writing Criticism Fiction Humanities Literature Nonfiction Prose','2004','https://ocw.mit.edu/courses/21w-731-1-writing-and-experience-exploring-self-in-society-spring-2004/','https://ocw.mit.edu/courses/21w-731-1-writing-and-experience-exploring-self-in-society-spring-2004/pages/syllabus/','8472af325e105576d7945349e50195b82d44ba49e93cebc4544c1ff6b7c1a692','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Andrea Walsh"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21W.747-2','21W.747-2','Rhetoric: Rhetoric of Science','This course is an introduction to the history, theory, practice, and implications of rhetoric, the art and craft of persuasion. This course specifically focuses on the ways that scientists use various methods of persuasion in the construction of scientific knowledge.','Communication Criticism Humanities Literature Nonfiction Prose Rhetoric Social Science Technical Writing','2006','https://ocw.mit.edu/courses/21w-747-2-rhetoric-rhetoric-of-science-spring-2006/','https://ocw.mit.edu/courses/21w-747-2-rhetoric-rhetoric-of-science-spring-2006/pages/syllabus/','5efa2af617ac443edd36c515855646396afa76aea505069b2b06ebad8afb39c7','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Mya Poe"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21W.758','21W.758','Genre Fiction Workshop: Fantasy','Fantasy is currently one of the most popular genres across every platform in fiction. From film to gaming to literature, fantasy tops the charts. Why? Why do people who believe in democracy and live with the magic technology appear to long for wizards and dragons and the matters of kingship? In this class, we will explore this question, and from that base read articles, novels, write exercises and stories in this genre.','Creative Writing Fiction Humanities Literature','2016','https://ocw.mit.edu/courses/21w-758-genre-fiction-workshop-fantasy-fall-2016/','https://ocw.mit.edu/courses/21w-758-genre-fiction-workshop-fantasy-fall-2016/pages/syllabus/','82f0483aa0bf9843903aa24d7a64c1ae94abb9a183ddf9bf42cfb92ca382a3d9','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Shariann Lewitt"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('21W.777','21W.777','Science Writing in Contemporary Society','This class addresses the craft of writing about science in and for contemporary society, both its pleasures and its challenges. We will read essays, reportage, op-eds, and web-based articles on a variety of topics concerning science, technology, medicine and nature. Readings by contemporary writers such as Elizabeth Kolbert, Atul Gawande, and Michael Pollan will serve as examples of the craft and sources of ideas for our own writing.','Academic Writing Creative Writing Criticism Humanities Literature Nonfiction Prose','2017','https://ocw.mit.edu/courses/21w-777-science-writing-in-contemporary-society-spring-2017/','https://ocw.mit.edu/courses/21w-777-science-writing-in-contemporary-society-spring-2017/pages/syllabus/','42cd21b99cf6fb3f56741a78854c5c7a4f7904bddad9bdbf8295997289f09c01','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Karen Boiko"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('22.011','22.011','Nuclear Engineering: Science, Systems and Society','In this exploratory seminar, first-year undergraduate students learn the basic physics of nuclear energy and radiation, and learn to communicate their knowledge and perspective by writing a traditional Op-Ed piece. The technical content emphasizes the unique attributes and challenges of nuclear energy as a low-carbon solution as well as the peaceful applications of ionizing radiation to help humankind. The open-ended writing project combines personal creativity and technical knowledge to share important messages about science. The course employs blended learning, as students use the online course 22.011x , freely available on the MIT Open Learning Library , to learn the technical content, and meet together in person for the communication component, developing and polishing their Op-Eds.','Climate Communication Energy Hydrogen and Alternatives Nuclear Energy Social Science Technology','2020','https://ocw.mit.edu/courses/22-011-nuclear-engineering-science-systems-and-society-spring-2020/','https://ocw.mit.edu/courses/22-011-nuclear-engineering-science-systems-and-society-spring-2020/pages/syllabus/','d684c877016ffec297eb96d2702684262ebb0bfe2cb03fa49cbcc13b5656685c','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Marina Dang","Prof. Michael Short","Prof. Anne E. White"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('22.06','22.06','Engineering of Nuclear Systems','In this course, students explore the engineering design of nuclear power plants using the basic principles of reactor physics, thermodynamics, fluid flow and heat transfer. Topics include reactor designs, thermal analysis of nuclear fuel, reactor coolant flow and heat transfer, power conversion cycles, nuclear safety, and reactor dynamic behavior.','Engineering Nuclear Engineering Nuclear Physics Nuclear Systems, Policy, and Economics Physics Science','2010','https://ocw.mit.edu/courses/22-06-engineering-of-nuclear-systems-fall-2010/','https://ocw.mit.edu/courses/22-06-engineering-of-nuclear-systems-fall-2010/pages/syllabus/','bafa3ee747a19ff703617f726525dbf2aefc7fc60415d82139c0d5703c42aedd','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Jacopo Buongiorno"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('22.105','22.105','Electromagnetic Interactions','This course is a graduate level subject on electromagnetic theory with particular emphasis on basics and applications to Nuclear Science and Engineering. The basic topics covered include electrostatics, magnetostatics, and electromagnetic radiation. The applications include transmission lines, waveguides, antennas, scattering, shielding, charged particle collisions, Bremsstrahlung radiation, and Cerenkov radiation. Acknowledgments Professor Freidberg would like to acknowledge the immense contributions made to this course by its previous instructors, Ian Hutchinson and Ron Parker.','Electromagnetism Engineering Nuclear Engineering Nuclear Physics Physics Science','2005','https://ocw.mit.edu/courses/22-105-electromagnetic-interactions-fall-2005/','https://ocw.mit.edu/courses/22-105-electromagnetic-interactions-fall-2005/pages/syllabus/','9adf193ef7798ea277b9b37a2da18260330314ee9057149686caa4d3b005fa6d','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Jeffrey Freidberg"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('22.313J','22.313J','Thermal Hydraulics in Power Technology','This course covers the thermo-fluid dynamic phenomena and analysis methods for conventional and nuclear power stations. Specific topics include: kinematics and dynamics of two-phase flows; steam separation; boiling, instabilities, and critical conditions; single-channel transient analysis; multiple channels connected at plena; loop analysis including single and two-phase natural circulation; and subchannel analysis.','Energy Engineering Fluid Mechanics Fossil Fuels Mechanical Engineering Nuclear Energy Nuclear Engineering Physics Science Thermodynamics','2007','https://ocw.mit.edu/courses/22-313j-thermal-hydraulics-in-power-technology-spring-2007/','https://ocw.mit.edu/courses/22-313j-thermal-hydraulics-in-power-technology-spring-2007/pages/syllabus/','b2e8aae40f69629fce13bed20178ac2fb1926cac3e08ad3184ed65778f007ee5','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Jacopo Buongiorno"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('22.55J','22.55J','Principles of Radiation Interactions','The central theme of this course is the interaction of radiation with biological material. The course is intended to provide a broad understanding of how different types of radiation deposit energy, including the creation and behavior of secondary radiations; of how radiation affects cells and why the different types of radiation have very different biological effects. Topics will include: the effects of radiation on biological systems including DNA damage; in vitro cell survival models; and in vivo mammalian systems. The course covers radiation therapy, radiation syndromes in humans and carcinogenesis. Environmental radiation sources on earth and in space, and aspects of radiation protection are also discussed. Examples from the current literature will be used to supplement lecture material.','Chemistry Electromagnetism Engineering Nuclear Engineering Nuclear Physics Physical Chemistry Physics Radiological Engineering Science','2004','https://ocw.mit.edu/courses/22-55j-principles-of-radiation-interactions-fall-2004/','https://ocw.mit.edu/courses/22-55j-principles-of-radiation-interactions-fall-2004/pages/syllabus/','9ad0cb1aa45e1471431624356c21d7b7c185002a244bab22d3049aaa25aafd38','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Jeffrey Coderre"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('22.67J','22.67J','Principles of Plasma Diagnostics','This course is an introduction to the physical processes used to measure the properties of plasmas. It will cover diagnostics suitable for a wide range of plasmas, including magnetically confined fusion plasmas and high-energy-density plasmas. Techniques include the measurements of magnetic and electric fields, particle flux, refractive index, emission and scattering of electromagnetic waves, and nuclear diagnostics.','Nuclear Physics Physics Science','2023','https://ocw.mit.edu/courses/22-67j-principles-of-plasma-diagnostics-fall-2023/','https://ocw.mit.edu/courses/22-67j-principles-of-plasma-diagnostics-fall-2023/pages/syllabus/','dc2cc7aae08bbbf2f888280ff8dbd02b2953044bfa57a917dd128a8bb113cfe7','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Jack D. Hare"]','structured','22.611J Introduction to Plasma Physics I') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('22.67J',0,'22.611J');
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('22.A09','22.A09','Career Options for Biomedical Research','This course has been designed as a seminar to give students an understanding of how scientists with medical or scientific degrees conduct research in both hospital and academic settings. There will be interactive discussions with research clinicians and scientists about the career opportunities and research challenges in the biomedical field, which an MIT student might prepare for by obtaining an MD, PhD, or combined degrees. The seminar will be held in a case presentation format, with topics chosen from the radiological sciences, including current research in magnetic resonance imaging, positron emission tomography and other nuclear imaging techniques, and advances in radiation therapy. With the lectures as background, we will also examine alternative and related options such as biomedical engineering, medical physics, and medical engineering. We’ll use as examples and points of comparisons the curriculum paths available through MIT’s Department of Nuclear Science and Engineering. In past years we have given very modest assignments such as readings in advance of or after a seminar, and a short term project.','Biomedicine Engineering Health and Medicine Medical Imaging Nuclear Engineering Radiological Engineering','2006','https://ocw.mit.edu/courses/22-a09-career-options-for-biomedical-research-fall-2006/','https://ocw.mit.edu/courses/22-a09-career-options-for-biomedical-research-fall-2006/pages/syllabus/','0cf16d1b12cc64370d4dda271d48f4a620268b226c5b7e4e8751ac90094aec2d','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Bruce Rosen","Prof. Sidney Yip","Xin He"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('24.04J','24.04J','Justice','This course explores the ideal of social justice. What makes a society just? We will approach this question by studying three opposing theories of justice—utilitarianism, libertarianism, and egalitarian liberalism—each foundational to contemporary political thought and discourse.','Ethics Humanities Philosophy Political Science Social Justice Social Science Sociology','2012','https://ocw.mit.edu/courses/24-04j-justice-spring-2012/','https://ocw.mit.edu/courses/24-04j-justice-spring-2012/pages/syllabus/','020adec78a679d121def6ff7f890e0fac0417656e55600356c8e00758a9b26a6','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Lucas Stanczyk"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('24.120','24.120','Moral Psychology','This course is an examination of philosophical theories of action and motivation in the light of empirical findings from social psychology, sociology, and neuroscience. Topics include belief, desire, and moral motivation; sympathy and empathy; intentions and other committing states; strength of will and weakness of will; free will; addiction and compulsion; guilt, shame and regret; evil; self-knowledge and self-deception; and, virtues and character traits. This course is a CI-M course.','Ethics Humanities Philosophy Psychology Social Science','2009','https://ocw.mit.edu/courses/24-120-moral-psychology-spring-2009/','https://ocw.mit.edu/courses/24-120-moral-psychology-spring-2009/pages/syllabus/','9e6884119c0455ab105c053e071bb7cc5688373a40fd1b03fb4893ae9657ac3a','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Richard Holton"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('24.209','24.209','Philosophy In Film and Other Media','This course examines works of film in relation to thematic issues of philosophical importance that also occur in other arts, particularly literature and opera. Emphasis is put on film’s ability to represent and express feeling as well as cognition. Both written and cinematic works by Sturges, Shaw, Cocteau, Hitchcock, Joyce, and Bergman, among others, are considered. There are no tests or quizzes, however students write two major papers on media/philosophical research topics of their choosing.','Film and Video Fine Arts Humanities Literature Media Studies Philosophy Visual Arts','2004','https://ocw.mit.edu/courses/24-209-philosophy-in-film-and-other-media-spring-2004/','https://ocw.mit.edu/courses/24-209-philosophy-in-film-and-other-media-spring-2004/pages/syllabus/','a4a1581ce45b984c7d930557d6b40e42225a005f963530da4adcf0ddd81e3847','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Irving Singer"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('24.231','24.231','Ethics','This will be a seminar on classic and contemporary work on central topics in ethics. The first third of the course will focus on metaethics : we will examine the meaning of moral claims and ask whether there is any sense in which moral principles are objectively valid. The second third of the course will focus on normative ethics : what makes our lives worth living, what makes our actions right or wrong, and what do we owe to others? The final third of the course will focus on moral character : what is virtue, and how important is it? Can we be held responsible for what we do? When and why?','Ethics Humanities Philosophy','2009','https://ocw.mit.edu/courses/24-231-ethics-fall-2009/','https://ocw.mit.edu/courses/24-231-ethics-fall-2009/pages/syllabus/','0d158f77b47b44fac62856f23c99971d2f29391c699e894ae2b57cc5e4805fc0','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Julia Markovits"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('24.251','24.251','Introduction to Philosophy of Language','This course explores the nature of meaning and truth, and their bearing on the use of language in communication. No knowledge of logic or linguistics is presupposed.','Humanities Linguistics Philosophy Philosophy of Language','2011','https://ocw.mit.edu/courses/24-251-introduction-to-philosophy-of-language-fall-2011/','https://ocw.mit.edu/courses/24-251-introduction-to-philosophy-of-language-fall-2011/pages/syllabus/','709b2b7552e4a17b908c9f79c78fb30615f4312df62a3dc939a1aefa597d74b9','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Stephen Yablo"]','review_required','It is recommended that students take one philosophy subject before taking this course.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('24.900','24.900','Introduction to Linguistics','This class provides some answers to basic questions about the nature of human language. Throughout the course, we examine a number of ways in which human language is a complex but law-governed mental system. Much of the class is devoted to studying some core aspects of this system in detail; we also spend individual classes discussing a number of other issues, including how language is acquired, how languages change over time, language endangerment, and others.','Humanities Linguistics','2022','https://ocw.mit.edu/courses/24-900-introduction-to-linguistics-spring-2022/','https://ocw.mit.edu/courses/24-900-introduction-to-linguistics-spring-2022/pages/syllabus/','cf0b118737950412fb31f4663ede9bf27d882e264683f32d08dbe734465ebefa','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Norvin W. Richards"]','no_formal_course','There are no prerequisites for this course.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('24.906J','24.906J','Linguistic Studies of Bilingualism','This course studies the development of bilingualism in human history (from Australopithecus to present day). It focuses on linguistic aspects of bilingualism; models of bilingualism and language acquisition; competence versus performance; effects of bilingualism on other domains of human cognition; brain imaging studies; early versus late bilingualism; opportunities to observe and conduct original research; and implications for educational policies among others. The course is taught in English.','Humanities Language Linguistics Semantics','2012','https://ocw.mit.edu/courses/24-906j-linguistic-studies-of-bilingualism-fall-2012/','https://ocw.mit.edu/courses/24-906j-linguistic-studies-of-bilingualism-fall-2012/pages/syllabus/','c4d9e45d1a761d97b98323021489d8443250b9fac974fc964176603cea60fb18','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Suzanne Flynn"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('24.912','24.912','Black Matters: Introduction to Black Studies','Interdisciplinary survey of people of African descent that draws on the overlapping approaches of history, literature, anthropology, legal studies, media studies, performance, linguistics, and creative writing. This course connects the experiences of African-Americans and of other American minorities, focusing on social, political, and cultural histories, and on linguistic patterns.','African American Studies Humanities Language Literature Philosophy Society','2017','https://ocw.mit.edu/courses/24-912-black-matters-introduction-to-black-studies-spring-2017/','https://ocw.mit.edu/courses/24-912-black-matters-introduction-to-black-studies-spring-2017/pages/syllabus/','ddb52b0504103035fd4dd6af9dc49119b6149e76744521a92064645fdb9b13b0','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Michel DeGraff"]','no_formal_course','None') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('24.946','24.946','Linguistic Theory and the Japanese Language','This course is a detailed examination of the grammar of Japanese and its structure which is significantly different from English, with special emphasis on problems of interest in the study of linguistic universals. Data from a broad group of languages is studied for comparison with Japanese. This course assumes familiarity with linguistic theory.','Humanities Japanese Language Linguistics','2004','https://ocw.mit.edu/courses/24-946-linguistic-theory-and-the-japanese-language-fall-2004/','https://ocw.mit.edu/courses/24-946-linguistic-theory-and-the-japanese-language-fall-2004/pages/syllabus/','6b7dd9dd0670c0c49554b136a96c0a85538d25344a6cdc1783e465ac455b0514','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Shigeru Miyagawa"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('24.954','24.954','Pragmatics in Linguistic Theory','This course is the third and final part of our graduate introduction to semantics. The other two classes are 24.970 Introduction to Semantics and 24.973 Advanced Semantics . The semester will be divided into somewhat independent units. One unit will be devoted to conversational implicatures (mainly scalar implicatures) and another to presupposition. In each unit, we will discuss basic concepts and technical tools and then devote some time to recent work which illustrates their application.','Humanities Linguistics Semantics','2010','https://ocw.mit.edu/courses/24-954-pragmatics-in-linguistic-theory-spring-2010/','https://ocw.mit.edu/courses/24-954-pragmatics-in-linguistic-theory-spring-2010/pages/syllabus/','4e0e665ff8275ae57cb91c4dab71be00d5a0db8d04e446544fc0d05b5b9228ef','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Danny Fox"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('24.973','24.973','Advanced Semantics','This course is the second of the three parts of our graduate introduction to semantics. The others are 24.970 Introduction to Semantics and 24.954 Pragmatics in Linguistic Theory . Like the other courses, this one is not meant as an overview of the field and its current developments. Our aim is to help you to develop the ability for semantic analysis, and we think that exploring a few topics in detail together with hands-on practical work is more effective than offering a bird’s-eye view of everything. Once you have gained some experience in doing semantic analysis, reading around in the many recent handbooks and in current issues of major journals and attending our seminars and colloquia will give you all you need to prosper. Because we want to focus, we need to make difficult choices as to which topics to cover. This year, we will focus on topics having to do with modality, conditionals, tense, and aspect.','Humanities Linguistics Semantics','2009','https://ocw.mit.edu/courses/24-973-advanced-semantics-spring-2009/','https://ocw.mit.edu/courses/24-973-advanced-semantics-spring-2009/pages/syllabus/','de91aaadfef276c57d4bd7f25a306d1f202ca01b55b31c9212692f5d8acbb0f3','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Kai von Fintel"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('3.012','3.012','Fundamentals of Materials Science','This course focuses on the fundamentals of structure, energetics, and bonding that underpin materials science. It is the introductory lecture class for sophomore students in Materials Science and Engineering, taken with 3.014 and 3.016 to create a unified introduction to the subject. Topics include: an introduction to thermodynamic functions and laws governing equilibrium properties, relating macroscopic behavior to atomistic and molecular models of materials; the role of electronic bonding in determining the energy, structure, and stability of materials; quantum mechanical descriptions of interacting electrons and atoms; materials phenomena, such as heat capacities, phase transformations, and multiphase equilibria to chemical reactions and magnetism; symmetry properties of molecules and solids; structure of complex, disordered, and amorphous materials; tensors and constraints on physical properties imposed by symmetry; and determination of structure through diffraction. Real-world applications include engineered alloys, electronic and magnetic materials, ionic and network solids, polymers, and biomaterials. This course is a core subject in MIT’s undergraduate Energy Studies Minor . This Institute-wide program complements the deep expertise obtained in any major with a broad understanding of the interlinked realms of science, technology, and social sciences as they relate to energy and associated environmental challenges.','Engineering Materials Science and Engineering Physics Science Thermodynamics','2005','https://ocw.mit.edu/courses/3-012-fundamentals-of-materials-science-fall-2005/','https://ocw.mit.edu/courses/3-012-fundamentals-of-materials-science-fall-2005/pages/syllabus/','86d7e963aebcc4a12cf434431b0dcf90a3c14194e7ace8e8e190e97cdd386714','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Darrell Irvine","Prof. Nicola Marzari"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('3.032','3.032','Mechanical Behavior of Materials','Here we will learn about the mechanical behavior of structures and materials, from the continuum description of properties to the atomistic and molecular mechanisms that confer those properties to all materials. We will cover elastic and plastic deformation, creep, and fracture of materials including crystalline and amorphous metals, ceramics, and (bio)polymers, and will focus on the design and processing of materials from the atomic to the macroscale to achieve desired mechanical behavior. Integrated laboratories provide the opportunity to explore these concepts through hands-on experiments including instrumentation of pressure vessels, visualization of atomistic deformation in bubble rafts, nanoindentation, and uniaxial mechanical testing, as well as writing assignments to communicate these findings to either general scientific or nontechnical audiences.','Classical Mechanics Engineering Materials Science and Engineering Mechanical Engineering Physics Science Solid Mechanics','2007','https://ocw.mit.edu/courses/3-032-mechanical-behavior-of-materials-fall-2007/','https://ocw.mit.edu/courses/3-032-mechanical-behavior-of-materials-fall-2007/pages/syllabus/','b732c1945c933f13f7b8076cbd1dfd4dbed987ac9313dd913bae954fdb242ab0','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. John Vander Sande","Prof. Krystyn van Vliet"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('3.054','3.054','Cellular Solids: Structure, Properties and Applications','This course reviews the processing and structure of cellular materials as they are created from polymers, metals, ceramics, glasses, and composites, develops models for the mechanical behavior of cellular solids, and shows how the unique properties of honeycombs and foams are exploited in applications such as lightweight structural panels, energy absorption devices and thermal insulation. The applications of cellular solids in medicine include increased fracture risk due to trabecular bone loss in patients with osteoporosis, the development of metal foam coatings for orthopaedic implants, and designing porous scaffolds for tissue engineering that mimic the extracellular matrix. Modelling of cellular materials applied to natural materials and biomimicking is explored. Students taking the graduate version of the class are required to complete additional assignments.','Biological Engineering Cell and Tissue Engineering Engineering Materials Science and Engineering Mechanical Engineering','2015','https://ocw.mit.edu/courses/3-054-cellular-solids-structure-properties-and-applications-spring-2015/','https://ocw.mit.edu/courses/3-054-cellular-solids-structure-properties-and-applications-spring-2015/pages/syllabus/','53891b0d6f10760536e5f244709b8f769702b6d5315033c7908685e85036959a','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Lorna Gibson"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('3.091','3.091SC','Introduction to Solid State Chemistry','Introduction to Solid State Chemistry is a first-year single-semester college course on the principles of chemistry. This unique and popular course satisfies MIT’s general chemistry degree requirement, with an emphasis on solid-state materials and their application to engineering systems. Course Format This course has been designed for independent study. It provides everything you will need to understand the concepts covered in the course. The materials include: A complete set of Lecture Videos by Prof. Sadoway. Detailed Course Notes for most video sessions, plus readings in several suggested textbooks. Homework problems with solution keys, to further develop your understanding. For Further Study collections of links to supplemental online content. Self-Assessment pages containing quiz and exam problems to assess your mastery, and Help Session Videos in which teaching assistants take you step-by-step through exam problem solutions. About OCW Scholar OCW Scholar courses are designed specifically for OCW’s single largest audience: independent learners. These courses are substantially more complete than typical OCW courses, and include new custom-created content as well as materials repurposed from previously published courses. Learn more about OCW Scholar .','Chemical Engineering Chemistry Engineering Materials Science and Engineering Science','2010','https://ocw.mit.edu/courses/3-091sc-introduction-to-solid-state-chemistry-fall-2010/','https://ocw.mit.edu/courses/3-091sc-introduction-to-solid-state-chemistry-fall-2010/pages/syllabus/','7663be6f46fc1e0bf8b56c3032d4fad32d7a0fee8ef2950fc39cfb92876fc43e','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Donald Sadoway"]','review_required','Freshman entering MIT have a wide range of chemistry backgrounds, from no or little exposure in high school, to one or more years of advanced chemistry. This course accommodates that diversity, presuming only a motivation to learn chemistry, basic knowledge of high school physics and math, and problem-solving skills.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('3.185','3.185','Transport Phenomena in Materials Engineering','This course deals with solid-state diffusion, homogeneous and heterogeneous chemical reactions, and spinodal decomposition. Topics covered include: heat conduction in solids, convective and radiative heat transfer boundary conditions; fluid dynamics, 1-D solutions to the Navier-Stokes equations, boundary layer theory, turbulent flow, and coupling with heat conduction and diffusion in fluids to calculate heat and mass transfer coefficients.','Chemical Engineering Engineering Fluid Mechanics Materials Science and Engineering Mechanical Engineering Physics Science Solid Mechanics Thermodynamics Transport Processes','2003','https://ocw.mit.edu/courses/3-185-transport-phenomena-in-materials-engineering-fall-2003/','https://ocw.mit.edu/courses/3-185-transport-phenomena-in-materials-engineering-fall-2003/pages/syllabus/','1097e9f9d2b1bd2048736fc0122d4b3ac1447f2351125eacbcaa286df98d2eca','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Adam Powell"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('3.23','3.23','Electrical, Optical, and Magnetic Properties of Materials','This class discusses the origin of electrical, magnetic and optical properties of materials, with a focus on the acquisition of quantum mechanical tools. It begins with an analysis of the properties of materials, presentation of the postulates of quantum mechanics, and close examination of the hydrogen atom, simple molecules and bonds, and the behavior of electrons in solids and energy bands. Introducing the variation principle as a method for the calculation of wavefunctions, the course continues with investigation of how and why materials respond to different electrical, magnetic and electromagnetic fields and probes and study of the conductivity, dielectric function, and magnetic permeability in metals, semiconductors, and insulators. A survey of common devices such as transistors, magnetic storage media, optical fibers concludes the semester. Note: The Magnetics unit was taught by co-instructor David Paul; that material is not available at this time.','Atomic, Molecular, Optical Physics Electromagnetism Engineering Materials Science and Engineering Physics Quantum Mechanics Science','2007','https://ocw.mit.edu/courses/3-23-electrical-optical-and-magnetic-properties-of-materials-fall-2007/','https://ocw.mit.edu/courses/3-23-electrical-optical-and-magnetic-properties-of-materials-fall-2007/pages/syllabus/','da3836e427a625e4165e5915c0d28d2a2a7891b65d1db989aa08cf36bc7eeb81','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. David Paul","Prof. Nicola Marzari"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('3.46','3.46','Photonic Materials and Devices','This course covers the theory, design, fabrication and applications of photonic materials and devices. After a survey of optical materials design for semiconductors, dielectrics and polymers, the course examines ray optics, electromagnetic optics and guided wave optics; physics of light-matter interactions; and device design principles of LEDs, lasers, photodetectors, modulators, fiber and waveguide interconnects, optical filters, and photonic crystals. Device processing topics include crystal growth, substrate engineering, thin film deposition, etching and process integration for dielectric, silicon and compound semiconductor materials. The course also covers microphotonic integrated circuits and applications in telecom/datacom systems. Course assignments include four design projects that emphasize materials, devices and systems applications.','Atomic, Molecular, Optical Physics Electromagnetism Engineering Materials Science and Engineering Physics Quantum Mechanics Science','2006','https://ocw.mit.edu/courses/3-46-photonic-materials-and-devices-spring-2006/','https://ocw.mit.edu/courses/3-46-photonic-materials-and-devices-spring-2006/pages/syllabus/','749b9bcefdcf4b61258638f31aa480f8175a0665ce2481067d7c2e8909f004f7','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Lionel C. Kimerling","Dr. Sajan Saini"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('3.A08','3.A08','Attraction and Repulsion: The Magic of Magnets','This Freshman Advising Seminar surveys the many applications of magnets and magnetism. To the Chinese and Greeks of ancient times, the attractive and repulsive forces between magnets must have seemed magical indeed. Through the ages, miraculous curative powers have been attributed to magnets, and magnets have been used by illusionists to produce “magical” effects. Magnets guided ships in the Age of Exploration and generated the electrical industry in the 19th century. Today they store information and entertainment on disks and tapes, and produce sound in speakers, images on TV screens, rotation in motors, and levitation in high-speed trains. Students visit various MIT projects related to magnets (including superconducting electromagnets) and read about and discuss the history, legends, pseudoscience, science, and technology of types of magnets, including applications in medicine. Several short written reports and at least one oral presentation will be required of each participant.','Electromagnetism History History of Science and Technology Humanities Physics Science','2005','https://ocw.mit.edu/courses/3-a08-attraction-and-repulsion-the-magic-of-magnets-fall-2005/','https://ocw.mit.edu/courses/3-a08-attraction-and-repulsion-the-magic-of-magnets-fall-2005/pages/syllabus/','dcd8eaa16dc8f7916647254100ad60cf4d0ef5671b8e1d5044d30f77e21d300a','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. James Livingston"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('4.104','4.104','Architecture Studio: Intentions','This is the second undergraduate design studio. It introduces a full range of architectural ideas and issues through drawing exercises, analyses of precedents, and explored design methods. Students will develop design skills by conceptualizing and representing architectural ideas and making aesthetic judgments about building design. Discussions regarding architecture’s role in mediating culture, nature and technology will help develop the students’ architectural vocabulary.','Architectural Design Architecture Fine Arts','2005','https://ocw.mit.edu/courses/4-104-architecture-studio-intentions-spring-2005/','https://ocw.mit.edu/courses/4-104-architecture-studio-intentions-spring-2005/pages/syllabus/','2b626f69b3b0ea1fe0a76d342494ac089e5324fcb5f0e35e6d6ea3a28ef84c4b','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Joel Turkel"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('4.123','4.123','Architectural Design, Level I: Perceptions and Processes','This studio explores the notion of in-between by engaging several relationships; the relationship between intervention and perception, between representation and notation and between the fixed and the temporal. In the Exactitude in Science , Jorge Luis Borges tells the perverse tale of the one to one scale map, where the desire for precision and power leads to the escalating production of larger and more accurate maps of the territory. For Jean Baudrillard, “The territory no longer precedes the map nor survives it. …it is the map that precedes the territory… and thus, it would be the territory whose shreds are slowly rotting across the map.” The map or the territory, left to ruin-shredding across the ‘other’, beautifully captures the tension between reality and representation. Mediating between collective desire and territorial surface, maps filter, create, frame, scale, orient, and project. A map has agency. It is not merely representational but operational, the experience and discursive potential of this process lies in the reciprocity between the representation and the real. It is in-between these specific sets of relationships that this studio positions itself.','Architectural Design Architecture Environmental Design Fine Arts','2003','https://ocw.mit.edu/courses/4-123-architectural-design-level-i-perceptions-and-processes-fall-2003/','https://ocw.mit.edu/courses/4-123-architectural-design-level-i-perceptions-and-processes-fall-2003/pages/syllabus/','e389853ebb01891825a617da1ad8c4f25f26fd7eb37d77196c99a5d1bc492193','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Meejin Yoon"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('4.143','4.143','Immaterial Limits: Process and Duration','This studio proposes to engage tectonics as a material process. By exploring transformation, indeterminacy and mutability inherent in material and landscape processes, students will be challenged to engage notions of duration as a design strategy for architecture and urbanism. While the second law of thermodynamics states that the material universe tends toward a state of increasing disorder, architects build and construct in opposition to these forces. Attempting to delay the processes of disorder, decay and collapse, tectonics is often seen as the embodied expression of an arrested moment the finite resolution of the building process. Yet the processes that enable and disable architecture extend beyond any arrested moment. A more detailed description can be found in the syllabus section.','Architectural Engineering Architectural History and Criticism Architecture Fine Arts','2002','https://ocw.mit.edu/courses/4-143-immaterial-limits-process-and-duration-fall-2002/','https://ocw.mit.edu/courses/4-143-immaterial-limits-process-and-duration-fall-2002/pages/syllabus/','604c661899b5aa8cc5f8d5bba669ae125b898121d4211d0dec169cac3f01ca7b','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Meejin Yoon"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('4.175','4.175','Case Studies in City Form','This course serves as an introduction to urban form and design, focusing on the physical, historical, and social form of cities. Selected cities are analyzed, drawn, and compared, to develop a working understanding of urban and architectural form. The development of map making and urban representation is discussed, and use of the computer is required. A special focus is placed on the historical development of the selected cities, especially mid-nineteenth and mid-twentieth century periods of expansion. Readings focus on urban design theory in the twentieth century and will be discussed during a weekly seminar on them. This is a methods class for S.M.Arch.S. students in Architecture and Urbanism.','Architectural Design Architecture Fine Arts Social Science Urban Studies','2005','https://ocw.mit.edu/courses/4-175-case-studies-in-city-form-fall-2005/','https://ocw.mit.edu/courses/4-175-case-studies-in-city-form-fall-2005/pages/syllabus/','dae618ef4ffb3040e07ccd81047549cc760362a7f55de84a026d314a148e8fa7','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Michael Dennis","Mr. Anubhav Gupta"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('4.196','4.196','Architecture Design, Level II: Cuba Studio','This architectural studio will have one main project for the semester: to explore the issues surrounding the redesign of an area in Havana, Cuba. It is a typical area about the size of a Law of Indies block that presently has a mix of housing, work, and shopping, in buildings that need to be replaced and others that need to be rehabilitated. There is also vacant land, and buildings that are unused. Part of the blocks front on the Malecon, the street next to the water. The other edge fronts onto a typical neighborhood. The intention is to study the culture through an understanding of one area of Havana and then design an “echo” in architectural form. The design will include public space as well as a mix of buildings: some new, some rehabilitated.','Anthropology Architectural Design Architecture Cultural Anthropology Environmental Design Fine Arts Social Science','2004','https://ocw.mit.edu/courses/4-196-architecture-design-level-ii-cuba-studio-spring-2004/','https://ocw.mit.edu/courses/4-196-architecture-design-level-ii-cuba-studio-spring-2004/pages/syllabus/','c9344f7f370d49b9e2cc87b273bc3eb5ef00f33030c691b6c20c1e535427ddb2','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Jan Wampler"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('4.273','4.273','Introduction to Design Inquiry','This subject explores the varied nature and practice of computation in design. We will view computation and design broadly. Computation will include both work done on the computer (digital computing) and by-hand. Design will include both the process of making designs and artifacts, as well as the designs and artifacts themselves. The aim of the course is to develop a view of computation and design beyond the specifics of techniques and tools, and a critical, self-awareness of our own approaches and metaphors for computation and design.','Architectural Design Architecture Fine Arts','2004','https://ocw.mit.edu/courses/4-273-introduction-to-design-inquiry-fall-2004/','https://ocw.mit.edu/courses/4-273-introduction-to-design-inquiry-fall-2004/pages/syllabus/','88828c0ff44a80c4fd5bd43bbed6a5f1fbc9f23f1eda812fa0b953c2ffdab3d8','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Terry Knight"]','review_required','None. This is a required subject for first year SMArchS students in Computation. However, it is open to other interested students with the permission of the instructor.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('4.303','4.303','Dialogue in Art, Architecture, and Urbanism','In this class we will examine how the idea of the city has been “translated” by artists, architects, and other diverse disciplines. We will consider how collaborations between artists and architects might provide opportunities for rethinking / redesigning urban spaces. The class will look specifically at planned cities like Brasilia, Las Vegas, Canberra, and Celebration and compare such tabula rasa designs with the redesign of recyclable urban spaces demonstrated in projects such as Ground Zero, Barcelona 2004, and Boston’s Rose Kennedy Greenway. While the course will involve some reading and discussion, coursework will focus largely on the students’ own projects / interventions that should evolve over the course of the semester. Of the two weekly class meetings, one will be a group discussion or lecture with the whole class and visiting guests, and the other will be an individual meeting between the student and the instructor to discuss his or her work for the class, including the final project.','Architecture Environmental Design Fine Arts Social Science Urban Studies Visual Arts','2003','https://ocw.mit.edu/courses/4-303-dialogue-in-art-architecture-and-urbanism-fall-2003/','https://ocw.mit.edu/courses/4-303-dialogue-in-art-architecture-and-urbanism-fall-2003/pages/syllabus/','1285c97ed39676e80e6b7718f9213d703f35c98cbfa6329b9e8da9a5b8e82552','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Antonio Muntadas"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('4.343','4.343','Photography and Related Media','Subject combines practical instruction, readings, lectures, field trips, visiting artists, group discussions, and individual reviews. Fosters a critical awareness of how images in our culture are produced and constructed. Student-initiated term project at the core of exploration. Special consideration given to the relationship of space and the photographic image. Practical instruction in basic black and white techniques, digital imaging, fundamentals of camera operation, lighting, film exposure, development, and printing. Open to beginning and advanced students. Lab fee. Enrollment limited with preference given to current Master of Architecture students.','Fine Arts Media Studies Photography Visual Arts','2002','https://ocw.mit.edu/courses/4-343-photography-and-related-media-fall-2002/','https://ocw.mit.edu/courses/4-343-photography-and-related-media-fall-2002/pages/syllabus/','ae44b372a72784796094cc04fbfa0e560282e7b32d2cca14ddeaf4b043d5bb0b','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Reiner Leist"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('4.401','4.401','Introduction to Building Technology','The course aims at providing a fundamental understanding of the physics related to buildings and to propose an overview of the various issues that have to be adequately combined to offer the occupants a physical, functional and psychological well-being. Students will be guided through the different components, constraints and systems of a work of architecture. These will be examined both independently and in the manner in which they interact and affect one another.','Architectural Design Architecture Buildings Civil Engineering Energy Engineering Environmental Design Fine Arts Structural Engineering Technology','2006','https://ocw.mit.edu/courses/4-401-introduction-to-building-technology-spring-2006/','https://ocw.mit.edu/courses/4-401-introduction-to-building-technology-spring-2006/pages/syllabus/','b1bc2f946b4f5044a3836a50ac72780377a8196a20632727900390fc39fd8957','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Marilyne Andersen"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('4.448','4.448','Analysis of Historic Structures','An analysis of historical structures is presented themed sections based around construction materials. Structures from all periods of history are analyzed. The goal of the class is to provide an understanding of the preservation of historic structures for all students.','Architectural Engineering Architectural History and Criticism Architecture Civil Engineering Engineering Fine Arts Structural Engineering','2004','https://ocw.mit.edu/courses/4-448-analysis-of-historic-structures-fall-2004/','https://ocw.mit.edu/courses/4-448-analysis-of-historic-structures-fall-2004/pages/syllabus/','d65f18f893bd45ee1c4b55f9275b07180d0eb48984b15f90504101726c601d09','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. John Ochsendorf"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('4.493','4.493','Natural Light in Design','Today, computer-based simulations are becoming increasingly popular, especially when daylighting and energy conservation are amongst the key goals for a project. This two-week workshop will expose participants to the current daylighting simulation models and beyond, by introducing realistic and dynamic assessment methods through hands-on exercises and application to a design project. Open to students and practitioners. This course is offered during the Independent Activities Period (IAP), which is a special 4-week term at MIT that runs from the first week of January until the end of the month.','Architectural Design Architecture Computational Modeling and Simulation Engineering Environmental Design Fine Arts Systems Engineering','2006','https://ocw.mit.edu/courses/4-493-natural-light-in-design-january-iap-2006/','https://ocw.mit.edu/courses/4-493-natural-light-in-design-january-iap-2006/pages/syllabus/','7f175bc4fb36b60ae3ae18a613ae7e5d0179d18fd76a20354a82aa6e905885ec','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Marilyne Andersen"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('4.580','4.580','Inquiry into Computation and Design','This subject explores the varied nature and practice of computation in design. We will view computation and design broadly. Computation will include both work done on the computer (digital computing) and by-hand. Design will include both the process of making designs and artifacts, as well as the designs and artifacts themselves. The aim of the course is to develop a view of computation and design beyond the specifics of techniques and tools, and a critical, self-awareness of our own approaches and metaphors for computation and design.','Architectural Design Architecture Computational Science and Engineering Engineering Fine Arts Systems Engineering','2006','https://ocw.mit.edu/courses/4-580-inquiry-into-computation-and-design-fall-2006/','https://ocw.mit.edu/courses/4-580-inquiry-into-computation-and-design-fall-2006/pages/syllabus/','4d675f858b526072d6c0dd8873e5278cc283e7e543dbc2401fe4cbc7288be316','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Terry Knight"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('4.614','4.614','Religious Architecture and Islamic Cultures','This course introduces the history of Islamic cultures through their most vibrant material signs: the religious architecture that spans fourteen centuries and three continents — Asia, Africa, and Europe. The course presents Islamic architecture both as a historical tradition and as a cultural catalyst that influenced and was influenced by the civilizations with which it came in contact.','Architectural History and Criticism Architecture Fine Arts Middle Eastern Studies Religious Architecture Society','2002','https://ocw.mit.edu/courses/4-614-religious-architecture-and-islamic-cultures-fall-2002/','https://ocw.mit.edu/courses/4-614-religious-architecture-and-islamic-cultures-fall-2002/pages/syllabus/','4e2f0f73bfcca4392d30bbbf8f0a7239ce6a4f0f80e0384692fd9af2a029db4e','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Nasser Rabbat"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('4.651','4.651','Art Since 1940','This subject focuses on the objects, history, context, and critical discussion surrounding art since World War II. Because of the burgeoning increase in art production, the course is necessarily selective. We will trace major developments and movements in art up to the present, primarily from the US; but we will also be looking at art from Europe, Asia, Africa, Latin America, and the Middle East, as well as art “on the margins” — art that has been overlooked by the mainstream critical press, but may have a broad cultural base in its own community. We will ask what function art serves in its various cultures of origin, and why art has been such a lightning rod for political issues around the world.','Anthropology Art History Cultural Anthropology Fine Arts Social Science','2010','https://ocw.mit.edu/courses/4-651-art-since-1940-fall-2010/','https://ocw.mit.edu/courses/4-651-art-since-1940-fall-2010/pages/syllabus/','bb1c8bf8e1315161f03c1c0c6ce3cf863d7fc0f347c76dfb7b957b2e09157f47','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Caroline Jones"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('4.A21','4.A21','Stories Without Words: Photographing the First Year','The transition from high school and home to college and a new living environment can be a fascinating and interesting time, made all the more challenging and interesting by being at MIT. More than recording the first semester through a series of snapshots, this freshman seminar will attempt to teach photography as a method of seeing and a tool for better understanding new surroundings. Over the course of the semester, students will develop a body of work through a series of assignments, and then attempt to describe the conditions and emotions of their new environment in a cohesive final presentation.','Fine Arts Photography Visual Arts','2006','https://ocw.mit.edu/courses/4-a21-stories-without-words-photographing-the-first-year-fall-2006/','https://ocw.mit.edu/courses/4-a21-stories-without-words-photographing-the-first-year-fall-2006/pages/syllabus/','ac4290bd1af112b80b4f1c85e5910cf106de009610e5421497c9967c0a187714','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Mr. Keith McCluskey"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('5.069','5.069','Crystal Structure Analysis','This course covers the following topics: X-ray diffraction: symmetry, space groups, geometry of diffraction, structure factors, phase problem, direct methods, Patterson methods, electron density maps, structure refinement, how to grow good crystals, powder methods, limits of X-ray diffraction methods, and structure data bases.','Analytical Chemistry Atomic, Molecular, Optical Physics Chemistry Physics Science','2010','https://ocw.mit.edu/courses/5-069-crystal-structure-analysis-spring-2010/','https://ocw.mit.edu/courses/5-069-crystal-structure-analysis-spring-2010/pages/syllabus/','ff7c1e56920996c05e0e30f5fb9e14248d74aad7765bf0f5b9130360e1a70fe7','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Peter Mueller"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('5.12','5.12','Organic Chemistry I','This subject deals primarily with the basic principles to understand the structure and reactivity of organic molecules. Emphasis is on substitution and elimination reactions and chemistry of the carbonyl group. The course also provides an introduction to the chemistry of aromatic compounds.','Chemistry Organic Chemistry Science','2005','https://ocw.mit.edu/courses/5-12-organic-chemistry-i-spring-2005/','https://ocw.mit.edu/courses/5-12-organic-chemistry-i-spring-2005/pages/syllabus/','8fedc646de0839b0a1c71510b0e08a0f82f329065ef45640935a8cddfafe4362','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Kimberly Berkowski","Prof. Sarah O’Connor"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('5.36','5.36','Biochemistry Laboratory','The course, which spans two thirds of a semester, provides students with a research-inspired laboratory experience that introduces standard biochemical techniques in the context of investigating a current and exciting research topic, acquired resistance to the cancer drug Gleevec. Techniques include protein expression, purification, and gel analysis, PCR, site-directed mutagenesis, kinase activity assays, and protein structure viewing. This class is part of the new laboratory curriculum in the MIT Department of Chemistry. Undergraduate Research-Inspired Experimental Chemistry Alternatives ( URIECA ) introduces students to cutting edge research topics in a modular format. Acknowledgments Development of this course was funded through an HHMI Professors grant to Professor Catherine L. Drennan.','Biochemistry Biology Science','2009','https://ocw.mit.edu/courses/5-36-biochemistry-laboratory-spring-2009/','https://ocw.mit.edu/courses/5-36-biochemistry-laboratory-spring-2009/pages/syllabus/','a1c7b9dcf7ce4fb961ac9dc621cc2a2dd0b9813c9d13892c5aeb41a196cd4e54','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Elizabeth Vogel Taylor"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('5.61','5.61','Physical Chemistry','This course is an introduction to quantum mechanics for use by chemists. Topics include particles and waves, wave mechanics, semi-classical quantum mechanics, matrix mechanics, perturbation theory, molecular orbital theory, molecular structure, molecular spectroscopy, and photochemistry. Emphasis is on creating and building confidence in the use of intuitive pictures.','Chemistry Physical Chemistry Science','2017','https://ocw.mit.edu/courses/5-61-physical-chemistry-fall-2017/','https://ocw.mit.edu/courses/5-61-physical-chemistry-fall-2017/pages/syllabus/','27a4b65ef959bb59817d207d1031dfb519a0d4ec525498a0383a34a0233f8b6a','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Robert Field"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('5.74','5.74','Introductory Quantum Mechanics II','This course covers topics in time-dependent quantum mechanics, spectroscopy, and relaxation, with an emphasis on descriptions applicable to condensed phase problems and a statistical description of ensembles.','Health and Medicine Physics Quantum Mechanics Science Spectroscopy','2009','https://ocw.mit.edu/courses/5-74-introductory-quantum-mechanics-ii-spring-2009/','https://ocw.mit.edu/courses/5-74-introductory-quantum-mechanics-ii-spring-2009/pages/syllabus/','37b3e239f9dbf3f5265a325e1bd9a90e78b721e60d28588b62629972401f664c','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Andrei Tokmakoff"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.0001','6.0001','Introduction to Computer Science and Programming in Python','6.0001 Introduction to Computer Science and Programming in Python is intended for students with little or no programming experience. It aims to provide students with an understanding of the role computation can play in solving problems and to help students, regardless of their major, feel justifiably confident of their ability to write small programs that allow them to accomplish useful goals. The class uses the Python 3.5 programming language.','Algorithms and Data Structures Computer Science Engineering Programming Languages','2016','https://ocw.mit.edu/courses/6-0001-introduction-to-computer-science-and-programming-in-python-fall-2016/','https://ocw.mit.edu/courses/6-0001-introduction-to-computer-science-and-programming-in-python-fall-2016/pages/syllabus/','5224ea1799964900529dfaa6eb8c0a29a13c70a69fd9e81f7f24289c1dfd84f4','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Ana Bell","Prof. Eric Grimson","Prof. John Guttag"]','review_required','6.0001 Introduction to Computer Science and Programming in Python is intended for students with little or no programming experience. It aims to provide students with an understanding of the role computation can play in solving problems and to help students, regardless of their major, feel justifiably confident of their ability to write small programs that allow them to accomplish useful goals. The class uses the Python 3.5 programming language.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.0002','6.0002','Introduction to Computational Thinking and Data Science','6.0002 is the continuation of 6.0001 Introduction to Computer Science and Programming in Python and is intended for students with little or no programming experience. It aims to provide students with an understanding of the role computation can play in solving problems and to help students, regardless of their major, feel justifiably confident of their ability to write small programs that allow them to accomplish useful goals. The class uses the Python 3.5 programming language.','Computer Science Engineering Mathematics Probability and Statistics','2016','https://ocw.mit.edu/courses/6-0002-introduction-to-computational-thinking-and-data-science-fall-2016/','https://ocw.mit.edu/courses/6-0002-introduction-to-computational-thinking-and-data-science-fall-2016/pages/syllabus/','b5be045453c90696c22228ff5b67ebdea2b9557f2e1e476607a0d11f976a9326','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Eric Grimson","Prof. John Guttag","Dr. Ana Bell"]','structured','Prerequisites 6.0001 Introduction to Computer Science and Programming in Python or permission of the instructor.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('6.0002',0,'6.0001');
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.001','6.001','Structure and Interpretation of Computer Programs','This course introduces students to the principles of computation. Upon completion of 6.001, students should be able to explain and apply the basic methods from programming languages to analyze computational systems, and to generate computational solutions to abstract problems. Substantial weekly programming assignments are an integral part of the course. This course is worth 4 Engineering Design Points.','Computation Computer Science Engineering Mathematics Theory of Computation','2005','https://ocw.mit.edu/courses/6-001-structure-and-interpretation-of-computer-programs-spring-2005/','https://ocw.mit.edu/courses/6-001-structure-and-interpretation-of-computer-programs-spring-2005/pages/syllabus/','247dcf22065313dbbed7b7b372d4ee2e5a21e5b1488b5a0e2232525beee91a22','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Eric Grimson","Prof. Peter Szolovits","Prof. Trevor Darrell"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.003','6.003','Signals and Systems','6.003 covers the fundamentals of signal and system analysis, focusing on representations of discrete-time and continuous-time signals (singularity functions, complex exponentials and geometrics, Fourier representations, Laplace and Z transforms, sampling) and representations of linear, time-invariant systems (difference and differential equations, block diagrams, system functions, poles and zeros, convolution, impulse and step responses, frequency responses). Applications are drawn broadly from engineering and physics, including feedback and control, communications, and signal processing.','Digital Systems Electrical Engineering Engineering Signal Processing','2011','https://ocw.mit.edu/courses/6-003-signals-and-systems-fall-2011/','https://ocw.mit.edu/courses/6-003-signals-and-systems-fall-2011/pages/syllabus/','c29acd9b5607704e1ab7eef257bb9e6a4839c44b351becb96793459fe2a370f1','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Dennis Freeman"]','structured','Prerequisites 6.02 Introduction to EECS II') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('6.003',0,'6.02');
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.004','6.004','Computation Structures','This course introduces architecture of digital systems, emphasizing structural principles common to a wide range of technologies. It covers the topics including multilevel implementation strategies, definition of new primitives (e.g., gates, instructions, procedures, processes) and their mechanization using lower-level elements. It also includes analysis of potential concurrency, precedence constraints and performance measures, pipelined and multidimensional systems, instruction set design issues and architectural support for contemporary software structures.','Computer Design and Engineering Computer Science Digital Systems Electrical Engineering Engineering','2017','https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/','https://ocw.mit.edu/courses/6-004-computation-structures-spring-2017/pages/syllabus/','0528f113c92ed25127bd79d5d1e20b5d1dd6765fa71d39d8658e19e6150203bb','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Chris Terman"]','structured','Prerequisites 8.02 Physics II: Electricity and Magnetism') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('6.004',0,'8.02');
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.005','6.005','Software Construction','6.005 Software Construction introduces fundamental principles and techniques of software development, i.e., how to write software that is safe from bugs, easy to understand, and ready for change. The course includes problem sets and a final project. Important topics include specifications and invariants; testing; abstract data types; design patterns for object-oriented programming; concurrent programming and concurrency; and functional programming. The 6.005 website homepage from Spring 2016, along with all course materials, is available to OpenCourseWare users.','Algorithms and Data Structures Computer Networks Computer Science Engineering Software Design and Engineering','2016','https://ocw.mit.edu/courses/6-005-software-construction-spring-2016/','https://ocw.mit.edu/courses/6-005-software-construction-spring-2016/pages/syllabus/','738c1a58b67be782b94e8ece8aa3c709e05d71d94a26c6ea8568943d0d8765cf','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Robert Miller","Dr. Max Goldman"]','review_required','No explicit prerequisite section was found in the archived syllabus HTML. Instructor review is required; no absence of requirements is inferred.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.006','6.006','Introduction to Algorithms','This course is an introduction to mathematical modeling of computational problems, as well as common algorithms, algorithmic paradigms, and data structures used to solve these problems. It emphasizes the relationship between algorithms and programming and introduces basic performance measures and analysis techniques for these problems.','Algorithms and Data Structures Computation Computer Science Engineering Mathematics Theory of Computation','2020','https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/','https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/pages/syllabus/','31275e5711da75a5aff7087ee09ab2b20ada838f50f3174b29685c8a7ad732e1','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Erik Demaine","Dr. Jason Ku","Prof. Justin Solomon"]','review_required','Prerequisites 6.0001 Introduction to Computer Science and Programming in Python : Basic experience programming in Python 3. 6.042J Mathematics for Computer Science : Basic knowledge of discrete mathematics: set theory, relations and logic, combinatorics, proofs, recursion, number theory, graph theory, and probability. We strongly caution against taking 6.006 before having fulfilled the listed prerequisites. We will evaluate your understanding of the prerequisite material via a short Problem Set 0 assignment . All students must submit this evaluation, regardless of prerequisite status. We will assign each submission a letter grade. If you receive a C or below on the assignment, you will need to meet with a staff member to review your performance before you will be allowed to take the class. We will not grade any other assignments from you until a good faith attempt of Problem Set 0 has been submitted. The grade for this assignment will NOT affect your final grade in the class, but turning it in is required for taking this class.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('6.006',0,'6.0001');
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('6.006',1,'6.042J');
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.01','6.01SC','Introduction to Electrical Engineering and Computer Science I','This course provides an integrated introduction to electrical engineering and computer science, taught using substantial laboratory experiments with mobile robots. Our primary goal is for you to learn to appreciate and use the fundamental design principles of modularity and abstraction in a variety of contexts from electrical engineering and computer science. Our second goal is to show you that making mathematical models of real systems can help in the design and analysis of those systems. Finally, we have the more typical goals of teaching exciting and important basic material from electrical engineering and computer science, including modern software engineering, linear systems analysis, electronic circuits, and decision-making. Course Format This course has been designed for independent study. It includes all of the materials you will need to understand the concepts covered in this subject. The materials in this course include: Lecture videos from Spring 2011, taught by Prof. Dennis Freeman Recitation videos, developed for OCW Scholar by teaching assistant Kendra Pugh Course notes Software and design labs Homework assignments and additional exercises Nano-quizzes and exams with solutions Content Development Leslie Kaelbling Jacob White Harold Abelson Dennis Freeman Tomás Lozano-Pérez Isaac Chuang','Artificial Intelligence Computer Science Electrical Engineering Engineering Robotics and Control Systems Software Design and Engineering','2011','https://ocw.mit.edu/courses/6-01sc-introduction-to-electrical-engineering-and-computer-science-i-spring-2011/','https://ocw.mit.edu/courses/6-01sc-introduction-to-electrical-engineering-and-computer-science-i-spring-2011/pages/syllabus/','7e38c55dc5f21e5b625a0d9ff41e1d3d76bb73395d61f798c71fe48e1adb4f0a','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Leslie Kaelbling","Prof. Jacob White","Prof. Harold Abelson","Prof. Dennis Freeman","Prof. Tomás Lozano-Pérez","Prof. Isaac Chuang"]','review_required','At MIT, 6.01 has no formal prerequisites. Students are expected to take 8.02 Physics II: Electricity and Magnetism as a co-requisite. This OCW Scholar course will be most useful to students with the following background and skills: Mathematics Sequences and series, some trigonometry (for poles) No extensive skill with calculus is required, but students should understand that velocity is the derivative of position, and be able to estimate the velocity of an object from a graph of its position. Programming Some programming experience is good, but not necessarily required. The Python Tutorial is designed to get students up to speed with Python, while a course like 6.189 A Gentle Introduction to Programming Using Python may be useful for students will little or no programming experience. Physics Some exposure to solving basic circuits: Ohm’s law, passive components (such as resistors and capacitors), reducing a circuit to a system of linear equations.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.011','6.011','Signals, Systems and Inference','This course covers signals, systems and inference in communication, control and signal processing. Topics include input-output and state-space models of linear systems driven by deterministic and random signals; time- and transform-domain representations in discrete and continuous time; and group delay. State feedback and observers. Probabilistic models; stochastic processes, correlation functions, power spectra, spectral factorization. Least-mean square error estimation; Wiener filtering. Hypothesis testing; detection; matched filters.','Electrical Engineering Engineering Robotics and Control Systems Signal Processing Telecommunications','2018','https://ocw.mit.edu/courses/6-011-signals-systems-and-inference-spring-2018/','https://ocw.mit.edu/courses/6-011-signals-systems-and-inference-spring-2018/pages/syllabus/','8bac11c9ee48fb42047bb3a1944b432ee71b3754ba10c11e84a20b7b479d725c','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. George Verghese","Prof. Alan V. Oppenheim","Prof. Peter Hagelstein"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.033','6.033','Computer System Engineering','This class covers topics on the engineering of computer software and hardware systems. Topics include techniques for controlling complexity; strong modularity using client-server design, operating systems; performance, networks; naming; security and privacy; fault-tolerant systems, atomicity and coordination of concurrent activities, and recovery; impact of computer systems on society.','Computer Design and Engineering Computer Networks Computer Science Engineering Operating Systems Software Design and Engineering','2018','https://ocw.mit.edu/courses/6-033-computer-system-engineering-spring-2018/','https://ocw.mit.edu/courses/6-033-computer-system-engineering-spring-2018/pages/syllabus/','de41b8fcf772fcc12a6329c3086b1a8b4ddf958b01f2286a6d15ec952b90d78e','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Katrina LaCurts"]','structured','Prerequisites 6.004 Computation Structures and 6.005 Software Construction or 6.009 Fundamentals of Programming') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
