INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.034','6.034','Artificial Intelligence','This course introduces students to the basic knowledge representation, problem solving, and learning methods of artificial intelligence. Upon completion of 6.034, students should be able to develop intelligent systems by assembling solutions to concrete computational problems; understand the role of knowledge representation, problem solving, and learning in intelligent-system engineering; and appreciate the role of problem solving, vision, and language in understanding human intelligence from a computational perspective.','Algorithms and Data Structures Artificial Intelligence Computer Science Engineering Theory of Computation','2010','https://ocw.mit.edu/courses/6-034-artificial-intelligence-fall-2010/','https://ocw.mit.edu/courses/6-034-artificial-intelligence-fall-2010/pages/syllabus/','8884749a71746ed63ae3a03bf105d554a64ebb86c48347df95048ae9cc9c6d48','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Patrick Henry Winston"]','review_required','No explicit prerequisite section was found in the archived syllabus HTML. Instructor review is required; no absence of requirements is inferred.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.035','6.035','Computer Language Engineering','This course analyzes issues associated with the implementation of higher-level programming languages. Topics covered include: fundamental concepts, functions, and structures of compilers, the interaction of theory and practice, and using tools in building software. The course includes a multi-person project on compiler design and implementation.','Computer Science Engineering Programming Languages Software Design and Engineering','2010','https://ocw.mit.edu/courses/6-035-computer-language-engineering-spring-2010/','https://ocw.mit.edu/courses/6-035-computer-language-engineering-spring-2010/pages/syllabus/','8e42a69d92ee72305c4781c62f867431f120c764c3855aca6864d94b1d98da0a','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Saman Amarasinghe","Prof. Martin Rinard"]','review_required','Prerequisites 6.170 and proficiency in Java') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('6.035',0,'6.170');
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.041','6.041SC','Probabilistic Systems Analysis and Applied Probability','This course introduces students to the modeling, quantification, and analysis of uncertainty. The tools of probability theory, and of the related field of statistical inference, are the keys for being able to analyze and make sense of data. These tools underlie important advances in many fields, from the basic sciences to engineering and management. Course Format This course has been designed for independent study. It provides everything you will need to understand the concepts covered in the course. The materials include: Lecture Videos by MIT Professor John Tsitsiklis Lecture Slides and Readings Recitation Problems and Solutions Recitation Help Videos by MIT Teaching Assistants Tutorial Problems and Solutions Tutorial Help Videos by MIT Teaching Assistants Problem Sets with Solutions Exams with Solutions Related Resource A complementary resource, Introduction to Probability , is provided by the videos developed for an EdX version of 6.041. These videos cover more or less the same content, in somewhat different order, and in somewhat more detail than the videotaped live lectures.','Discrete Mathematics Engineering Mathematics Probability and Statistics Systems Engineering','2013','https://ocw.mit.edu/courses/6-041sc-probabilistic-systems-analysis-and-applied-probability-fall-2013/','https://ocw.mit.edu/courses/6-041sc-probabilistic-systems-analysis-and-applied-probability-fall-2013/pages/syllabus/','299eb8b4c3971d0e3d8955959fa17341ec368937e3bc2ce6e37cca0a0e694f6e','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. John Tsitsiklis"]','structured','Prerequisites The prerequisites for this course are 18.01 Single Variable Calculus and 18.02 Multivariable Calculus Although this is not a mathematics course, it does rely on the language and some tools from mathematics. It requires a level of comfort with mathematical reasoning, familiarity with sequences, limits, infinite series, and the chain rule, as well as the ability to work with ordinary or multiple integrals.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('6.041',0,'18.01');
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('6.041',1,'18.02');
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.042J','6.042J','Mathematics for Computer Science','This subject offers an interactive introduction to discrete mathematics oriented toward computer science and engineering. The subject coverage divides roughly into thirds: Fundamental concepts of mathematics: Definitions, proofs, sets, functions, relations. Discrete structures: graphs, state machines, modular arithmetic, counting. Discrete probability theory. On completion of 6.042J, students will be able to explain and apply the basic methods of discrete (noncontinuous) mathematics in computer science. They will be able to use these methods in subsequent courses in the design and analysis of algorithms, computability theory, software engineering, and computer systems. This course is part of the Open Learning Library , which is free to use. You have the option to sign up and enroll in the course if you want to track your progress, or you can view and use all the materials without enrolling.','Applied Mathematics Computer Science Engineering Mathematics Probability and Statistics','2015','https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-spring-2015/','https://ocw.mit.edu/courses/6-042j-mathematics-for-computer-science-spring-2015/pages/syllabus/','619502094f9d23d5e20da908f05d893babc5718d03eb3e84bec6d10dac51f4d7','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Albert R. Meyer","Prof. Adam Chlipala"]','structured','Prerequisite The prerequisite is 18.01 Single Variable Calculus . In particular, some familiarity with sequences and series, limits, and differentiation and integration of functions of one variable are necessary.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('6.042J',0,'18.01');
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.046J','6.046J','Design and Analysis of Algorithms','This is an intermediate algorithms course with an emphasis on teaching techniques for the design and analysis of efficient algorithms, emphasizing methods of application. Topics include divide-and-conquer, randomization, dynamic programming, greedy algorithms, incremental improvement, complexity, and cryptography.','Algorithms and Data Structures Applied Mathematics Computer Networks Computer Science Cryptography Engineering Mathematics','2015','https://ocw.mit.edu/courses/6-046j-design-and-analysis-of-algorithms-spring-2015/','https://ocw.mit.edu/courses/6-046j-design-and-analysis-of-algorithms-spring-2015/pages/syllabus/','60d9f81cf10e6ef12d5cbce8f48c097aaffe89bee8298c996e56a01f2f61c78f','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Erik Demaine","Prof. Srini Devadas","Prof. Nancy Lynch"]','structured','Prerequisites This course is the header course for the Theory of Computation concentration. You are expected, and strongly encouraged, to have taken: 6.006 Introduction to Algorithms 6.042J / 18.062J Mathematics for Computer Science Petitions for waivers will be considered by the course staff. Students will be responsible for material covered in prerequisites.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
