INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.071J','6.071J','Introduction to Electronics, Signals, and Measurement','The course is designed to provide a practical - hands on - introduction to electronics with a focus on measurement and signals. The prerequisites are courses in differential equations, as well as electricity and magnetism. No prior experience with electronics is necessary. The course will integrate demonstrations and laboratory examples with lectures on the foundations. Throughout the course we will use modern “virtual instruments” as test-beds for understanding electronics. The aim of the course is to provide students with the practical knowledge necessary to work in a modern science or engineering setting.','Differential Equations Electrical Engineering Electronics Engineering Mathematics Signal Processing','2006','https://ocw.mit.edu/courses/6-071j-introduction-to-electronics-signals-and-measurement-spring-2006/','https://ocw.mit.edu/courses/6-071j-introduction-to-electronics-signals-and-measurement-spring-2006/pages/syllabus/','56895b46fd6099fc00e7982aba88ac6df9a556f9fda16145d8db09b44da321f4','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. David Cory","Prof. Ian Hutchinson","Prof. Manos Chaniotakis"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.087','6.087','Practical Programming in C','This course provides a thorough introduction to the C programming language, the workhorse of the UNIX operating system and lingua franca of embedded processors and micro-controllers. The first two weeks will cover basic syntax and grammar, and expose students to practical programming techniques. The remaining lectures will focus on more advanced concepts, such as dynamic memory allocation, concurrency and synchronization, UNIX signals and process control, library development and usage. Daily programming assignments and weekly laboratory exercises are required. Knowledge of C is highly marketable for summer internships, UROPs, and full-time positions in software and embedded systems development.','Computer Science Engineering Programming Languages Software Design and Engineering','2010','https://ocw.mit.edu/courses/6-087-practical-programming-in-c-january-iap-2010/','https://ocw.mit.edu/courses/6-087-practical-programming-in-c-january-iap-2010/pages/syllabus/','706a20808fb3bf8927578ac86dcba125119b27a8f32d5db17139b9a74d05bdd2','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Daniel Weller","Sharat Chikkerur"]','structured','Prerequisites This course assumes a basic understanding of the principles of programming. Prior knowledge of C is neither expected nor desired. The primary prerequisite of this course is 6.00 Introduction to Computer Science and Programming , 1.00 Introduction to Computers and Engineering Problem Solving , 6.01 Introduction to Electrical Engineering and Computer Science I , or another introductory programming course at MIT. If you are unsure of the adequacy of your programming background, please speak to a member of the course staff as soon as possible. As the duration of this course is only three weeks, the material will be covered at a relatively fast pace, and catching up will be difficult.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('6.087',0,'6.00');
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('6.087',0,'1.00');
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('6.087',0,'6.01');
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.092','6.092','Introduction to Programming in Java','This course is an introduction to software engineering, using the Java™ programming language. It covers concepts useful to 6.005. Students will learn the fundamentals of Java. The focus is on developing high quality, working software that solves real problems. The course is designed for students with some programming experience, but if you have none and are motivated you will do fine. Students who have taken 6.005 should not take this course. Each class is composed of one hour of lecture and one hour of assisted lab work. This course is offered during the Independent Activities Period (IAP), which is a special 4-week term at MIT that runs from the first week of January until the end of the month.','Computer Science Engineering Programming Languages Software Design and Engineering','2010','https://ocw.mit.edu/courses/6-092-introduction-to-programming-in-java-january-iap-2010/','https://ocw.mit.edu/courses/6-092-introduction-to-programming-in-java-january-iap-2010/pages/syllabus/','ff44f85bc64d33098532d1c32b00807815ef4c7c713d17c8d48ffd3ec98b138c','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Evan Jones","Adam Marcus","Eugene Wu"]','review_required','No explicit prerequisite section was found in the archived syllabus HTML. Instructor review is required; no absence of requirements is inferred.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.101','6.101','Introductory Analog Electronics Laboratory','6.101 is an introductory experimental laboratory that explores the design, construction, and debugging of analog electronic circuits. Lectures and six laboratory projects investigate the performance characteristics of diodes, transistors, JFETs, and op-amps, including the construction of a small audio amplifier and preamplifier. Seven weeks are devoted to the design and implementation, and written and oral presentation of a project in an environment similar to that of engineering design teams in industry. The course provides opportunity to simulate real-world problems and solutions that involve trade offs and the use of engineering judgment. Engineers from local analog engineering companies come to campus to help students with their design projects.','Electrical Engineering Electronics Engineering','2007','https://ocw.mit.edu/courses/6-101-introductory-analog-electronics-laboratory-spring-2007/','https://ocw.mit.edu/courses/6-101-introductory-analog-electronics-laboratory-spring-2007/pages/syllabus/','054ce99fa8020bd16c1abc743f0f1379e83678b1c2c7d7bc431c7e506e273b71','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Ron Roscoe"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.163','6.163','Strobe Project Laboratory','This is a laboratory experience course with a focus on photography, electronic imaging, and light measurement, much of it at short duration. In addition to teaching these techniques, the course provides students with experience working in a laboratory and teaches good work habits and techniques for approaching laboratory work. A major purpose of 6.163 is to provide students with many opportunities to sharpen their communication skills: oral, written, and visual.','Atomic, Molecular, Optical Physics Electrical Engineering Engineering Fine Arts Photography Physics Science Visual Arts','2005','https://ocw.mit.edu/courses/6-163-strobe-project-laboratory-fall-2005/','https://ocw.mit.edu/courses/6-163-strobe-project-laboratory-fall-2005/pages/syllabus/','04edcc1772b17e7a56f3355cdb194a5656e76fae2793d8875e1423ce31319776','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. James Bales"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.186','6.186','Mobile Autonomous Systems Laboratory','MASLab (Mobile Autonomous System Laboratory), also known as 6.186, is a robotics contest. The contest takes place during MIT’s Independent Activities Period and participants earn 6 units of P/F credit and 6 Engineering Design Points. Teams of three to four students have less than a month to build and program sophisticated robots which must explore an unknown playing field and perform a series of tasks. MASLab provides a significantly more difficult robotics problem than many other university-level robotics contests. Although students know the general size, shape, and color of the floors and walls, the students do not know the exact layout of the playing field. In addition, MASLab robots are completely autonomous, or in other words, the robots operate, calculate, and plan without human intervention. Finally, MASLab is one of the few robotics contests in the country to use a vision based robotics problem.','Artificial Intelligence Computer Science Electrical Engineering Engineering Mechanical Engineering Robotics and Control Systems','2005','https://ocw.mit.edu/courses/6-186-mobile-autonomous-systems-laboratory-january-iap-2005/','https://ocw.mit.edu/courses/6-186-mobile-autonomous-systems-laboratory-january-iap-2005/pages/syllabus/','87cf88dce26ddea47d3a9fa3b42004df400facc2c5d278e8202fed7f0f03940f','https://creativecommons.org/licenses/by-nc-sa/4.0/','["No Faculty ","Prof. Leslie Kaelbling"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.189','6.189','A Gentle Introduction to Programming Using Python','This course will provide a gentle, yet intense, introduction to programming using Python for highly motivated students with little or no prior experience in programming. The course will focus on planning and organizing programs, as well as the grammar of the Python programming language. The course is designed to help prepare students for 6.01 Introduction to EECS I . 6.01 assumes some knowledge of Python upon entering; the course material for 6.189 has been specially designed to make sure that concepts important to 6.01 are covered. This course is offered during the Independent Activities Period (IAP), which is a special 4-week term at MIT that runs from the first week of January until the end of the month.','Computer Science Engineering Programming Languages Software Design and Engineering','2011','https://ocw.mit.edu/courses/6-189-a-gentle-introduction-to-programming-using-python-january-iap-2011/','https://ocw.mit.edu/courses/6-189-a-gentle-introduction-to-programming-using-python-january-iap-2011/pages/syllabus/','30303cccd283ad3d915c80a62254b0783e0d559e2829d0e154549d4d34917dd8','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Sarina Canelake"]','review_required','This course will provide a gentle, yet intense, introduction to programming using Python for highly motivated students with little or no prior experience in programming. The course will focus on planning and organizing programs, as well as the grammar of the Python programming language. The course is designed to help prepare students for 6.01 Introduction to EECS I . 6.01 assumes some knowledge of Python upon entering; the course material for 6.189 has been specially designed to make sure that concepts important to 6.01 are covered. This course is offered during the Independent Activities Period (IAP), which is a special 4-week term at MIT that runs from the first week of January until the end of the month.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.243J','6.243J','Dynamics of Nonlinear Systems','This course provides an introduction to nonlinear deterministic dynamical systems. Topics covered include: nonlinear ordinary differential equations; planar autonomous systems; fundamental theory: Picard iteration, contraction mapping theorem, and Bellman-Gronwall lemma; stability of equilibria by Lyapunov’s first and second methods; feedback linearization; and application to nonlinear circuits and control systems.','Computer Science Electrical Engineering Engineering Robotics and Control Systems Systems Engineering Theory of Computation','2003','https://ocw.mit.edu/courses/6-243j-dynamics-of-nonlinear-systems-fall-2003/','https://ocw.mit.edu/courses/6-243j-dynamics-of-nonlinear-systems-fall-2003/pages/syllabus/','17871f7ee7bb8f9d85a99eb7792d4e51a51bb96447be33f6d743fcad3f2f7311','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Alexandre Megretski"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.262','6.262','Discrete Stochastic Processes','Discrete stochastic processes are essentially probabilistic systems that evolve in time via random changes occurring at discrete fixed or random intervals. This course aims to help students acquire both the mathematical principles and the intuition necessary to create, analyze, and understand insightful models for a broad range of these processes. The range of areas for which discrete stochastic-process models are useful is constantly expanding, and includes many applications in engineering, physics, biology, operations research and finance.','Discrete Mathematics Mathematics Probability and Statistics','2011','https://ocw.mit.edu/courses/6-262-discrete-stochastic-processes-spring-2011/','https://ocw.mit.edu/courses/6-262-discrete-stochastic-processes-spring-2011/pages/syllabus/','fbfa7956715a2c109a69d70400f4228dc290f5af2675f61f898937e76ec4e356','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Robert Gallager"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.336J','6.336J','Introduction to Numerical Simulation (SMA 5211)','6.336J is an introduction to computational techniques for the simulation of a large variety of engineering and physical systems. Applications are drawn from aerospace, mechanical, electrical, chemical and biological engineering, and materials science. Topics include: mathematical formulations; network problems; sparse direct and iterative matrix solution techniques; Newton methods for nonlinear problems; discretization methods for ordinary, time-periodic and partial differential equations, fast methods for partial differential and integral equations, techniques for dynamical system model reduction and approaches for molecular dynamics. This course was also taught as part of the Singapore-MIT Alliance (SMA) programme as course number SMA 5211 (Introduction to Numerical Simulation).','Engineering Numerical Simulation Systems Engineering','2003','https://ocw.mit.edu/courses/6-336j-introduction-to-numerical-simulation-sma-5211-fall-2003/','https://ocw.mit.edu/courses/6-336j-introduction-to-numerical-simulation-sma-5211-fall-2003/pages/syllabus/','906aaf5b87f249f5b780d6a7a53ef1a4bf52a5b479b9d4522b1891aaf2c1eae8','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Jacob White","Prof. Jaime Peraire","Prof. Luca Daniel","Prof. Nicholas Hadjiconstantinou","Prof. Anthony T. Patera"]','review_required','18.03 or 18.06 or equivalent; and familiarity with MATLAB®.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.4210','6.4210','Robotic Manipulation','Introduces the fundamental algorithmic approaches for creating robot systems that can autonomously manipulate physical objects in unstructured environments such as homes and restaurants. Topics include perception (including approaches based on deep learning and approaches based on 3D geometry), planning (robot kinematics and trajectory generation, collision-free motion planning, task-and-motion planning, and planning under uncertainty), as well as dynamics and control (both model-based and learning-based). Homework assignments will guide students through building a software stack that will enable a robotic arm to autonomously manipulation objects in cluttered scenes (like a kitchen). A final project will allow students to dig deeper into a specific aspect of their choosing. The class has hardware available for ambitious final projects, but will also make heavy use of simulation using cloud resources.','Artificial Intelligence Computer Science Electrical Engineering Engineering Robotics and Control Systems','2022','https://ocw.mit.edu/courses/6-4210-robotic-manipulation-fall-2022/','https://ocw.mit.edu/courses/6-4210-robotic-manipulation-fall-2022/pages/syllabus/','2965636697da5fcc70a63708e03092a2a9facfe3650181fc3a449619186c324f','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Russell Tedrake"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.441','6.441','Information Theory','This is a graduate-level introduction to mathematics of information theory. We will cover both classical and modern topics, including information entropy, lossless data compression, binary hypothesis testing, channel coding, and lossy data compression.','Applied Mathematics Computation Computer Science Engineering Mathematics Probability and Statistics Theory of Computation','2016','https://ocw.mit.edu/courses/6-441-information-theory-spring-2016/','https://ocw.mit.edu/courses/6-441-information-theory-spring-2016/pages/syllabus/','4140014a69ed3476ceee9ce8fc7415d4e12e7d6e2a9720f3c69db8dec9405447','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Yury Polyanskiy"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.4590','6.4590','Foundations of Information Policy','In this class, we will consider the interaction between law, policy, and technology as they relate to the evolving controversies over control of the internet. Our goal is for participants to develop the technical, legal, and rhetorical skills to analyze and participate in the evolution of the global public policy environments that govern human behavior on the internet. Topics include history of internet policy, the relationship between technical architecture and law, privacy, cybersecurity, freedom of expression, intellectual property, electronic surveillance, trade policy, and international affairs.','Computer Science Engineering Public Administration Science and Technology Policy Social Science','2024','https://ocw.mit.edu/courses/6-4590-foundations-of-information-policy-fall-2024/','https://ocw.mit.edu/courses/6-4590-foundations-of-information-policy-fall-2024/pages/syllabus/','37cef1c8973bd65358b9b09d7ab021c5862909776658ed82b2ab0fc9a9753fdf','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Daniel Weitzner","Prof. Michael M.J. Fischer","Prof. Harold Abelson"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.5660','6.5660','Computer Systems Security','This course covers design and implementation of secure computer systems. The lectures cover attacks that compromise security as well as techniques for achieving security, based on recent research papers. Topics include operating system security, privilege separation, capabilities, language-based security, cryptographic network protocols, trusted hardware, and security in web applications and mobile phones. The labs involve implementing and compromising a web application that sandboxes arbitrary code, supporting TLS certificates, and adding two-factor authentication. The course materials, which can be accessed via the external link to the left, are available for reuse under a Creative Commons Attribution 3.0 license.','Computer Design and Engineering Computer Science Engineering Software Design and Engineering','2024','https://ocw.mit.edu/courses/6-5660-computer-systems-security-spring-2024/','https://ocw.mit.edu/courses/6-5660-computer-systems-security-spring-2024/pages/syllabus/','79b4da15158d790a8915ba8b55902ad51a586fc3731300fa600004f2df138502','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Nickolai Zeldovich"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.635','6.635','Advanced Electromagnetism','In 6.635, topics covered include: special relativity, electrodynamics of moving media, waves in dispersive media, microstrip integrated circuits, quantum optics, remote sensing, radiative transfer theory, scattering by rough surfaces, effective permittivities, random media, Green’s functions for planarly layered media, integral equations in electromagnetics, method of moments, time domain method of moments, EM waves in periodic structures: photonic crystals and negative refraction.','Atomic, Molecular, Optical Physics Electromagnetism Physics Quantum Mechanics Science','2003','https://ocw.mit.edu/courses/6-635-advanced-electromagnetism-spring-2003/','https://ocw.mit.edu/courses/6-635-advanced-electromagnetism-spring-2003/pages/syllabus/','730bb582e3a313cd97df2320652eaa3eb56caddabb00aadaea5a4e59c1e7ae1e','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Jin Au Kong"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.691','6.691','Seminar in Electric Power Systems','This course comprises of a seminar on planning and operation of modern electric power systems. Content varies with current interests of instructor and class; emphasis on engineering aspects, but economic issues may be examined too. Core topics include: overview of power system structure and operation; representation of components, including transmission lines, transformers, generating plants, loads; power flow analysis, dynamics and control of multimachine systems, steady-state and transient stability, system protection; economic dispatch; mobile and isolated power systems; computation and simulation.','Electric Power Electrical Engineering Electricity Energy Engineering','2006','https://ocw.mit.edu/courses/6-691-seminar-in-electric-power-systems-spring-2006/','https://ocw.mit.edu/courses/6-691-seminar-in-electric-power-systems-spring-2006/pages/syllabus/','90cc6bff22383295d28ffb76e32aa8b4a3c76f3319fa4eefa490e8abaf10f2ed','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. James L. Kirtley Jr."]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.763','6.763','Applied Superconductivity','This course provides a phenomenological approach to superconductivity, with emphasis on superconducting electronics. Topics include: electrodynamics of superconductors, London’s model, flux quantization, Josephson Junctions, superconducting quantum devices, equivalent circuits, high-speed superconducting electronics, and quantized circuits for quantum computing. The course also provides an overview of type II superconductors, critical magnetic fields, pinning, the critical state model, superconducting materials, and microscopic theory of superconductivity.','Electrical Engineering Electromagnetism Electronic Materials Electronics Engineering Materials Science and Engineering Physics Science','2005','https://ocw.mit.edu/courses/6-763-applied-superconductivity-fall-2005/','https://ocw.mit.edu/courses/6-763-applied-superconductivity-fall-2005/pages/syllabus/','db616622d850e843afa118ba787ffd80ae5baa23de421286759f4f7400c29076','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Terry Orlando"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.781J','6.781J','Submicrometer and Nanometer Technology','This course surveys techniques to fabricate and analyze submicron and nanometer structures, with applications. Optical and electron microscopy is reviewed. Additional topics that are covered include: surface characterization, preparation, and measurement techniques, resist technology, optical projection, interferometric, X-ray, ion, and electron lithography; Aqueous, ion, and plasma etching techniques; lift-off and electroplating; and ion implantation. Applications in microelectronics, microphotonics, information storage, and nanotechnology will also be explored. Acknowledgements The Instructors would like to thank Bob Barsotti, Bryan Cord, and Ben Wunsch for their work on the Atomic Force Microscope video. They would also like to thank Bryan Cord for creating each video.','Electrical Engineering Engineering Mechanical Engineering Microtechnology Nanotechnology','2006','https://ocw.mit.edu/courses/6-781j-submicrometer-and-nanometer-technology-spring-2006/','https://ocw.mit.edu/courses/6-781j-submicrometer-and-nanometer-technology-spring-2006/pages/syllabus/','f0e5300a7a5fd0e2d3e04e1e21e2dbfa30fa3690b4185bb05b4c847bed4c4d42','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. George Barbastathis","Prof. Henry Smith","Prof. Karl Berggren"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.801','6.801','Machine Vision','This course is an introduction to the process of generating a symbolic description of the environment from an image. It covers the physics of image formation, image analysis, binary image processing, and filtering. Machine vision has applications in robotics and the intelligent interaction of machines with their environment. Students taking the graduate version complete additional assignments.','Artificial Intelligence Computer Science Engineering Graphics and Visualization','2020','https://ocw.mit.edu/courses/6-801-machine-vision-fall-2020/','https://ocw.mit.edu/courses/6-801-machine-vision-fall-2020/pages/syllabus/','0d33f4ce0893eba33bbf800e7918bca4fbeddf9cf343e7c1f2bed350d62883bb','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Berthold Horn"]','structured','Prerequisites 6.003 Signal Processing or permission of the instructor.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('6.801',0,'6.003');
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.811','6.811','Principles and Practice of Assistive Technology','6.811: Principles and Practice of Assistive Technology (PPAT) is an interdisciplinary, project-based course, centered around a design project in which small teams of students work closely with a person with a disability in the Cambridge area to design a device, piece of equipment, app, or other solution that helps them live more independently.','Computer Science Electrical Engineering Electronics Engineering Health and Medicine Human-Computer Interfaces Mechanical Design Mechanical Engineering Public Health','2014','https://ocw.mit.edu/courses/6-811-principles-and-practice-of-assistive-technology-fall-2014/','https://ocw.mit.edu/courses/6-811-principles-and-practice-of-assistive-technology-fall-2014/pages/syllabus/','4b1ca55f4cb3da0725dd4870b9da39d2fe52e7f4af621a5a16df7a73a79fd31d','https://creativecommons.org/licenses/by-nc-sa/4.0/','["William Li","Grace Teo","Prof. Robert Miller"]','no_formal_course','There are no formal prerequisites for the course. We seek students from a wide range of backgrounds and disciplines. Teams of three to four students will complement each other’s skill sets. Many of the students are in Mechanical Engineering, Electrical Engineering, and Computer Science, but students from all majors are welcome. This course is a good fit for students interested in public service, user-centered product design, working closely with a client with a disability (potentially in consultation with their caregivers and / or clinicians), and tackling difficult, real-world problems.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.826','6.826','Principles of Computer Systems','6.826 provides an introduction to the basic principles of computer systems, with emphasis on the use of rigorous techniques as an aid to understanding and building modern computing systems. Particular attention is paid to concurrent and distributed systems. Topics covered include: specification and verification, concurrent algorithms, synchronization, naming, networking, replication techniques (including distributed cache management), and principles and algorithms for achieving reliability.','Computer Design and Engineering Computer Science Engineering Theory of Computation','2002','https://ocw.mit.edu/courses/6-826-principles-of-computer-systems-spring-2002/','https://ocw.mit.edu/courses/6-826-principles-of-computer-systems-spring-2002/pages/syllabus/','59308058eb19ddf2d1d39b13bd4a474f5a09c7d0242070039a949f0d0a94d1cc','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Butler Lampson","Prof. Martin Rinard"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.830','6.830','Database Systems','This course relies on primary readings from the database community to introduce graduate students to the foundations of database systems, focusing on basics such as the relational algebra and data model, schema normalization, query optimization, and transactions. It is designed for students who have taken 6.033 (or equivalent); no prior database experience is assumed, though students who have taken an undergraduate course in databases are encouraged to attend.','Algorithms and Data Structures Business Computer Science Data Mining Engineering Information Technology Software Design and Engineering','2010','https://ocw.mit.edu/courses/6-830-database-systems-fall-2010/','https://ocw.mit.edu/courses/6-830-database-systems-fall-2010/pages/syllabus/','4b89ff9d9999fc7f7275d899199b61335976bcbeed2f75095af3db2c6d064b9b','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Samuel Madden","Prof. Robert Morris","Prof. Michael Stonebraker","Dr. Carlo Curino"]','structured','Prerequisites Students should have taken 6.033 Introduction to Systems or equivalent as well as 6.006 Introduction to Algorithms or equivalent. If you do not have experience in these subjects and would like to take the course, please contact the instructor. Prior database experience is not required.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('6.830',0,'6.033');
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('6.830',1,'6.006');
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.831','6.831','User Interface Design and Implementation','6.831/6.813 examines human-computer interaction in the context of graphical user interfaces. The course covers human capabilities, design principles, prototyping techniques, evaluation techniques, and the implementation of graphical user interfaces. Deliverables include short programming assignments and a semester-long group project. Students taking the graduate version also have readings from current literature and additional assignments.','Computer Science Engineering Fine Arts Graphic Design Human-Computer Interfaces Software Design and Engineering Visual Arts','2011','https://ocw.mit.edu/courses/6-831-user-interface-design-and-implementation-spring-2011/','https://ocw.mit.edu/courses/6-831-user-interface-design-and-implementation-spring-2011/pages/syllabus/','7508c8e8f6edf7de7fb1260c07192175eca1f210305eb3522d6dff5fffc7982b','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Robert Miller"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.837','6.837','Computer Graphics','This course provides introduction to computer graphics algorithms, software and hardware. Topics include: ray tracing, the graphics pipeline, transformations, texture mapping, shadows, sampling, global illumination, splines, animation and color. This course offers 6 Engineering Design Points in MIT’s EECS program.','Algorithms and Data Structures Computer Science Engineering Graphics and Visualization Programming Languages','2012','https://ocw.mit.edu/courses/6-837-computer-graphics-fall-2012/','https://ocw.mit.edu/courses/6-837-computer-graphics-fall-2012/pages/syllabus/','17696ba18176d5bdcb5ce871d4bb63efdc4278a0ae9aa49434354335b38dcb7f','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Wojciech Matusik","Prof. Frédo Durand"]','review_required','Prerequisites It is useful if you have knowledge of the following: C++: All assignments are in C++ Calculus, Linear Algebra: Solving equations, derivatives, integral; vectors, matrices, basis, solving systems of equations') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.849','6.849','Geometric Folding Algorithms: Linkages, Origami, Polyhedra','This course focuses on the algorithms for analyzing and designing geometric foldings. Topics include reconfiguration of foldable structures, linkages made from one-dimensional rods connected by hinges, folding two-dimensional paper (origami), and unfolding and folding three-dimensional polyhedra. Applications to architecture, robotics, manufacturing, and biology are also covered in this course. Acknowledgments Thanks to videographers Martin Demaine and Jayson Lynch.','Algorithms and Data Structures Computer Science Engineering Fine Arts Mathematics Topology and Geometry Visual Arts','2012','https://ocw.mit.edu/courses/6-849-geometric-folding-algorithms-linkages-origami-polyhedra-fall-2012/','https://ocw.mit.edu/courses/6-849-geometric-folding-algorithms-linkages-origami-polyhedra-fall-2012/pages/syllabus/','3b8b44744be83574fe038ea7d4aed304bf063a504df19c71a951d616eeb9de2b','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Erik Demaine"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.857','6.857','Network and Computer Security','6.857 Network and Computer Security is an upper-level undergraduate, first-year graduate course on network and computer security. It fits within the Computer Systems and Architecture Engineering concentration.','Computer Networks Computer Science Cryptography Engineering Public Administration Security Studies Social Science','2014','https://ocw.mit.edu/courses/6-857-network-and-computer-security-spring-2014/','https://ocw.mit.edu/courses/6-857-network-and-computer-security-spring-2014/pages/syllabus/','9a62201a1fd4ab892178bab5f2ba1ead702b2c7142f1106dfb5ae96d3912f11d','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Ronald Rivest"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.858','6.858','Computer Systems Security','6.858 Computer Systems Security is a class about the design and implementation of secure computer systems. Lectures cover threat models, attacks that compromise security, and techniques for achieving security, based on recent research papers. Topics include operating system (OS) security, capabilities, information flow control, language security, network protocols, hardware security, and security in web applications.','Computer Design and Engineering Computer Science Engineering Software Design and Engineering','2014','https://ocw.mit.edu/courses/6-858-computer-systems-security-fall-2014/','https://ocw.mit.edu/courses/6-858-computer-systems-security-fall-2014/pages/syllabus/','49b963877ae1f67e1bcae9f7ac38ef4000acaf962815d8f7eae1ea949bf03394','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Nickolai Zeldovich"]','structured','Prerequisites 6.033 Computer System Engineering') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_prerequisite (course_code,group_no,prerequisite_code) VALUES ('6.858',0,'6.033');
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.867','6.867','Machine Learning','6.867 is an introductory course on machine learning which gives an overview of many concepts, techniques, and algorithms in machine learning, beginning with topics such as classification and linear regression and ending up with more recent topics such as boosting, support vector machines, hidden Markov models, and Bayesian networks. The course will give the student the basic ideas and intuition behind modern machine learning methods as well as a bit more formal understanding of how, why, and when they work. The underlying theme in the course is statistical inference as it provides the foundation for most of the methods covered.','Algorithms and Data Structures Artificial Intelligence Cognitive Science Computer Science Engineering Mathematics Probability and Statistics Science','2006','https://ocw.mit.edu/courses/6-867-machine-learning-fall-2006/','https://ocw.mit.edu/courses/6-867-machine-learning-fall-2006/pages/syllabus/','d13486e12af36ea1f87ca0dae67a100656567d3e75aa46ce62e6d661d6883b28','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Rohit Singh","Prof. Tommi Jaakkola","Ali Mohammad"]','review_required','No explicit prerequisite section was found in the archived syllabus HTML. Instructor review is required; no absence of requirements is inferred.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.871','6.871','Knowledge-Based Applications Systems','This course covers the development of programs containing a significant amount of knowledge about their application domain. The course includes a brief review of relevant AI techniques; case studies from a number of application domains, chosen to illustrate principles of system development; a discussion of technical issues encountered in building a system, including selection of knowledge representation, knowledge acquisition, etc.; and a discussion of current and future research. The course also provides hands-on experience in building an expert system (term project).','Artificial Intelligence Business Computer Science Data Mining Engineering Information Technology Software Design and Engineering','2005','https://ocw.mit.edu/courses/6-871-knowledge-based-applications-systems-spring-2005/','https://ocw.mit.edu/courses/6-871-knowledge-based-applications-systems-spring-2005/pages/syllabus/','4cecc239c1afbc0793587533c33e3f6775e75991cb6e8fc169404257f0474932','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Randall Davis"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.883','6.883','Pervasive Human Centric Computing (SMA 5508)','This course is broad, covering a wide range of topics that have to do with the post-pc era of computing. It is a hands-on project course that also includes some foundational subjects. Students will program iPAQ handheld computers, cell phones (series 60 phones), speech processing, vision, Cricket location systems, GPS, and more. Most of the programming will be using Python®, but Python® can be learned and mastered during the course. This course was also taught as part of the Singapore-MIT Alliance (SMA) programme as course number SMA 5508 (Pervasive Computing).','Computer Science Engineering Human-Computer Interfaces Programming Languages Theory of Computation','2006','https://ocw.mit.edu/courses/6-883-pervasive-human-centric-computing-sma-5508-spring-2006/','https://ocw.mit.edu/courses/6-883-pervasive-human-centric-computing-sma-5508-spring-2006/pages/syllabus/','77b4e7c7df3004c56e9d90ae2a67a732063cffe1548ba38c08240692e0a8a41e','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Larry Rudolph"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.895','6.895','Theory of Parallel Systems (SMA 5509)','6.895 covers theoretical foundations of general-purpose parallel computing systems, from languages to architecture. The focus is on the algorithmic underpinnings of parallel systems. The topics for the class will vary depending on student interest, but will likely include multithreading, synchronization, race detection, load balancing, memory consistency, routing networks, message-routing algorithms, and VLSI layout theory. The class will emphasize randomized algorithms and probabilistic analysis, including high-probability arguments. This course was also taught as part of the Singapore-MIT Alliance (SMA) programme as course number SMA 5509 (Theory of Parallel Systems).','Algorithms and Data Structures Computer Science Engineering Theory of Computation','2003','https://ocw.mit.edu/courses/6-895-theory-of-parallel-systems-sma-5509-fall-2003/','https://ocw.mit.edu/courses/6-895-theory-of-parallel-systems-sma-5509-fall-2003/pages/syllabus/','dbb3ed44f7c7c5552909baa95f32d2ceb3412195b8310419d878222f8f439ec5','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Bradley Kuszmaul","Prof. Charles Leiserson","Prof. Hsu Wen Jing","Prof. Michael Bender"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.931','6.931','Development of Inventions and Creative Ideas','This course examines the role of the engineer as patent expert and as technical witness in court and patent interference and related proceedings. It discusses the rights and obligations of engineers in connection with educational institutions, government, and large and small businesses. It compares various manners of transplanting inventions into business operations, including development of New England and other U.S. electronics and biotechnology industries and their different types of institutions. The course also considers American systems of incentive to creativity apart from the patent laws in the atomic energy and space fields. Acknowledgment The instructors would like to thank Joanne Rines and Elijah Ercolino for their efforts in preparing this course.','Business Engineering Innovation Legal Studies Public Administration Science and Technology Policy Social Science','2008','https://ocw.mit.edu/courses/6-931-development-of-inventions-and-creative-ideas-spring-2008/','https://ocw.mit.edu/courses/6-931-development-of-inventions-and-creative-ideas-spring-2008/pages/syllabus/','ced9568312eba283fa4cf528fa9b593a7fd0345a2bf8a520a4ced6854abcfb2d','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Dedric Carter","Dr. Robert Rines"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.976','6.976','High Speed Communication Circuits and Systems','6.976 covers circuit and system level design issues of high speed communication systems, with primary focus being placed on wireless and broadband data link applications. Specific circuit topics include transmission lines, high speed and low noise amplifiers, VCO’s, and high speed digital circuits. Specific system topics include frequency synthesizers, clock and data recovery circuits, and GMSK transceivers. In addition to learning analysis skills for the above items, students will gain a significant amount of experience in simulating circuits in SPICE and systems in CppSim (a custom C++ simulator).','Computer Design and Engineering Computer Networks Computer Science Digital Systems Electrical Engineering Engineering Telecommunications','2003','https://ocw.mit.edu/courses/6-976-high-speed-communication-circuits-and-systems-spring-2003/','https://ocw.mit.edu/courses/6-976-high-speed-communication-circuits-and-systems-spring-2003/pages/syllabus/','6201faf48765f84150a1ae418bc391da379d51e6b1b978543d37dcb7771b1923','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Michael Perrott"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.S087','6.S087','Foundation Models and Generative AI','ChatGPT, Copilot, CLIP, Dall-E, Stable-Diffusion, AlphaFold, self-driving cars—is now the time that artificial intelligence (AI) lives up to all its hype? What’s the secret sauce behind these recent breakthroughs within AI? They’re called foundation models and generative AI, and it is changing everything. With the help of it, some believe that artificial general intelligence (AGI) has already been achieved. In this non-technical series of lectures, we will start with a short history of AI, then move on to with what supervised learning and reinforcement learning is missing, and conclude with the deep practical and foundational implications foundation models and how we arrive at them via self-supervised learning. We cover applications in both science and business. All backgrounds are welcome.','Artificial Intelligence Computer Science Engineering','2024','https://ocw.mit.edu/courses/6-s087-foundation-models-and-generative-ai-january-iap-2024/','https://ocw.mit.edu/courses/6-s087-foundation-models-and-generative-ai-january-iap-2024/pages/syllabus/','30b2a6d1f8cefb8284b87d176ddeead08f38f8e147c4aa66857d1d7397c9b1df','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Rickard Gabrielsson"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('6.S897','6.S897','Machine Learning for Healthcare','This course introduces students to machine learning in healthcare, including the nature of clinical data and the use of machine learning for risk stratification, disease progression modeling, precision medicine, diagnosis, subtype discovery, and improving clinical workflows.','Artificial Intelligence Computer Science Engineering Health and Medicine Human-Computer Interfaces Medical Imaging Public Health','2019','https://ocw.mit.edu/courses/6-s897-machine-learning-for-healthcare-spring-2019/','https://ocw.mit.edu/courses/6-s897-machine-learning-for-healthcare-spring-2019/pages/syllabus/','9080f3004022f01a0bf0b2da3f7fb4a1bbf147e5cc8e6430aeab49cb68cdc9a4','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Peter Szolovits","Prof. David Sontag"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('7.003','7.003','Applied Molecular Biology Lab','7.003 is an experimental biology course. You will spend most of your time in the teaching laboratory practicing fundamental techniques in molecular biology, genetics, and cell biology, and working with the model organism Saccharomyces cerevisiae (budding yeast). In addition to learning how to accurately and safely perform these techniques, we want to help you understand how and why they work and what scientific questions they can address. The goal is for you to be able to design your own experiments to perform by the end of the semester.','Biology Cell Biology Genetics Molecular Biology Science','2022','https://ocw.mit.edu/courses/7-003-applied-molecular-biology-lab-spring-2022/','https://ocw.mit.edu/courses/7-003-applied-molecular-biology-lab-spring-2022/pages/syllabus/','a4bdaca693a361025ae439d23ccc76cc83f4f682f45148defef6df15ffef242b','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Vanessa Cheung","Dr. Eric Chu"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('7.01','7.01SC','Fundamentals of Biology','Fundamentals of Biology focuses on the basic principles of biochemistry, molecular biology, genetics, and recombinant DNA. These principles are necessary to understanding the basic mechanisms of life and anchor the biological knowledge that is required to understand many of the challenges in everyday life, from human health and disease to loss of biodiversity and environmental quality. Course Format This course has been designed for independent study. It consists of four units, one for each topic. The units can be used individually or in combination. The materials for each unit include: Lecture Videos by MIT faculty. Learning activities, including Interactive Concept Quizzes , designed to reinforce main concepts from lectures. Problem Sets you do on your own and check your answers against the Solutions when you’re done. Problem Solving Video help sessions taught by experienced MIT Teaching Assistants. Lists of important Terms and Definitions. Suggested Topics and Links for further study. Exams with Solution Keys. Content Development Eric Lander Robert Weinberg Tyler Jacks Hazel Sive Graham Walker Sallie Chisholm Dr. Michelle Mischke','Biology Science','2011','https://ocw.mit.edu/courses/7-01sc-fundamentals-of-biology-fall-2011/','https://ocw.mit.edu/courses/7-01sc-fundamentals-of-biology-fall-2011/pages/syllabus/','c4f8a60bf40ee9ba31d48e2c3666ce1d32da316f4384ebd7825ad2f97564fa02','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Eric Lander","Prof. Robert Weinberg","Prof. Tyler Jacks","Prof. Hazel Sive","Prof. Graham Walker","Prof. Sallie Chisholm","Dr. Michelle Mischke"]','no_formal_course','There are no formal prerequisites for this course. At MIT, it is usually taken during the freshman (first) year. Prior to taking this course, you may want to review Pre-7.01 Getting up to Speed in Biology , a self-paced course designed to help prepare students for their first college-level biology class.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('7.16','7.16','Experimental Molecular Biology: Biotechnology II','The course applies molecular biology and reverse genetics approaches to the study of apoptosis, or programmed cell death (PCD), in Drosophila cells. RNA interference (RNAi), or double stranded RNA-mediated gene silencing, will be used to inhibit expression of candidate apoptosis-related genes in cultured Drosophila cells. Teams of 2 or 3 students will design and carry out experiments to address questions about the genes involved in the regulation and execution of PCD in this system. Some projects involve the use of DNA damaging agents or other cytotoxic chemicals or drugs to help understand the pathways that control a cell’s decision to undergo apoptosis. Instruction and practice in written and oral communication are provided.','Biological Engineering Biology Biotechnology Engineering Molecular Biology Science','2005','https://ocw.mit.edu/courses/7-16-experimental-molecular-biology-biotechnology-ii-spring-2005/','https://ocw.mit.edu/courses/7-16-experimental-molecular-biology-biotechnology-ii-spring-2005/pages/syllabus/','f5d59dad42f6e2a6831008a527cd3611f3180f8d7d77244cd82c46fabb56af11','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Christopher Burge","Prof. David Sabatini","Dr. Marilee Ogren-Balkema","Dr. Alice Rushforth"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('7.89J','7.89J','Topics in Computational and Systems Biology','This is a seminar based on research literature. Papers covered are selected to illustrate important problems and approaches in the field of computational and systems biology, and provide students a framework from which to evaluate new developments. The MIT Initiative in Computational and Systems Biology ( CSBi ) is a campus-wide research and education program that links biology, engineering, and computer science in a multidisciplinary approach to the systematic analysis and modeling of complex biological phenomena. This course is one of a series of core subjects offered through the CSB Ph.D. program, for students with an interest in interdisciplinary training and research in the area of computational and systems biology.','Biological Engineering Biology Computation and Systems Biology Computational Biology Engineering Science','2010','https://ocw.mit.edu/courses/7-89j-topics-in-computational-and-systems-biology-fall-2010/','https://ocw.mit.edu/courses/7-89j-topics-in-computational-and-systems-biology-fall-2010/pages/syllabus/','7b56ce2c162879a14be7b099ebbdcae94c810b881809c3744977ab30ac62c54a','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Christopher Burge","Prof. Jeff Gore","Prof. Wendy Gilbert","Prof. Bruce Tidor","Prof. Forest White"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('8.01','8.01SC','Classical Mechanics','This first course in the physics curriculum introduces classical mechanics. Historically, a set of core concepts—space, time, mass, force, momentum, torque, and angular momentum—were introduced in classical mechanics in order to solve the most famous physics problem, the motion of the planets. The principles of mechanics successfully described many other phenomena encountered in the world. Conservation laws involving energy, momentum and angular momentum provided a second parallel approach to solving many of the same problems. In this course, we will investigate both approaches: Force and conservation laws. Our goal is to develop a conceptual understanding of the core concepts, a familiarity with the experimental verification of our theoretical laws, and an ability to apply the theoretical framework to describe and predict the motions of bodies.','Classical Mechanics Physics Science','2016','https://ocw.mit.edu/courses/8-01sc-classical-mechanics-fall-2016/','https://ocw.mit.edu/courses/8-01sc-classical-mechanics-fall-2016/pages/syllabus/','a65c112a121ba88f201cc7803f2c9242d793503a7bab7f119f3c797194e8e86e','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Deepto Chakrabarty","Dr. Peter Dourmashkin","Dr. Michelle Tomasik","Prof. Anna Frebel","Prof. Vladan Vuletic"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('8.02X','8.02X','Physics II: Electricity & Magnetism with an Experimental Focus','This course is an introduction to electromagnetism and electrostatics. Topics include: electric charge, Coulomb’s law, electric structure of matter, conductors and dielectrics, concepts of electrostatic field and potential, electrostatic energy, electric currents, magnetic fields, Ampere’s law, magnetic materials, time-varying fields, Faraday’s law of induction, basic electric circuits, electromagnetic waves, and Maxwell’s equations. The course has an experimental focus, and includes several experiments that are intended to illustrate the concepts being studied. Acknowledgements Prof. Roland wishes to acknowledge that the structure and content of this course owe much to the contributions of Prof. Ambrogio Fasoli.','Electromagnetism Physics Science','2005','https://ocw.mit.edu/courses/8-02x-physics-ii-electricity-magnetism-with-an-experimental-focus-spring-2005/','https://ocw.mit.edu/courses/8-02x-physics-ii-electricity-magnetism-with-an-experimental-focus-spring-2005/pages/syllabus/','69f6f85a4d7eb983cc370cfb0ab81489b14e06e73b36b3cedbd3fd6dcad70548','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Gunther M. Roland","Dr. Peter Dourmashkin"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('8.044','8.044','Statistical Physics I','This course offers an introduction to probability, statistical mechanics, and thermodynamics. Numerous examples are used to illustrate a wide variety of physical phenomena such as magnetism, polyatomic gases, thermal radiation, electrons in solids, and noise in electronic devices. This course is an elective subject in MIT’s undergraduate Energy Studies Minor . This Institute-wide program complements the deep expertise obtained in any major with a broad understanding of the interlinked realms of science, technology, and social sciences as they relate to energy and associated environmental challenges.','Mathematics Physics Probability and Statistics Science Thermodynamics','2013','https://ocw.mit.edu/courses/8-044-statistical-physics-i-spring-2013/','https://ocw.mit.edu/courses/8-044-statistical-physics-i-spring-2013/pages/syllabus/','e8405abbbdd9667decd6afc780a57a23a72ada53892c0c7ca10bf9c3b25df154','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Thomas Greytak"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('8.08','8.08','Statistical Physics II','This course covers probability distributions for classical and quantum systems. Topics include: Microcanonical, canonical, and grand canonical partition-functions and associated thermodynamic potentials. Also discussed are conditions of thermodynamic equilibrium for homogenous and heterogenous systems. The course follows 8.044 , Statistical Physics I, and is second in this series of undergraduate Statistical Physics courses.','Classical Mechanics Mathematics Physics Probability and Statistics Quantum Mechanics Science','2005','https://ocw.mit.edu/courses/8-08-statistical-physics-ii-spring-2005/','https://ocw.mit.edu/courses/8-08-statistical-physics-ii-spring-2005/pages/syllabus/','fad4e66781099eff7f031069854a11c281dc61c36a1eb90dedac172532db17ad','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Xiao-Gang Wen"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('8.224','8.224','Exploring Black Holes: General Relativity & Astrophysics','Study of physical effects in the vicinity of a black hole as a basis for understanding general relativity, astrophysics, and elements of cosmology. Extension to current developments in theory and observation. Energy and momentum in flat spacetime; the metric; curvature of spacetime near rotating and nonrotating centers of attraction; trajectories and orbits of particles and light; elementary models of the Cosmos. Weekly meetings include an evening seminar and recitation. The last third of the semester is reserved for collaborative research projects on topics such as the Global Positioning System, solar system tests of relativity, descending into a black hole, gravitational lensing, gravitational waves, Gravity Probe B, and more advanced models of the Cosmos.','Astrophysics Physics Relativity Science','2003','https://ocw.mit.edu/courses/8-224-exploring-black-holes-general-relativity-astrophysics-spring-2003/','https://ocw.mit.edu/courses/8-224-exploring-black-holes-general-relativity-astrophysics-spring-2003/pages/syllabus/','951438aaa1df2cfefb455d4c1bd50c6e1cf17f025cd4b5126400318037ec7f52','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Edmund Bertschinger","Prof. Edwin F. Taylor"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('8.321','8.321','Quantum Theory I','This is the first semester of a two-semester graduate-level subject on quantum theory, stressing principles. Quantum theory explains the nature and behavior of matter and energy on the atomic and subatomic level. Topics include Fundamental Concepts, Quantum Dynamics, Composite Systems, Symmetries in Quantum Mechanics, and Approximation Methods.','Physics Quantum Mechanics Science Theoretical Physics','2017','https://ocw.mit.edu/courses/8-321-quantum-theory-i-fall-2017/','https://ocw.mit.edu/courses/8-321-quantum-theory-i-fall-2017/pages/syllabus/','c437b939ca99e8c9bcd5088a2b7c320b04dae9b3ba99cb5c1ec2fc638acb95ac','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Senthil Todadri"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('8.333','8.333','Statistical Mechanics I:  Statistical Mechanics of Particles','Statistical Mechanics is a probabilistic approach to equilibrium properties of large numbers of degrees of freedom. In this two-semester course, basic principles are examined. Topics include: Thermodynamics, probability theory, kinetic theory, classical statistical mechanics, interacting systems, quantum statistical mechanics, and identical particles.','Mathematics Particle Physics Physics Probability and Statistics Quantum Mechanics Science Thermodynamics','2013','https://ocw.mit.edu/courses/8-333-statistical-mechanics-i-statistical-mechanics-of-particles-fall-2013/','https://ocw.mit.edu/courses/8-333-statistical-mechanics-i-statistical-mechanics-of-particles-fall-2013/pages/syllabus/','b7fc50068e5e85d567f83019ff37084805a8c0d7da69c64ce2ae3cd1adf7598e','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Mehran Kardar"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('8.511','8.511','Theory of Solids I','This is the first term of a theoretical treatment of the physics of solids. Topics covered include crystal structure and band theory, density functional theory, a survey of properties of metals and semiconductors, quantum Hall effect, phonons, electron phonon interaction and superconductivity.','Atomic, Molecular, Optical Physics Condensed Matter Physics Engineering Mechanical Engineering Physics Science Solid Mechanics','2004','https://ocw.mit.edu/courses/8-511-theory-of-solids-i-fall-2004/','https://ocw.mit.edu/courses/8-511-theory-of-solids-i-fall-2004/pages/syllabus/','82693a93e69f9dbf3131f0300e49978cb50ace0f50cca0a77c1245d2149ae5b6','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Patrick Lee"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('8.591J','8.591J','Systems Biology','This course provides an introduction to cellular and population-level systems biology with an emphasis on synthetic biology, modeling of genetic networks, cell-cell interactions, and evolutionary dynamics. Cellular systems include genetic switches and oscillators, network motifs, genetic network evolution, and cellular decision-making. Population-level systems include models of pattern formation, cell-cell communication, and evolutionary systems biology.','Biological Engineering Biology Cell Biology Computation and Systems Biology Engineering Physics Science Synthetic Biology','2014','https://ocw.mit.edu/courses/8-591j-systems-biology-fall-2014/','https://ocw.mit.edu/courses/8-591j-systems-biology-fall-2014/pages/syllabus/','f33f93e307a50f1cb37e6711c1abbc16be97ed4e3f5c0b2eb4676899e98aa91a','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Jeff Gore"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('8.851','8.851','Effective Field Theory','Effective field theory is a fundamental framework to describe physical systems with quantum field theory. Part I of this course covers common tools used in effective theories. Part II is an in depth study of the Soft-Collinear Effective Theory (SCET), an effective theory for hard interactions in collider physics.','Particle Physics Physics Science','2013','https://ocw.mit.edu/courses/8-851-effective-field-theory-spring-2013/','https://ocw.mit.edu/courses/8-851-effective-field-theory-spring-2013/pages/syllabus/','c5c5afafad9c30da0075e9c2fb44b3a5d700590e3cbaf138b11be411bc947726','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Iain Stewart"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('8.942','8.942','Cosmology','This course provides an overview of astrophysical cosmology with emphasis on the Cosmic Microwave Background (CMB) radiation, galaxies and related phenomena at high redshift, and cosmic structure formation. Additional topics include cosmic inflation, nucleosynthesis and baryosynthesis, quasar (QSO) absorption lines, and gamma-ray bursts. Some background in general relativity is assumed.','Astrophysics Physics Science','2001','https://ocw.mit.edu/courses/8-942-cosmology-fall-2001/','https://ocw.mit.edu/courses/8-942-cosmology-fall-2001/pages/syllabus/','5014ce6c0abff8e15fafee24bd2b7398a0664259d8a3aa70b7b2fde34d5312cf','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Edmund Bertschinger"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('9.01','9.01','Neuroscience and Behavior','This course covers the relation of structure and function at various levels of neuronal integration. Topics include functional neuroanatomy and neurophysiology, sensory and motor systems, centrally programmed behavior, sensory systems, sleep and dreaming, motivation and reward, emotional displays of various types, “higher functions” and the neocortex, and neural processes in learning and memory.','Biology Cognitive Science Neuroscience Psychology Science Social Science','2003','https://ocw.mit.edu/courses/9-01-neuroscience-and-behavior-fall-2003/','https://ocw.mit.edu/courses/9-01-neuroscience-and-behavior-fall-2003/pages/syllabus/','6a487a26211b27060b080a532b0b9ff0628e374e0e0f48bf8009d6d9a9398b8a','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Gerald E. Schneider"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('9.04','9.04','Sensory Systems','This course examines the neural bases of sensory perception. The focus is on physiological and anatomical studies of the mammalian nervous system as well as behavioral studies of animals and humans. Topics include visual pattern, color and depth perception, auditory responses and sound localization, and somatosensory perception.','Anatomy and Physiology Biology Health and Medicine Neurobiology Neuroscience Science Sensory-Neural Systems','2013','https://ocw.mit.edu/courses/9-04-sensory-systems-fall-2013/','https://ocw.mit.edu/courses/9-04-sensory-systems-fall-2013/pages/syllabus/','b303527697901c962be47b68b36f281ac5bc08f894b189628a4ee90c73e07661','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Peter H. Schiller","Prof. M. Christian Brown"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('9.123','9.123','Neurotechnology in Action','This course, as a part of MIT’s Center for Neurobiological Engineering curriculum , explores cutting-edge neurotechnology that is essential for advances in all aspects of neuroscience, including improvements in existing methods as well as the development, testing and discussion of completely new paradigms. Readings and in-class sessions cover the fields of electrophysiology, light microscopy, cellular engineering, optogenetics, electron microscopy, MRI / fMRI, and MEG / EEG. The course is designed with lectures that cover the background, context, and theoretical descriptions of neurotechnologies, and labs, which provide firsthand demonstrations as well as in situ lab tours.','Biological Engineering Biomedical Instrumentation Biotechnology Cognitive Science Engineering Health and Medicine Science','2014','https://ocw.mit.edu/courses/9-123-neurotechnology-in-action-fall-2014/','https://ocw.mit.edu/courses/9-123-neurotechnology-in-action-fall-2014/pages/syllabus/','483bd730b75dfa33980e251046b02b7f77432c1dfd8bd5d2b71ffec1e413d8f5','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Alan Jasanoff","Prof. Edward Boyden","Maxine Jonas"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('9.20','9.20','Animal Behavior','The introductory topics will cover various approaches to the study of animals and their behavior. Key concepts in studies of animal behavior, emphasizing ethology, are covered in class and in the assigned readings from Scott (2005), supplemented by selections from other books, especially from classics in the field as well as selected videos. Next, key concepts in sociobiology are covered using readings from Alcock (2001), supplemented by selections from additional books and some video presentations.','Biology Cognitive Science Ecology Science','2013','https://ocw.mit.edu/courses/9-20-animal-behavior-fall-2013/','https://ocw.mit.edu/courses/9-20-animal-behavior-fall-2013/pages/syllabus/','e84d7e03205b7d8193737a3ed401ba0fa62014a5cad524b036d75ad946f27343','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Gerald E. Schneider"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('9.35','9.35','Sensation And Perception','This course provides an introduction to important philosophical questions about the mind, specifically those that are intimately connected with contemporary psychology and neuroscience. Are our concepts innate, or are they acquired by experience? (And what does it even mean to call a concept ‘innate’?) Are ‘mental images’ pictures in the head? Is color in the mind or in the world? Is the mind nothing more than the brain? Can there be a science of consciousness? The course will include guest lectures by Professors.','Biology Cognitive Science Health and Medicine Neuroscience Psychology Science Sensory-Neural Systems Social Science','2009','https://ocw.mit.edu/courses/9-35-sensation-and-perception-spring-2009/','https://ocw.mit.edu/courses/9-35-sensation-and-perception-spring-2009/pages/syllabus/','5cb7a56d1d490b8ae415672c25ff123d7a78093b8a32390461af1b4c8cb20af0','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Benjamin Balas"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('9.46','9.46','Neuroscience of Morality','How do we decide whether an action is morally wrong? How do we choose to do what is right? When and why do we punish wrong-doers? Moral behavior and moral evaluation are functions of the human brain. It is just becoming possible to use neuroscientific methods to understand how they work. This course will consider the mechanisms of morality as a question for neuroscientists.','Cognitive Science Psychology Science Social Science','2017','https://ocw.mit.edu/courses/9-46-neuroscience-of-morality-fall-2017/','https://ocw.mit.edu/courses/9-46-neuroscience-of-morality-fall-2017/pages/syllabus/','f46d7e367bb3482c317a95d2aeebadbe9d0709117bd47acbbd68ab413a894b79','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Rebecca Saxe"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('9.520','9.520','Statistical Learning Theory and Applications','This course is for upper-level graduate students who are planning careers in computational neuroscience. This course focuses on the problem of supervised learning from the perspective of modern statistical learning theory starting with the theory of multivariate function approximation from sparse data. It develops basic tools such as Regularization including Support Vector Machines for regression and classification. It derives generalization bounds using both stability and VC theory. It also discusses topics such as boosting and feature selection and examines applications in several areas: Computer Vision, Computer Graphics, Text Classification, and Bioinformatics. The final projects, hands-on applications, and exercises are designed to illustrate the rapidly increasing practical uses of the techniques described throughout the course.','Biology Cognitive Science Computation and Systems Biology Mathematics Neuroscience Probability and Statistics Science','2006','https://ocw.mit.edu/courses/9-520-statistical-learning-theory-and-applications-spring-2006/','https://ocw.mit.edu/courses/9-520-statistical-learning-theory-and-applications-spring-2006/pages/syllabus/','8c19f6ff798d86869e8dc6dfdff3b084f8421b3e5795c792836045af7a579df9','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Tomaso Poggio"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('9.63','9.63','Laboratory in Cognitive Science','Teaches principles of experimental methods in human perception and cognition, including design and statistical analysis. Combines lectures and hands-on experimental exercises; requires an independent experimental project. Some experience in programming desirable. To foster improved writing and presentation skills in conducting and critiquing research in cognitive science, students are required to provide reports and give oral presentations of three team experiments; a fourth individually conducted experiment includes a proposal with revision, and concluding written and oral reports.','Cognitive Science Science','2002','https://ocw.mit.edu/courses/9-63-laboratory-in-cognitive-science-fall-2002/','https://ocw.mit.edu/courses/9-63-laboratory-in-cognitive-science-fall-2002/pages/syllabus/','800687256a1bbe42120b2d0fe66b9528d4b6decb650f4d2157189a262c570924','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Pawan Sinha"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('9.675','9.675','The Development of Object and Face Recognition','This course takes a ‘back to the beginning’ view that aims to better understand the end result. What might be the developmental processes that lead to the organization of ‘booming, buzzing confusions’ into coherent visual objects? This course examines key experimental results and computational proposals pertinent to the discovery of objects in complex visual inputs. The structure of the course is designed to get students to learn and to focus on the genre of study as a whole; to get a feel for how science is done in this field.','Cognitive Science Computational Modeling and Simulation Engineering Science Systems Engineering','2006','https://ocw.mit.edu/courses/9-675-the-development-of-object-and-face-recognition-spring-2006/','https://ocw.mit.edu/courses/9-675-the-development-of-object-and-face-recognition-spring-2006/pages/syllabus/','204fe7a90f30a8f46341fca71445c0edacf6e932e3e02b84f49769bf35af489d','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Pawan Sinha"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('9.85','9.85','Infant and Early Childhood Cognition','This course is an introduction to cognitive development focusing on children’s understanding of objects, agents, and causality. It develops a critical understanding of experimental design. The course discusses how developmental research might address philosophical questions about the origins of knowledge, appearance and reality, and the problem of other minds. It provides instruction and practice in written communication as needed for cognitive science research (including critical reviews of journal papers, a literature review and an original research proposal), as well as instruction and practice in oral communication in the form of a poster presentation of a journal paper.','Cognitive Science Psychology Science Social Science','2012','https://ocw.mit.edu/courses/9-85-infant-and-early-childhood-cognition-fall-2012/','https://ocw.mit.edu/courses/9-85-infant-and-early-childhood-cognition-fall-2012/pages/syllabus/','cdf1fbe03749804faaa6fbf4e7317fa0ea78f1443666c23e98f73fe0c4966653','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Laura Schulz"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('9.916-A','9.916-A','Probability and Causality in Human Cognition','Probability theory captures a number of essential characteristics of human cognition, including aspects of perception, reasoning, belief revision, and learning. Expressions of degree of belief were used in language long before people began codifying the laws of probability theory. This course explores the history and debates over codifying the laws of probability, how probability theory applies to specific cognitive processes, how it relates to the human understanding of causality, and how new computational approaches to causal modeling provide a framework for understanding human probabilistic reasoning. This class is suitable for advanced undergraduates or graduate students specializing in cognitive science, artificial intelligence, and related fields.','Cognitive Science Mathematics Probability and Statistics Science','2003','https://ocw.mit.edu/courses/9-916-a-probability-and-causality-in-human-cognition-spring-2003/','https://ocw.mit.edu/courses/9-916-a-probability-and-causality-in-human-cognition-spring-2003/pages/syllabus/','66e88556c40d8cbd1e8a41780a617b378fd0a84cb1e2d9f40693d758a5dde01b','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Joshua Tenenbaum"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('9.95-A','9.95-A','Research Topics in Neuroscience','This series of research talks by members of the Department of Brain and Cognitive Sciences introduces students to different approaches to the study of the brain and mind. Topics include: From Neurons to Neural Networks Prefrontal Cortex and the Neural Basis of Cognitive Control Hippocampal Memory Formation and the Role of Sleep The Formation of Internal Modes for Learning Motor Skills Look and See: How the Brain Selects Objects and Directs the Eyes How the Brain Wires Itself','Biology Cognitive Science Neuroscience Psychology Science Social Science','2003','https://ocw.mit.edu/courses/9-95-a-research-topics-in-neuroscience-january-iap-2003/','https://ocw.mit.edu/courses/9-95-a-research-topics-in-neuroscience-january-iap-2003/pages/syllabus/','b79e17d02d0970d7960d390b26ef50e0547babc54e623c20966c83efb422c53d','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Peter H. Schiller"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('CC.112','CC.112','Philosophy of Love','This course explores the nature of love through works of philosophy, literature, film, poetry, and individual experience. It investigates the distinction among eros, philia, and agape. Students discuss ideas of love as a feeling, an action, a species of ‘knowing someone,’ or a way to give or take. Authors studied include Plato, Kant, Buber, D. H. Lawrence, Rumi, and Aristotle. This course is part of the Concourse program at MIT.','Classics Ethics Humanities Literature Philosophy Political Philosophy','2013','https://ocw.mit.edu/courses/cc-112-philosophy-of-love-spring-2013/','https://ocw.mit.edu/courses/cc-112-philosophy-of-love-spring-2013/pages/syllabus/','51389055545e368044d8a5dc722d8d9fdf1d91616e42e8777ff48edfc2c1b956','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Lee Perlman"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('CMS.360','CMS.360','Introduction to Civic Media','This course examines civic media in comparative, transnational and historical perspectives through the use of various theoretical tools, research approaches, and project design methods.','Communication Fine Arts Media Studies Social Science','2012','https://ocw.mit.edu/courses/cms-360-introduction-to-civic-media-fall-2012/','https://ocw.mit.edu/courses/cms-360-introduction-to-civic-media-fall-2012/pages/syllabus/','1cd11373daaabd68df802833f8028453e8e938d237c290edeae00cbaec96d9ad','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Sasha Costanza-Chock","Rebecca Hurwitz"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('CMS.594','CMS.594','Education Technology Studio','Students use media and technology to develop new forms of learning experiences in schools, workplaces, and informal settings. Students participate in a range of new and ongoing projects that hone understanding and skills in learning science, instructional design, development and evaluation.','Educational Technology Teaching and Education','2019','https://ocw.mit.edu/courses/cms-594-education-technology-studio-spring-2019/','https://ocw.mit.edu/courses/cms-594-education-technology-studio-spring-2019/pages/syllabus/','7aadc534170816f7aee323c7d174d2ad5816b02596e6a145b7edf21f25051aec','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Rachel Slama","Garron Hillaire","Dr. Joshua Littenberg-Tobias","Dr. Jose Ruiperez-Valiente"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('CMS.615','CMS.615','Games for Social Change','Run as a workshop, students collaborate in teams to design and prototype games for social change and civic engagement. Through readings, discussion, and presentations, we explore principles of game design and the social history of games. Guest speakers from academia, industry, the non-profit sector, and the gaming community contribute unique and diverse perspectives. Course culminates in an end of semester open house to showcase our games.','Digital Media Fine Arts Game Design Media Studies','2013','https://ocw.mit.edu/courses/cms-615-games-for-social-change-fall-2013/','https://ocw.mit.edu/courses/cms-615-games-for-social-change-fall-2013/pages/syllabus/','bf908cfc28b05675da4aeb982ad60e96a4edc6527b27e96bddb3c9bb67255512','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Scot Osterweil"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('CMS.801','CMS.801','Media in Transition','This course centers on historical eras in which the form and function of media technologies were radically transformed. It includes consideration of the “Gutenberg Revolution,” the rise of modern mass media, and the “digital revolution,” among other case studies of media transformation and cultural change. Readings are in cultural and social history and historiographic method.','Fine Arts History Humanities Media Studies','2012','https://ocw.mit.edu/courses/cms-801-media-in-transition-fall-2012/','https://ocw.mit.edu/courses/cms-801-media-in-transition-fall-2012/pages/syllabus/','fe3ba4767d6099f4be517c8daf4b3ff1d52562f74d29d9ab20402ad7f9e04d04','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Jeffrey S. Ravel"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('EC.050','EC.050','Recreate Experiments from History: Inform the Future from the Past: Galileo','2010 marks the 400th anniversary of Galileo’s astonishing sightings of features on the moon, stars, and moons around Jupiter that no one had seen before. Recreate these new ways of seeing and exploring from the materials and techniques Galileo had on hand, while you reflect on the times and works of Galileo. What was it like to improvise new ways of seeing and exploring from the materials and techniques on hand? What do we notice? What surprises us? How can we relate to past experience and ideas? What are we curious to research? How does our experimenting grow into our learning? Let your own curiosity drive your explorations.','History Humanities Intellectual History','2010','https://ocw.mit.edu/courses/ec-050-recreate-experiments-from-history-inform-the-future-from-the-past-galileo-january-iap-2010/','https://ocw.mit.edu/courses/ec-050-recreate-experiments-from-history-inform-the-future-from-the-past-galileo-january-iap-2010/pages/syllabus/','a978baa782d7e745f777d4ba51c74645778295ec6cb285a243f2798d066cb5b6','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Elizabeth Cavicchi"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('EC.715','EC.715','D-Lab: Water, Sanitation, and Hygiene','This course focuses on disseminating Water, Sanitation and Hygiene (WASH) or water/environment innovations in developing countries and underserved communities worldwide. It emphasizes core WASH and water/environment principles, culture-specific solutions, tools for start-ups, appropriate and sustainable technologies, behavior change, social marketing, building partnerships, and the theory and practice of innovation diffusion.','Aquatic Sciences and Water Quality Control Earth Science Engineering Environmental Engineering Health and Medicine Public Health Science Society Sustainability The Developing World','2019','https://ocw.mit.edu/courses/ec-715-d-lab-water-sanitation-and-hygiene-fall-2019/','https://ocw.mit.edu/courses/ec-715-d-lab-water-sanitation-and-hygiene-fall-2019/pages/syllabus/','9e50a3bbc377470f260ad0f310ab04df6e0a3626af6a6cb80ec6105b8febc748','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Libby Hsu","Susan Murcott"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('EC.S01','EC.S01','Internet Technology in Local and Global Communities','This course is based on the work of the MIT-African Internet Technology Initiative (MIT-AITI). MIT-AITI is an innovative approach by MIT students to integrate computers and internet technology into the education of students in African schools. The program focuses upon programming principles, cutting-edge internet technology, free open-source systems, and even an entrepreneurship seminar to introduce students in Africa to the power of information technology in today’s world. MIT-AITI achieves this goal by sending MIT students to three African nations in order to teach both students and teachers through intensive classroom and lab sessions for six weeks. The AITI program is implemented with emphasis on classroom teaching, community-oriented projects, and independent learning. This course has two major components: Content from a spring 2005 preparatory seminar offered by the MIT-AITI leadership. The goal of this seminar is to adequately prepare the AITI student teachers for their upcoming summer experiences in Africa. A snapshot of the summer 2005 MIT-AITI program. This includes the Java®-based curriculum that MIT-AITI ambassadors teach in Africa each year, as well as content from an entrepreneurship seminar offered concurrently with the IT class.','Business Digital Media Educational Technology Electrical Engineering Engineering Entrepreneurship Fine Arts Media Studies Teaching and Education Telecommunications','2005','https://ocw.mit.edu/courses/ec-s01-internet-technology-in-local-and-global-communities-spring-2005-summer-2005/','https://ocw.mit.edu/courses/ec-s01-internet-technology-in-local-and-global-communities-spring-2005-summer-2005/pages/syllabus/','90c405710c71a32fb92df9765bd91c6c22a3dcb10c01b5ce74dab5076caa2cf5','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Mr. Manish Gaudi","Prof. Paul Gray"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('EC.S11','EC.S11','Engineering Capacity in Community-Based Healthcare','This multidisciplinary seminar addresses fundamental issues in global health faced by community-based healthcare programs in developing countries. Students will broadly explore topics with expert lecturers and guided readings. Topics will be further illuminated with case studies from healthcare programs in urban centers of Zambia. Multidisciplinary teams will be formed to develop feasible solutions to specific health challenges posed in the case studies and encouraged to pursue their ideas beyond the seminar. Possible global health topics include community-based AIDS/HIV management, maternity care, health diagnostics, and information technology in patient management and tracking. Students from Medicine, Public Health, Engineering, Management, and Social Sciences are encouraged to enroll. No specific background experience is expected, but students should have some relevant skills or experiences.','Biomedical Enterprise Business Health Care Management Health and Medicine Public Health Society The Developing World','2005','https://ocw.mit.edu/courses/ec-s11-engineering-capacity-in-community-based-healthcare-fall-2005/','https://ocw.mit.edu/courses/ec-s11-engineering-capacity-in-community-based-healthcare-fall-2005/pages/syllabus/','f410dbc611a7bcdd32e75cea275bccd199858b8f738df53ead651719d0360a92','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Ms. Christina DeFilippo","Mr. Eric Soller","Ms. Kathie Dionisio","Ms. MaryAnn Dakkak","Mr. Peter J. Mack","Mr. Sankey Chibale","Mr. Will DelHagen"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('ES.242','ES.242','Gender Issues in Academics and Academia','Does it matter in education whether or not you’ve got a Y chromosome? You bet it does. In this discussion-based seminar, we will explore why males vastly outrank females in math and science and career advancements (particularly in academia), and why girls get better grades and go to college more often than boys. Do the sexes have different learning styles? Are women denied advanced opportunities in academia and the workforce? How do family life and family decisions affect careers for both men and women?','Gender Studies Society Women''s Studies','2004','https://ocw.mit.edu/courses/es-242-gender-issues-in-academics-and-academia-spring-2004/','https://ocw.mit.edu/courses/es-242-gender-issues-in-academics-and-academia-spring-2004/pages/syllabus/','2a7676fc3113c85d0d39c159e4d76d059069cbc5d5a9f6091ce7d10168e6ab25','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Holly Sweet","Kayla Jacobs","Laurel Ruhlen"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('ES.259','ES.259','Information and Communication Technology in Africa','This is a discussion-based, interactive seminar on the development of information and communication technology in Sub-Saharan Africa. The students will seek to understand the issues surrounding designing and instituting policy, and explore the possible ways in which they can make an impact on information and communication technology in Africa.','Business Electrical Engineering Engineering Information Technology Society Telecommunications The Developing World','2006','https://ocw.mit.edu/courses/es-259-information-and-communication-technology-in-africa-spring-2006/','https://ocw.mit.edu/courses/es-259-information-and-communication-technology-in-africa-spring-2006/pages/syllabus/','ba8057d45657e34e26727f51af818d90a9f977ff1b092ddbacc138ad2f5b5b09','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Raja Bobbili","Prof. Shigeru Miyagawa"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('ES.291','ES.291','Learning Seminar: Experiments in Education','This seminar explores experiments in education and discusses how education and learning might be done, through reading and discussion. This seminar is not a survey of experiments in education, but rather, its goal is to determine how learning should happen and what kinds of contexts allow it to happen.','Teaching and Education','2003','https://ocw.mit.edu/courses/es-291-learning-seminar-experiments-in-education-spring-2003/','https://ocw.mit.edu/courses/es-291-learning-seminar-experiments-in-education-spring-2003/pages/syllabus/','c6e10e539a8cf09093c78c0639e6eaa1e58503ec6ead183e55effd7a3e44d1c0','https://creativecommons.org/licenses/by-nc-sa/4.0/','["James Rising"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('ES.S41','ES.S41','Speak Italian With Your Mouth Full','The participants in this seminar will dive into learning basic conversational Italian, Italian culture, and the Mediterranean diet. Each class is based on the preparation of a delicious dish and on the bite-sized acquisition of parts of the Italian language and culture. A good diet is not based on recipes only, it is also rooted in healthy habits and in culture. At the end of the seminar the participants will be able to cook some healthy and tasty recipes and to understand and speak basic Italian.','European and Russian Studies Humanities Italian Language Society','2012','https://ocw.mit.edu/courses/es-s41-speak-italian-with-your-mouth-full-spring-2012/','https://ocw.mit.edu/courses/es-s41-speak-italian-with-your-mouth-full-spring-2012/pages/syllabus/','0c495e23138b851de8b3ca429273724b807c8983d666a27e9d016a38960748aa','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Paola Rebusco","Graham Gordon Ramsay"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('ESD.10','ESD.10','Introduction to Technology and Policy','This course explores perspectives in the policy process - agenda setting, problem definition, framing the terms of debate, formulation and analysis of options, implementation and evaluation of policy outcomes using frameworks including economics and markets, law, and business and management. Methods include cost/benefit analysis, probabilistic risk assessment, and system dynamics. Exercises include developing skills to work on the interface between technology and societal issues; simulation exercises; case studies; and group projects that illustrate issues involving multiple stakeholders with different value structures, high levels of uncertainty, multiple levels of complexity; and value trade-offs that are characteristic of engineering systems. Emphasis on negotiation, team building and group dynamics, and management of multiple actors and leadership.','Business Information Technology Leadership Operations Management Public Administration Science and Technology Policy Social Science','2006','https://ocw.mit.edu/courses/esd-10-introduction-to-technology-and-policy-fall-2006/','https://ocw.mit.edu/courses/esd-10-introduction-to-technology-and-policy-fall-2006/pages/syllabus/','3c82b15353704158b2410d8ae85abc21c99c2a3af2561ba078f78611ac26d92f','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Dan Ross","Prof. Annalisa Weigel"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('ESD.290','ESD.290','Special Topics in Supply Chain Management','This subject presents a range of advanced topics in integrated logistics and supply chain management. The course was conducted in a lecture-discussion format, with participation of corporate executives as guest lecturers. Students prepare industry assessment analyses and make formal classroom presentations. Specific topics alternate from year to year, but basic content includes procurement strategies and strategic sourcing, dynamic pricing and revenue management tactics, mitigation of supply chain risk through supply contracts, strategic outsourcing of supply chain functions and operations, management and operation of third party logistics providers, and management of supply chain security.','Business Engineering Operations Management Supply Chain Management Systems Engineering','2005','https://ocw.mit.edu/courses/esd-290-special-topics-in-supply-chain-management-spring-2005/','https://ocw.mit.edu/courses/esd-290-special-topics-in-supply-chain-management-spring-2005/pages/syllabus/','ee1a5967d058097d436d015b6dd6805d5815bbf563bd5608df77c0e5c75614e6','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Brian Subirana","Prof. John Williams","Prof. Sanjay Sarma"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('ESD.36','ESD.36','System Project Management','Subject focuses on management principles, methods, and tools to effectively plan and implement successful system and product development projects. Material is divided into four major sections: project preparation, planning, monitoring, and adaptation. Brief review of classical techniques such as CPM and PERT. Emphasis on new methodologies and tools such as Design Structure Matrix (DSM), probabilistic project simulation, as well as project system dynamics (SD). Topics are covered from strategic, tactical, and operational perspectives. Industrial case studies expose factors that are typical drivers of success and failure in complex projects with both hardware and software content. Term projects analyze and evaluate past and ongoing projects in student’s area of interest. Projects used to apply concepts discussed in class.','Business Management Project Management','2012','https://ocw.mit.edu/courses/esd-36-system-project-management-fall-2012/','https://ocw.mit.edu/courses/esd-36-system-project-management-fall-2012/pages/syllabus/','2b52c1787f2cf9cf00ee4d1d723add58021694da829c4fd50d5db7f427f96299','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Olivier de Weck","Dr. James Lyneis","Prof. Dan Braha"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('ESD.71','ESD.71','Engineering Systems Analysis for Design','Engineering systems design must have the flexibility to take advantage of new opportunities while avoiding disasters. This subject develops “real options” analysis to create design flexibility and measure its value so that it can be incorporated into system optimization. It builds on essential concepts of system models, decision analysis, and financial concepts. Emphasis is placed on calculating value of real options with special attention given to efficient analysis and practical applications. The material is organized and presented to deal with the contextual reality of technological systems, that substantially distinguishes the analysis of real options in engineering systems from that of financial options. Note This MIT OpenCourseWare site is based on the materials from Professor de Neufville’s ESD.71 Web site . Additional materials, updated as needed by Professor de Neufville, can be found there.','Engineering Systems Design Systems Engineering Systems Optimization','2008','https://ocw.mit.edu/courses/esd-71-engineering-systems-analysis-for-design-fall-2008/','https://ocw.mit.edu/courses/esd-71-engineering-systems-analysis-for-design-fall-2008/pages/syllabus/','193686547d6eb4bf6d84f1b411421f5203371c5fa83d88d4062bbf054c9ee872','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Richard de Neufville"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('ESD.S51','ESD.S51','Systems Leadership and Management Praxis','SLaM (Systems Leadership and Management) Praxis is a course is designed to introduce students to the dynamics of strategic decision making in corporate boardrooms through team exercises, simulations, and role playing. The case studies and team exercises will introduce students to strategy choices in the high tech sector, but these learnings are just as valid in other industries. We will also have invited guest speakers from the industry who have lived through difficult corporate situations and can provide insights into the cases discussed in class.','Business Innovation Leadership Management','2014','https://ocw.mit.edu/courses/esd-s51-systems-leadership-and-management-praxis-summer-2014/','https://ocw.mit.edu/courses/esd-s51-systems-leadership-and-management-praxis-summer-2014/pages/syllabus/','61f12ef265ec2e84390f28c244a8279d5eefa73598265634a2331260e55e08af','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Michael A. M. Davies"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('HST.151','HST.151','Principles of Pharmacology','The object of the course is to teach students an approach to the study of pharmacologic agents. It is not intended to be a review of the pharmacopoeia. The focus is on the basic principles of biophysics, biochemistry and physiology, as related to the mechanisms of drug action, biodistribution and metabolism. The course consists of lectures and student-led case discussions. Topics covered include: mechanisms of drug action, dose-response relations, pharmacokinetics, drug delivery systems, drug metabolism, toxicity of pharmacological agents, drug interaction and substance abuse. Selected agents and classes of agents are examined in detail.','Health and Medicine Pharmacology and Toxicology','2005','https://ocw.mit.edu/courses/hst-151-principles-of-pharmacology-spring-2005/','https://ocw.mit.edu/courses/hst-151-principles-of-pharmacology-spring-2005/pages/syllabus/','6bbdfd82522ddde515d715a18f1e48f4f75ae7a78b790a5be85f54ac2042353c','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Carl Rosow","Dr. David Standaert","Prof. Gary Strichartz"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('HST.508','HST.508','Quantitative Genomics','This course provides a foundation in the following four areas: evolutionary and population genetics; comparative genomics; structural genomics and proteomics; and functional genomics and regulation.','Biology Functional Genomics Genetics Health and Medicine Proteomics Science','2005','https://ocw.mit.edu/courses/hst-508-quantitative-genomics-fall-2005/','https://ocw.mit.edu/courses/hst-508-quantitative-genomics-fall-2005/pages/syllabus/','4439916816033737497cef8c75785625e2083e17a9ab935d74ed47743fcbcf23','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Isaac Kohane","Prof. Leonid Mirny","Prof. Robert Berwick","Dr. Alvin Kho"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('HST.582J','HST.582J','Biomedical Signal and Image Processing','This course presents the fundamentals of digital signal processing with particular emphasis on problems in biomedical research and clinical medicine. It covers principles and algorithms for processing both deterministic and random signals. Topics include data acquisition, imaging, filtering, coding, feature extraction, and modeling. The focus of the course is a series of labs that provide practical experience in processing physiological data, with examples from cardiology, speech processing, and medical imaging. The labs are done in MATLAB® during weekly lab sessions that take place in an electronic classroom. Lectures cover signal processing topics relevant to the lab exercises, as well as background on the biological signals processed in the labs.','Biomedical Instrumentation Biomedical Signal and Image Processing Biomedicine Electrical Engineering Engineering Health and Medicine Medical Imaging Signal Processing','2007','https://ocw.mit.edu/courses/hst-582j-biomedical-signal-and-image-processing-spring-2007/','https://ocw.mit.edu/courses/hst-582j-biomedical-signal-and-image-processing-spring-2007/pages/syllabus/','7b543f9416a19d5d77e5d2da731fda3c22859f12d6bec0d608a0ab136510c609','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Gari Clifford","Dr. John Fisher","Dr. Julie Greenberg","Dr. William Wells"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('HST.721','HST.721','The Peripheral Auditory System','In this course, experimental approaches to the study of hearing and deafness are presented through lectures, laboratory exercises and discussions of the primary literature on the auditory periphery. Topics include inner-ear development, functional anatomy of the inner ear, cochlear mechanics and micromechanics, mechano-electric transduction by hair cells, outer hair cells’ electromotility and the cochlear amplifier, otoacoustic emissions, synaptic transmission, stimulus coding in auditory nerve responses, efferent control of cochlear function, damage and repair of hair-cell organs, and sensorineural hearing loss.','Anatomy and Physiology Biology Biophysics Health and Medicine Neuroscience Science Sensory-Neural Systems','2005','https://ocw.mit.edu/courses/hst-721-the-peripheral-auditory-system-fall-2005/','https://ocw.mit.edu/courses/hst-721-the-peripheral-auditory-system-fall-2005/pages/syllabus/','98dbd1587e4bf7771e630eb1ca85a20795fb0fc4d69bc964781e73aa75dc07a2','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Charlie Liberman","Prof. Joe C. Adams"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('HST.921','HST.921','Information Technology in the Health Care System of the Future','This innovative, trans-faculty subject teaches how information technologies (IT) are reshaping and redefining the health care marketplace through improved economies of scale, greater technical efficiencies in the delivery of care to patients, advanced tools for patient education and self-care, network integrated decision support tools for clinicians, and the emergence of e-commerce in health care. Student tutorials provide an opportunity for interactive discussion. Interdisciplinary project teams comprised of Harvard and MIT graduate students in medicine, business, law, education, engineering, computer science, public health, and government collaborate to design innovative IT applications. Projects are presented during the final class. Starting in Spring 2010, this course will be titled Enabling Technology Innovation in Healthcare and the Life Sciences .','Biomedical Enterprise Business Health Care Management Health and Medicine Information Technology','2009','https://ocw.mit.edu/courses/hst-921-information-technology-in-the-health-care-system-of-the-future-spring-2009/','https://ocw.mit.edu/courses/hst-921-information-technology-in-the-health-care-system-of-the-future-spring-2009/pages/syllabus/','88f764c917a5bcd739708dca0dd336f50c2e1ba1a5f8b00c02076a7f348b70d8','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Bryan Bergeron","Dr. Daniel Sands","Prof. Steven Locke","Mirena Bagur"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('HST.950J','HST.950J','Biomedical Computing','Analyzes computational needs of clinical medicine reviews systems and approaches that have been used to support those needs, and the relationship between clinical data and gene and protein measurements. Topics: the nature of clinical data; architecture and design of healthcare information systems; privacy and security issues; medical expertsystems; introduction to bioinformatics. Case studies and guest lectures describe contemporary systems and research projects. Term project using large clinical and genomic data sets integrates classroom topics.','Biological Engineering Biomedical Instrumentation Biomedicine Business Computational Biology Engineering Health and Medicine Information Technology','2010','https://ocw.mit.edu/courses/hst-950j-biomedical-computing-fall-2010/','https://ocw.mit.edu/courses/hst-950j-biomedical-computing-fall-2010/pages/syllabus/','a30a303747a32b35b32652de9d2242b29518c14660d61e8af73eb30b497b3b5a','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Peter Szolovits","Prof. Gil Alterovitz"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('HST.953','HST.953','Collaborative Data Science for Healthcare','This course provides an introductory survey of data science tools in healthcare. It was created by members of MIT Critical Data , a global consortium consisting of healthcare practitioners, computer scientists, and engineers from academia, industry, and government, that seeks to place data and research at the front and center of healthcare operations. The most daunting global health issues right now are the result of interconnected crises. In this course, we highlight the importance of a multidisciplinary approach to health data science. It is intended for front-line clinicians and public health practitioners, as well as computer scientists, engineers, and social scientists, whose goal is to understand health and disease better using digital data captured in the process of care. What you’ll learn: Principles of data science as applied to health Analysis of electronic health records Artificial intelligence and machine learning in healthcare This course is part of the Open Learning Library , which is free to use. You have the option to sign up and enroll in the course if you want to track your progress, or you can view and use all the materials without enrolling.','Artificial Intelligence Business Computer Science Data Mining Engineering Health Care Management Health and Medicine Public Health','2020','https://ocw.mit.edu/courses/hst-953-collaborative-data-science-for-healthcare-fall-2020/','https://ocw.mit.edu/courses/hst-953-collaborative-data-science-for-healthcare-fall-2020/pages/syllabus/','0042f5d2d246cee04173bc7a20c771f0627c96acfef8c1e7ffd94dc07b81dd02','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Leo A. Celi","Dr. Louis  Agha-Mir-Salim","Marie-Laure  Charpignon"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('IDS.720J','IDS.720J','Tools for Analysis: Design for Real Estate and Infrastructure Development','This course is an introduction to the analytical tools that support design and decision-making in real estate and infrastructure development. There is a particular focus on identifying and valuing sources of flexibility using “real options”, Monte-Carlo simulation, and other techniques from the field of engineering systems. This course integrates economic and engineering perspectives, and is suitable for students with various backgrounds. It serves to provide useful preparation for thesis work in the area. The course applies the approach to the design and phasing of a mega infrastructure real estate project. Note This MIT OpenCourseWare site is based, in part, on materials on Design for Real Estate and Infrastructure Development from Professor de Neufville’s and Professor Geltner’s Web site .','Business Computational Modeling and Simulation Engineering Real Estate Social Science Systems Design Systems Engineering Urban Planning Urban Studies','2010','https://ocw.mit.edu/courses/ids-720j-tools-for-analysis-design-for-real-estate-and-infrastructure-development-spring-2010/','https://ocw.mit.edu/courses/ids-720j-tools-for-analysis-design-for-real-estate-and-infrastructure-development-spring-2010/pages/syllabus/','1d8837f6ca021bdb6f8126cbec90521989d2f77a18b16dd035e6e8ea7f8bbde8','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Richard de Neufville","Prof. David Geltner"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('MAS.110','MAS.110','Fundamentals of Computational Media Design','This class covers the history of 20th century art and design from the perspective of the technologist. Methods for visual analysis, oral critique, and digital expression are introduced. Class projects this term use the OLPC XO (One Laptop Per Child) laptop, Csound and Python software.','Art History Digital Media Fine Arts Graphic Design Media Studies Visual Arts','2008','https://ocw.mit.edu/courses/mas-110-fundamentals-of-computational-media-design-fall-2008/','https://ocw.mit.edu/courses/mas-110-fundamentals-of-computational-media-design-fall-2008/pages/syllabus/','743817fb91b4cbf6a1024f17d0d02a63229d4d1d687754ec5f6ef90da300d39f','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Barry Vercoe","Prof. David Small","Dr. Henry Holtzman","Dr. V. Michael Bove"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('MAS.630','MAS.630','Affective Computing','This course instructs students on how to develop technologies that help people measure and communicate emotion, that respectfully read and that intelligently respond to emotion, and have internal mechanisms inspired by the useful roles emotions play.','Artificial Intelligence Cognitive Science Computer Science Engineering Psychology Science Social Science','2015','https://ocw.mit.edu/courses/mas-630-affective-computing-fall-2015/','https://ocw.mit.edu/courses/mas-630-affective-computing-fall-2015/pages/syllabus/','a19653a51239d08f0864306f170ea47b6f82fe1e4a34cb2efda9bc84eccbf88e','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Rosalind W. Picard"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('MAS.771','MAS.771','Autism Theory and Technology','This course illuminates current theories about autism together with challenges faced by people on the autism spectrum. Theories in communicating, interacting socially, managing cognitive and affective overload, and achieving independent lifestyles are covered. In parallel, the course presents state-of-the-art technologies being developed for helping improve both theoretical understanding and practical outcomes. Participants are expected to meet and interact with people on the autism spectrum. Weekly reading, discussion, and a term project are required.','Computer Science Educational Technology Engineering Health and Medicine Human-Computer Interfaces Mental Health Psychology Social Science Teaching and Education','2011','https://ocw.mit.edu/courses/mas-771-autism-theory-and-technology-spring-2011/','https://ocw.mit.edu/courses/mas-771-autism-theory-and-technology-spring-2011/pages/syllabus/','e199d043b3b6b52e489ebb147675d4168453db984c268837c696ceec9bb86a53','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Rosalind W. Picard","Dr. Matthew Goodwin"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('MAS.961','MAS.961','Networks, Complexity and Its Applications','Networks are a ubiquitous way to represent complex systems, including those in the social and economic sciences. The goal of the course is to equip students with conceptual tools that can help them understand complex systems that emerge in both nature and social systems. This is a course intended for a general audience and will discuss applications of networks and complexity to diverse systems, including epidemic spreading, social networks and the evolution of economic development.','Business Digital Media Engineering Fine Arts Mathematics Media Studies Organizational Behavior Probability and Statistics Systems Engineering','2011','https://ocw.mit.edu/courses/mas-961-networks-complexity-and-its-applications-spring-2011/','https://ocw.mit.edu/courses/mas-961-networks-complexity-and-its-applications-spring-2011/pages/syllabus/','5e337c15e4a7245cbb88cec5001a87052b33f22551076d44cf754e6f673eeecc','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Cesar Hidalgo"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('MAS.962','MAS.962','Special Topics in Media Technology: Computational Semantics','How do words get their meanings? How can word meanings be represented and used by machines? We will explore three families of approaches to these questions from a computational perspective. Relational / structural methods such as semantic networks represent the meaning of words in terms of their relations to other words. Knowledge of the world through perception and action leads to the notion of external grounding, a process by which word meanings are ‘attached’ to the world. How an agent theorizes about, and conceptualizes its world provides yet another foundation for word meanings. We will examine each of these perspectives, and consider ways to integrate them.','Computation Fine Arts Humanities Linguistics Mathematics Media Studies Semantics','2002','https://ocw.mit.edu/courses/mas-962-special-topics-in-media-technology-computational-semantics-fall-2002/','https://ocw.mit.edu/courses/mas-962-special-topics-in-media-technology-computational-semantics-fall-2002/pages/syllabus/','965e7bdfc83d914495a84c6a042a0bd08e0c0b3de51f9647113cabdf78e4b302','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Deb Roy"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('MAS.964','MAS.964','Common Sense Reasoning for Interactive Applications','This course will explore the state of the art in common sense knowledge, and class projects will design and build interfaces that can exploit this knowledge to make more usable and helpful interfaces. Course requirements will consist of critiques of class readings (about 2 papers/week), and a final project (paper or computer implementation project). Grades will be based primarily on the projects, as well as a small component for class and online participation','Artificial Intelligence Computer Science Engineering Human-Computer Interfaces Software Design and Engineering','2002','https://ocw.mit.edu/courses/mas-964-common-sense-reasoning-for-interactive-applications-fall-2002/','https://ocw.mit.edu/courses/mas-964-common-sense-reasoning-for-interactive-applications-fall-2002/pages/syllabus/','c3370602702ac750368389700bf60b10c8908741e375c462239350471b25ee6d','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Henry Lieberman"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('MAS.S60','MAS.S60','How to AI (Almost) Anything','Artificial Intelligence (AI) holds great promise as a technology to enhance digital productivity, physical interactions, overall well-being, and the human experience. To enable the true impact of AI, these systems will need to be grounded in real-world data modalities, from language-only systems to vision, audio, sensors, medical data, music, art, smell, and taste. This course will introduce the basic principles of AI (focusing on modern deep learning and foundation models) and how we can apply AI to novel real-world data modalities. In addition, we will introduce the principles of multimodal AI that can process many modalities at once, such as connecting language and multimedia, music and art, sensing and actuation, and more. Through lectures, readings, discussions, and a significant research component, this course will develop critical thinking skills and intuitions when applying AI to new data modalities, knowledge of recent technical achievements in AI, and a deeper understanding of the AI research process.','Artificial Intelligence Computer Science Engineering','2025','https://ocw.mit.edu/courses/mas-s60-how-to-ai-almost-anything-spring-2025/','https://ocw.mit.edu/courses/mas-s60-how-to-ai-almost-anything-spring-2025/pages/syllabus/','981039c69d69f28d40f65eaaeb544133982b3c3054a57ecd91d0ff86f2e7fdd6','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Paul Liang"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('PE.550','PE.550','Designing Your Life','This course provides an exciting, eye-opening, and thoroughly useful inquiry into what it takes to live an extraordinary life, on your own terms. The instructors address what it takes to succeed, to be proud of your life, and to be happy in it. Participants tackle career satisfaction, money, body, vices, and relationship to themselves. They learn how to confront issues in their lives, how to live life, and how to learn from it. A short version of this course meets during the Independent Activities Period (IAP), which is a special 4-week term at MIT that runs from the first week of January until the end of the month. Then this semester-long extension of the IAP course is taught to interested members of the MIT community. This not-for-credit course is sponsored by the Department of Science, Technology, and Society. A similar, semester-long version of this course is taught in the Sloan Fellows Program. Acknowledgment The instructors would like to thank Prof. David Mindell for his sponsorship of this course, his hopes for its continued expansion, and his commitment to the well-being of MIT students.','Health and Medicine Mental Health','2009','https://ocw.mit.edu/courses/pe-550-designing-your-life-spring-2009/','https://ocw.mit.edu/courses/pe-550-designing-your-life-spring-2009/pages/syllabus/','2f0b1abfe8f073f1c083b7bb72d8c0cb298967c7c50364d52fe9a72c7fc5d612','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Gabriella Jordan","Lauren Zander"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('PE.910','PE.910','Physical Intelligence','For all of the bodies attached to the many great minds that walk the Institute’s halls, in the work that goes on at MIT the body is present as an object of study, but is all but unrecognized as an important dimension of our intelligence and experience. Yet the body is the basis of our experience in the world; it is the very foundation on which cognitive intelligence is built. Using the MIT gymnastics gym as our laboratory, the Physical Intelligence activity will take an innovative, hands-on approach to explore the kinesthetic intelligence of the body as applicable to a wide range of disciplines. Via exercises, activities, readings and discussions designed to excavate our physical experience, we will not only develop balance, agility, flexibility and strength, but a deep appreciation for the inherent unity of mind and body that suggests physical intelligence as a powerful complement to cognitive intelligence.','Cognitive Science Health and Medicine Physical Education and Recreation Science','2002','https://ocw.mit.edu/courses/pe-910-physical-intelligence-january-iap-2002/','https://ocw.mit.edu/courses/pe-910-physical-intelligence-january-iap-2002/pages/syllabus/','1f993fd848d4eb2a88c13644ac82711cad92c671df8cb4018acdf1bd460ccc28','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Noah Riskin"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('RES.11-002','RES.11-002','Intentional Public Disruptions: Art, Responsibility, and Pedagogy','During the fall of 2017, art educator B. Stephen Carpenter II began a residency at the MIT Center for Art, Science & Technology (CAST). He provided new perspectives on issues of access, privilege, and the global water crisis through a series of seminars, performances, and workshops. Carpenter’s seminars illustrated ways of disrupting systems of oppression and ways to increase access to potable water in politically marginalized communites in the United States and abroad.','Curriculum and Teaching Fine Arts Global Poverty Latin and Caribbean Studies Public Administration Social Science Social Welfare Society Teaching and Education Urban Studies Visual Arts','2017','https://ocw.mit.edu/courses/res-11-002-intentional-public-disruptions-art-responsibility-and-pedagogy-fall-2017/','https://ocw.mit.edu/courses/res-11-002-intentional-public-disruptions-art-responsibility-and-pedagogy-fall-2017/pages/syllabus/','51b08d4cd7313f1579d5fc3f6ab0b21dd1cd4a0143f1cbaf3cd1bc2a0ae9207e','https://creativecommons.org/licenses/by-nc-sa/4.0/','["B. Stephen Carpenter II","Prof. Lawrence Susskind"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('RES.12-001','RES.12-001','Topics in Fluid Dynamics','This resource presents a collection of essays developed from the author’s experience teaching the course 12.800 Fluid Dynamics of the Atmosphere and Ocean , offered to graduate students entering the MIT/WHOI Joint Program in Oceanography . The collection includes the following three essays: Essay 1: Lagrangian and Eulerian Representations of Fluid Flow Part 1: Kinematics and the Equations of Motion Part 2: Advection of Parcels and Fields Essay 2: Dimensional Analysis of Models and Data Sets: Similarity Solutions and Scaling Analysis Essay 3: A Coriolis Tutorial Part 1: The Coriolis Force, Inertial and Geostrophic Motion Part 2: A Rotating Shallow Water Model and Geostrophic Adjustment Part 3: Beta Effects and Western Propagation Part 4: Wind-Driven Ocean Circulation and the Sverdrup Relation Part 5: On the Seasonally-Varying Circulation of the Arabian Sea The goal of this resource is to help each student master the concepts and mathematical tools that make up the foundation of classical and geophysical fluid dynamics. These essays treat these topics in considerably greater depth than a comprehensive fluids textbook can afford, and they are accompanied by data files (MATLAB® and Fortran) to allow some application and experimentation. They should be suitable for self-study.','Classical Mechanics Earth Science Engineering Fluid Mechanics Geophysics Hydrodynamics Mechanical Engineering Ocean Engineering Oceanography Physics Science','2024','https://ocw.mit.edu/courses/res-12-001-topics-in-fluid-dynamics-fall-2024/','https://ocw.mit.edu/courses/res-12-001-topics-in-fluid-dynamics-fall-2024/pages/syllabus/','7d2ec06d9934511981ada2c42281305e05c18adbbfca9f6b10e9ee649cda220b','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. James F. Price"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('RES.15-001','RES.15-001','MIT Sloan Teaching Resources Library','Sloan’s Teaching Resources Library provides open access to case studies and management simulations for management educators and students worldwide. This collection of teaching materials and games focuses on areas in which Sloan’s innovative research and teaching are on the cutting edge, including action learning, entrepreneurship, leadership and ethics, operations management, strategy, sustainability, and system dynamics. Formerly known as LearningEdge , and MIT Sloan Teaching Innovation Resources (MSTIR) . Online Publication','Accounting Business Entrepreneurship Finance Leadership Management Operations Management Organizational Behavior','2008','https://ocw.mit.edu/courses/res-15-001-mit-sloan-learningedge-fall-2008/','https://ocw.mit.edu/courses/res-15-001-mit-sloan-learningedge-fall-2008/pages/syllabus/','cf0ecab6dcdd1006221f83ac2dfc1af8929f77f5043f0ddd5b0437b3681decab','https://creativecommons.org/licenses/by-nc-sa/4.0/','["MIT Sloan Faculty"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('RES.16-001','RES.16-001','Lean Enterprise en Español','Este curso contiene un subconjunto de material en español del curso 16.660J (en Inglés). Para la versión en Inglés, por favor vea 16.660J Introduction to Lean Six Sigma Methods January IAP 2012 . El programa presenta los fundamentos del pensamiento Lean a través de conceptos y herramientas prácticas y aplicables. Este curso cubre los principios fundamentales, prácticas y herramientas de una empresa Lean, incluyendo Lean Six Sigma y otros métodos de enfoques modernos para la productividad organizacional. El curso incluye ejemplos y ejercicios aplicados en la industria aeroespacial, automotriz, servicios de salud y otros sectores. La metodología es altamente interactiva con simulaciones y ejercicios orientados hacia el aprendizaje de conceptos aplicados en experiencias grupales, incluyendo una simulación Lego®, tour virtual a fábricas, charlas de expertos entre otros. Este curso fue ofrecido en la Pontificia Universidad Católica de Chile a través del Centro de Excelencia en Gestión de Producción (GEPUC) de 17 a 19 abril, 2013. MIT Professional Education Conecta A Los Profesionales Con Conocimiento Y Expertise Avanzado A Traves De Entrenamiento Y Capacitacion Los cursos y programas ofrecidos por MIT Professional Education son diseñados por expertos de MIT para conectar a profesionales de la industria con los últimos avances tecnológicos y de conocimiento. La inmersión en un intenso ambiente de aprendizaje permite a profesionales alrededor del mundo la oportunidad de acceder a información crucial para nutrir sus carreras, generar un mayor desarrollo empresarial e impactar al mundo. Nuestros programas le entregan a los participantes acceso inigualable a los mayores expertos de cada área. Esta experiencia de aprendizaje altamente focalizada les permite acceder a tópicos de interés vital y compartir con expertos reconocidos a nivel mundial además de incorporarse a una red internacional de colegas talentosos. Para mayor información acerca de los programas de MIT Professional Education favor visitar: http://professionaleducation.mit.edu .','Business Health Care Management Leadership Operations Management Project Management','2012','https://ocw.mit.edu/courses/res-16-001-lean-enterprise-en-espanol-january-iap-2012/','https://ocw.mit.edu/courses/res-16-001-lean-enterprise-en-espanol-january-iap-2012/pages/syllabus/','ecb8f0275b358ad20ee3ee2a59cecbd2404520472d93d284b5ae86c07c9a88da','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Earll Murman","Hugh McManus","Luis Fernando Alarcón Cardenas","Isabel Alarcón González"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('RES.18-002','RES.18-002','Introduction to MATLAB','This course was offered as a non-credit program during the Independent Activities Period (IAP) , January 2008. A more recent version is available as course 18.S997 Introduction To MATLAB Programming , including video lectures. The course, intended for students with no programming experience, provides the foundations of programming in MATLAB®. Variables, arrays, conditional statements, loops, functions, and plots are explained. At the end of the course, students should be able to use MATLAB in their own work, and be prepared to deepen their MATLAB programming skills and tackle other languages for computing, such as Java, C++, or Python. The course mostly follows the official MATLAB Manual , available from The MathWorks . We will cover material from chapters 2-5.','Applied Mathematics Computational Modeling and Simulation Computer Science Engineering Mathematics Programming Languages Systems Engineering','2008','https://ocw.mit.edu/courses/res-18-002-introduction-to-matlab-spring-2008/','https://ocw.mit.edu/courses/res-18-002-introduction-to-matlab-spring-2008/pages/syllabus/','c595e2b230329e2582b0299d9d9818ff56c22683930d2cf83033bcd93a61acd3','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Yossi Farjoun"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('RES.18-008','RES.18-008','Calculus Revisited: Complex Variables, Differential Equations, and Linear Algebra','Calculus Revisited is a series of videos and related resources that covers the materials normally found in freshman- and sophomore-level introductory mathematics courses. Complex Variables, Differential Equations, and Linear Algebra is the third course in the series, consisting of 20 Videos, 3 Study Guides, and a set of Supplementary Notes. Students should have mastered the first two courses in the series ( Single Variable Calculus and Multivariable Calculus ) before taking this course. The series was first released in 1972, but equally valuable today for students who are learning these topics for the first time. About the Instructor Herb Gross has taught math as senior lecturer at MIT and was the founding math department chair at Bunker Hill Community College. He is the developer of the Mathematics As A Second Language website, providing arithmetic and algebra materials to elementary and middle school teachers. Acknowledgements Funding for this resource was provided by the Gabriella and Paul Rosenbaum Foundation . Other Resources by Herb Gross Calculus Revisited: Single Variable Calculus Calculus Revisited: Multivariable Calculus','Calculus Differential Equations Linear Algebra Mathematics','2011','https://ocw.mit.edu/courses/res-18-008-calculus-revisited-complex-variables-differential-equations-and-linear-algebra-fall-2011/','https://ocw.mit.edu/courses/res-18-008-calculus-revisited-complex-variables-differential-equations-and-linear-algebra-fall-2011/pages/syllabus/','1dbafea02e5cb2464dd6f1a66751e884863a58a47d82d202df021d9d0524f4fa','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Herbert Gross"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('RES.2-002','RES.2-002','Finite Element Procedures for Solids and Structures','Finite element analysis is now widely used for solving complex static and dynamic problems encountered in engineering and the sciences. In these two video courses, Professor K. J. Bathe , a researcher of world renown in the field of finite element analysis, teaches the basic principles used for effective finite element analysis, describes the general assumptions, and discusses the implementation of finite element procedures for linear and nonlinear analyses. These videos were produced in 1982 and 1986 by the MIT Center for Advanced Engineering Study.','Computational Modeling and Simulation Engineering Mechanical Engineering Numerical Simulation Solid Mechanics Systems Engineering','2010','https://ocw.mit.edu/courses/res-2-002-finite-element-procedures-for-solids-and-structures-spring-2010/','https://ocw.mit.edu/courses/res-2-002-finite-element-procedures-for-solids-and-structures-spring-2010/pages/syllabus/','da4e62be8917a14f09b575fcc9cac3e291a564d7ca02d3b4ee3e6034e315e50f','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Klaus-Jürgen Bathe"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('RES.21G-01','RES.21G-01','Kana','Learning hiragana and katakana is an important part of reading and speaking Japanese. The following pages contain: Hiragana - stroke order videos , pronunciation, and vocabulary for each character; reading and listening audio exercises ; handouts on how to construct words and sentences; interactive quizzes testing character recognition; and printable worksheets to practice writing characters. Katakana - pronunciation and vocabulary for each character ; reading and listening audio exercises ; interactive quizzes testing character and vocabulary recognition; and printable worksheets to practice writing characters. These materials were developed as part of the Japanese curriculum at MIT for students of all levels to learn and review. Students and instructors are encouraged to incorporate them directly or as supplements in their study of Japanese. Technical Requirements This site is encoded in Unicode (UTF-8); please check your browser settings if characters render incorrectly: Internet Explorer version 6.0+ (Windows) - View → Encoding Safari version 4.0+ (Mac OSX) - View → Text Encoding Firefox 3.0+ (all platforms) - View → Character Encoding Opera (all platforms) - View → Encoding','Humanities Japanese Language','2010','https://ocw.mit.edu/courses/res-21g-01-kana-spring-2010/','https://ocw.mit.edu/courses/res-21g-01-kana-spring-2010/pages/syllabus/','fc02e156fd7582017455f46879f343388fdd98179240573176c6910dfeef71b6','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Ikue Shingu","Yoshimi Nagaya","Masami Ikeda-Lamm","Tomoko Graham","Prof. Shigeru Miyagawa"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('RES.21G-505','RES.21G-505','Kanji Learning Any Time, Any Place for Japanese V','This resource aims to enhance students’ learning of kanji by providing a series of video lectures that cover the kanji characters in Tobira lessons 1–5. The video lectures not only teach how to write kanji but also provide stories behind the kanji characters.','Humanities Japanese Language','2022','https://ocw.mit.edu/courses/res-21g-505-kanji-learning-any-time-any-place-for-japanese-v-spring-2022/','https://ocw.mit.edu/courses/res-21g-505-kanji-learning-any-time-any-place-for-japanese-v-spring-2022/pages/syllabus/','58a5fa1b709841de17901eb79b055c5ce27a3ed493f5f34fe26b7105a62b3070','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Takako Aikawa","Dr. Meghan Perdue"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('RES.24-002','RES.24-002','MIT-Haiti Initiative / Inisyativ MIT-Ayiti','The mission of the MIT-Haiti Initiative is to promote active learning in Kreyòl so that Haitians can have universal access to quality education in the language that most of them speak at home. Platfòm MIT-Ayiti , launched in 2019, offers a wealth of freely accessible educational resources in Kreyòl, including downloadable lesson plans and picture books categorized by topic, alongside official curricula from Haiti’s Ministry of National Education. The target audience for these resources includes students at all levels from pre-kindergarten through high school, and we offer materials in all disciplines. We also host and invite contributions from all educators who are willing to submit their own materials in Kreyòl. We work with these contributions, in konbit (collaborative) mode, to improve these submissions before publication. Men anpil, chay pa lou! (That is, many hands make light work!) The Initiative’s original website , launched in 2010, includes software tools for math, physics, genetics, and biochemistry education, as well as a preliminary (work-in-progress) glossary of Kreyòl equivalents for English words commonly used in the STEM disciplines.','Curriculum and Teaching Humanities Latin and Caribbean Studies Linguistics Society Teaching and Education','2023','https://ocw.mit.edu/courses/res-24-002-mit-haiti-initiative-inisyativ-mit-ayiti-spring-2023/','https://ocw.mit.edu/courses/res-24-002-mit-haiti-initiative-inisyativ-mit-ayiti-spring-2023/pages/syllabus/','500d86631b40d649a243a0513c12eb3b354e9303e420de1c488fb9473a5fb764','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Michel DeGraff","Prof. Haynes Miller"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('RES.6-001','RES.6-001','Continuum Electromechanics','First published in 1981 by MIT Press, Continuum Electromechanics , courtesy of MIT Press and used with permission, provides a solid foundation in electromagnetics, particularly conversion of energy between electrical and mechanical forms. Topics include: electrodynamic laws, electromagnetic forces, electromechanical kinematics, charge migration, convection, relaxation, magnetic diffusion and induction interactions, laws and approximations of fluid mechanics, static equilibrium, electromechanical flows, thermal and molecular diffusion, and streaming interactions. The applications covered include transducers, rotating machines, Van de Graaff machines, image processing, induction machines, levitation of liquid metals, shaping of interfaces in plastics and glass processing, orientation of ferrofluid seals, cryogenic fluids, liquid crystal displays, thunderstorm electrification, fusion machines, magnetic pumping of liquid metals, magnetohydrodynamic power generation, inductive and dielectric heating, electrophoretic particle motion, electrokinetic and electrocapillary interactions in biological systems, and electron beams.','Electrical Engineering Electromagnetism Engineering Mechanical Engineering Physics Quantum Mechanics Science','2009','https://ocw.mit.edu/courses/res-6-001-continuum-electromechanics-spring-2009/','https://ocw.mit.edu/courses/res-6-001-continuum-electromechanics-spring-2009/pages/syllabus/','0204e400a4e758e998385e093bb941f4bab2b4e364bc0d558d78b35f535bcd64','https://creativecommons.org/licenses/by-nc-sa/4.0/','["James R. Melcher"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('RES.6-006','RES.6-006','Video Demonstrations in Lasers and Optics','This resource contains demonstrations used to illustrate the theory and applications of lasers and optics. A detailed listing of the topics can be found below. Lasers today are being used in an ever-increasing number of applications. In fact, there is hardly a field that has not been touched by the laser. Lasers are playing key roles in the home, office, hospital, factory, outdoors, and theater, as well as in the laboratory. To learn about lasers and related optics, one usually takes a course or two, or acquires the necessary information from books and journal articles. To make this learning more vivid and more exciting, and, one hopes, more understandable, one needs to see some of the basic phenomena involved. To fill this need, Professor Ezekiel has videotaped 48 demonstrations that illustrate most of the fundamental phenomena relating to lasers and physical optics. By using split-screen inserts and a wide range of video-recording capabilities, it is possible to show real-time effects in lasers and optics with the simultaneous manipulation of the components that cause these effects. In this way, one can see effects in close up that would be difficult, if not impossible, to display in front of an audience or in the classroom. These video demonstrations are designed for: The individual student of lasers and optics who wants to observe the various phenomena covered in theoretical treatments in courses, books, and technical papers. The Instructor in lasers and optics in a company, university, college, or high school who wants to illustrate, in class, many of the fundamental phenomena in optics and lasers. These videos were produced by the MIT Center for Advanced Engineering Study.','Atomic, Molecular, Optical Physics Electromagnetism Physics Quantum Mechanics Science','2008','https://ocw.mit.edu/courses/res-6-006-video-demonstrations-in-lasers-and-optics-spring-2008/','https://ocw.mit.edu/courses/res-6-006-video-demonstrations-in-lasers-and-optics-spring-2008/pages/syllabus/','a69581354677e5fe1a63df721e5a9852f3764c4c6add43c66d6454e36bcda7fd','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Shaoul Ezekiel"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('RES.6-013','RES.6-013','AI 101','Machine vision. Data wrangling. Reinforcement learning. What do these terms even mean? In AI 101, MIT researcher Brandon Leshchinskiy offers an introduction to artificial intelligence that’s designed specifically for those with little to no background in the subject. The workshop starts with a summary of key concepts in AI, followed by an interactive exercise where participants train their own algorithm. Finally, it closes with a summary of key takeaways and Q/A. All are welcome!','Artificial Intelligence Computer Science Engineering','2021','https://ocw.mit.edu/courses/res-6-013-ai-101-fall-2021/','https://ocw.mit.edu/courses/res-6-013-ai-101-fall-2021/pages/syllabus/','4b95e3e5632d21c5d702563d8fcf6dabd989e84bf92bd19999ee689e6f405273','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Brandon Leshchinskiy"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('RES.7-005','RES.7-005','Biology Teaching Assistant (TA) Training','The MIT Biology Department supports TAs’ teaching by providing a specialized Teaching Assistant (TA) training program in Biology Pedagogy, for which TAs can earn a training certificate. This program has been developed in response to the feedback of previous TAs, and is designed to actively meet each TA’s needs as they are teaching. It provides practical knowledge that directly relates to their teaching responsibilities each week, and provides them with the opportunity to practice different skills and techniques in a supportive environment.','Curriculum and Teaching Teaching and Education','2021','https://ocw.mit.edu/courses/res-7-005-biology-teaching-assistant-ta-training-fall-2021/','https://ocw.mit.edu/courses/res-7-005-biology-teaching-assistant-ta-training-fall-2021/pages/syllabus/','519ac1b9912a1f6c5ea2113fb14b304d6c6884d7c654380b097d8fa3973d8eb8','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Summer Morrill"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('RES.8-002','RES.8-002','A WikiTextBook for Introductory Mechanics','This e-Book is a first step toward a shift in the role of the printed textbook from authoritative serial repository to modular, customizable, linkable, interactive hub. The ideal modern textbook should provide a clear overview of the domain, short summaries of key content, links to more detailed online source material, embedded self-assessment, and a vehicle for instant student feedback. This open-source e-Book for introductory mechanics uses ideas from modeling physics to encourage strategic, concept-based problem solving and employs a wiki format to enable multiple parallel organizations of the material, links to resources and student comments. Online Publication','Classical Mechanics Physics Science','2009','https://ocw.mit.edu/courses/res-8-002-a-wikitextbook-for-introductory-mechanics-fall-2009/','https://ocw.mit.edu/courses/res-8-002-a-wikitextbook-for-introductory-mechanics-fall-2009/pages/syllabus/','302c0a628e7a5ae7db724e9c088a3c622c3dcedfa5029d73ef4ec850e79c6bb1','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Analia Barrantes","Andrew Pawl","David E. Pritchard","Stephen E. Wilk"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('RES.8-009','RES.8-009','Introduction to Oscillations and Waves ','Introduction to Oscillations and Waves covers the basic mathematics and physics of oscillatory and wave phenomena. By the end of the course, students should be able to explain why oscillations appear in many near equilibrium systems, the various mathematical properties of those oscillations in various contexts, how oscillations and waves are related, and the basic mathematical description and properties of a wave. This course was offered as part of MITES Summer , a six-week, residential STEM experience for rising high school seniors. MIT Introduction to Technology, Engineering, and Science (MITES) provides transformative experiences that bolster confidence, create lifelong community, and build an exciting, challenging foundation in STEM for highly motivated 7th–12th grade students from diverse and underrepresented backgrounds.','Atomic, Molecular, Optical Physics Classical Mechanics Electromagnetism Physics Science','2017','https://ocw.mit.edu/courses/res-8-009-introduction-to-oscillations-and-waves-summer-2017/','https://ocw.mit.edu/courses/res-8-009-introduction-to-oscillations-and-waves-summer-2017/pages/syllabus/','d34541e5f22a1283666d77ca068f383e955821d537f5b32268cab854f22f07f5','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Mobolaji Williams"]','review_required','With regard to mathematics, students should be proficient in algebra, matrix addition/multiplication, trigonometry, analytic geometry, and basic differentiation/integration. With regard to physics, students should have had prior exposure to and practice with Newton’s laws of motion, 1D kinematics, 2D projectile motion, and conservation of energy/momentum.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('RES.9-006','RES.9-006','AFNI Training Bootcamp','This training course is an introduction to the use of the AFNI software suites for the analysis of functional MRI (fMRI) data. It is not intended as an introduction to how fMRI works but is aimed at people who are already doing fMRI data analysis, or those who will be in the near future. AFNI (Analysis of Functional NeuroImages) is a leading software suite of C, Python, and R programs and shell scripts, primarily developed for the analysis and display of anatomical and fMRI data. It is freely available for research purposes. This event was organized by the Center for Brains, Minds, and Machines (CBMM) Trainee Leadership Council. CBMM is a multi-institutional NSF Science and Technology Center headquartered at MIT that is dedicated to developing a computationally based understanding of human intelligence and establishing an engineering practice based on that understanding. CBMM brings together computer scientists, cognitive scientists, and neuroscientists to create a new field—the science and engineering of intelligence.','Biomedical Signal and Image Processing Cognitive Science Health and Medicine Medical Imaging Science','2018','https://ocw.mit.edu/courses/res-9-006-afni-training-bootcamp-spring-2018/','https://ocw.mit.edu/courses/res-9-006-afni-training-bootcamp-spring-2018/pages/syllabus/','e416dda61b376a4121aa074fca4e843078699b22cbcbf72f27383b8240350be0','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Rick Reynolds","Daniel Glen","Gang Chen"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('RES.CMS-001','RES.CMS-001','Media Literacy in the Age of Deepfakes','Media Literacy in the Age of Deepfakes aims to equip students with the critical skills to better understand the past and contemporary threat of misinformation. Students will learn about different ways to analyze emerging forms of misinformation such as “deepfake” videos as well as how new technologies can be used to create a more just and equitable society. This module consists of three interconnected sections. We begin by defining and contextualizing some key terms related to misinformation. We then focus on the proliferation of deepfakes within our media environment. Lastly, we explore synthetic media for the civic good, including AI-enabled projects geared towards satire, investigative documentary, and public history. In Event of Moon Disaster, an award-winning deepfake art installation about the “failed” Apollo 11 moon landing, serves as a central case study. This learning module also includes a suite of educator resources that consists of a syllabus, bibliography, and design prompts. We encourage teachers to draw on and adapt these resources for the purposes of their own classes. Visit Media Literacy in the Age of Deepfakes to access the learning module and educator resources. A sample of some of these materials can be found on OCW. This course was produced by the MIT Center for Advanced Virtuality , with support from the J-WEL: Abdul Latif Jameel World Education Lab .','Artificial Intelligence Computer Science Engineering Fine Arts Media Studies Teaching and Education','2021','https://ocw.mit.edu/courses/res-cms-001-media-literacy-in-the-age-of-deepfakes-spring-2021/','https://ocw.mit.edu/courses/res-cms-001-media-literacy-in-the-age-of-deepfakes-spring-2021/pages/syllabus/','201d5ae6e4d8a4f5f4bcff3358c736eeb1d0244986acc5e6a3eae5f3ffd36747','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Joshua Glick","Prof. D. Fox Harrell"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('RES.EC-001','RES.EC-001','Exploring Fairness in Machine Learning for International Development','In an effort to build the capacity of the students and faculty on the topics of bias and fairness in machine learning (ML) and appropriate use of ML, the MIT CITE team developed capacity-building activities and material. This material covers content through four modules that an be integrated into existing courses over a one to two week period.','Artificial Intelligence Computer Science Curriculum and Teaching Engineering Teaching and Education','2020','https://ocw.mit.edu/courses/res-ec-001-exploring-fairness-in-machine-learning-for-international-development-spring-2020/','https://ocw.mit.edu/courses/res-ec-001-exploring-fairness-in-machine-learning-for-international-development-spring-2020/pages/syllabus/','d097669a6f056f68488d8535ffcdcbd45f0f7ea4aa441be72ec9d06058b2e0b9','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Richard Fletcher","Prof. Daniel Frey","Dr. Mike Teodorescu","Amit Gandhi","Audace Nakeshimana"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('RES.ENV-004','RES.ENV-004','MIT Climate Portal','To inform and empower the public on the complex issue of climate change, the Massachusetts Institute of Technology has created a Climate Portal, an online home for timely, science-based information about the causes and consequences of climate change—and what can be done to address it. Whether you are new to climate change or ready for a deeper exploration, the MIT Climate Portal offers a virtual place to ground your knowledge and ask your questions of experts. It also highlights MIT’s latest climate change research and initiatives for action. The MIT Climate Portal is managed by the MIT Environmental Solutions Initiative , with support from the MIT Office of the Vice President for Research .','Climate Studies Earth Science Energy Public Administration Science Science and Technology Policy Social Science','2020','https://ocw.mit.edu/courses/res-env-004-mit-climate-portal-fall-2020/','https://ocw.mit.edu/courses/res-env-004-mit-climate-portal-fall-2020/pages/syllabus/','d282cf5b05f23f4cd00060930a09edfa633786e3d299d00643cf04ad417ad1be','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Laur Hesse Fisher"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('RES.ES-001','RES.ES-001','MIT Prison Education Initiative Discussion About Incarceration','The MIT Prison Education Initiative (PEI) hosted this non-credit January IAP course to give the MIT community an opportunity to engage in discussions about mass incarceration and criminal justice reform. The Independent Activities Period (IAP) is a special four week term at MIT that runs from the first week of January until the end of the month.','Social Science Society','2021','https://ocw.mit.edu/courses/res-es-001-mit-prison-education-initiative-discussion-about-incarceration-january-iap-2021/','https://ocw.mit.edu/courses/res-es-001-mit-prison-education-initiative-discussion-about-incarceration-january-iap-2021/pages/syllabus/','04351ace2f5cc52423d5b91348893ca0360b079e0f5eeda44d74b9970f80ee6a','https://creativecommons.org/licenses/by-nc-sa/4.0/','["MIT Prison Education Initiative "]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('RES.LL-001','RES.LL-001','Introduction to Radar Systems','This set of 10 lectures (about 11+ hours in duration) was excerpted from a three-day course developed at MIT Lincoln Laboratory to provide an understanding of radar systems concepts and technologies to military officers and DoD civilians involved in radar systems development, acquisition, and related fields. That three-day program consists of a mixture of lectures, demonstrations, laboratory sessions, and tours. Online Publication','Electrical Engineering Electromagnetism Electronics Engineering Physics Science Signal Processing','2007','https://ocw.mit.edu/courses/res-ll-001-introduction-to-radar-systems-spring-2007/','https://ocw.mit.edu/courses/res-ll-001-introduction-to-radar-systems-spring-2007/pages/syllabus/','1c81fe47799f0efacd07933c5224cebd08f58098dbf48a938003630e7c818363','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Robert M. O''Donnell"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('RES.SOLVEX','RES.SOLVEX','Business and Impact Planning for Social Enterprises (0.SolveX)','People in every corner of the world are innovating to solve social and environmental problems in their communities. In the past decade, new programs like MIT Solve have emerged to support those social entrepreneurs and drive partnerships to accelerate their impact. However, many startups find it difficult to develop business plans that clearly communicate their work and impact. The main focus of this course is to help early-stage social impact startups define key aspects of their business by examining case studies from leading social entrepreneurs and both nonprofit and for-profit enterprises around the world. The course was created by MIT Solve for MITx, and is now archived on the Open Learning Library (OLL) , which is free to use. You have the option to sign up and enroll in each module if you want to track your progress, or you can view and use all the materials without enrolling.','Business Entrepreneurship Management','2021','https://ocw.mit.edu/courses/res-solvex-business-and-impact-planning-for-social-enterprises-0-solvex-summer-2021/','https://ocw.mit.edu/courses/res-solvex-business-and-impact-planning-for-social-enterprises-0-solvex-summer-2021/pages/syllabus/','36779418b2c8394455b1917abd4be2539650fbf9506240540540b69a90b5a2e8','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Anjali Sastry"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('RES.SUD-01','RES.SUD-01','Substance Use Disorder Ventures Program ','Substance Use Disorder (SUD) Ventures is an intense and immersive hybrid program, offered through MIT Open Learning, whose aim is to fuel the next generation of innovation in the field of substance use treatment and research. This program is designed to support researchers and other innovators in the field of SUD with knowledge and examples of how to bring their innovations to market. The program and its research are supported by the National Institute on Drug Abuse of the National Institutes of Health under Award Number UE5DA056914. This award is subject to the Cooperative Agreement Terms and Conditions of Award as set forth in RFA DA-22–020, entitled “Growing Great Ideas: Research Education Course in Product Development and Entrepreneurship for Life Science Researchers (UE5 Clinical Trial Not Allowed).”','Biomedical Enterprise Business Entrepreneurship Health and Medicine Public Health','2025','https://ocw.mit.edu/courses/res-sud-01-substance-use-disorder-ventures-program-spring-2025/','https://ocw.mit.edu/courses/res-sud-01-substance-use-disorder-ventures-program-spring-2025/pages/syllabus/','e056391141e6453463f9a377016085ddb51759bdf52aa5474329383dfe6f2a2c','https://creativecommons.org/licenses/by-nc-sa/4.0/','["MIT SUD Ventures Team"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('RES.TLL-010','RES.TLL-010','Syllabus Checklist to Support Student Belonging & Achievement','The syllabus informs students’ first impressions of a class, the instructor, and their evaluation of whether they will succeed. Given the important role of the syllabus for students and for instructors’ intentional design of the course, this syllabus checklist is a tool to guide instructors in their construction and revision of course design, assessment descriptions, teaching practices, and policies in their syllabi. Many of the checklist items also apply beyond the syllabus to other communication channels in the course (e.g., Learning Management Systems, course wikis, classroom conversations). The checklist is adapted from a comprehensive and detailed rubric developed by members of MIT’s Teaching + Learning Lab .','Curriculum and Teaching Teaching and Education','2025','https://ocw.mit.edu/courses/res-tll-010-syllabus-checklist-to-support-student-belonging-achievement-spring-2025/','https://ocw.mit.edu/courses/res-tll-010-syllabus-checklist-to-support-student-belonging-achievement-spring-2025/pages/syllabus/','3a3ad7ff3cc986e8f024ed8667c2cf4ca2d335ae5a2a782e3c7cb3e19c8cc395','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Ruthann Thomas"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('STS.003','STS.003','The Rise of Modern Science','This subject introduces the history of science from antiquity to the present. Students consider the impact of philosophy, art, magic, social structure, and folk knowledge on the development of what has come to be called “science” in the Western tradition, including those fields today designated as physics, biology, chemistry, medicine, astronomy and the mind sciences. Topics include concepts of matter, nature, motion, body, heavens, and mind as these have been shaped over the course of history. Students read original works by Aristotle, Vesalius, Newton, Lavoisier, Darwin, Freud, and Einstein, among others.','History History of Science and Technology Humanities Public Administration Science and Technology Policy Social Science','2010','https://ocw.mit.edu/courses/sts-003-the-rise-of-modern-science-fall-2010/','https://ocw.mit.edu/courses/sts-003-the-rise-of-modern-science-fall-2010/pages/syllabus/','83bffb2e571f0f138b721fb1ed943cf2fd74e51a276f66c1a089d9ac22de5b43','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. David Jones","Prof. David Kaiser"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('STS.011','STS.011','American Science: Ethical Conflicts and Political Choices','We will explore the changing political choices and ethical dilemmas of American scientists from the atomic scientists of World War II to biologists in the present wrestling with the questions raised by cloning and other biotechnologies. As well as asking how we would behave if confronted with the same choices, we will try to understand the choices scientists have made by seeing them in their historical and political contexts. Some of the topics covered include: the original development of nuclear weapons and the bombing of Hiroshima and Nagasaki; the effects of the Cold War on American science; the space shuttle disasters; debates on the use of nuclear power, wind power, and biofuels; abuse of human subjects in psychological and other experiments; deliberations on genetically modified food, the human genome project, human cloning, embryonic stem cell research; and the ethics of archaeological science in light of controversies over museum collections.','American History American Politics Ethics History History of Science and Technology Humanities Philosophy Political Science Social Science','2007','https://ocw.mit.edu/courses/sts-011-american-science-ethical-conflicts-and-political-choices-fall-2007/','https://ocw.mit.edu/courses/sts-011-american-science-ethical-conflicts-and-political-choices-fall-2007/pages/syllabus/','41e046ded0baa91df632671d98033b4389003274fc232ee384b6a5738627fc87','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Brendan Foley"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('STS.036','STS.036','Technology and Nature in American History','This course considers how the visual and material world of “nature” has been reshaped by industrial practices, ideologies, and institutions, particularly in nineteenth- and twentieth-century America. Topics include land-use patterns; the changing shape of cities and farms; the redesign of water systems; the construction of roads, dams, bridges, irrigation systems; the creation of national parks; ideas about wilderness; and the role of nature in an industrial world. From small farms to suburbia, Walden Pond to Yosemite, we will ask how technological and natural forces have interacted, and whether there is a place for nature in a technological world. Acknowledgement This class is based on one originally designed and taught by Prof. Deborah Fitzgerald. Her Fall 2004 version can be viewed by following the link under Archived Courses on the right side of this page.','American History Civil Engineering Engineering History History of Science and Technology Humanities Social Science Urban Planning Urban Studies','2008','https://ocw.mit.edu/courses/sts-036-technology-and-nature-in-american-history-spring-2008/','https://ocw.mit.edu/courses/sts-036-technology-and-nature-in-american-history-spring-2008/pages/syllabus/','1774c7625f4718a9c244412ed192ca0ae83921be13b6812bcebee4c290289c34','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Jamie Pietruska"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('STS.062J','STS.062J','Drugs, Politics, and Culture','This class examines the relationship between a number of mind-altering substances and cultural processes. We look at the relationship between drugs and such phenomena as poverty, religion, technology, inter-generational conflict, colonialism, and global capitalism. We read about the physiological and psychological effects of these substances – ranging from alcohol to LSD, cocaine and ecstasy – and ask why different societies prohibit and sanction different drugs. We examine the use of mind-altering substances in a number of “traditional” societies, and follow the development of a global trade in such substances as sugar, coffee, tea, nicotine, cocaine, and marijuana concurrent with the evolution of global capitalism. We look at the use of LSD as a mind-control substance by the CIA and as a mind-altering substance in the 1960’s counter-culture, and we look at the rise of Prozac® and Viagra® as popular, if controversial, pharmaceutical products in recent years. Finally, we evaluate America’s current drug laws.','Health and Medicine Pharmacology and Toxicology Public Health Social Science Sociology','2006','https://ocw.mit.edu/courses/sts-062j-drugs-politics-and-culture-spring-2006/','https://ocw.mit.edu/courses/sts-062j-drugs-politics-and-culture-spring-2006/pages/syllabus/','03b2d7dddb3b55f3b95bf3951753dff69c742d16c9a2f138c93a44c4de9d7d65','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Hugh Gusterson"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('STS.310','STS.310','History of Science','This course offers an introduction to the history and historiography of science from ancient Greece to the present. It is designed to serve as an introduction for those who have no prior background in the field and to deepen the knowledge of those who already do. We will consider how the history of science has responded to its encounters with philosophy, sociology, economics, and anthropology. Our readings and discussions will focus on determining what makes particular works effective, understanding major contemporary trends and debates in the history of science, and establishing resources for further research.','History History of Science and Technology Humanities Intellectual History','2015','https://ocw.mit.edu/courses/sts-310-history-of-science-fall-2015/','https://ocw.mit.edu/courses/sts-310-history-of-science-fall-2015/pages/syllabus/','3eb607b6493114067b249f6addb18810fecae9ae7e6d4e1e8dad75e153236ae4','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Robin Scheffler"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('STS.429','STS.429','Food and Power in the Twentieth Century','In this class, food serves as both the subject and the object of historical analysis. As a subject, food has been transformed over the last 100 years, largely as a result of ever more elaborate scientific and technological innovations. From a need to preserve surplus foods for leaner times grew an elaborate array of techniques – drying, freezing, canning, salting, etc – that changed not only what people ate, but how far they could/had to travel, the space in which they lived, their relations with neighbors and relatives, and most of all, their place in the economic order of things. The role of capitalism in supporting and extending food preservation and development was fundamental. As an object, food offers us a way into cultural, political, economic, and techno-scientific history. Long ignored by historians of science and technology, food offers a rich source for exploring, e.g., the creation and maintenance of mass-production techniques, industrial farming initiatives, the politics of consumption, vertical integration of business firms, globalization, changing race and gender identities, labor movements, and so forth. How is food different in these contexts, from other sorts of industrial goods? What does the trip from farm to table tell us about American culture and history?','Economics History Humanities Modern History Political Economy Social Science','2005','https://ocw.mit.edu/courses/sts-429-food-and-power-in-the-twentieth-century-spring-2005/','https://ocw.mit.edu/courses/sts-429-food-and-power-in-the-twentieth-century-spring-2005/pages/syllabus/','9b6118d26a492eb0e1a36c526eaa9c1df4c58380f0fb55b8144c0c30e3bc10c6','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Deborah Fitzgerald"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('STS.467','STS.467','Research Seminar in Deep Sea Archaeology','STS.467 examines the intellectual foundations of archaeology in the deep sea. The course explores the current convergence of oceanography, archaeology, and engineering which allows scientists to discover, survey, and excavate shipwrecks in deep water with robots and submarines. The course seeks to address the following questions: How are new devices best employed for archaeological work? How do new capabilities (e.g. higher frequencies, higher resolution, all digital data output) change operations plans and research designs? What new technologies will be required? Area studies focus on the Aegean in Minoan times and western Sicily during Phoenician, Greek, and Roman hegemony.','Archaeology Earth Science Engineering Ocean Engineering Ocean Exploration Oceanography Science Social Science','2002','https://ocw.mit.edu/courses/sts-467-research-seminar-in-deep-sea-archaeology-spring-2002/','https://ocw.mit.edu/courses/sts-467-research-seminar-in-deep-sea-archaeology-spring-2002/pages/syllabus/','699b22da9a023b136de02b087d890e5c982ea3f7537cd93189421d64803b9757','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. David Mindell","Dr. Claire Calcagno"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('WGS.115','WGS.115','Gender and Technology','This course considers a wide range of issues related to the contemporary and historical use of technology, the development of new technologies, and the cultural representation of technology, including the role women have played in the development of technology and the effect of technological change on the roles of women and ideas of gender. It discusses the social implications of technology and its understanding and deployment in different cultural contexts. It investigates the relationships between technology and identity categories, such as gender, race, class, and sexuality, and examines how technology offers possibilities for new social relations and how to evaluate them.','Gender Studies History History of Science and Technology Humanities Society','2013','https://ocw.mit.edu/courses/wgs-115-gender-and-technology-spring-2013/','https://ocw.mit.edu/courses/wgs-115-gender-and-technology-spring-2013/pages/syllabus/','40426c323e1caef1f9bc48a8944fff2e0b1d89506bf5bc53a456982876ced2d4','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. K.J. Surkan"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('WGS.301J','WGS.301J','Feminist Thought','This course analyzes theories of gender and politics, especially ideologies of gender and their construction; definitions of public and private spheres; and gender issues in citizenship, the development of the welfare state, experiences of war and revolution, class formation, and the politics of sexuality.','Gender Studies Society Women''s Studies','2023','https://ocw.mit.edu/courses/wgs-301j-feminist-thought-fall-2023/','https://ocw.mit.edu/courses/wgs-301j-feminist-thought-fall-2023/pages/syllabus/','e9841138afe35d49956d4e9b50a980d0e516a569e4ebace06bf347d22050cdcc','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Prof. Elizabeth A. Wood"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
INSERT INTO m2_course (code,source_course_code,title,description,topics,source_year,source_url,syllabus_url,source_sha256,license_url,instructors_json,prerequisite_status,prerequisite_evidence) VALUES ('WGS.645','WGS.645','Gendering U.S. Immigration Policy: Sociopolitical, Theological and Feminist Perspectives ','This course uses theories of gender to explore sociopolitical, ethical and theological perspectives on immigration policy, with a focus on the U.S. The course begins with an overview of global developments in the feminization of migration and ethical and policy dilemmas that are specific to the current era.','American Politics Gender Studies Political Science Public Administration Public Policy Social Science Society Women''s Studies','2019','https://ocw.mit.edu/courses/wgs-645-gendering-u-s-immigration-policy-sociopolitical-theological-and-feminist-perspectives-spring-2019/','https://ocw.mit.edu/courses/wgs-645-gendering-u-s-immigration-policy-sociopolitical-theological-and-feminist-perspectives-spring-2019/pages/syllabus/','6c05f8af6b4818444c1fa7cefddc81255fec9fcb39477d8bc24fad9f2af20d91','https://creativecommons.org/licenses/by-nc-sa/4.0/','["Dr. Choi Hee An","Dr. Philip Kretsedemas"]','review_required','Prerequisites have not yet been verified against the published syllabus. Staff review is required before automatic recommendation.') ON DUPLICATE KEY UPDATE source_course_code=VALUES(source_course_code),title=VALUES(title),description=VALUES(description),topics=VALUES(topics),source_year=VALUES(source_year),source_url=VALUES(source_url),syllabus_url=VALUES(syllabus_url),source_sha256=VALUES(source_sha256),license_url=VALUES(license_url),instructors_json=VALUES(instructors_json),prerequisite_status=VALUES(prerequisite_status),prerequisite_evidence=VALUES(prerequisite_evidence);
